globalThis.ANDE_CHUNKS["0e4f9ae28f711b6cc76e778d7e0c9ceff7b7bb04f419810539d41b5034dbd032"] = [{"id":"meituan_social:4469665768","sourceKey":"meituan_social","company":"美团","title":"Senior Legal Counsel (Saudi Arabia)","city":"利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4469665768&jobShareType=1","duty":"Job Description:\n\nWe are seeking a qualified and experienced Legal Counsel to join our legal team in Saudi Arabia. This role will primarily support various business lines on corporate, advisory, contract, and dispute resolution matters.\n\nKey Responsibilities:\n\n1. Conduct legal research and provide comprehensive legal advice and support on transactions and commercial matters; identify and assess legal risks and develop strategies to mitigate them.\n\n2. Draft, review, and negotiate contracts, agreements, and other legal documents.\n\n3. Work closely with senior management and business units to ensure legal requirements are met.\n\n4. Support the business units to communicate with relevant authorities, associations and other external stakeholders, to maintain a business friendly regulatory environment\n\n5. Handle dispute matters, including civil, commercial, administrative, labor litigation and arbitration, and other ADR proceedings. Develop litigation strategies. Represent the company in legal proceedings and negotiations.\n\n6. Stay up-to-date with changes in the legal landscape and industry trends.\n\n7. Develop an adequate and high-quality resource pool of external law firms, and maintain strong relationships with external legal advisors and partners.","requirements":"Qualifications:\n\n1. A bachelor degree of law.\n\n2. Qualified lawyer in Saudi Arabia.\n\n3. Minimum 7 years of relevant experience of relevant work experience, among which at least 5 years in Saudi Arabia.\n\n4. Native Arabic speaker, with fluent English proficiency (both written and spoken) as a working language\n\n5. Excellent knowledge of corporate law, contract law, and commercial law.\n\n6. Strong analytical, communication, and stakeholder management skills\n\n7. Ability to work independently and as part of a team.\n\n8. Proven track record of managing complex legal projects and deadlines.","description":"部门介绍\n公司事务平台负责构建公司的公共战略体系，助力业务可持续发展及公司对外影响力的提升。通过内外部风险管理，确保公司合规发展；通过深耕公共战略，推动内外良好沟通，连接公司发展与社会期待，助力业务高质量发展；通过管理社会责任议题、公益投入等，助力公司创造更多社会价值；同时为公司提供行政、采购等基础服务。我们坚持“懂业务、拿结果，勇担当、善协同，不唯上、只唯真”的工作理念，期待具有公共战略素养、了解公司治理逻辑的你加入！\n\n岗位职责\nJob Description:\n\nWe are seeking a qualified and experienced Legal Counsel to join our legal team in Saudi Arabia. This role will primarily support various business lines on corporate, advisory, contract, and dispute resolution matters.\n\nKey Responsibilities:\n\n1. Conduct legal research and provide comprehensive legal advice and support on transactions and commercial matters; identify and assess legal risks and develop strategies to mitigate them.\n\n2. Draft, review, and negotiate contracts, agreements, and other legal documents.\n\n3. Work closely with senior management and business units to ensure legal requirements are met.\n\n4. Support the business units to communicate with relevant authorities, associations and other external stakeholders, to maintain a business friendly regulatory environment\n\n5. Handle dispute matters, including civil, commercial, administrative, labor litigation and arbitration, and other ADR proceedings. Develop litigation strategies. Represent the company in legal proceedings and negotiations.\n\n6. Stay up-to-date with changes in the legal landscape and industry trends.\n\n7. Develop an adequate and high-quality resource pool of external law firms, and maintain strong relationships with external legal advisors and partners.\n\n岗位基本要求\nQualifications:\n\n1. A bachelor degree of law.\n\n2. Qualified lawyer in Saudi Arabia.\n\n3. Minimum 7 years of relevant experience of relevant work experience, among which at least 5 years in Saudi Arabia.\n\n4. Native Arabic speaker, with fluent English proficiency (both written and spoken) as a working language\n\n5. Excellent knowledge of corporate law, contract law, and commercial law.\n\n6. Strong analytical, communication, and stakeholder management skills\n\n7. Ability to work independently and as part of a team.\n\n8. Proven track record of managing complex legal projects and deadlines.\n\n具备以下条件优先\n1. Diverse professional background, including experience in law firms, in-house legal teams, regulatory authorities, and/or judicial institutions (e.g., courts or prosecutorial bodies) in Saudi Arabia\n\n2. Overseas education experience in an English-speaking country\n\n3. Experience working with or advising multinational companies\n\n4. Familiarity with e-commerce, platform businesses, or fast-growing tech environment\n\n岗位亮点\nTo work in a fast growing and dynamic business with an amicable transnational legal team.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4691862605","sourceKey":"meituan_social","company":"美团","title":"品牌官旗场域增长运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4691862605&jobShareType=1","duty":"1. 负责官旗品牌场域搭建及运营策略制定与落地执行，明确场域目标用户并通过运营策略提升场域用户活跃度和转化率。  \n2. 有较好的C端视角，分析场域用户行为数据，挖掘用户需求，推动运营策略迭代与体验优化。根据目标用户制定商品招商标准，并协同商家运营推动招商。 \n3. 有一定的玩法和裂变经历，能够基于场域/店铺属性，设计用户增长玩法及策略。完善促销工具的使用规则，对钱效和用户体验指标负责，确保资源合理配置与用户满意度提升。\n4. 监控关键运营指标，定期输出分析复盘，持续迭代场域经营策略。","requirements":"1. 大学本科及以上学历，3年以上产品运营、场域运营、用户增长相关工作经验。  \n2. 熟悉电商或本地生活场域运营模式，具备供给运营或场域运营经验者优先。  \n3. 具备较强的数据分析能力，熟练使用SQL等工具，能通过数据驱动业务增长。  \n4. 学习能力强，能面对复杂问题的做拆解并不断迭代，能够深入理解与思考行业逻辑并找到突破点；\n4. 自驱力强、有较强的沟通表达能力，具有主人翁意识和团队协作精神，能够协调各方资源推动完成工作，确保推进落地。\n5. 逻辑清晰，具备较强的自驱力能力，对用户体验和商家生态有深刻理解。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1. 负责官旗品牌场域搭建及运营策略制定与落地执行，明确场域目标用户并通过运营策略提升场域用户活跃度和转化率。  \n2. 有较好的C端视角，分析场域用户行为数据，挖掘用户需求，推动运营策略迭代与体验优化。根据目标用户制定商品招商标准，并协同商家运营推动招商。 \n3. 有一定的玩法和裂变经历，能够基于场域/店铺属性，设计用户增长玩法及策略。完善促销工具的使用规则，对钱效和用户体验指标负责，确保资源合理配置与用户满意度提升。\n4. 监控关键运营指标，定期输出分析复盘，持续迭代场域经营策略。\n\n岗位基本要求\n1. 大学本科及以上学历，3年以上产品运营、场域运营、用户增长相关工作经验。  \n2. 熟悉电商或本地生活场域运营模式，具备供给运营或场域运营经验者优先。  \n3. 具备较强的数据分析能力，熟练使用SQL等工具，能通过数据驱动业务增长。  \n4. 学习能力强，能面对复杂问题的做拆解并不断迭代，能够深入理解与思考行业逻辑并找到突破点；\n4. 自驱力强、有较强的沟通表达能力，具有主人翁意识和团队协作精神，能够协调各方资源推动完成工作，确保推进落地。\n5. 逻辑清晰，具备较强的自驱力能力，对用户体验和商家生态有深刻理解。\n\n具备以下条件优先\n有相关场域用户增长经验、会SQL优先考虑\n\n岗位亮点\n1.核心岗位，具备高成长性； \n2.团队氛围好、凝聚力强、目标感强、互动融洽、积极有活力，欢迎加入一起共同成长。\n3. 工作地点位于北京核心区域，交通便利，办公环境优越。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4669451731","sourceKey":"meituan_social","company":"美团","title":"无人车远程驾驶安全员组长","city":"武汉市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4669451731&jobShareType=1","duty":"1.团队管理，负责团队人员“选用育励汰”，制定并落实团队管理制度，保障团队稳定性与战斗力。  \n\n2.业务管理，根据需求安排人员排班出勤，针对目标制定管理动作并执行落地，为结果达成负责；制定业务目标及执行策略，通过数据化管控确保目标达成。  \n\n3.培训管理，负责制定标准化培训课程与考核方案，定期组织技能认证与能力评估，确保团队成员技能水平持续符合业务要求，建立知识管理机制，推动经验沉淀与案例库建设。  \n\n4.安全管理，负责团队安全管理，建立常态化安全检查机制，定期开展安全巡检把控风险，负责突发事件应急响应，制定应急预案并持续优化处置流程。  \n\n5.项目管理，统筹跨部门资源协调，主导重点项目全流程推进，确保项目按期高质量交付；系统梳理业务痛点，推动工具、产品、流程的持续优化，定期输出改进方案。","requirements":"1.本科及以上学历，3年以上一线团队管理经验。  \n\n2.具备项目管理经验，能制定执行计划，协调跨团队资源，确保目标达成。  \n\n3.沟通协调和执行能力强，能高效推动跨部门协作，能快速响应业务需求，确保管理动作落地。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1.团队管理，负责团队人员“选用育励汰”，制定并落实团队管理制度，保障团队稳定性与战斗力。  \n\n2.业务管理，根据需求安排人员排班出勤，针对目标制定管理动作并执行落地，为结果达成负责；制定业务目标及执行策略，通过数据化管控确保目标达成。  \n\n3.培训管理，负责制定标准化培训课程与考核方案，定期组织技能认证与能力评估，确保团队成员技能水平持续符合业务要求，建立知识管理机制，推动经验沉淀与案例库建设。  \n\n4.安全管理，负责团队安全管理，建立常态化安全检查机制，定期开展安全巡检把控风险，负责突发事件应急响应，制定应急预案并持续优化处置流程。  \n\n5.项目管理，统筹跨部门资源协调，主导重点项目全流程推进，确保项目按期高质量交付；系统梳理业务痛点，推动工具、产品、流程的持续优化，定期输出改进方案。\n\n岗位基本要求\n1.本科及以上学历，3年以上一线团队管理经验。  \n\n2.具备项目管理经验，能制定执行计划，协调跨团队资源，确保目标达成。  \n\n3.沟通协调和执行能力强，能高效推动跨部门协作，能快速响应业务需求，确保管理动作落地。\n\n具备以下条件优先\n1.有自动驾驶相关管理岗位经验优先。\n\n2.管理过20人以上团队者优先。\n\n3.对安全驾驶规范、测试标准、风险评估等有深刻理解者优先。\n\n4.具备企业培训体系设计经验经验者优先。\n\n岗位亮点\n1.自动驾驶+AI最前沿科技的探索，深入参与科技硬件对生活服务的改变，提升自身价值。 \n\n2.2026年测试团队规模快速增长，发展机会多，建设比见证更值得期待！","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4653662426","sourceKey":"meituan_social","company":"美团","title":"小象超市-商品财务综合分析","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4653662426&jobShareType=1","duty":"1、负责商品财务管理报表体系搭建与迭代，统筹月度经营分析报告的编制与输出，深入解读品类经营进展、识别经营风险并提出改善建议；\n2、围绕品类维度开展深度分析（UE拆解、Price/Mix归因、毛利结构诊断等），为品类策略制定和商品经营决策提供数据支撑；\n3、牵头年度预算编制、滚动预测及定期回顾，推动预算与实际经营的闭环管理；\n4、从成本、费用、定价等多角度挖掘利润优化机会，协同采购、运营等业务团队推动降本增效方案落地；\n5、推动财务分析线上化与数据建设，搭建自动化报表和分析工具，提升团队整体数据处理效率；\n6、追踪零售行业动态，开展有效的行业对标与经营策略研究。","requirements":"1、本科及以上学历，8年以上财务相关工作经验，专业技术过硬；\n2、具备扎实的财务基本功、较强的逻辑思维和数字敏感性，熟练掌握数据处理与分析工具（SQL/AI等）；\n3、善于将复杂数据转化为清晰的业务洞察，具备较强的文字综合表达和汇报呈现能力；\n4、工作责任心强，具备良好的跨部门沟通协调能力，能推动多团队协作达成目标；\n5、较强的学习能力与自驱力，能主动沉淀方法论、优化工作流程；\n6、具备零售/快消行业FP&A、品类分析、咨询等相关经验优先；\n7、具备AI工具应用意识，能借助AI辅助工具（如大模型、智能数据处理工具等）提升数据分析和报告产出效率，有AI+财务数字化项目经验者优先。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1、负责商品财务管理报表体系搭建与迭代，统筹月度经营分析报告的编制与输出，深入解读品类经营进展、识别经营风险并提出改善建议；\n2、围绕品类维度开展深度分析（UE拆解、Price/Mix归因、毛利结构诊断等），为品类策略制定和商品经营决策提供数据支撑；\n3、牵头年度预算编制、滚动预测及定期回顾，推动预算与实际经营的闭环管理；\n4、从成本、费用、定价等多角度挖掘利润优化机会，协同采购、运营等业务团队推动降本增效方案落地；\n5、推动财务分析线上化与数据建设，搭建自动化报表和分析工具，提升团队整体数据处理效率；\n6、追踪零售行业动态，开展有效的行业对标与经营策略研究。\n\n岗位基本要求\n1、本科及以上学历，8年以上财务相关工作经验，专业技术过硬；\n2、具备扎实的财务基本功、较强的逻辑思维和数字敏感性，熟练掌握数据处理与分析工具（SQL/AI等）；\n3、善于将复杂数据转化为清晰的业务洞察，具备较强的文字综合表达和汇报呈现能力；\n4、工作责任心强，具备良好的跨部门沟通协调能力，能推动多团队协作达成目标；\n5、较强的学习能力与自驱力，能主动沉淀方法论、优化工作流程；\n6、具备零售/快消行业FP&A、品类分析、咨询等相关经验优先；\n7、具备AI工具应用意识，能借助AI辅助工具（如大模型、智能数据处理工具等）提升数据分析和报告产出效率，有AI+财务数字化项目经验者优先。\n\n岗位亮点\n1、深度参与商品经营全链条分析，快速建立零售业务全局视角；\n2、直接支持业务决策层的月度经营复盘与战略规划，提升商业洞察力和综合竞争力；\n3、有机会主导财务分析体系线上化建设，兼具业务深度与技术广度的成长空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4411692443","sourceKey":"meituan_social","company":"美团","title":"Partner Management Manager","city":"科威特城","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4411692443&jobShareType=1","duty":"Job Responsibilities: \n1. Responsible for daily communication and relationship maintenance with local logistics partners in Kuwait City to ensure smooth cooperation. \n2. Coordinate and optimize logistics operations to improve overall operational efficiency and service quality. \n3. Monitor partner performance and regularly evaluate and drive improvement measures. \n4. Assist in formulating and executing logistics cooperation strategies to support the company's business development goals. \n5. Deal with abnormal problems in the process of cooperation and coordinate and solve them in a timely manner.","requirements":"1. College degree, logistics, supply chain or related major is preferred. \n2. More than 5 years of work experience in logistics or logistics operations. \n3. Familiar with the logistics market and operation mode in the Middle East, local experience in Kuwait is preferred. \n4. Have good communication and coordination skills and cross-departmental collaboration skills. \n5. Fluent in English, Arabic proficiency is preferred.","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\nJob Responsibilities: \n1. Responsible for daily communication and relationship maintenance with local logistics partners in Kuwait City to ensure smooth cooperation. \n2. Coordinate and optimize logistics operations to improve overall operational efficiency and service quality. \n3. Monitor partner performance and regularly evaluate and drive improvement measures. \n4. Assist in formulating and executing logistics cooperation strategies to support the company's business development goals. \n5. Deal with abnormal problems in the process of cooperation and coordinate and solve them in a timely manner.\n\n岗位基本要求\n1. College degree, logistics, supply chain or related major is preferred. \n2. More than 5 years of work experience in logistics or logistics operations. \n3. Familiar with the logistics market and operation mode in the Middle East, local experience in Kuwait is preferred. \n4. Have good communication and coordination skills and cross-departmental collaboration skills. \n5. Fluent in English, Arabic proficiency is preferred.\n\n岗位亮点\n1. Join a fast-growing international logistics team with a wide range of career development opportunities. \n2. The work location is located in Kuwait City, and you can enjoy competitive compensation and benefits. \n3. Participate in key partner management projects, accumulate high-end customer resources and industry experience. \n4. Flat management model to encourage innovation and initiative. \n5. Provide a complete training system and international work platform.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4692036520","sourceKey":"meituan_social","company":"美团","title":"2027秋招-客服产品运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4692036520&jobShareType=1","duty":"1. System Management: Oversee daily maintenance, configuration, and version updates of customer service systems to ensure stable operations.Improve system efficiency by deploying AI capabilities.​2. Requirement Management: Collect and analyze system requirements from CE-Sites, coordinating with product and R&D teams for feature development and optimization.​3. Data Analysis: Monitor system performance, analyze usage data, and provide recommendations to improve tool efficiency and user experience.​4. Training and Support: Provide system training for the customer service team, develop related manuals and documentation, and offer on-site support when needed.","requirements":"1. Product and System Understanding​​Familiar with common customer service, operations, and project management tools (e.g., Zendesk, Salesforce, Jira, Feishu, WeCom, ServiceNow, etc.)​​Able to understand tool logic, core functions, configuration methods, and permission management mechanisms​​Knowledge and understanding of AI concepts and applications​​2. Data Analysis​​Proficient in SQL, and data visualization tools (e.g., Looker Studio, Power BI)​​Capable of interpreting event tracking data, logs, and reports to analyze tool performance and suggest improvements​​3. Process Design and Optimization​​Skilled in mapping and analyzing business processes, and proposing tool-based improvements​​Familiar with automation thinking and process engines (e.g., N8N, Zapier, Alibaba Cloud RPA, etc.)​​4. Cross-functional Communication and Project Management​​Strong ability to communicate with product managers, engineers, customer service teams, and business stakeholders​​Knowledge of basic project management (e.g., timeline planning, backlog management, milestone tracking)​​5. Tool Training and Adoption​​Experience in promoting and training users on new tools​​Capable of creating training materials, SOPs, and FAQs​​6. User Experience and Feedback Loop​​Skilled at collecting frontline user feedback and turning pain points into actionable solutions​​Familiar with basic user research or survey design​​7. System Configuration and Permission Management​​Hands-on experience with tool configuration, such as setting up IVR flows, ticket routing rules, or custom fields​​Understands user account systems and access control mechanisms","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. System Management: Oversee daily maintenance, configuration, and version updates of customer service systems to ensure stable operations.Improve system efficiency by deploying AI capabilities.​2. Requirement Management: Collect and analyze system requirements from CE-Sites, coordinating with product and R&D teams for feature development and optimization.​3. Data Analysis: Monitor system performance, analyze usage data, and provide recommendations to improve tool efficiency and user experience.​4. Training and Support: Provide system training for the customer service team, develop related manuals and documentation, and offer on-site support when needed.\n\n岗位基本要求\n1. Product and System Understanding​​Familiar with common customer service, operations, and project management tools (e.g., Zendesk, Salesforce, Jira, Feishu, WeCom, ServiceNow, etc.)​​Able to understand tool logic, core functions, configuration methods, and permission management mechanisms​​Knowledge and understanding of AI concepts and applications​​2. Data Analysis​​Proficient in SQL, and data visualization tools (e.g., Looker Studio, Power BI)​​Capable of interpreting event tracking data, logs, and reports to analyze tool performance and suggest improvements​​3. Process Design and Optimization​​Skilled in mapping and analyzing business processes, and proposing tool-based improvements​​Familiar with automation thinking and process engines (e.g., N8N, Zapier, Alibaba Cloud RPA, etc.)​​4. Cross-functional Communication and Project Management​​Strong ability to communicate with product managers, engineers, customer service teams, and business stakeholders​​Knowledge of basic project management (e.g., timeline planning, backlog management, milestone tracking)​​5. Tool Training and Adoption​​Experience in promoting and training users on new tools​​Capable of creating training materials, SOPs, and FAQs​​6. User Experience and Feedback Loop​​Skilled at collecting frontline user feedback and turning pain points into actionable solutions​​Familiar with basic user research or survey design​​7. System Configuration and Permission Management​​Hands-on experience with tool configuration, such as setting up IVR flows, ticket routing rules, or custom fields​​Understands user account systems and access control mechanisms\n\n岗位亮点\nAt Keeta, you'll be part of Meituan's ambitious global expansion journey, witnessing the industry's influence extend from China to the world. You'll gain hands-on experience in navigating global markets and broaden your international perspective.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4692027679","sourceKey":"meituan_social","company":"美团","title":"2027秋招-客服工具运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4692027679&jobShareType=1","duty":"1. Support the development and optimization of customer service products and operations across international markets.​2. Analyze operational data, customer feedback and business insights to identify issues and improvement opportunities.​3. Work closely with Product, Technology and Operations teams to translate business needs into solutions and drive implementation.​4. Monitor key customer service and operational metrics, and support initiatives to improve service quality and operational efficiency.​5. Participate in projects related to customer service automation, AI and process optimization.​6. Conduct market research, competitor analysis and user experience research to support business decisions.​7. Support cross-functional projects and collaborate with stakeholders across different markets.","requirements":"1. Bachelor’s or Master’s degree; majors in Business, Economics, Management, Data Analytics, Computer Science, Engineering, or related fields are preferred.​2. Open to fresh graduates and candidates with 0–2 years of experience.​3. Strong interest in Internet products, customer experience and business operations.​4. Strong analytical, problem-solving and learning capabilities.​5. Good data sensitivity and proficiency in Google Sheets; SQL or data analysis experience is a plus.​6. Strong communication, ownership and cross-functional collaboration skills.​7. Comfortable working in a fast-paced and international environment.​8. Fluent English communication skills; additional languages are a plus.​9. Familiarity with AI/NLP concepts and trends in conversational AI; experience with LLM-based products, chatbot design, or intelligent customer service solutions is a plus.","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. Support the development and optimization of customer service products and operations across international markets.​2. Analyze operational data, customer feedback and business insights to identify issues and improvement opportunities.​3. Work closely with Product, Technology and Operations teams to translate business needs into solutions and drive implementation.​4. Monitor key customer service and operational metrics, and support initiatives to improve service quality and operational efficiency.​5. Participate in projects related to customer service automation, AI and process optimization.​6. Conduct market research, competitor analysis and user experience research to support business decisions.​7. Support cross-functional projects and collaborate with stakeholders across different markets.\n\n岗位基本要求\n1. Bachelor’s or Master’s degree; majors in Business, Economics, Management, Data Analytics, Computer Science, Engineering, or related fields are preferred.​2. Open to fresh graduates and candidates with 0–2 years of experience.​3. Strong interest in Internet products, customer experience and business operations.​4. Strong analytical, problem-solving and learning capabilities.​5. Good data sensitivity and proficiency in Google Sheets; SQL or data analysis experience is a plus.​6. Strong communication, ownership and cross-functional collaboration skills.​7. Comfortable working in a fast-paced and international environment.​8. Fluent English communication skills; additional languages are a plus.​9. Familiarity with AI/NLP concepts and trends in conversational AI; experience with LLM-based products, chatbot design, or intelligent customer service solutions is a plus.\n\n岗位亮点\n1. Global Exposure: Work on customer service products and operations across international markets.​2. Fast Growth: Gain hands-on experience in product and business operations projects from end to end.​3. AI & Technology: Explore the application of AI, automation and emerging technologies in customer service.​4. Cross-functional Experience: Collaborate with Product, Technology and Operations teams and develop a broad understanding of Internet businesses.​5. Data-driven Environment: Use data and customer insights to identify problems and drive real business improvements.​6. Graduate-friendly: We value learning agility, analytical thinking and potential over years of experience.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4723607466","sourceKey":"meituan_social","company":"美团","title":"劳动者管理","city":"上海市/北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4723607466&jobShareType=1","duty":"1.用工风险治理：定期回扫业务风险，设计并落地业务布防动作，降低用工风险发生率\n2.业务风险处置：负责业务风险case的识别、接收、跟进、协调及闭环处理，联动财税法等协同部门制定处理方案，降低业务风险。\n3.响应体系搭建：梳理业务内不同角色响应机制和话术，确保前线能够及时妥善处置不升级外溢用工风险\n劳动者治理：梳理、优化劳动者治理相关规则，结合业务场景完善管理标准，推动规则落地执行，规范劳动者行为，提升治理效率。\n4.合规管理：基于合规要求对业务用工管理方式进行适时调整，确保业务能够在合规框架内运行\n5.基础劳动者管理：参与劳动者基础管理相关规则、制度的梳理、修订及完善，包括但不限于劳动者准入、日常行为规范、考核标准等，确保规则贴合业务实际、符合合规要求。\n6.风控场景管理：梳理识别违规风控场景，协助搭建并优化风控识别规则，监控劳动者违规行为，及时识别违规线索。","requirements":"本科及以上学历，人力资源管理、用工管理、法学等相关专业优先。\n1-3年相关工作经验，有劳动者管理、用户链路优化、权限管理、风控合规、用工风险处理相关经验者优先。\n工作认真负责、严谨细致，有较强的责任心和执行力，能承受一定的工作压力，具备良好的自我调节能力。\n具备一定的风险敏感度，能及时识别用工及风控相关风险，提出合理的防范建议。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1.用工风险治理：定期回扫业务风险，设计并落地业务布防动作，降低用工风险发生率\n2.业务风险处置：负责业务风险case的识别、接收、跟进、协调及闭环处理，联动财税法等协同部门制定处理方案，降低业务风险。\n3.响应体系搭建：梳理业务内不同角色响应机制和话术，确保前线能够及时妥善处置不升级外溢用工风险\n劳动者治理：梳理、优化劳动者治理相关规则，结合业务场景完善管理标准，推动规则落地执行，规范劳动者行为，提升治理效率。\n4.合规管理：基于合规要求对业务用工管理方式进行适时调整，确保业务能够在合规框架内运行\n5.基础劳动者管理：参与劳动者基础管理相关规则、制度的梳理、修订及完善，包括但不限于劳动者准入、日常行为规范、考核标准等，确保规则贴合业务实际、符合合规要求。\n6.风控场景管理：梳理识别违规风控场景，协助搭建并优化风控识别规则，监控劳动者违规行为，及时识别违规线索。\n\n岗位基本要求\n本科及以上学历，人力资源管理、用工管理、法学等相关专业优先。\n1-3年相关工作经验，有劳动者管理、用户链路优化、权限管理、风控合规、用工风险处理相关经验者优先。\n工作认真负责、严谨细致，有较强的责任心和执行力，能承受一定的工作压力，具备良好的自我调节能力。\n具备一定的风险敏感度，能及时识别用工及风控相关风险，提出合理的防范建议。\n\n岗位亮点\n项目前景良好，可拥有广阔的职业和个人的发展空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4735964258","sourceKey":"meituan_social","company":"美团","title":"美团企业版-大客户销售经理（华东）","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4735964258&jobShareType=1","duty":"1.协助销售负责人制定客户画像及行业策略和不同方向的销售机会探索和业务团队管理；\n2.负责开发“用餐、员工福利”等方向的企业客户，制定和主动开拓商机、执行销售计划、完成签约，最终拿到销售结果；\n3.持续提升对企业用餐、员工福利的解决方案的理解和优化，与售前、实施、客户成功团队协作，确保签约客户的顺利上线和最终使用；\n4.为客户的收入和续约负责。","requirements":"1.大学本科及以上学历，3年以上To B销售经验，有成熟的销售打单和客户推动策略和方法，销售基本功扎实；\n2.具备较强的结构化思考与沟通能力、不错的文案撰写和讲解能力，有很强的目标意识和自驱力；\n3.思路清晰，能够准确把握产品优势和客户心理，高效整合内外部资源促进业绩达成；\n4.积极主动，正直诚信。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.协助销售负责人制定客户画像及行业策略和不同方向的销售机会探索和业务团队管理；\n2.负责开发“用餐、员工福利”等方向的企业客户，制定和主动开拓商机、执行销售计划、完成签约，最终拿到销售结果；\n3.持续提升对企业用餐、员工福利的解决方案的理解和优化，与售前、实施、客户成功团队协作，确保签约客户的顺利上线和最终使用；\n4.为客户的收入和续约负责。\n\n岗位基本要求\n1.大学本科及以上学历，3年以上To B销售经验，有成熟的销售打单和客户推动策略和方法，销售基本功扎实；\n2.具备较强的结构化思考与沟通能力、不错的文案撰写和讲解能力，有很强的目标意识和自驱力；\n3.思路清晰，能够准确把握产品优势和客户心理，高效整合内外部资源促进业绩达成；\n4.积极主动，正直诚信。\n\n具备以下条件优先\n有Tob顾问式销售、解决方案销售和SaaS销售曾获得的销冠者或费控销售，有其他企业消费平台销售经验背景的优先；\n曾主导过国央企、金融、零售、科技企业大型SaaS项目销售背景者优先。\n\n岗位亮点\n1.【新业务】美团内部孵化的、专门面向企业市场的To B业务。我们为“企业公务消费管理”提供一站式SaaS服务，涵盖企业用餐、报销费控等多个领域（这些领域已经在服务美团自身）。我们帮助企业实现公务消费线上化，助力企业降本增效，帮助员工告别线下报销；\n2.【空间大】公务消费有数万亿的大盘，有足够的想象力；该业务会涉及外卖、到店餐饮等业务类型，能给大家提供足够的学习成长空间；\n3.【有盼头】To B的大势刚刚开始，依托于美团过去10年的积累，依托于对美团自身服务的积累，我们认为很有机会把业务做大做成；\n4.【氛围好】务实求真，创业氛围；人际简单，组织扁平。这是一个巨大的机会，也需要长期的耐心；To B星辰大海，征程期待有你。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4735917214","sourceKey":"meituan_social","company":"美团","title":"水产运输主管","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4735917214&jobShareType=1","duty":"1. 承运商与车辆管理：负责合作车辆、承运商日常管理，包含系统维护、车辆安全检查、司机培训、KPI考核及各类运输异常问题处理。\n2. 排班派车与线路统筹：根据每日货量合理规划运输线路、完成派车调度，整理司机单据，保障每日运输有序落地。\n3. 现场运输管控：开展每日车队晨会、车辆安全巡检、运输环境标准核查，落实现场标准化管理。\n4. 运输节点把控：全程跟进供应商到货、上货、发车进度，严格把控各时间节点，保障链路时效。\n5. 到站交接合规管理：监督车辆到站交接流程合规性，快速处理交接环节出现的异常问题。\n6. 在途与末端巡检：负责车辆在途跟踪、尾站巡车、封签检查，不定期跟车核查链路问题，排查司机违规操作。\n7. 跨部门协同：联动各横向业务部门，高效解决运输链路卡点、异常故障，保障业务顺畅运转。\n8. 数据复盘与整改：按日、周、月维度统计运营数据，梳理不达标问题，输出整改方案并落地闭环。\n9. 服从团队管理：接受公司出差、异地调动、班次轮岗等工作安排，完成上级交办的其他工作。","requirements":"1. 经验要求：具备3年及以上城配/运输运营管理经验，有水产冷链运输经验优先，非硬性要求。\n2. 管理能力：可独立管理10人左右劳务车队团队，具备现场带队、人员统筹、现场管控能力。\n3. 综合素养：沟通能力强，擅长处理各类突发异常事件，责任心强、承压能力突出。\n4. 技能要求：熟练使用各类办公软件，具备数据整理、复盘分析、方案输出能力。\n5. 工作态度：吃苦耐劳、主动上进，服从排班轮岗安排，适配多班次工作节奏。\n6. 工作地点：杭州市萧山区，接受多时段轮岗，每日在岗9小时。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 承运商与车辆管理：负责合作车辆、承运商日常管理，包含系统维护、车辆安全检查、司机培训、KPI考核及各类运输异常问题处理。\n2. 排班派车与线路统筹：根据每日货量合理规划运输线路、完成派车调度，整理司机单据，保障每日运输有序落地。\n3. 现场运输管控：开展每日车队晨会、车辆安全巡检、运输环境标准核查，落实现场标准化管理。\n4. 运输节点把控：全程跟进供应商到货、上货、发车进度，严格把控各时间节点，保障链路时效。\n5. 到站交接合规管理：监督车辆到站交接流程合规性，快速处理交接环节出现的异常问题。\n6. 在途与末端巡检：负责车辆在途跟踪、尾站巡车、封签检查，不定期跟车核查链路问题，排查司机违规操作。\n7. 跨部门协同：联动各横向业务部门，高效解决运输链路卡点、异常故障，保障业务顺畅运转。\n8. 数据复盘与整改：按日、周、月维度统计运营数据，梳理不达标问题，输出整改方案并落地闭环。\n9. 服从团队管理：接受公司出差、异地调动、班次轮岗等工作安排，完成上级交办的其他工作。\n\n岗位基本要求\n1. 经验要求：具备3年及以上城配/运输运营管理经验，有水产冷链运输经验优先，非硬性要求。\n2. 管理能力：可独立管理10人左右劳务车队团队，具备现场带队、人员统筹、现场管控能力。\n3. 综合素养：沟通能力强，擅长处理各类突发异常事件，责任心强、承压能力突出。\n4. 技能要求：熟练使用各类办公软件，具备数据整理、复盘分析、方案输出能力。\n5. 工作态度：吃苦耐劳、主动上进，服从排班轮岗安排，适配多班次工作节奏。\n6. 工作地点：杭州市萧山区，接受多时段轮岗，每日在岗9小时。\n\n具备以下条件优先\n1. 有水产冷链运输管理实操经验；\n2. 具备承运商、车队管理及运输异常处置实战经验；\n3. 熟悉多班次现场调度，可接受轮岗；\n4. 具备数据分析、问题整改闭环能力；\n5. 有异地调动经历，人员稳定性强。\n\n岗位亮点\n1. 业务体系成熟：负责完整的城配运输链路管理，从派车、现场、在途、末端、复盘全流程锻炼，成长维度全面。\n2. 管理权限独立：直管10人劳务团队，独立负责车辆、司机、承运商考核管理，锻炼现场统筹与团队管理能力。\n3. 发展空间灵活：支持异地调动、多仓轮岗，接触多区域运营模式，积累多城市水产物流运营经验。\n4. 工作内容扎实：兼顾现场实操、数据复盘、异常攻坚，能力提升快，岗位含金量高。\n5. 准入门槛友好：水产经验不做硬性强制，优秀运输管理经验者均可适配，包容性强。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4734741429","sourceKey":"meituan_social","company":"美团","title":"闪购-品牌-精准广告产品运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4734741429&jobShareType=1","duty":"职责：负责品牌精准广告销售策略的生产到落地，推进重点品类及重点客户开拓，为重点品类精准广告收入目标负责。 1、了解品类/行业政策等宏观形势，深入思考内外部变化的影响，识别业务风险和机会方向，分析对手潜在竞争/策略，定期输出品类策略建议；\n2、围绕品类需求和痛点找到相应解法，如活动节点/新流量/新能力，设计出一套可行的运转方案，并沉淀行业通案解决策略，将资源抓手运营到卖进中；\n3、主动跟销售/策划/产品/运营/商分等多角色多职能协作推进新模式/新产品/新策略的试点/扩量推全/优化迭代；\n4、在产品迭代上能够同时具有业务视角和产品视角，帮助判断产品形态推进的优先级。","requirements":"1、3年以上互联网商业分析、经营分析经验，有水饮、酒水、乳品、休闲食品行业分析经验者优先； \n2、数据分析能力：要求对数据有敏感性，逻辑清晰，业务理解力强，能够从数据中获得业务洞察，并形成明确的业务观点，掌握数据分析工具，能够独立完整实现分析闭环； \n3、熟悉互联网和广告产品实施流程，有产品视角。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n职责：负责品牌精准广告销售策略的生产到落地，推进重点品类及重点客户开拓，为重点品类精准广告收入目标负责。 1、了解品类/行业政策等宏观形势，深入思考内外部变化的影响，识别业务风险和机会方向，分析对手潜在竞争/策略，定期输出品类策略建议；\n2、围绕品类需求和痛点找到相应解法，如活动节点/新流量/新能力，设计出一套可行的运转方案，并沉淀行业通案解决策略，将资源抓手运营到卖进中；\n3、主动跟销售/策划/产品/运营/商分等多角色多职能协作推进新模式/新产品/新策略的试点/扩量推全/优化迭代；\n4、在产品迭代上能够同时具有业务视角和产品视角，帮助判断产品形态推进的优先级。\n\n岗位基本要求\n1、3年以上互联网商业分析、经营分析经验，有水饮、酒水、乳品、休闲食品行业分析经验者优先； \n2、数据分析能力：要求对数据有敏感性，逻辑清晰，业务理解力强，能够从数据中获得业务洞察，并形成明确的业务观点，掌握数据分析工具，能够独立完整实现分析闭环； \n3、熟悉互联网和广告产品实施流程，有产品视角。\n\n岗位亮点\n能与行业头部品牌共创即时零售生意增长模型，拥有更广阔的各零售品类的行业视角，接触一手的消费者行业洞察，通过这些积累对未来个人发展有更强的职业竞争力和更广的职业选择空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4240991239","sourceKey":"meituan_social","company":"美团","title":"供应商管理","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4240991239&jobShareType=1","duty":"1、负责供应商周期性绩效考核计划，并执行具体的评估和稽核工作，确保供应商的持续改进和优质服务；\n\n2、负责供应商履约管理与投诉管理，核实投诉与履约问题，督促问题整改、执行处罚； \n\n3、负责建立供应商质量体系并落实、追踪，监督供应商产品质量，建立质量数据库，保证产品质量稳定性；\n\n4、负责供应商库存管理，确保项目交付时效，有效管理库存数量，推动产品及时换新；\n\n5、与公司各部门配合，及时处理客户/各部门的反馈、投诉和建议，提高服务满意度。","requirements":"1、本科及以上学历；\n\n2、5年以上供应商管理经验； \n\n3、具备良好的数据统计分析能力、逻辑推理能力和问题解决能力，坚守原则；\n\n4、团队协作能力强，能与团队成员默契合作，善于学习与思考，执行力强；","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1、负责供应商周期性绩效考核计划，并执行具体的评估和稽核工作，确保供应商的持续改进和优质服务；\n\n2、负责供应商履约管理与投诉管理，核实投诉与履约问题，督促问题整改、执行处罚； \n\n3、负责建立供应商质量体系并落实、追踪，监督供应商产品质量，建立质量数据库，保证产品质量稳定性；\n\n4、负责供应商库存管理，确保项目交付时效，有效管理库存数量，推动产品及时换新；\n\n5、与公司各部门配合，及时处理客户/各部门的反馈、投诉和建议，提高服务满意度。\n\n岗位基本要求\n1、本科及以上学历；\n\n2、5年以上供应商管理经验； \n\n3、具备良好的数据统计分析能力、逻辑推理能力和问题解决能力，坚守原则；\n\n4、团队协作能力强，能与团队成员默契合作，善于学习与思考，执行力强；\n\n岗位亮点\n覆盖多品类供应商管理，接触不同行业液态，发展深度增加。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4152628788","sourceKey":"meituan_social","company":"美团","title":"核心本地商业外卖业务内控BP","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4152628788&jobShareType=1","duty":"1. 负责核心本地商业外卖业务的内控体系建设与优化， 根据外卖业务重点及风险评估情况，制定工作计划。\n2. 深入业务一线，与业务团队协作，识别关键风险点并制定相应控制措施，推动内控流程落地执行，降低业务风险并提升运营效率。\n3. 根据业务管理全景，从制度体系、流程机制、权限管理、监控机制等方面提升业务整体管控水平，通过数字化手段持续监控风险水位变化。\n4. 对各重点业务领域开展风险摸牌，业务建立良好的沟通和协作关系 ，识别重大风险和量化影响，深度挖掘根因并落地治理措施，通过建立可落地的风险监控指标持续监督，对发现的风险制定改进方案，并跟踪完成整改。","requirements":"1. 大学本科及以上学历。  \n2. 具备5年以上内控、内审、风险管理、管理咨询等相关工作经验，有本地生活、餐饮或互联网平台业务背景者优先。  \n3. 熟悉企业内部控制框架及合规管理要求，具备较强的风险识别与分析能力。  \n4. 具备良好的沟通协调能力与跨部门协作经验，能推动复杂项目落地。  \n5. 熟练掌握SQL数据分析。\n6.具备AI思维与工具应用能力，能将AI能力主动引入风险识别、数据分析、治理措施等内控日常工作场景中，持续进行AI应用探索与落地。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1. 负责核心本地商业外卖业务的内控体系建设与优化， 根据外卖业务重点及风险评估情况，制定工作计划。\n2. 深入业务一线，与业务团队协作，识别关键风险点并制定相应控制措施，推动内控流程落地执行，降低业务风险并提升运营效率。\n3. 根据业务管理全景，从制度体系、流程机制、权限管理、监控机制等方面提升业务整体管控水平，通过数字化手段持续监控风险水位变化。\n4. 对各重点业务领域开展风险摸牌，业务建立良好的沟通和协作关系 ，识别重大风险和量化影响，深度挖掘根因并落地治理措施，通过建立可落地的风险监控指标持续监督，对发现的风险制定改进方案，并跟踪完成整改。\n\n岗位基本要求\n1. 大学本科及以上学历。  \n2. 具备5年以上内控、内审、风险管理、管理咨询等相关工作经验，有本地生活、餐饮或互联网平台业务背景者优先。  \n3. 熟悉企业内部控制框架及合规管理要求，具备较强的风险识别与分析能力。  \n4. 具备良好的沟通协调能力与跨部门协作经验，能推动复杂项目落地。  \n5. 熟练掌握SQL数据分析。\n6.具备AI思维与工具应用能力，能将AI能力主动引入风险识别、数据分析、治理措施等内控日常工作场景中，持续进行AI应用探索与落地。\n\n具备以下条件优先\n有互联网内控实践经验的优先；CPA、CIA、CISA等优先。\n\n岗位亮点\n头部互联网公司的公司层面内控团队，能博采各家所长，让专业技能更加精进，成长发展空间大，内部发展前景佳；能深入了解业务、行业，掌握业务规律和本质；公司提供内外多元化学习交流的机会，与优秀团队探索共创，共同成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4674477972","sourceKey":"meituan_social","company":"美团","title":"Keeta-履约产品运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4674477972&jobShareType=1","duty":"1. 负责keeta履约产品的运营策略制定与执行，提升产品使用效率与用户满意度。  \n2. 深入理解业务场景，协同产品、技术团队优化系统功能，推动产品迭代与落地。  \n3. 通过数据分析与用户反馈，挖掘产品使用痛点，提出运营优化方案并推动改进。  \n4. 设计并落地培训体系，提升业务团队对工具的理解与使用能力。  \n5. 监控核心指标，定期输出运营分析报告，为产品优化提供数据支持。\n6. 利用AI建设白皮书、智能培训、自主化答疑工具等，提高组织效率。","requirements":"1. 大学本科及以上学历，3年以上工具产品运营或系统运营相关经验。  \n2. 具备较强的数据分析能力，熟练使用数据分析工具，能通过数据驱动运营决策。  \n3. 熟悉B端或工具型产品运营逻辑，有履约、供应链、出行等行业背景者优先。  \n4. 优秀的跨团队协作能力，能高效推动产品、技术、业务等多方合作。  \n5. 逻辑清晰，责任心强，具备较强的项目管理和问题解决能力。\n6. 有AI实践并成功落地应用经验。\n7.英语能力强，可以做日常办公语言","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. 负责keeta履约产品的运营策略制定与执行，提升产品使用效率与用户满意度。  \n2. 深入理解业务场景，协同产品、技术团队优化系统功能，推动产品迭代与落地。  \n3. 通过数据分析与用户反馈，挖掘产品使用痛点，提出运营优化方案并推动改进。  \n4. 设计并落地培训体系，提升业务团队对工具的理解与使用能力。  \n5. 监控核心指标，定期输出运营分析报告，为产品优化提供数据支持。\n6. 利用AI建设白皮书、智能培训、自主化答疑工具等，提高组织效率。\n\n岗位基本要求\n1. 大学本科及以上学历，3年以上工具产品运营或系统运营相关经验。  \n2. 具备较强的数据分析能力，熟练使用数据分析工具，能通过数据驱动运营决策。  \n3. 熟悉B端或工具型产品运营逻辑，有履约、供应链、出行等行业背景者优先。  \n4. 优秀的跨团队协作能力，能高效推动产品、技术、业务等多方合作。  \n5. 逻辑清晰，责任心强，具备较强的项目管理和问题解决能力。\n6. 有AI实践并成功落地应用经验。\n7.英语能力强，可以做日常办公语言\n\n岗位亮点\n1. 深度参与核心产品的运营\n2. 国际化视野\n3. 公司内部 AI 工具完善（CatPaw/美境/NoCode 等），鼓励用 AI 替代重复劳动","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3643663856","sourceKey":"meituan_social","company":"美团","title":"自有品牌品质管理","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3643663856&jobShareType=1","duty":"1.负责自有品牌商品的品质管理工作，包括商品设计、生产、供应链管理等环节。\n2.制定并执行品质管理标准和流程，确保产品符合公司要求和客户期望。\n3.负责协调与供应商、生产工厂等相关方沟通，解决品质问题和提升产品品质。\n4.监控产品质量数据，分析问题原因并提出改进措施，提高产品品质水平。","requirements":"1.大学本科及以上学历，专业不限，有相关专业背景者优先。\n2.至少5年以上商品与供应链管理或品质管理相关工作经验，有自有品牌管理经验者优先。\n3.具备较强的沟通协调能力、问题分析能力和团队管理能力。\n4.熟悉商品生产流程、品质管理标准和相关法律法规。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.负责自有品牌商品的品质管理工作，包括商品设计、生产、供应链管理等环节。\n2.制定并执行品质管理标准和流程，确保产品符合公司要求和客户期望。\n3.负责协调与供应商、生产工厂等相关方沟通，解决品质问题和提升产品品质。\n4.监控产品质量数据，分析问题原因并提出改进措施，提高产品品质水平。\n\n岗位基本要求\n1.大学本科及以上学历，专业不限，有相关专业背景者优先。\n2.至少5年以上商品与供应链管理或品质管理相关工作经验，有自有品牌管理经验者优先。\n3.具备较强的沟通协调能力、问题分析能力和团队管理能力。\n4.熟悉商品生产流程、品质管理标准和相关法律法规。\n\n岗位亮点\n1.薪资福利优厚，提供广阔的发展空间和良好的职业发展平台。\n2.可与跨部门团队紧密合作，拓展行业人脉和经验。\n3.在公司自有品牌管理领域有着丰富的经验积累和发展机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4630698953","sourceKey":"meituan_social","company":"美团","title":"AI信贷策略专家","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4630698953&jobShareType=1","duty":"智能决策： 深度洞察美团生态业务，结合AI能力，主导信贷产品准入、额度、定价等核心风险策略的迭代优化，推动策略向“智能生成”转型。\n模型共建： 与算法、模型团队紧密协作，参与从特征工程到模型选择的全过程，并重点负责推动AI/ML模型在风险策略中的应用落地、效果评估与反馈优化。\n数据驱动： 建立数据驱动的策略监控与评估体系，并探索借助AI工具提升归因分析效率，敏锐发现潜在风险与业务机会，快速定位问题并驱动解决方案落地。\n系统落地： 与产品、研发团队高效协作，将智能化的风控策略与逻辑，清晰、准确地转化为产品需求，并跟进系统功能的顺利上线与稳定运行。","requirements":"AI能力要求： 对AI技术有浓厚兴趣和探索欲；具备使用Prompt Engineering优化工作流的经验，能将AI工具实际应用于数据分析、策略挖掘或报告撰写等场景；对RAG、Agent等AI应用框架有基本认知者优先。\n专业经验： 3年及以上金融机构（银行、头部互联网金融、消费金融公司等）信贷风险管理经验，熟悉信贷全生命周期的风控策略体系。\n核心能力： 卓越的逻辑思维能力与数据敏感性，能够从复杂数据中提炼商业洞察；精通SQL，熟练掌握Python/R等至少一种数据分析工具。\n软性素质： 强烈的自驱力与责任心，对业务结果负责；具备出色的沟通协作能力，能够适应快速变化的业务节奏。","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n智能决策： 深度洞察美团生态业务，结合AI能力，主导信贷产品准入、额度、定价等核心风险策略的迭代优化，推动策略向“智能生成”转型。\n模型共建： 与算法、模型团队紧密协作，参与从特征工程到模型选择的全过程，并重点负责推动AI/ML模型在风险策略中的应用落地、效果评估与反馈优化。\n数据驱动： 建立数据驱动的策略监控与评估体系，并探索借助AI工具提升归因分析效率，敏锐发现潜在风险与业务机会，快速定位问题并驱动解决方案落地。\n系统落地： 与产品、研发团队高效协作，将智能化的风控策略与逻辑，清晰、准确地转化为产品需求，并跟进系统功能的顺利上线与稳定运行。\n\n岗位基本要求\nAI能力要求： 对AI技术有浓厚兴趣和探索欲；具备使用Prompt Engineering优化工作流的经验，能将AI工具实际应用于数据分析、策略挖掘或报告撰写等场景；对RAG、Agent等AI应用框架有基本认知者优先。\n专业经验： 3年及以上金融机构（银行、头部互联网金融、消费金融公司等）信贷风险管理经验，熟悉信贷全生命周期的风控策略体系。\n核心能力： 卓越的逻辑思维能力与数据敏感性，能够从复杂数据中提炼商业洞察；精通SQL，熟练掌握Python/R等至少一种数据分析工具。\n软性素质： 强烈的自驱力与责任心，对业务结果负责；具备出色的沟通协作能力，能够适应快速变化的业务节奏。\n\n岗位亮点\nAI机会：有机会深度参与并主导大模型等前沿AI技术，在万亿级交易规模场景下的风控应用落地，重构建智能决策体系，这是业内极具稀缺性和前瞻性的实践机会。\n成长与资源： 我们提供扁平化的沟通氛围和结果导向的文化，你的优秀想法可以快速被验证和落地。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4717478661","sourceKey":"meituan_social","company":"美团","title":"AI Builder（智能学习方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4717478661&jobShareType=1","duty":"1. 以 AI native 的视角重新审视学习发展领域的全链路工作——需求诊断、方案设计、内容生产、交付运营、效果评估——识别哪些环节应该被 AI 重构、哪些应该被彻底重新定义，而不仅是「提效」；\n2. 端到端负责智能学习方向的体系搭建与落地：从场景洞察、方案设计、原型验证到规模化推广，构建可复用的 AI 学习解决方案（如 AI 学习内容生产体系、个性化学习 Agent、智能陪练与教练、学习数据洞察等）；\n3. 主导 AI native 学习工作方法的设计与沉淀，将 prompt 工程、Agent 编排、知识库建设等能力转化为组织可复制的方法论和工具，赋能 HRBP、培训运营等角色转型；\n4. 搭建学习效果度量与数据闭环，用数据验证 AI 重构带来的价值（效率、体验、学习效果），驱动持续迭代；\n5. 与 HR 团队、业务团队、技术团队深度协作，推动智能学习方案在组织内规模化落地，并跟踪业界 AI 与学习发展融合的前沿实践，持续引入创新。","requirements":"1. 本科及以上学历，5 年以上工作经验，在 AI 应用、学习发展（L&D）、组织发展（OD）或相关领域有体系化的专业积累；\n2. 具备真正的大模型应用实战经验：熟悉 Prompt Engineering、Agent 编排、RAG 知识库、工作流自动化等，能独立完成从想法到可用原型的构建，而非仅停留在概念层面；\n3. 具备领域重构的能力与视野：不是在现有流程上叠加 AI，而是能从第1性原理出发，重新设计 AI 时代的学习发展工作方式，并有推动组织接受和采纳新范式的领导力；\n4. 有优秀的体系化思考与抽象能力，能把点状实践沉淀为可复制、可规模化的方法论和产品化工具；\n5. 强自驱力与好奇心，享受在模糊地带定义问题、快速验证、用数据说话的工作方式；\n6. 良好的沟通与跨界协作能力，能在 HR、业务、技术三种语言体系间自如切换。","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n1. 以 AI native 的视角重新审视学习发展领域的全链路工作——需求诊断、方案设计、内容生产、交付运营、效果评估——识别哪些环节应该被 AI 重构、哪些应该被彻底重新定义，而不仅是「提效」；\n2. 端到端负责智能学习方向的体系搭建与落地：从场景洞察、方案设计、原型验证到规模化推广，构建可复用的 AI 学习解决方案（如 AI 学习内容生产体系、个性化学习 Agent、智能陪练与教练、学习数据洞察等）；\n3. 主导 AI native 学习工作方法的设计与沉淀，将 prompt 工程、Agent 编排、知识库建设等能力转化为组织可复制的方法论和工具，赋能 HRBP、培训运营等角色转型；\n4. 搭建学习效果度量与数据闭环，用数据验证 AI 重构带来的价值（效率、体验、学习效果），驱动持续迭代；\n5. 与 HR 团队、业务团队、技术团队深度协作，推动智能学习方案在组织内规模化落地，并跟踪业界 AI 与学习发展融合的前沿实践，持续引入创新。\n\n岗位基本要求\n1. 本科及以上学历，5 年以上工作经验，在 AI 应用、学习发展（L&D）、组织发展（OD）或相关领域有体系化的专业积累；\n2. 具备真正的大模型应用实战经验：熟悉 Prompt Engineering、Agent 编排、RAG 知识库、工作流自动化等，能独立完成从想法到可用原型的构建，而非仅停留在概念层面；\n3. 具备领域重构的能力与视野：不是在现有流程上叠加 AI，而是能从第1性原理出发，重新设计 AI 时代的学习发展工作方式，并有推动组织接受和采纳新范式的领导力；\n4. 有优秀的体系化思考与抽象能力，能把点状实践沉淀为可复制、可规模化的方法论和产品化工具；\n5. 强自驱力与好奇心，享受在模糊地带定义问题、快速验证、用数据说话的工作方式；\n6. 良好的沟通与跨界协作能力，能在 HR、业务、技术三种语言体系间自如切换。\n\n具备以下条件优先\n1. 有用 AI 重构一个完整业务领域的成功案例（不限于学习发展）；\n2. 熟悉学习科学、成人学习理论、721 法则、教练技术等 L&D 专业方法，并能思考其在 AI 时代的演化；\n3. 有 Agent 平台、低代码平台、内部工具产品的建设经验；\n4. 有推动组织级变革（change management）的经验。\n\n岗位亮点\n1. 站在 AI 重构组织的最前沿： 这不是在既有流程上「+AI」的优化岗，而是用 AI native 的方式重新定义学习发展工作范式的开创性岗位——你的工作成果将直接塑造组织在 AI 时代的学习与人才发展模式；\n2. 端到端的主人翁空间： 从场景洞察、方案设计到规模化落地全链路负责，没有历史包袱，从零到一构建智能学习体系，享有充分的决策权与资源支持；\n3. 真实场景 + 真实用户 + 真实影响： 面向组织内数万员工的学习发展需求，你的每一次迭代都能获得真实反馈与规模化验证，效果可度量、价值可量化；\n4. 跨界融合的稀缺舞台： 同时深耕 AI 前沿应用与学习发展专业领域，与 HR、业务、技术多方深度协作，成为既懂 AI 又懂组织的复合型专家，这是未来十年最稀缺的职业护城河。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4730014568","sourceKey":"meituan_social","company":"美团","title":"小象超市-训练运营专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4730014568&jobShareType=1","duty":"1、搭建知识管理体系，推进知识管理平台建设实现标准按岗位分类沉淀与版本管理，维护标准档案追踪各环节时间节点保障训练节奏可控；\n2、梳理训练全链路系统需求，推动培训项目管理、演练单、检核、标签、认证五大系统功能完善与迭代；\n3、设计运营训练数据看板，输出学习完成率、认证覆盖率、训练员配比等核心指标。推进PDA自助演练等数字化工具岗位覆盖，建立训练数据线上化机制；\n4、设计能力认证体系，组织鉴定官选拔与培训，建立校准机制统一打分标准。统筹全国认证进度与产能预测，按岗位/区域拆解目标，识别产能缺口推动资源补位；\n5、设计带教标准与流程，统一训练四步骤（准备-呈现-试做-追踪），关键环节强制留痕。推动新人带训标准化。","requirements":"1、5年以上连锁零售/餐饮行业训练体系搭建、知识管理或培训运营经验，前置仓/便利店/快餐背景优先。\n2、熟悉SOC鉴定、训练四步骤、标准化教学包开发方法论，了解培训系统与数据看板产品逻辑。\n3、具备将复杂业务标准拆解为结构化知识的能力，能同时与标准组、BP、产品/研发、业务运营多方对话。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、搭建知识管理体系，推进知识管理平台建设实现标准按岗位分类沉淀与版本管理，维护标准档案追踪各环节时间节点保障训练节奏可控；\n2、梳理训练全链路系统需求，推动培训项目管理、演练单、检核、标签、认证五大系统功能完善与迭代；\n3、设计运营训练数据看板，输出学习完成率、认证覆盖率、训练员配比等核心指标。推进PDA自助演练等数字化工具岗位覆盖，建立训练数据线上化机制；\n4、设计能力认证体系，组织鉴定官选拔与培训，建立校准机制统一打分标准。统筹全国认证进度与产能预测，按岗位/区域拆解目标，识别产能缺口推动资源补位；\n5、设计带教标准与流程，统一训练四步骤（准备-呈现-试做-追踪），关键环节强制留痕。推动新人带训标准化。\n\n岗位基本要求\n1、5年以上连锁零售/餐饮行业训练体系搭建、知识管理或培训运营经验，前置仓/便利店/快餐背景优先。\n2、熟悉SOC鉴定、训练四步骤、标准化教学包开发方法论，了解培训系统与数据看板产品逻辑。\n3、具备将复杂业务标准拆解为结构化知识的能力，能同时与标准组、BP、产品/研发、业务运营多方对话。\n\n岗位亮点\n① 建设期非维护期——从0到1搭建训练体系底层基础设施，产出直接复制全国。\n\n② 训练正从成本中心变成业务杠杆，中台是放大器——通过系统化和标准化提升BP落地效率，直接支撑业务规模化复制。\n\n③ 跨职能视角——同时对接标准组、大区BP、产品/研发，建立训练全链路完整认知，职业成长复利极高。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4618934489","sourceKey":"meituan_social","company":"美团","title":"Keeta-商家管理（Merchant operation）","city":"圣保罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4618934489&jobShareType=1","duty":"1.负责制定与优化商管理全链路策略，包括但不限于商招募、准入审核标准、分级分类、汰换机制等，建立完善的商生命周期管理体系。\n2.搭建并持续优化商考核评估体系，定期进行商绩效评估与质量审核，对不符合平台发展要求的商执行预警、辅导及汰换，推动商持续改进。\n3.负责商管理相关预算的编制、管控与效果评估，建立预算与考核联动的资源分配机制，确保投入产出比最优化。。\n4.处理商相关投诉与异常事件，组织根因分析并推动闭环整改；收集并反馈商侧需求与痛点，协同内外部资源推动解决，提升商满意度和忠诚度。\n5.定期输出商质量与绩效分析报告，为业务决策提供数据支持；推动商培训与能力提升项目，提升整体商质量水平。","requirements":"1.大学本科及以上学历，5年以上零售、供应链或平台运营相关工作经验。\n2.具备商管理经验，熟悉商准入、运营、考核、汰换的全流程，有完整绩效考核与预算管理实操经验者优先。\n3.具备较强的数据分析能力与逻辑策略规划能力，能独立完成考核方案与预算方案的制定、推行与效果评估。\n4.工作责任心强，具备良好的沟通协调能力、问题分析能力及跨部门协作能力。\n5.有0到1搭建商管理体系或重要规则制定经验者优先。\n6.英语流利者优先。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1.负责制定与优化商管理全链路策略，包括但不限于商招募、准入审核标准、分级分类、汰换机制等，建立完善的商生命周期管理体系。\n2.搭建并持续优化商考核评估体系，定期进行商绩效评估与质量审核，对不符合平台发展要求的商执行预警、辅导及汰换，推动商持续改进。\n3.负责商管理相关预算的编制、管控与效果评估，建立预算与考核联动的资源分配机制，确保投入产出比最优化。。\n4.处理商相关投诉与异常事件，组织根因分析并推动闭环整改；收集并反馈商侧需求与痛点，协同内外部资源推动解决，提升商满意度和忠诚度。\n5.定期输出商质量与绩效分析报告，为业务决策提供数据支持；推动商培训与能力提升项目，提升整体商质量水平。\n\n岗位基本要求\n1.大学本科及以上学历，5年以上零售、供应链或平台运营相关工作经验。\n2.具备商管理经验，熟悉商准入、运营、考核、汰换的全流程，有完整绩效考核与预算管理实操经验者优先。\n3.具备较强的数据分析能力与逻辑策略规划能力，能独立完成考核方案与预算方案的制定、推行与效果评估。\n4.工作责任心强，具备良好的沟通协调能力、问题分析能力及跨部门协作能力。\n5.有0到1搭建商管理体系或重要规则制定经验者优先。\n6.英语流利者优先。\n\n岗位亮点\n1.直接主导商考核体系与预算管控的设计与落地，对商生态质量有全局影响力。\n2.覆盖商管全链路，从准入到汰换全流程参与，兼具策略制定与执行落地双重锻炼，能力成长空间大。\n3.岗位处于业务关键节点，分析报告与策略输出直接影响业务决策，个人价值体现充分。\n4.业务处于0-1的体系建设与优化阶段，发挥空间充足。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4677345093","sourceKey":"meituan_social","company":"美团","title":"无人机-资深商业分析师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4677345093&jobShareType=1","duty":"1. 负责重点业务经营分析与策略支持：面向无人机即时配送及相关创新业务，搭建核心经营指标体系，持续识别业务增长、效率、成本与用户体验中的关键问题，形成可落地的策略建议并推动闭环。\n\n2. 牵头复杂专项与关键项目交付：独立负责跨团队、高复杂度的分析项目，包括但不限于业务规划、增长策略、经营诊断、成本效率、商业模式与新区域/新场景评估；能够从模糊问题中提炼关键假设，推动结果落地。\n\n3. 推动商业分析 AI 化与能力沉淀：探索并落地 AI、智能体、自动化分析等技术在经营分析中的应用，建设可复用的分析工具、数据产品、知识库与工作流，提升团队分析效率和决策质量。\n\n4. 研究前沿技术及创新业务的商业化机会：围绕低空经济、即时零售等方向开展行业研究与商业判断，结合公司业务基础识别可验证机会，支持试点设计、资源投入和战略决策。\n\n5. 建设团队方法论并培养人才：沉淀经营分析的方法论、项目管理机制和高质量交付标准；在重点项目中带领团队成员成长，提升团队独立思考、业务判断和跨部门协同能力。","requirements":"1. 5–8 年及以上互联网经营分析、商业策略、咨询、投资研究或新业务战略相关经验；有即时零售、物流履约、供应链、平台业务或本地生活经验者优先。\n\n2. 具备扎实的经营分析与商业判断能力，能够将复杂、模糊的业务问题拆解为清晰的分析框架、关键假设和行动方案；不止能“取数做分析”，更能推动业务决策和结果落地。\n\n3. 有独立负责复杂项目的经历，能够协调产品、运营、算法、财务、业务等多方资源；具备较强的项目 owner 意识。\n\n4. 对 AI、数据产品、智能体或分析自动化有实际应用经验或强烈兴趣，能够理解技术能力边界，并转化为业务场景与组织能力。\n\n5. 对低空经济、具身智能等前沿技术及其商业化有持续关注和思考；能够在高不确定性环境下形成独立观点，并通过小步试验验证假设。\n\n6. 有团队管理、项目带教或方法论建设经验者优先。","description":"部门介绍\n为了更好地提升城市即时配送的效率与体验，2017年，美团启动了无人机配送服务的探索，通过科技创新推动履约工具变革，加快建设空地协同的本地即时配送网络。\n在过去的六年里，美团无人机完成了飞行器、自动化机场及智能调度系统的研发工作，实现了研发设计、生产制造、运营运维全链条布局，达成了城市复杂场景物流无人机高频次、高密度、多天时、多天侯运行。\n2023年7月，美团无人机在上海发布了自主研发的第四代无人机，跟此前机型相比，新机型升级了环境适应能力，可在“零下20度至50度”的中雨、中雪、6级风、弱光等环境中稳定飞行，能够适应97%以上国内城市的自然环境要求。\n截至2024年12月，美团无人机已在深圳、北京、上海、广州、南京、迪拜等城市开通53条航线，并累计完成订单超40万单。即时零售配送服务覆盖了办公、社区、景区、市政公园、校园、医疗、图书馆等多种场景。在医疗场景中，美团无人机可围绕医疗血液、检验样本、院前急救物资、特殊药品等医疗物资配送需求建设端到端的全天时急送网络。\n\n岗位职责\n1. 负责重点业务经营分析与策略支持：面向无人机即时配送及相关创新业务，搭建核心经营指标体系，持续识别业务增长、效率、成本与用户体验中的关键问题，形成可落地的策略建议并推动闭环。\n\n2. 牵头复杂专项与关键项目交付：独立负责跨团队、高复杂度的分析项目，包括但不限于业务规划、增长策略、经营诊断、成本效率、商业模式与新区域/新场景评估；能够从模糊问题中提炼关键假设，推动结果落地。\n\n3. 推动商业分析 AI 化与能力沉淀：探索并落地 AI、智能体、自动化分析等技术在经营分析中的应用，建设可复用的分析工具、数据产品、知识库与工作流，提升团队分析效率和决策质量。\n\n4. 研究前沿技术及创新业务的商业化机会：围绕低空经济、即时零售等方向开展行业研究与商业判断，结合公司业务基础识别可验证机会，支持试点设计、资源投入和战略决策。\n\n5. 建设团队方法论并培养人才：沉淀经营分析的方法论、项目管理机制和高质量交付标准；在重点项目中带领团队成员成长，提升团队独立思考、业务判断和跨部门协同能力。\n\n岗位基本要求\n1. 5–8 年及以上互联网经营分析、商业策略、咨询、投资研究或新业务战略相关经验；有即时零售、物流履约、供应链、平台业务或本地生活经验者优先。\n\n2. 具备扎实的经营分析与商业判断能力，能够将复杂、模糊的业务问题拆解为清晰的分析框架、关键假设和行动方案；不止能“取数做分析”，更能推动业务决策和结果落地。\n\n3. 有独立负责复杂项目的经历，能够协调产品、运营、算法、财务、业务等多方资源；具备较强的项目 owner 意识。\n\n4. 对 AI、数据产品、智能体或分析自动化有实际应用经验或强烈兴趣，能够理解技术能力边界，并转化为业务场景与组织能力。\n\n5. 对低空经济、具身智能等前沿技术及其商业化有持续关注和思考；能够在高不确定性环境下形成独立观点，并通过小步试验验证假设。\n\n6. 有团队管理、项目带教或方法论建设经验者优先。\n\n具备以下条件优先\n有即时零售、物流履约、供应链网络、城市运营或新业务从 0 到 1 的经营分析经验；\n有 AI 产品、智能体、数据产品、BI/分析自动化等实际落地经验；\n有咨询公司、战略投资、创新业务孵化或创业经历；\n能够带领小团队或在复杂项目中承担总负责人角色。\n\n岗位亮点\n深度参与无人机即时配送及前沿科技商业化探索，面对真实业务问题，而非纯研究型岗位。\n有机会推动 AI 技术重构经营分析的工作方式，形成可规模化复制的组织能力。\n同时接触即时零售、低空经济、人工智能、机器人等前沿议题，与业务、技术和行业专家共同推进创新。\n能够承担高影响力的经营课题，直接参与业务规划、关键决策与新机会验证。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4435349863","sourceKey":"meituan_social","company":"美团","title":"快乐猴-门店3R标准运营专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4435349863&jobShareType=1","duty":"对门店加工（烘焙、3R热出等商品）的出品质量、缺货、损耗负责，具体职责包含：\n1、制定并持续优化门店加工SOP，保障门店出品质量，助力门店加工品的销售额提升；\n2、优化门店排产方案，指导一线操作，实现损耗与缺货的均衡；\n3、搭建门店加工的日常监控体系，帮助门店识别问题，对销售额与成本波动诊断并改善。","requirements":"本科及以上学历，计算机、数学、统计学等相关专业；\n具备较高的数据逻辑和数据敏感性，熟练掌握相关数据提取工具，有丰富的数据分析、挖掘、清洗和建模的经验，会SQL优先；\n3年零售运营/数据分析/商业分析经验；\n执行力强，统筹协同沟通能力强；\n硬折扣行业背景优先；\n掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n对门店加工（烘焙、3R热出等商品）的出品质量、缺货、损耗负责，具体职责包含：\n1、制定并持续优化门店加工SOP，保障门店出品质量，助力门店加工品的销售额提升；\n2、优化门店排产方案，指导一线操作，实现损耗与缺货的均衡；\n3、搭建门店加工的日常监控体系，帮助门店识别问题，对销售额与成本波动诊断并改善。\n\n岗位基本要求\n本科及以上学历，计算机、数学、统计学等相关专业；\n具备较高的数据逻辑和数据敏感性，熟练掌握相关数据提取工具，有丰富的数据分析、挖掘、清洗和建模的经验，会SQL优先；\n3年零售运营/数据分析/商业分析经验；\n执行力强，统筹协同沟通能力强；\n硬折扣行业背景优先；\n掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位亮点\n负责从0到1的核心项目搭建，发展空间大，团队氛围好，福利多元，除了五险一金，还提供补充商业保险、年度体检、团建经费、节日礼金等全方位福利","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4386548338","sourceKey":"meituan_social","company":"美团","title":"快乐猴-华南门店区域中台","city":"广州市/深圳市/佛山市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4386548338&jobShareType=1","duty":"1. 负责所辖城市门店的日常营运支持与标准化落地，确保门店运营高效、合规。  \n2. 协助门店提升业绩，通过数据分析、现场辅导等方式推动关键指标改善。  \n3. 统筹城市级门店培训、人员带教及运营流程优化，提升团队专业能力。  \n4. 协同总部与区域团队，推动新店开业筹备及老店项目试点工作。  \n5. 收集门店反馈，识别共性问题并提出系统性解决方案，推动营运体系持续优化。","requirements":"1. 大学本科及以上学历，3年以上连锁零售营运管理经验。  \n2. 熟悉门店运营全流程，具备较强的现场管理、问题诊断与解决能力。  \n3. 具备优秀的沟通协调能力，能有效联动门店、区域与总部资源。  \n4. 数据敏感度高，能运用数据分析工具支持业务决策。  \n5. 能适应高频出差，工作地点广州市。\n6. 掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1. 负责所辖城市门店的日常营运支持与标准化落地，确保门店运营高效、合规。  \n2. 协助门店提升业绩，通过数据分析、现场辅导等方式推动关键指标改善。  \n3. 统筹城市级门店培训、人员带教及运营流程优化，提升团队专业能力。  \n4. 协同总部与区域团队，推动新店开业筹备及老店项目试点工作。  \n5. 收集门店反馈，识别共性问题并提出系统性解决方案，推动营运体系持续优化。\n\n岗位基本要求\n1. 大学本科及以上学历，3年以上连锁零售营运管理经验。  \n2. 熟悉门店运营全流程，具备较强的现场管理、问题诊断与解决能力。  \n3. 具备优秀的沟通协调能力，能有效联动门店、区域与总部资源。  \n4. 数据敏感度高，能运用数据分析工具支持业务决策。  \n5. 能适应高频出差，工作地点广州市。\n6. 掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位亮点\n1. 加入快速发展的硬折扣品牌，参与门店规模化扩张与运营体系升级。  \n2. 提供清晰的职业发展路径，可向区域管理或总部职能方向晋升。  \n3. 扁平化管理，拥有充分的自主决策空间与创新实践机会。  \n4. 富有竞争力的薪酬激励与完善的培训发展体系。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4624172303","sourceKey":"meituan_social","company":"美团","title":"运输调度主管","city":"广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4624172303&jobShareType=1","duty":"1. 负责广州区域内的日常运输调度工作，确保配送任务按时完成。  \n2. 协调管理100多台货运车辆，优化运输路线和车辆资源，提升配送效率。  \n3. 处理运输过程中的突发问题，及时协调司机、承运商及内部部门。  \n4. 监控运输成本，分析数据并提出改进方案。  \n5. 定期汇报运输运营情况，协助制定团队工作计划。","requirements":"1. 大学专科及以上学历，物流、运输或相关专业优先。  \n2. 3年以上物流运输调度经验，熟悉广州交通及配送网络。  \n3. 具备团队管理能力，能高效协调司机完成工作任务。  \n4. 熟练使用办公软件及物流调度系统。  \n5. 具备良好的沟通能力和协调能力。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责广州区域内的日常运输调度工作，确保配送任务按时完成。  \n2. 协调管理100多台货运车辆，优化运输路线和车辆资源，提升配送效率。  \n3. 处理运输过程中的突发问题，及时协调司机、承运商及内部部门。  \n4. 监控运输成本，分析数据并提出改进方案。  \n5. 定期汇报运输运营情况，协助制定团队工作计划。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、运输或相关专业优先。  \n2. 3年以上物流运输调度经验，熟悉广州交通及配送网络。  \n3. 具备团队管理能力，能高效协调司机完成工作任务。  \n4. 熟练使用办公软件及物流调度系统。  \n5. 具备良好的沟通能力和协调能力。\n\n具备以下条件优先\n大型电商物流管理经验优先\n\n岗位亮点\n1. 提供完善的物流行业培训及晋升通道。  \n2. 团队氛围积极，注重员工成长与发展。  \n3. 参与区域物流网络优化，积累行业核心经验。  \n4. 弹性工作制，兼顾效率与员工关怀。  \n5. 提供具有竞争力的薪资和绩效奖金。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4737612614","sourceKey":"meituan_social","company":"美团","title":"调度主管","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4737612614&jobShareType=1","duty":"1.负责日常配送任务的调度安排，确保车辆和人员合理配置。\n2.监控配送进度，及时处理异常情况，保障配送时效。\n3.协调司机、仓库及客户之间的沟通，提升服务满意度。\n4.优化调度流程，提高配送效率，降低运营成本。\n5.定期汇总调度数据，撰写运营分析报告。","requirements":"1.大学专科及以上学历，物流、运输或相关专业优先。\n2.具备3年以上物流调度或相关工作经验。\n3.熟悉深圳市区及周边道路情况，了解运输行业运作流程。\n4.具备良好的沟通协调能力和应急处理能力\n5.熟练使用办公软件及调度管理系统","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1.负责日常配送任务的调度安排，确保车辆和人员合理配置。\n2.监控配送进度，及时处理异常情况，保障配送时效。\n3.协调司机、仓库及客户之间的沟通，提升服务满意度。\n4.优化调度流程，提高配送效率，降低运营成本。\n5.定期汇总调度数据，撰写运营分析报告。\n\n岗位基本要求\n1.大学专科及以上学历，物流、运输或相关专业优先。\n2.具备3年以上物流调度或相关工作经验。\n3.熟悉深圳市区及周边道路情况，了解运输行业运作流程。\n4.具备良好的沟通协调能力和应急处理能力\n5.熟练使用办公软件及调度管理系统\n\n岗位亮点\n1.工作地点位于深圳市，交通便利，办公环境良好。\n2.提供完善的培训体系和职业发展通道。\n3.团队氛围融洽，注重员工成长与关怀。\n4.绩效奖金+年终奖励，薪酬具有竞争力。\n5.弹性工作时间，支持工作与生活平衡。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4698195844","sourceKey":"meituan_social","company":"美团","title":"企业业务大客户销售经理 (Key Account Manager of Keeta Corporate Business)","city":"香港特别行政区","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4698195844&jobShareType=1","duty":"1. 推广Keeta企业服务，通过多种方式，实现金融、贸易、传媒等行业目标客户的挖掘与引入;\n2. 自主完成销售策略的制定与实施，并能基于行业、客户动态适时调整销售策略；\n3. 独立完成项目投标、谈判、合同签署等商务流程；\n4. 深入理解和精准把握客户需求，结合自身产品能力，为客户提供匹配的解决方案以及根据客户需求，分析整理后反馈至产品团队，推动产品迭代；\n5. 进行客户分析，建立并维护客户关系，挖掘不同客群的深度需求，持续探索和挖掘新业务模式和合作空间；\n6. 运用AI工具进行客户画像分析、销售预测及市场动态监控，提升商务决策效率，以制定业务中长期的发展策略。\n\n1. Promote Keeta's enterprise services through multiple channels to identify and acquire target clients in finance, trade, media, and other sectors.\n2. Independently develop and implement sales strategies, adjusting tactically based on industry and client dynamics.\n3. Manage the full business cycle—including project bidding, negotiation, and contract signing.\n4. Develop a deep understanding of client needs and leverage our product capabilities to deliver tailored solutions; analyze and synthesize client feedback to drive product iteration.\n5. Conduct client analysis, build and maintain strong relationships, uncover deeper needs across customer segments, and continuously explore new business models and collaboration opportunities.\n6. Utilize AI tools for client profiling, sales forecasting, and market intelligence monitoring to enhance business decision-making efficiency and inform mid-to-long-term growth strategies.","requirements":"1.本科及以上学历，有三年以上客户成功、解决方案交付、顾问咨询相关工作经验，有SaaS、互联网、金融行业从业经验者优先；\n2.具备较强的人际沟通及逻辑思维能力，能够准确把握产品优势和客户心理，高效整合内外部资源促进业绩达成；\n3.客户服务意识强，有同理心、有耐心，持续让客户成功；\n4.学习能力强，需要深度学习并掌握公司的产品，能在业务发展中不断总结经验并迭代方法；\n5.推动能力强，对外推动产品被深度使用，对内推动产品或服务持续迭代；\n6.正直诚信，具备高度责任心与执行力；\n7.英语及粤语可作为工作语言；\n8.具备AI工具使用经验（如ChatGPT/Claude、AI销售辅助工具等），能快速上手智能化办公系统。\n\n1. Bachelor's degree or above, with 3+ years of experience in customer success, solution delivery, or consulting. Experience in SaaS, internet, or financial industries is a strong plus.\n2. Strong interpersonal and logical thinking skills; able to articulate product value and read client psychology, coordinating internal and external resources to hit targets.\n3. Customer-centric mindset with empathy and patience—committed to driving client success.\n4. Fast learner capable of deeply understanding our products and continuously refining approaches through practice.\n5. Strong execution drive—externally pushing for deep product adoption, internally advocating for product/service iteration.\n6. High integrity, strong ownership, and ability to deliver.\n7. Proficiency in English and Cantonese as working languages.\n8. Hands-on experience with AI tools (e.g., ChatGPT/Claude, AI-powered sales assistants), able to quickly onboard intelligent office systems.","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. 推广Keeta企业服务，通过多种方式，实现金融、贸易、传媒等行业目标客户的挖掘与引入;\n2. 自主完成销售策略的制定与实施，并能基于行业、客户动态适时调整销售策略；\n3. 独立完成项目投标、谈判、合同签署等商务流程；\n4. 深入理解和精准把握客户需求，结合自身产品能力，为客户提供匹配的解决方案以及根据客户需求，分析整理后反馈至产品团队，推动产品迭代；\n5. 进行客户分析，建立并维护客户关系，挖掘不同客群的深度需求，持续探索和挖掘新业务模式和合作空间；\n6. 运用AI工具进行客户画像分析、销售预测及市场动态监控，提升商务决策效率，以制定业务中长期的发展策略。\n\n1. Promote Keeta's enterprise services through multiple channels to identify and acquire target clients in finance, trade, media, and other sectors.\n2. Independently develop and implement sales strategies, adjusting tactically based on industry and client dynamics.\n3. Manage the full business cycle—including project bidding, negotiation, and contract signing.\n4. Develop a deep understanding of client needs and leverage our product capabilities to deliver tailored solutions; analyze and synthesize client feedback to drive product iteration.\n5. Conduct client analysis, build and maintain strong relationships, uncover deeper needs across customer segments, and continuously explore new business models and collaboration opportunities.\n6. Utilize AI tools for client profiling, sales forecasting, and market intelligence monitoring to enhance business decision-making efficiency and inform mid-to-long-term growth strategies.\n\n岗位基本要求\n1.本科及以上学历，有三年以上客户成功、解决方案交付、顾问咨询相关工作经验，有SaaS、互联网、金融行业从业经验者优先；\n2.具备较强的人际沟通及逻辑思维能力，能够准确把握产品优势和客户心理，高效整合内外部资源促进业绩达成；\n3.客户服务意识强，有同理心、有耐心，持续让客户成功；\n4.学习能力强，需要深度学习并掌握公司的产品，能在业务发展中不断总结经验并迭代方法；\n5.推动能力强，对外推动产品被深度使用，对内推动产品或服务持续迭代；\n6.正直诚信，具备高度责任心与执行力；\n7.英语及粤语可作为工作语言；\n8.具备AI工具使用经验（如ChatGPT/Claude、AI销售辅助工具等），能快速上手智能化办公系统。\n\n1. Bachelor's degree or above, with 3+ years of experience in customer success, solution delivery, or consulting. Experience in SaaS, internet, or financial industries is a strong plus.\n2. Strong interpersonal and logical thinking skills; able to articulate product value and read client psychology, coordinating internal and external resources to hit targets.\n3. Customer-centric mindset with empathy and patience—committed to driving client success.\n4. Fast learner capable of deeply understanding our products and continuously refining approaches through practice.\n5. Strong execution drive—externally pushing for deep product adoption, internally advocating for product/service iteration.\n6. High integrity, strong ownership, and ability to deliver.\n7. Proficiency in English and Cantonese as working languages.\n8. Hands-on experience with AI tools (e.g., ChatGPT/Claude, AI-powered sales assistants), able to quickly onboard intelligent office systems.\n\n具备以下条件优先\n具备金融、贸易、传媒、医药等行业关键客户资源 (Possess key client resources in industries such as finance, trade, media, and healthcare)\n\n岗位亮点\n1.创新业务的操盘手，挑战与机会并存；\n2.能够全方位了解外卖业务模式，有足够的空间和灵活度全面发挥你的才能；\n3.核心业务的核心部门，团队气氛好，学习成长型团队；\n4.前沿AI工具矩阵，让你专注于高价值商务决策。\n\n1. Be the driving force behind an innovative business—challenges and opportunities in equal measure.\n2. Gain a comprehensive understanding of the enterprise service business model, with ample room and flexibility to fully showcase your talent.\n3. Join a core team at the heart of our business—collaborative, supportive, and growth-oriented.\n4. Cutting-edge AI tool matrix that lets you focus on high-value business decision-making.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4586411171","sourceKey":"meituan_social","company":"美团","title":"供给运营专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4586411171&jobShareType=1","duty":"1.深度研究行业，对不同战场、不同供给类型制定供给标准，建设和完善输入输出指标体系。\n2.通过一系列精细化的运营方式实现供给竞争力提升，引导强化用户购票心智。\n2.站在景区品类视角，挖掘应季品类、热点品类的增长机会，通过建立与营销场的合作机制，整合营销资源，助力业务拿到好货，搞试点并推广；","requirements":"1.3年以上供给商家及供给运营相关工作经验；\n2.理解行业特征，理解用户和商家需求，熟悉互联网行业商家运营模式，具备较强的商业敏感度和创新意识。\n3.具备项目规划能力和较强的数据分析能力，能够根据业务发展需求充分协调各类资源配置；\n4.具备良好的项目管理能力和沟通协调能力；","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1.深度研究行业，对不同战场、不同供给类型制定供给标准，建设和完善输入输出指标体系。\n2.通过一系列精细化的运营方式实现供给竞争力提升，引导强化用户购票心智。\n2.站在景区品类视角，挖掘应季品类、热点品类的增长机会，通过建立与营销场的合作机制，整合营销资源，助力业务拿到好货，搞试点并推广；\n\n岗位基本要求\n1.3年以上供给商家及供给运营相关工作经验；\n2.理解行业特征，理解用户和商家需求，熟悉互联网行业商家运营模式，具备较强的商业敏感度和创新意识。\n3.具备项目规划能力和较强的数据分析能力，能够根据业务发展需求充分协调各类资源配置；\n4.具备良好的项目管理能力和沟通协调能力；\n\n具备以下条件优先\n1.有互联网公司商品运营及供给运营经验者优先。\n2.有推进过大型合作项目经验者优先。\n3.有复杂项目管理经验者优先。\n\n岗位亮点\n1.负责整体基础供给的标准化和供给竞争力提升，工作复杂度和模糊度高，具备挑战性。\n2.供给运营核心岗位，能够深入了解业务核心策略。\n3.拥有全局视野和行业化认知，提升业务理解深度和广度，快速成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4690916293","sourceKey":"meituan_social","company":"美团","title":"生鲜供应链品控主管-武汉","city":"武汉市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4690916293&jobShareType=1","duty":"1、负责小象超市生鲜商品到仓、到货、到客全链路各环节的品质管理、食安稽查工作，从源头到餐桌，预防和优化商品质量问题，提升用户满意度；\n2、负责小象超市供应链及服务站品质管理，快速提升各业务模块人员专业能力；\n3、负责跟踪解决出现的商品质量问题，避免商品质量问题重复出现，影响用户体验；\n4、解决突发的食品安全问题，降低食品安全风险；","requirements":"1、大专以上学历，3年以上商超零食品质管理经验或供应链品质管理经验；\n2、具备很强的跨部门沟通表达及协作能力，能快速推进项目落地；\n3、有极强的责任心、自驱性墙，能承受较强的工作压力；\n4、具备正直诚信的价值观，有较强的原则","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责小象超市生鲜商品到仓、到货、到客全链路各环节的品质管理、食安稽查工作，从源头到餐桌，预防和优化商品质量问题，提升用户满意度；\n2、负责小象超市供应链及服务站品质管理，快速提升各业务模块人员专业能力；\n3、负责跟踪解决出现的商品质量问题，避免商品质量问题重复出现，影响用户体验；\n4、解决突发的食品安全问题，降低食品安全风险；\n\n岗位基本要求\n1、大专以上学历，3年以上商超零食品质管理经验或供应链品质管理经验；\n2、具备很强的跨部门沟通表达及协作能力，能快速推进项目落地；\n3、有极强的责任心、自驱性墙，能承受较强的工作压力；\n4、具备正直诚信的价值观，有较强的原则\n\n具备以下条件优先\n务实，吃苦耐劳\n\n岗位亮点\n五险一金，绩效奖金，晋升发展\n优先\n1、热爱互联网和新零售行业，具有极强的快速学习能力\n2、有较强的质量管理方法论且可以快速结合业务特点落地能力\n3、有吃苦精神","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4688770910","sourceKey":"meituan_social","company":"美团","title":"Java研发工程师-算法工程方向","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4688770910&jobShareType=1","duty":"1、负责骑行智能策略平台的设计与开发，覆盖车辆调度、用户增长等核心业务场景；\n2、负责AI Agent探索和实践，推动AI Agent在业务场景中落地并取得真实业务价值；\n3、与算法和数据团队深度合作，挖掘增量机会，提升智能化策略迭代效率，并通过Agent能力对回测、回放、仿真等基础能力进行升级。","requirements":"1、大学本科以上学历，具备扎实的编程基础和数据结构算法基础，优秀的编程能力和问题解决能力； \n2、3年以上分布式系统开发经验，具备复杂业务场景下核心系统或高并发系统项目开发经验； \n3、精通Java及面向对象设计开发，深入理解面向服务的架构，精通微服务开发，掌握Linux/MySQL/NoSQL核心原理等； \n4、喜欢钻研，对业务、产品和技术都有浓厚的兴趣；AI First，对AI驱动业务有强烈的激情；勤于思考总结，结果导向。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1、负责骑行智能策略平台的设计与开发，覆盖车辆调度、用户增长等核心业务场景；\n2、负责AI Agent探索和实践，推动AI Agent在业务场景中落地并取得真实业务价值；\n3、与算法和数据团队深度合作，挖掘增量机会，提升智能化策略迭代效率，并通过Agent能力对回测、回放、仿真等基础能力进行升级。\n\n岗位基本要求\n1、大学本科以上学历，具备扎实的编程基础和数据结构算法基础，优秀的编程能力和问题解决能力； \n2、3年以上分布式系统开发经验，具备复杂业务场景下核心系统或高并发系统项目开发经验； \n3、精通Java及面向对象设计开发，深入理解面向服务的架构，精通微服务开发，掌握Linux/MySQL/NoSQL核心原理等； \n4、喜欢钻研，对业务、产品和技术都有浓厚的兴趣；AI First，对AI驱动业务有强烈的激情；勤于思考总结，结果导向。\n\n具备以下条件优先\n1、有用户增长、网约车调度、供应链方向建设经验优先；\n2、有AI技术探索与实践经验优先，包括 AI Coding、Harness Engineering、Agent 开发以及 AI 驱动的产研协作新范式等。\n\n岗位亮点\n1、参与前沿算法工程实践，推动AI技术在真实业务场景中的规模化应用；\n2、千万级订单规模业务场景，深度参与大体量、高复杂度业务场景的技术方案设计和开发落地。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4622010100","sourceKey":"meituan_social","company":"美团","title":"低价项目产品运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4622010100&jobShareType=1","duty":"1.制定酒旅低价项目BC端运营策略并落地，为供给质量和交易额负责。\n2.负责酒旅项目产品工具的建设，协同产研团队提升策略运营效率。\n3.负责项目的数据分析，数据驱动进行经营诊断，为下一步举措提供数据基础。\n4.协调内部各部门资源，推动项目整体运营达成目标。","requirements":"1.大学本科及以上学历，3年以上产品运营或用户运营经验。\n2.熟悉互联网产品运营流程和方法，具备良好的数据分析能力，熟练使用SQL。\n3.有较强的自驱力和责任心，强目标导向，能够拿结果。\n4.具备较强的沟通和协调能力，能够与多个部门进行良好的合作与沟通。\n5.能够将对AI的知识和洞察与业务理解相结合，历史有使用AI提升运营效率的实际项目经验，包括但不限于：运用大模型辅助用户洞察报告撰写与数据分析解读，或将AI能力融入运营链路并产出业务价值。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1.制定酒旅低价项目BC端运营策略并落地，为供给质量和交易额负责。\n2.负责酒旅项目产品工具的建设，协同产研团队提升策略运营效率。\n3.负责项目的数据分析，数据驱动进行经营诊断，为下一步举措提供数据基础。\n4.协调内部各部门资源，推动项目整体运营达成目标。\n\n岗位基本要求\n1.大学本科及以上学历，3年以上产品运营或用户运营经验。\n2.熟悉互联网产品运营流程和方法，具备良好的数据分析能力，熟练使用SQL。\n3.有较强的自驱力和责任心，强目标导向，能够拿结果。\n4.具备较强的沟通和协调能力，能够与多个部门进行良好的合作与沟通。\n5.能够将对AI的知识和洞察与业务理解相结合，历史有使用AI提升运营效率的实际项目经验，包括但不限于：运用大模型辅助用户洞察报告撰写与数据分析解读，或将AI能力融入运营链路并产出业务价值。\n\n岗位亮点\n1.参与项目产品运营的全流程，快速提升个人能力和职业发展。\n2.业务涉及合作多个酒旅专项团队，有机会以更多的视角去理解行业。\n3.酒旅重点项目，历史已取得较好基础与成绩，团队氛围非常好。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4611929667","sourceKey":"meituan_social","company":"美团","title":"神抢手整合营销专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4611929667&jobShareType=1","duty":"1. 建立神抢手频道的用户增长玩法，围绕 DAU、访问转化、复访、下单转化等指标，设计阶段性增长策略和运营节奏。结合 AI 技术能力（如智能推荐、用户分层模型、AI 人群圈选等）提升增长效率和精准度。\n2. 策划并落地频道级营销活动，包括但不限于大牌合作、主题场景等。探索 AI 辅助活动创意生成、智能选品、动态定价等创新玩法，提升活动策划效率与效果。\n3.主动挖掘创新机会，例如热点借势、城市/人群分层玩法、社交裂变等，提升频道声量和用户访问习惯。利用 AI 工具进行热点预测、内容生成（AIGC）、素材批量化生产及效果优化。\n4. 对活动数据负责，建立从曝光、点击、访问、转化、复访到 DAU 拉动的评估体系，持续优化活动 ROI、DAU 成本。借助 AI 数据分析工具进行智能归因、效果预测和策略迭代。","requirements":"1. 3-6 年互联网活动运营、整合营销、用户增长或平台型业务运营经验，有本地生活、电商、外卖、零售、内容平台经验优先。有 AI 工具在运营场景中的实操经验者优先。\n2. 具备较强的营销策划能力，能把商品、价格、场景、用户情绪和传播内容结合起来，做出有新鲜感、有传播点、有业务结果的活动。了解 AI 在内容生成、智能推荐、用户洞察等方向的应用，具备用 AI 提升策划效率的意识。\n3. 对用户和内容有感觉，熟悉小红书、抖音、视频号、知乎、朋友圈等不同渠道的用户心智和传播增长思路。了解 AIGC 内容创作逻辑和不同渠道的 AI 辅助内容分发策略。\n4. 具备较强的自驱力和创新意识，不满足于执行既定活动，能主动提出新玩法、新机制、新资源组合，并推动验证。对新事物保持好奇，持续探索 AI 技术在营销增长场景中的落地应用。","description":"部门介绍\n美团外卖秉承“帮大家吃得更好，生活更好”的使命，始终聚焦于消费者用餐需求。我们通过科技连接消费者和商家，依托庞大的骑手团队，以“线上+线下”的业务模式，为消费者提供品质化、精细化、多样化的餐饮外卖服务。\n外卖事业部是为用户与商家提供全链路交易服务的业务组织，围绕餐饮外卖搭建了包含外卖业务与创新孵化业务在内的多个部门。\n我们的目标是帮助商家开源增收、提高经营效率，促进餐饮行业数字化，以及为更多用户提供更便捷更有品质的外卖服务。加入我们，一起为上亿用户提供更好的用餐体验，帮助大家吃得更好，生活更好！\n\n岗位职责\n1. 建立神抢手频道的用户增长玩法，围绕 DAU、访问转化、复访、下单转化等指标，设计阶段性增长策略和运营节奏。结合 AI 技术能力（如智能推荐、用户分层模型、AI 人群圈选等）提升增长效率和精准度。\n2. 策划并落地频道级营销活动，包括但不限于大牌合作、主题场景等。探索 AI 辅助活动创意生成、智能选品、动态定价等创新玩法，提升活动策划效率与效果。\n3.主动挖掘创新机会，例如热点借势、城市/人群分层玩法、社交裂变等，提升频道声量和用户访问习惯。利用 AI 工具进行热点预测、内容生成（AIGC）、素材批量化生产及效果优化。\n4. 对活动数据负责，建立从曝光、点击、访问、转化、复访到 DAU 拉动的评估体系，持续优化活动 ROI、DAU 成本。借助 AI 数据分析工具进行智能归因、效果预测和策略迭代。\n\n岗位基本要求\n1. 3-6 年互联网活动运营、整合营销、用户增长或平台型业务运营经验，有本地生活、电商、外卖、零售、内容平台经验优先。有 AI 工具在运营场景中的实操经验者优先。\n2. 具备较强的营销策划能力，能把商品、价格、场景、用户情绪和传播内容结合起来，做出有新鲜感、有传播点、有业务结果的活动。了解 AI 在内容生成、智能推荐、用户洞察等方向的应用，具备用 AI 提升策划效率的意识。\n3. 对用户和内容有感觉，熟悉小红书、抖音、视频号、知乎、朋友圈等不同渠道的用户心智和传播增长思路。了解 AIGC 内容创作逻辑和不同渠道的 AI 辅助内容分发策略。\n4. 具备较强的自驱力和创新意识，不满足于执行既定活动，能主动提出新玩法、新机制、新资源组合，并推动验证。对新事物保持好奇，持续探索 AI 技术在营销增长场景中的落地应用。\n\n具备以下条件优先\n1. 有本地生活、即时零售、外卖、团购、秒杀、特价频道或爆品频道运营经验。\n2. 有从 0 到 1 打造频道活动 IP、增长项目或营销阵地的经验。\n3. 有 AI 在用户增长、活动运营、内容生产或数据分析场景中的实际落地经验，熟悉大模型应用（如 AI 智能推荐、AI 选品、AI 素材自动生成、AI 人群圈选等）。\n4. 关注行业 AI 应用趋势，有利用 AI 工具提升运营效率或推动运营创新的实践案例。\n\n岗位亮点\n1. 参与核心业务增长项目，直接影响产品关键指标。  \n2. 扁平化管理，高效协作的团队氛围。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3397095778","sourceKey":"meituan_social","company":"美团","title":"闪购-松鼠-店铺运营专家(华南)","city":"广州市/深圳市/福州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3397095778&jobShareType=1","duty":"1、根据城市消费特征及市场行情变化，借助AI工具辅助制定差异化商品、价格和用户策略\n2、根据门店爬坡/成熟阶段和地理位置，制定门店分层分类的差异化运营方案\n3、有效合作商管理，能够熟悉不同商家特征和诉求，确保总部策略和专项项目在门店落地执行\n4、洞察合作商特征和能力优势，挖掘出潜力增长机会点，沉淀方法论复制到更多商家\n5、具备行业视角，能够吸纳先进经验，有不错经营意识，能够从商家视角思考生意","requirements":"1、在商家运营、商品运营、价格运营至少一个方向有成功经验，具备一定方法论\n2、有较强的数据分析能力，熟练掌握表格处理办公软件，独立完成专项课题分析\n3、具备良好的沟通能力、团队协作能力，执行力强，目标性强，能够交付结果\n4、有较强的资源整合或项目管理能力，能够适应节奏快业务迭代快\n5、具有在大型零售商或电商公司的工作经验，或熟练使用SQL，或有商品管理经验者优先","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1、根据城市消费特征及市场行情变化，借助AI工具辅助制定差异化商品、价格和用户策略\n2、根据门店爬坡/成熟阶段和地理位置，制定门店分层分类的差异化运营方案\n3、有效合作商管理，能够熟悉不同商家特征和诉求，确保总部策略和专项项目在门店落地执行\n4、洞察合作商特征和能力优势，挖掘出潜力增长机会点，沉淀方法论复制到更多商家\n5、具备行业视角，能够吸纳先进经验，有不错经营意识，能够从商家视角思考生意\n\n岗位基本要求\n1、在商家运营、商品运营、价格运营至少一个方向有成功经验，具备一定方法论\n2、有较强的数据分析能力，熟练掌握表格处理办公软件，独立完成专项课题分析\n3、具备良好的沟通能力、团队协作能力，执行力强，目标性强，能够交付结果\n4、有较强的资源整合或项目管理能力，能够适应节奏快业务迭代快\n5、具有在大型零售商或电商公司的工作经验，或熟练使用SQL，或有商品管理经验者优先\n\n岗位亮点\n1、业务前景：松鼠从23年下半年成立，至今不到2年时间，已快速成为行业头部品牌，如今仍然保持着成倍增长，业务高速发展，组织及团队能力在快速迭代升级。\n2、团队氛围：这是一个实干、专业、乐于分享的团队，是一群感想敢干的人，为“让松鼠成为年轻人优先选择的便利店”理想而努力，为年轻人提供高品质差异化商品的即时服务。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4540665244","sourceKey":"meituan_social","company":"美团","title":"渠道经理","city":"贵阳市/郑州市/合肥市/太原市/南宁市/福州市/石家庄市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4540665244&jobShareType=1","duty":"1、渠道体系建设：负责所辖区域的渠道开发与管理，制定区域渠道策略，持续扩大市场渗透率。\n2、渠道拓展与维护：主导区域内代理商的招募、评估与日常运营管理，建立长期稳定的合作关系，提升渠道忠诚度与活跃度。\n3、业绩目标达成：制定并分解区域销售目标，追踪核心渠道数据，通过精细化运营手段推动渠道业绩持续增长。\n4、团队管理：组建并带领区域渠道团队，建立标准化销售流程，实施人才培养与梯队建设，提升团队整体战斗力。\n5、市场洞察：持续跟踪区域竞争态势，掌握客户需求变化，提炼市场洞察并反馈至产品及运营团队，驱动业务策略优化。\n6、跨部门协作：协同商品、运营、物流等部门，保障渠道履约质量，推动客户问题快速响应与解决。","requirements":"1、本科及以上学历，3年以上B端渠道销售/管理经验，有农产品、生鲜食材、餐饮供应链相关行业背景优先；\n2、具备较强的渠道开拓能力，有从0到1搭建区域渠道体系的成功经验；\n3、具备较强的内外部资源整合与协调能力，能在高速发展环境中带领团队完成挑战性目标；\n4、可接受出差，熟悉所在区域市场生态。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1、渠道体系建设：负责所辖区域的渠道开发与管理，制定区域渠道策略，持续扩大市场渗透率。\n2、渠道拓展与维护：主导区域内代理商的招募、评估与日常运营管理，建立长期稳定的合作关系，提升渠道忠诚度与活跃度。\n3、业绩目标达成：制定并分解区域销售目标，追踪核心渠道数据，通过精细化运营手段推动渠道业绩持续增长。\n4、团队管理：组建并带领区域渠道团队，建立标准化销售流程，实施人才培养与梯队建设，提升团队整体战斗力。\n5、市场洞察：持续跟踪区域竞争态势，掌握客户需求变化，提炼市场洞察并反馈至产品及运营团队，驱动业务策略优化。\n6、跨部门协作：协同商品、运营、物流等部门，保障渠道履约质量，推动客户问题快速响应与解决。\n\n岗位基本要求\n1、本科及以上学历，3年以上B端渠道销售/管理经验，有农产品、生鲜食材、餐饮供应链相关行业背景优先；\n2、具备较强的渠道开拓能力，有从0到1搭建区域渠道体系的成功经验；\n3、具备较强的内外部资源整合与协调能力，能在高速发展环境中带领团队完成挑战性目标；\n4、可接受出差，熟悉所在区域市场生态。\n\n岗位亮点\n美团快驴深耕B2B餐饮供应链业务，渠道正处于快速扩张阶段，将深度参与区域市场从0到1的开拓，直接操盘代理商体系建设与业务增长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4617791554","sourceKey":"meituan_social","company":"美团","title":"充电宝CKA销售（太原）","city":"太原市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4617791554&jobShareType=1","duty":"1. 连锁品牌开发：负责城市内10-50家门店连锁品牌的从0到1开发；识别品牌总部KP制定整体方案，一次谈判覆盖全品牌门店，而非逐店攻坚。\n2. 客户关系深耕：维护签约连锁品牌的核心客情，定期触达关键决策人；通过数据监测识别门店运营异常，推动解决并挖掘二次开发价值，实现客户生命周期价值最大化。\n3. 资源整合与跨部门协同：主动联动前后线及跨部门资源，为客户提供整体全局解决方案；将内外部资源转化为稳定的新客户获取渠道。\n4. 数据分析与谈判落地：结合客户历史数据与信息，制定个性化报价方案；运用顾问式销售挖掘客户真实痛点，平衡双方利益，推动合同签约落地。\n5. 市场洞察与复盘迭代：持续收集区域行业动态和市场布局，定期复盘客户跟进节奏，从成功/失败案例中提炼可复用方法论。","requirements":"【基础要求】\n1. 大专及以上学历，3年及以上B端地面销售经验\n2. 有完整的大客户从0到1开发案例（能说清楚：怎么找到KP、卡在哪、怎么突破、最终结果）\n3. 有CKA/KA等连锁、大客户销售经验者优先\n\n【能力要求】\n1. 连锁攻坚力：有全局思维能找总部关键KP、做标杆案例、批量复制覆盖，而非逐店谈判\n2. 谈判与逼单：能分析客户需求、提供优质解决方案并守住收益底线，不是过于消耗资源\n3. 作业习惯：有固定拜访节奏和客户分层逻辑，知道每天该去哪、为什么去\n4. 资源整合力：能主动搭建内外部资源，借力跨部门、合作商推进项目\n\n【底层特质】\n1. 内部归因：遇到客户拒绝，先反思自己的判断和方案，而非归因市场与挑战\n2. 韧性：能跟进长周期客户不轻易放弃，把每一次拒绝当作调整策略的起点\n3. 自驱力：主动复盘、主动约陪访、主动找方法，不等着被推着走","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1. 连锁品牌开发：负责城市内10-50家门店连锁品牌的从0到1开发；识别品牌总部KP制定整体方案，一次谈判覆盖全品牌门店，而非逐店攻坚。\n2. 客户关系深耕：维护签约连锁品牌的核心客情，定期触达关键决策人；通过数据监测识别门店运营异常，推动解决并挖掘二次开发价值，实现客户生命周期价值最大化。\n3. 资源整合与跨部门协同：主动联动前后线及跨部门资源，为客户提供整体全局解决方案；将内外部资源转化为稳定的新客户获取渠道。\n4. 数据分析与谈判落地：结合客户历史数据与信息，制定个性化报价方案；运用顾问式销售挖掘客户真实痛点，平衡双方利益，推动合同签约落地。\n5. 市场洞察与复盘迭代：持续收集区域行业动态和市场布局，定期复盘客户跟进节奏，从成功/失败案例中提炼可复用方法论。\n\n岗位基本要求\n【基础要求】\n1. 大专及以上学历，3年及以上B端地面销售经验\n2. 有完整的大客户从0到1开发案例（能说清楚：怎么找到KP、卡在哪、怎么突破、最终结果）\n3. 有CKA/KA等连锁、大客户销售经验者优先\n\n【能力要求】\n1. 连锁攻坚力：有全局思维能找总部关键KP、做标杆案例、批量复制覆盖，而非逐店谈判\n2. 谈判与逼单：能分析客户需求、提供优质解决方案并守住收益底线，不是过于消耗资源\n3. 作业习惯：有固定拜访节奏和客户分层逻辑，知道每天该去哪、为什么去\n4. 资源整合力：能主动搭建内外部资源，借力跨部门、合作商推进项目\n\n【底层特质】\n1. 内部归因：遇到客户拒绝，先反思自己的判断和方案，而非归因市场与挑战\n2. 韧性：能跟进长周期客户不轻易放弃，把每一次拒绝当作调整策略的起点\n3. 自驱力：主动复盘、主动约陪访、主动找方法，不等着被推着走\n\n具备以下条件优先\n互联网本地生活经验、3年及以上大客户销售经验\n\n岗位亮点\n🔋 美团充电宝CKA团队，专注城市及区域连锁品牌与头部客户开发，不是扫街是品牌覆盖\n🚀 平台资源加持：背靠美团本地生活生态，用流量赋能、品牌背书帮你打开客户大门\n📈 成长天花板高：从单城连锁到全国品牌，从商务专员到城市经理，成长路径清晰\n💰 高激励机制：业绩与收入直接挂钩，高业绩高提成\n🏆 有方法论的团队：不靠感觉靠打法，有连锁攻坚SOP、客户分层体系、城市经理陪访支持\n\n如果你热爱销售、享受攻坚大客户的成就感，我们希望和你一起：\n用「乘法思维」做业绩——打通一个品牌，覆盖几十家门店\n在美团生态里借力——平台流量、跨部门资源都是你的谈判筹码\n在有方法论的团队里成长——从优秀同事身上学到可复用的打法\n走一条清晰的晋升路径——业绩说话，成长看得见\n\n我们期待你是这样的人：\n有过硬的大客户开发经历，遇到拒绝会先反思自己的方案而不是抱怨市场，习惯主动复盘和自我驱动——如果这说的是你，欢迎投递。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4203880655","sourceKey":"meituan_social","company":"美团","title":"Sr Mgr, Employee Experience","city":"圣保罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4203880655&jobShareType=1","duty":"Plan, execute, and continuously evolve the internal communications strategy, aligned with Keeta’s cultural pillars and People team objectives;\nDevelop campaigns, content, and internal channels that foster engagement, active listening, and transparency at all organizational levels;\nPromote meaningful connections between leadership, field teams, and global employees;\nCo-lead Employer Branding initiatives in partnership with Talent Acquisition, Marketing, and other areas;\nMeasure and analyze communication metrics to drive data-based decisions and continuous improvement;\nLeverage technology (including AI) to personalize and scale internal communication efficiently;\nSupport internal events, internal marketing initiatives, and employee recognition and celebration moments;\nConnect and adapt communication strategies across multiple cultural contexts.","requirements":"Requirements\n\nSolid experience in Internal Communications, with both strategic and hands-on execution;\nExperience with Employer Branding and organizational culture projects;\nStrong analytical skills and proficiency in communication and engagement metrics;\nExperience in dynamic, fast-building environments (tech company background preferred);\nExcellent writing and storytelling skills for diverse audiences;\nAbility to work collaboratively in multicultural environments;\nAdvanced English (essential for working with global stakeholders).\nWork model: On-site.","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\nPlan, execute, and continuously evolve the internal communications strategy, aligned with Keeta’s cultural pillars and People team objectives;\nDevelop campaigns, content, and internal channels that foster engagement, active listening, and transparency at all organizational levels;\nPromote meaningful connections between leadership, field teams, and global employees;\nCo-lead Employer Branding initiatives in partnership with Talent Acquisition, Marketing, and other areas;\nMeasure and analyze communication metrics to drive data-based decisions and continuous improvement;\nLeverage technology (including AI) to personalize and scale internal communication efficiently;\nSupport internal events, internal marketing initiatives, and employee recognition and celebration moments;\nConnect and adapt communication strategies across multiple cultural contexts.\n\n岗位基本要求\nRequirements\n\nSolid experience in Internal Communications, with both strategic and hands-on execution;\nExperience with Employer Branding and organizational culture projects;\nStrong analytical skills and proficiency in communication and engagement metrics;\nExperience in dynamic, fast-building environments (tech company background preferred);\nExcellent writing and storytelling skills for diverse audiences;\nAbility to work collaboratively in multicultural environments;\nAdvanced English (essential for working with global stakeholders).\nWork model: On-site.\n\n具备以下条件优先\nNice to Have\n\nExperience in companies at an early operational stage in Brazil (stage 0→1), especially in high-growth contexts;\nPrevious experience in Chinese companies or working within multicultural environments influenced by Asian structures and dynamics.\n\n岗位亮点\nWe are looking for a strategic yet hands-on professional to lead the Internal Communications function in Brazil.\n\nThis person will be responsible for building bridges across teams, strengthening Keeta’s culture, and developing initiatives that elevate employee engagement and experience — from onboarding to recognition.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4451174575","sourceKey":"meituan_social","company":"美团","title":"HRBP（外派巴西）","city":"圣保罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4451174575&jobShareType=1","duty":"作为核心HRBP，你将深入国际化业务一线，支持策略与运营类团队，从组织发展、人才升级到氛围建设全链路驱动业务增长。这是一个真正国际化的舞台——你将与多国团队协作，在快速变化的海外市场中构建组织能力。\n\n核心职责\n1. 业务深耕与组织规划\n深入理解业务战略与发展方向，基于前瞻性判断制定组织与人力规划\n推动组织架构设计与迭代，确保组织能力匹配业务发展节奏\n作为业务 leader 的伙伴，提供组织诊断与策略建议\n\n2. 人才运营与判断\n管理人才全生命周期：选用育留汰\n在关键节点（绩效 cycle、晋升、调配）中做好对人的判断与运营\n搭建适配海外业务节奏的人才评估与盘点机制\n\n3. 人才密度持续升级\n主导本地市场与国际市场的关键岗位招聘，把控人才质量\n建立候选人甄选标准，提升团队整体人才密度\n推动内部人才流动与梯队建设\n\n4. 组织氛围建设\n搭建跨文化团队的沟通与协作机制\n打造开放、高效、有韧性的组织文化\n推动团队融合活动与员工体验优化","requirements":"极具韧性，能在高度不确定和快节奏环境中持续输出\n心态开放，对多元文化有真实的好奇心和适应力\n有深入业务的意愿和能力——不只做 HR 流程，而是真正理解商业逻辑\n对人有敏锐判断力，能在关键时刻做出高质量的人才决策\n英文基础不错，可以快速提升到工作语言水平","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n作为核心HRBP，你将深入国际化业务一线，支持策略与运营类团队，从组织发展、人才升级到氛围建设全链路驱动业务增长。这是一个真正国际化的舞台——你将与多国团队协作，在快速变化的海外市场中构建组织能力。\n\n核心职责\n1. 业务深耕与组织规划\n深入理解业务战略与发展方向，基于前瞻性判断制定组织与人力规划\n推动组织架构设计与迭代，确保组织能力匹配业务发展节奏\n作为业务 leader 的伙伴，提供组织诊断与策略建议\n\n2. 人才运营与判断\n管理人才全生命周期：选用育留汰\n在关键节点（绩效 cycle、晋升、调配）中做好对人的判断与运营\n搭建适配海外业务节奏的人才评估与盘点机制\n\n3. 人才密度持续升级\n主导本地市场与国际市场的关键岗位招聘，把控人才质量\n建立候选人甄选标准，提升团队整体人才密度\n推动内部人才流动与梯队建设\n\n4. 组织氛围建设\n搭建跨文化团队的沟通与协作机制\n打造开放、高效、有韧性的组织文化\n推动团队融合活动与员工体验优化\n\n岗位基本要求\n极具韧性，能在高度不确定和快节奏环境中持续输出\n心态开放，对多元文化有真实的好奇心和适应力\n有深入业务的意愿和能力——不只做 HR 流程，而是真正理解商业逻辑\n对人有敏锐判断力，能在关键时刻做出高质量的人才决策\n英文基础不错，可以快速提升到工作语言水平\n\n具备以下条件优先\n有海外工作经验或国际化业务背景\n\n岗位亮点\n真正国际化的舞台：与多国团队共事，在海外市场一线参与组织建设\n高速成长期 : 业务快速发展，HR 的每一个动作都直接影响业务结果\n高影响力: 直接支持核心业务团队，深入参与业务演进\n稀缺的成长机会:在国际化场景中积累独特的 HR 能力组合","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4738781104","sourceKey":"meituan_social","company":"美团","title":"AI营销产品经理","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4738781104&jobShareType=1","duty":"1.负责 AI 营销产品的规划与设计，将大模型能力与营销场景深度结合，打造智能化营销工具并形成解决方案。\n\n2.深入洞察客户经营及营销场景，挖掘餐饮行业的营销痛点，设计 AI 驱动的营销解决方案，并主导商业化的落地。\n\n3.跟踪 AI 领域技术趋势，推动产品创新，独立闭环关键客户的方案沟通与商业化决策，协同其他角色完成 AI 能力从 POC 到规模化落地。\n\n4.搭建 AI 营销产品的核心指标体系，为商业化目标及客户体验负责。\n\n5.与研发、销售团队紧密配合，平衡技术实现与业务需求，确保产品高质量交付。","requirements":"1.本科及以上学历，5年以上产品经验，有电商或餐饮行业各大平台营销和私域营销解决方案实操落地的经验。\n\n2.对 AI 产品有深入理解，熟悉大模型应用模式及AI架构，了解主流AI能力边界，有 AI 营销产品 0-1 搭建经验，有主导并拿到商业化结果的项目实践。\n\n3.结果导向，能独立完成从需求洞察到产品上线的全流程。\n\n4.沟通能力强，深入理解客户场景并推进产品价值迭代，对外可和销售一起谈客户，对内可协同研发团队快速落地。\n\n5.学习能力和执行力要强，保有好奇心，对新技术敏感，能快速将技术趋势转化为产品方案。","description":"部门介绍\n美团餐饮系统为餐饮企业提供一站式IT解决方案，帮助餐饮商户实现从供应链管理、生产管理、前厅管理到外卖的数字化经营。美团餐饮系统不仅打通了餐厅和平台，更帮助餐厅连接客人，让商户更了解顾客需求，在帮助商户做商业决策的同时给顾客带来更好的消费体验。\n我们持续建设和提升产研、销售、服务的核心能力，通过全新升级的美团餐饮系统一体化软硬件产品，助力餐饮商户进行线上化经营，帮助商户在推广新店、提升效率、降低成本、会员营销、流量扶持、智慧选址、供应链管理等方面强化经营能力。团队汇集了餐饮和SaaS领域的优秀人才，秉持着“以客户为中心”的初心和“长期有耐心”的耕耘精神，求真、敬畏、敢于自我否定、善于快速学习。期待同样愿意长期致力于餐饮产业数字化、智能化的你加入我们的团队，共同进步共同成长！\n\n岗位职责\n1.负责 AI 营销产品的规划与设计，将大模型能力与营销场景深度结合，打造智能化营销工具并形成解决方案。\n\n2.深入洞察客户经营及营销场景，挖掘餐饮行业的营销痛点，设计 AI 驱动的营销解决方案，并主导商业化的落地。\n\n3.跟踪 AI 领域技术趋势，推动产品创新，独立闭环关键客户的方案沟通与商业化决策，协同其他角色完成 AI 能力从 POC 到规模化落地。\n\n4.搭建 AI 营销产品的核心指标体系，为商业化目标及客户体验负责。\n\n5.与研发、销售团队紧密配合，平衡技术实现与业务需求，确保产品高质量交付。\n\n岗位基本要求\n1.本科及以上学历，5年以上产品经验，有电商或餐饮行业各大平台营销和私域营销解决方案实操落地的经验。\n\n2.对 AI 产品有深入理解，熟悉大模型应用模式及AI架构，了解主流AI能力边界，有 AI 营销产品 0-1 搭建经验，有主导并拿到商业化结果的项目实践。\n\n3.结果导向，能独立完成从需求洞察到产品上线的全流程。\n\n4.沟通能力强，深入理解客户场景并推进产品价值迭代，对外可和销售一起谈客户，对内可协同研发团队快速落地。\n\n5.学习能力和执行力要强，保有好奇心，对新技术敏感，能快速将技术趋势转化为产品方案。\n\n岗位亮点\n1.可深度参与AI产品策略的讨论和规划的制定，一起探索AI产品的新模式。\n\n2.可参与并主导AI在餐饮行业营销增长方向的深度应用，打造标杆性AI商业化案例。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4630048722","sourceKey":"meituan_social","company":"美团","title":"美团骑行-车辆运营主管（赣州）","city":"赣州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4630048722&jobShareType=1","duty":"1.负责所属区域的车辆运营管理工作，对有效运营车辆和活跃车辆指标负责；\n2.通过实地观察、数据分析、行业分析，制定提升市占营收的经营策略，例如车辆投放、调度策略，故障干预策略等，提升市占营收等指标；\n3.组建和管理运维团队，包括一线运维司机、摆车人员；\n4.对接区域内政府主管部门，配合政府部门对城市运营问题进行管理","requirements":"1.本科及以上学历，不限专业不限工作经历；2.具备较好的沟通协调能力和执行力。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.负责所属区域的车辆运营管理工作，对有效运营车辆和活跃车辆指标负责；\n2.通过实地观察、数据分析、行业分析，制定提升市占营收的经营策略，例如车辆投放、调度策略，故障干预策略等，提升市占营收等指标；\n3.组建和管理运维团队，包括一线运维司机、摆车人员；\n4.对接区域内政府主管部门，配合政府部门对城市运营问题进行管理\n\n岗位基本要求\n1.本科及以上学历，不限专业不限工作经历；2.具备较好的沟通协调能力和执行力。\n\n岗位亮点\n1.机会：在美团骑行这一成长迅速的行业中扮演关键角色，参与车辆运营管理的全过程。\n2.挑战：面对车辆运营中的各类问题和挑战，锻炼自身的管理和应变能力。\n3.发展：有机会参与团队建设和管理，为未来晋升为高级职位奠定基础。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4738521257","sourceKey":"meituan_social","company":"美团","title":"无人机通信系统解决方案工程师","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4738521257&jobShareType=1","duty":"1、主导通信链路测试与覆盖优化\n主导无人机 4G/5G、Wi-Fi 通信链路的测试验证：制定测试策略与指标体系（覆盖、时延、吞吐、切换成功率、丢包率等），组织外场与实验室测试，完成数据采集与深度分析，输出链路性能评估与优化结论；基于航线级数据定位弱覆盖、高干扰、异常切换区域的根因，主导与运营商及网络侧的覆盖优化协同，并跟踪落地效果。\n2、主导通信解决方案场景测试\n主导通信相关解决方案的场景化测试，涵盖 4G/5G 蜂窝网络、Wi-Fi、蓝牙、点对点图传等多种链路，以及多链路冗余、主备切换、多运营商智能切换、APN 专网等组合场景；设计典型城市低空飞行工况（高楼遮挡、多径、密集起降、高峰并发）下的验证方案，确保通信系统在真实运营环境下的可用性与可靠性。\n3、负责测试体系与能力建设\n制定测试方案、用例规范与报告模板，覆盖功能、性能、异常与边界场景；搭建数据采集—分析—报告的自动化工具链，提升测试效率与数据一致性；评审团队测试输出，指导初级工程师成长。\n4、负责问题闭环与优化效果评估\n建立通信问题跟踪与闭环机制，联动研发、网络优化团队复现定位疑难问题，跟踪闭环至验证通过；主导通信链路优化方案（多运营商切换策略、链路冗余与降级策略、天线布局优化、专网接入等）的验证设计与效果量化评估，通过前后对比数据支撑方案迭代决策。","requirements":"1. 本科及以上学历，通信工程、电子信息工程、计算机、自动化等相关专业；\n2. 3~5 年移动通信测试、网络优化或通信模组测试经验，有独立主导测试项目的完整闭环经验；\n3. 深入理解 4G/5G 空口协议与信令流程（接入、切换、重选、掉话等），能基于信令与 KPI 独立完成问题根因分析；\n4. 精通路测与信令分析工具，外场路测经验丰富；\n5. 具备较强的数据分析与自动化能力，能用完成数据处理、统计、可视化与报告自动化；\n6. 具备测试方案与测试体系设计能力，文档输出规范，有良好的跨团队沟通与推动能力；\n7. 能适应外场飞行测试与阶段性出差，工作细致、负责任心强。\n8、具备主动学习与探索AI新工具、新方法的意识，能持续将AI能力融入实际工作场景并独立落地；\n9、对AI工具有实际使用经验，能清晰阐述利用AI解决复杂问题的思路与方法，保持对AI前沿趋势的敏感度；","description":"部门介绍\n为了更好地提升城市即时配送的效率与体验，2017年，美团启动了无人机配送服务的探索，通过科技创新推动履约工具变革，加快建设空地协同的本地即时配送网络。\n在过去的六年里，美团无人机完成了飞行器、自动化机场及智能调度系统的研发工作，实现了研发设计、生产制造、运营运维全链条布局，达成了城市复杂场景物流无人机高频次、高密度、多天时、多天侯运行。\n2023年7月，美团无人机在上海发布了自主研发的第四代无人机，跟此前机型相比，新机型升级了环境适应能力，可在“零下20度至50度”的中雨、中雪、6级风、弱光等环境中稳定飞行，能够适应97%以上国内城市的自然环境要求。\n截至2024年12月，美团无人机已在深圳、北京、上海、广州、南京、迪拜等城市开通53条航线，并累计完成订单超40万单。即时零售配送服务覆盖了办公、社区、景区、市政公园、校园、医疗、图书馆等多种场景。在医疗场景中，美团无人机可围绕医疗血液、检验样本、院前急救物资、特殊药品等医疗物资配送需求建设端到端的全天时急送网络。\n\n岗位职责\n1、主导通信链路测试与覆盖优化\n主导无人机 4G/5G、Wi-Fi 通信链路的测试验证：制定测试策略与指标体系（覆盖、时延、吞吐、切换成功率、丢包率等），组织外场与实验室测试，完成数据采集与深度分析，输出链路性能评估与优化结论；基于航线级数据定位弱覆盖、高干扰、异常切换区域的根因，主导与运营商及网络侧的覆盖优化协同，并跟踪落地效果。\n2、主导通信解决方案场景测试\n主导通信相关解决方案的场景化测试，涵盖 4G/5G 蜂窝网络、Wi-Fi、蓝牙、点对点图传等多种链路，以及多链路冗余、主备切换、多运营商智能切换、APN 专网等组合场景；设计典型城市低空飞行工况（高楼遮挡、多径、密集起降、高峰并发）下的验证方案，确保通信系统在真实运营环境下的可用性与可靠性。\n3、负责测试体系与能力建设\n制定测试方案、用例规范与报告模板，覆盖功能、性能、异常与边界场景；搭建数据采集—分析—报告的自动化工具链，提升测试效率与数据一致性；评审团队测试输出，指导初级工程师成长。\n4、负责问题闭环与优化效果评估\n建立通信问题跟踪与闭环机制，联动研发、网络优化团队复现定位疑难问题，跟踪闭环至验证通过；主导通信链路优化方案（多运营商切换策略、链路冗余与降级策略、天线布局优化、专网接入等）的验证设计与效果量化评估，通过前后对比数据支撑方案迭代决策。\n\n岗位基本要求\n1. 本科及以上学历，通信工程、电子信息工程、计算机、自动化等相关专业；\n2. 3~5 年移动通信测试、网络优化或通信模组测试经验，有独立主导测试项目的完整闭环经验；\n3. 深入理解 4G/5G 空口协议与信令流程（接入、切换、重选、掉话等），能基于信令与 KPI 独立完成问题根因分析；\n4. 精通路测与信令分析工具，外场路测经验丰富；\n5. 具备较强的数据分析与自动化能力，能用完成数据处理、统计、可视化与报告自动化；\n6. 具备测试方案与测试体系设计能力，文档输出规范，有良好的跨团队沟通与推动能力；\n7. 能适应外场飞行测试与阶段性出差，工作细致、负责任心强。\n8、具备主动学习与探索AI新工具、新方法的意识，能持续将AI能力融入实际工作场景并独立落地；\n9、对AI工具有实际使用经验，能清晰阐述利用AI解决复杂问题的思路与方法，保持对AI前沿趋势的敏感度；\n\n具备以下条件优先\n1、有无人机、低空经济、车联网等行业通信测试经验；\n2、有测试自动化平台或工具链搭建经验；\n3、熟悉 5G 通信模组或 CPE 的测试与问题定位；\n4、有 Wi-Fi / 蓝牙射频性能或兼容性测试经验；\n5、了解点对点图传链路原理与测试方法；\n6、有运营商网络优化（覆盖优化、参数优化）项目经验；\n\n岗位亮点\n1. 真场景、真数据、真闭环：通信解决方案直接百万真实配送订单的安全运行。每一条航线、每一次切换、每一份覆盖分析，都对应真实商业运营。\n2. 站上低空经济风口：低空经济国家战略，国内\"连线成面\"常态化运营的城市低空航网，持有全国覆盖全境的民用无人驾驶航空器运营合格证。\n3. 技术栈全链路覆盖：4G/5G 蜂窝、Wi-Fi、蓝牙、点对点图传、APN 专网、多链路冗余切换——一次岗位覆盖运营商网优 + 终端测试 + 解决方案验证三重技术视野，还能接触雷达感知、飞控、调度系统的协同设计。\n4. 从 0 到 1 搭建测试体系：不主导制定通信方案及测试策略、指标体系、自动化工具链。\n5. 深圳核心团队，资源拉满：外场航线 + 实验室 + 屏蔽房 + 运营商联合测试资源全配齐，背靠美团研发体系，清晰晋升通道。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4225235458","sourceKey":"meituan_social","company":"美团","title":"销量预测专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4225235458&jobShareType=1","duty":"1、销量预测：负责城市、多品类长短周期的销量预测工作。需综合历史销售数据、运营策略、区域特色及市场竞争态势，主动运用AI/ML预测工具（如时序模型、梯度提升、神经网络等），输出精准预测结果，为订货、库存调配及人力资源安排提供核心数据支持；\n2、闭环与优化：持续监控并分析预测准确率，借助AI手段自动识别偏差根因，快速推动整改措施落地。通过预测模型的持续迭代和AI驱动的自动化闭环机制，不断提升预测精准度，并对核心预测指标负责；\n3、数据体系与归因分析：构建和完善覆盖城市、仓等多维度的预测监控与数据分析体系。能独立运用AI工具对业务运营结果进行深度下钻归因分析，沉淀有效策略，并主导推进预测流程或工具的产品化、自动化，提升整体效率；\n4、业务协同：深度融入运营模式，理解商品运营策略、促销规划及库存管理逻辑。通过AI赋能的精准预测，有效协同采购、供应链及运营团队，优化库存水平，保障商品充足供给（尤其是爆款与新品），降低滞销风险，提升库存周转效率，助力用户体验与经营效率双提升。","requirements":"1、经验背景：3年及以上大型零售企业（商超、便利店、品牌连锁等）供应链计划或需求预测相关经验；熟悉线下零售业务运作流程和关键指标者优先；有AI/ML预测项目落地经验者优先；\n2、数据与AI能力：具备扎实的数据统计和分析能力，能熟练使用数据分析工具进行数据提取、清洗和分析；熟悉常用预测模型及其应用场景；能独立使用或评估AI/ML工具（如Python、时序模型、AutoML等），有自动化预测体系搭建经验者加分；\n3、业务与逻辑思维：具备严谨的逻辑分析和系统性思维能力，对线下零售业务有高度敏感度；能洞察内外部因素对销量的潜在影响；能将业务洞察转化为AI模型输入，推动预测结果持续迭代；\n4、沟通与推动力：具备出色的跨部门沟通协调能力，能主动协同采购、运营、供应链等团队推动预测落地；具备AI工具推广和赋能团队的意愿与能力，有强烈责任心和自驱力。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、销量预测：负责城市、多品类长短周期的销量预测工作。需综合历史销售数据、运营策略、区域特色及市场竞争态势，主动运用AI/ML预测工具（如时序模型、梯度提升、神经网络等），输出精准预测结果，为订货、库存调配及人力资源安排提供核心数据支持；\n2、闭环与优化：持续监控并分析预测准确率，借助AI手段自动识别偏差根因，快速推动整改措施落地。通过预测模型的持续迭代和AI驱动的自动化闭环机制，不断提升预测精准度，并对核心预测指标负责；\n3、数据体系与归因分析：构建和完善覆盖城市、仓等多维度的预测监控与数据分析体系。能独立运用AI工具对业务运营结果进行深度下钻归因分析，沉淀有效策略，并主导推进预测流程或工具的产品化、自动化，提升整体效率；\n4、业务协同：深度融入运营模式，理解商品运营策略、促销规划及库存管理逻辑。通过AI赋能的精准预测，有效协同采购、供应链及运营团队，优化库存水平，保障商品充足供给（尤其是爆款与新品），降低滞销风险，提升库存周转效率，助力用户体验与经营效率双提升。\n\n岗位基本要求\n1、经验背景：3年及以上大型零售企业（商超、便利店、品牌连锁等）供应链计划或需求预测相关经验；熟悉线下零售业务运作流程和关键指标者优先；有AI/ML预测项目落地经验者优先；\n2、数据与AI能力：具备扎实的数据统计和分析能力，能熟练使用数据分析工具进行数据提取、清洗和分析；熟悉常用预测模型及其应用场景；能独立使用或评估AI/ML工具（如Python、时序模型、AutoML等），有自动化预测体系搭建经验者加分；\n3、业务与逻辑思维：具备严谨的逻辑分析和系统性思维能力，对线下零售业务有高度敏感度；能洞察内外部因素对销量的潜在影响；能将业务洞察转化为AI模型输入，推动预测结果持续迭代；\n4、沟通与推动力：具备出色的跨部门沟通协调能力，能主动协同采购、运营、供应链等团队推动预测落地；具备AI工具推广和赋能团队的意愿与能力，有强烈责任心和自驱力。\n\n具备以下条件优先\n可以熟练使用sql等技能优先\n\n岗位亮点\n1、深入核心业务，全面掌握新零售背景下的运作逻辑与挑战，直接参与AI预测体系的从0到1搭建；\n2、在真实复杂业务场景中，以AI工具为杠杆，锤炼兼具广度和深度的供应链计划与预测能力；\n3、与多元背景的专业团队协作，共同推动零售行业的AI化、智能化升级，站在行业变革前沿。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4450402567","sourceKey":"meituan_social","company":"美团","title":"KA口腔大客户销售（北京/武汉）","city":"北京市/武汉市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4450402567&jobShareType=1","duty":"1、根据业务目标，倒推动作，制定有效的策略及行动方案，达成结果；\n2、熟悉平台商业产品，结合客户需求，为客户提供定制化整合营销方案，并完成项目合作推进，为客户提供运营玩法、资源组合、广告预算等建议，最终完成新产品的开拓；\n3、擅长数据分析，如行业趋势分析、用户画像分析、分地域市场分析、对标分析、流量及转化率等维度，帮助合作客户得出有效的结论，并为客户提供对应的广告投放及运营建议；\n4、建立和维系与客户的良好关系，深挖客户需求，寻找新的合作机会，不断提升客户价值；\n5、与公司各部门配合，及时处理客户的反馈、投诉和建议，提高客户满意度。","requirements":"1、本科及以上学历；\n2、3-5年以上大客户销售或者运营经验；\n3、具有业务节奏的拆解能力，能梳理、管理客户的业务阶段，有决策链的判断技术，能灵活跟进业务进展，掌握并推进项目的步骤；\n4、良好的沟通能力，逻辑清晰，能够制作解决方案，应对高层商务谈判，有Call High（拜访高层）的方法和策略；\n5、具有良好的团队合作精神，勤奋、踏实，善于学习与思考，对行业信息敏感，执行力强；\n6、过往从事医疗/医美等行业，或者有知名互联网企业工作经验者优先。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1、根据业务目标，倒推动作，制定有效的策略及行动方案，达成结果；\n2、熟悉平台商业产品，结合客户需求，为客户提供定制化整合营销方案，并完成项目合作推进，为客户提供运营玩法、资源组合、广告预算等建议，最终完成新产品的开拓；\n3、擅长数据分析，如行业趋势分析、用户画像分析、分地域市场分析、对标分析、流量及转化率等维度，帮助合作客户得出有效的结论，并为客户提供对应的广告投放及运营建议；\n4、建立和维系与客户的良好关系，深挖客户需求，寻找新的合作机会，不断提升客户价值；\n5、与公司各部门配合，及时处理客户的反馈、投诉和建议，提高客户满意度。\n\n岗位基本要求\n1、本科及以上学历；\n2、3-5年以上大客户销售或者运营经验；\n3、具有业务节奏的拆解能力，能梳理、管理客户的业务阶段，有决策链的判断技术，能灵活跟进业务进展，掌握并推进项目的步骤；\n4、良好的沟通能力，逻辑清晰，能够制作解决方案，应对高层商务谈判，有Call High（拜访高层）的方法和策略；\n5、具有良好的团队合作精神，勤奋、踏实，善于学习与思考，对行业信息敏感，执行力强；\n6、过往从事医疗/医美等行业，或者有知名互联网企业工作经验者优先。\n\n具备以下条件优先\n1.消费医疗行业（口腔、医美、眼科）的市场运营经验优先；\n2.知名互联网平台企业工作经验者优先；\n\n岗位亮点\n大厂KA序列，具备更有市场认可度的业务专业序列，对于个人的业务专业度打造、产品线深度学习均有提升空间","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4596519179","sourceKey":"meituan_social","company":"美团","title":"点评技术-AI Builder 团队负责人","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4596519179&jobShareType=1","duty":"1. 团队建设与管理\n- 组建并管理点评 AI Builder 团队；\n- 明确团队能力模型，建立 Agent 工程、AI 工具集成、Prompt 工程、AI 评测等方向的梯队建设；\n- 推动团队文化建设，打造务实、自驱、开放、追求卓越的工程师团队。\n\n2. 面向业务的 Agent 工具建设\n- 深入了解点评各业务团队的工作流程和痛点；\n- 设计和建设面向业务团队的通用 Agent 交互平台，支持低代码/无代码创建、调试、部署 AI Agent，让非技术同学也能轻松使用 AI 能力；\n- 建设各类AI agent应用层能力。\n\n3. 业务工作流程识别与 AI 提效\n- 深度与业务、产品、运营高频共创，系统性梳理各团队的核心工作流程；\n- 识别适合 AI 介入的环节，评估提效潜力和实施路径；\n- 结合公司内部 AI 工具和外部 AI 能力，设计并落地提效方案；\n- 推动“人用工具 → 工具找人”的主动服务型产品能力转变。\n\n4. Agentic 架构与技术体系建设\n- 设计、实现和维护先进的 Agentic System，结合 Agentic RAG、Cognitive Architecture、Agentic Workflow 等前沿技术；\n- 解决在多模态模型、多 Agent 协作场景下的可扩展性和可靠性问题；\n- 完成存量 Tools/系统的低成本集成，支持业务团队自建 Skill 和 workflow；\n- 结合 CodeAgent 和 Spec Coding 模式，降低 AI 应用的构建门槛。\n\n5. 数据与知识体系建设\n- 保证底层数据口径统一，面向 Agent 友好；\n- 提供方便的企业数据集成和查询能力；\n- 低成本完成知识库的生产、管理、消费流程，保证知识无过时、冲突、冗余；\n- 完善基于测评驱动的 AI 应用生产流程，快速评估 LLM 和 Agent 效果。\n\n6. 模型能力与 AI 生态建设\n- 周期性进行 SOTA 模型评测，根据场景选择高性价比模型；\n- 协同训练师团队完成模型所需的训练数据生产、标注任务；\n- 跟踪内外部 AI 工具生态，评估并引入适合点评场景的 AI 能力。","requirements":"1. 5年+ 研发或 AI 应用相关经验，有团队管理经验（50人+）；\n2. 对 Agentic System 有扎实的理解，熟悉 LangChain、LangGraph、CrewAI 等框架；\n3. 精通 AI Coding，有 Spec Coding 实践经验；\n4. 曾直接与业务方合作，深入了解业务需求，并能将业务语言转化为技术方案；\n5. 出色的沟通和跨团队协作能力，能够有效推动技术方案在业务方的落地；\n6. 在构建可靠、可扩展、高性能系统方面有良好判断力，关注交付质量和工程体验；\n7. 对 AI 技术趋势有敏锐洞察，能快速学习和应用新工具、新框架。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1. 团队建设与管理\n- 组建并管理点评 AI Builder 团队；\n- 明确团队能力模型，建立 Agent 工程、AI 工具集成、Prompt 工程、AI 评测等方向的梯队建设；\n- 推动团队文化建设，打造务实、自驱、开放、追求卓越的工程师团队。\n\n2. 面向业务的 Agent 工具建设\n- 深入了解点评各业务团队的工作流程和痛点；\n- 设计和建设面向业务团队的通用 Agent 交互平台，支持低代码/无代码创建、调试、部署 AI Agent，让非技术同学也能轻松使用 AI 能力；\n- 建设各类AI agent应用层能力。\n\n3. 业务工作流程识别与 AI 提效\n- 深度与业务、产品、运营高频共创，系统性梳理各团队的核心工作流程；\n- 识别适合 AI 介入的环节，评估提效潜力和实施路径；\n- 结合公司内部 AI 工具和外部 AI 能力，设计并落地提效方案；\n- 推动“人用工具 → 工具找人”的主动服务型产品能力转变。\n\n4. Agentic 架构与技术体系建设\n- 设计、实现和维护先进的 Agentic System，结合 Agentic RAG、Cognitive Architecture、Agentic Workflow 等前沿技术；\n- 解决在多模态模型、多 Agent 协作场景下的可扩展性和可靠性问题；\n- 完成存量 Tools/系统的低成本集成，支持业务团队自建 Skill 和 workflow；\n- 结合 CodeAgent 和 Spec Coding 模式，降低 AI 应用的构建门槛。\n\n5. 数据与知识体系建设\n- 保证底层数据口径统一，面向 Agent 友好；\n- 提供方便的企业数据集成和查询能力；\n- 低成本完成知识库的生产、管理、消费流程，保证知识无过时、冲突、冗余；\n- 完善基于测评驱动的 AI 应用生产流程，快速评估 LLM 和 Agent 效果。\n\n6. 模型能力与 AI 生态建设\n- 周期性进行 SOTA 模型评测，根据场景选择高性价比模型；\n- 协同训练师团队完成模型所需的训练数据生产、标注任务；\n- 跟踪内外部 AI 工具生态，评估并引入适合点评场景的 AI 能力。\n\n岗位基本要求\n1. 5年+ 研发或 AI 应用相关经验，有团队管理经验（50人+）；\n2. 对 Agentic System 有扎实的理解，熟悉 LangChain、LangGraph、CrewAI 等框架；\n3. 精通 AI Coding，有 Spec Coding 实践经验；\n4. 曾直接与业务方合作，深入了解业务需求，并能将业务语言转化为技术方案；\n5. 出色的沟通和跨团队协作能力，能够有效推动技术方案在业务方的落地；\n6. 在构建可靠、可扩展、高性能系统方面有良好判断力，关注交付质量和工程体验；\n7. 对 AI 技术趋势有敏锐洞察，能快速学习和应用新工具、新框架。\n\n具备以下条件优先\n1. 有团队搭建或从 0 到 1 建设 AI 应用平台的经验；\n2. 熟悉 AI 工具生态（Multica、Dify、Antigravity等）；\n3. 有 Agent 评测体系设计经验，熟悉 AgentBench、GAIA 等评测框架；\n4. 在 Prompt Engineering、RAG 系统设计、LLM 微调方面有深度实践；\n5. 有推动组织级 AI 转型或 AI 工具落地推广的成功案例。\n\n岗位亮点\n1. 参与核心AI能力建设，推动技术在真实业务场景中的规模化应用。  \n2. 与技术团队协作，接触前沿AI技术与海量数据资源。  \n3. 工作地点灵活，支持北京或上海办公。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4456961971","sourceKey":"meituan_social","company":"美团","title":"履约-众包站长-东莞","city":"东莞市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4456961971&jobShareType=1","duty":"1.对负责区域制定配送体验优化方案并有效地执行方案，同时对执行结果进行有效复盘；\n2.重点围绕骑手的招聘，培训，提效，留存，淘汰等环节开展工作，保证负责区域的运力活力以及提升履约服务质量，提升用户体验；\n3.处理由履约原因产生的相关商户问题，以及能够良好地协同其他部门进行问题解决；\n4.对负责的骑手运营项目，能够做出短、中、长期的规划，制定高效的运营方案并达成业务结果。","requirements":"1.本科及以上学历，有物流、互联网、O2O等相关行业或运营经验者优先；\n2.熟练运用互联网常见分析工具，掌握物流数据分析方法论；\n3.业务灵敏度强，能从数据运营中发现问题，并提出解决路径；\n4.有较强的自驱与学习能力，有长远职业发展的规划。","description":"部门介绍\n美团配送是以科技为内核的即时物流品牌，利用高效、稳定、广阔的配送网络和前沿科技能力为各行业客户提供涵盖商流物流一体化、流量赋能、行业定制化即时配送、末端配送、前置仓等服务在内的全方位同城物流综合解决方案。\n作为科技创新和智慧物流的实践者，美团配送在人工智能（AI）、5G应用、物联网（IoT）、云计算等多维度不断探索科创蓝海，让同城物流进入数智化时代。美团配送在IoT智能设备、外卖柜、换电网络、无人配送体系等硬件设施与服务上不断推陈出新，持续优化骑手、消费者、商家体验；自研同城物流系统，通过智能分析为用户提供更便捷的生活方式，为商家提供更高效的履约服务。\n加入我们，一起把世界送到消费者手中！\n\n岗位职责\n1.对负责区域制定配送体验优化方案并有效地执行方案，同时对执行结果进行有效复盘；\n2.重点围绕骑手的招聘，培训，提效，留存，淘汰等环节开展工作，保证负责区域的运力活力以及提升履约服务质量，提升用户体验；\n3.处理由履约原因产生的相关商户问题，以及能够良好地协同其他部门进行问题解决；\n4.对负责的骑手运营项目，能够做出短、中、长期的规划，制定高效的运营方案并达成业务结果。\n\n岗位基本要求\n1.本科及以上学历，有物流、互联网、O2O等相关行业或运营经验者优先；\n2.熟练运用互联网常见分析工具，掌握物流数据分析方法论；\n3.业务灵敏度强，能从数据运营中发现问题，并提出解决路径；\n4.有较强的自驱与学习能力，有长远职业发展的规划。\n\n具备以下条件优先\n1.具有2年及以上物流运营经验者优先；\n2.具有运营项目管理经验者优先；\n3.对物流行业有强烈兴趣，有韧性有规划。\n\n岗位亮点\n1.能够参与并推动履约运营体系完善与搭建；\n2.可参与到跨部门重点项目协调推进；\n3.可与优秀物流运营者共同成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4670366749","sourceKey":"meituan_social","company":"美团","title":"调度主管","city":"佛山市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4670366749&jobShareType=1","duty":"1. 负责日常运输任务的调度安排，确保车辆和人员合理配置，保障配送时效。  \n2. 监控运输过程中的异常情况，及时协调处理并反馈，提升运营效率。  \n3. 管理调度团队，制定排班计划，监督团队执行标准作业流程。  \n4. 与仓储、客服及外部承运商保持沟通，优化配送路径和资源配置。","requirements":"1. 大学专科及以上学历，物流、运输或相关专业优先。  \n2. 具备2年以上物流调度或相关岗位工作经验。  \n3. 熟悉佛山及周边地区交通路线，具备基本的路线规划能力。  \n4. 具备较强的沟通协调能力和团队管理能力，能带领70人团队高效运作。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责日常运输任务的调度安排，确保车辆和人员合理配置，保障配送时效。  \n2. 监控运输过程中的异常情况，及时协调处理并反馈，提升运营效率。  \n3. 管理调度团队，制定排班计划，监督团队执行标准作业流程。  \n4. 与仓储、客服及外部承运商保持沟通，优化配送路径和资源配置。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、运输或相关专业优先。  \n2. 具备2年以上物流调度或相关岗位工作经验。  \n3. 熟悉佛山及周边地区交通路线，具备基本的路线规划能力。  \n4. 具备较强的沟通协调能力和团队管理能力，能带领70人团队高效运作。\n\n岗位亮点\n1. 提供完善的培训体系和职业发展通道。  \n2. 团队规模大，管理挑战与成长机会并存。  \n3. 工作地点位于佛山市，交通便利，生活配套齐全。  \n4. 绩效激励机制明确，多劳多得，发展空间广阔。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4527890989","sourceKey":"meituan_social","company":"美团","title":"快乐猴-门店拓展PMO","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4527890989&jobShareType=1","duty":"一、项目推进与管控\n负责项目全生命周期管理，为项目从线索到开业的时效性负责\n利用专业经验助力门店开发/拓展同事提报项目，确保提报质量与效率\n识别并预警项目商务与时效相关风险，提前制定应对方案\n二、跨方协同与问题解决\n协同项目相关方，推动解决项目中的 corner case 及复杂问题\n建立并维护高效的跨团队沟通机制，确保信息同步顺畅\n三、方法论沉淀与能力建设\n具备总结提炼能力，将项目中遇到的问题转化为通用化解决方案\n持续优化项目管理流程与工具，提升团队整体效能\n四、项目基础事务管理\n完成项目中必要的基础事务性工作（盖章、邮寄等）\n严格遵守公司盖章标准与规则，确保合规操作","requirements":"一、基本条件\n1.本科及以上学历，项目管理、工商管理、理工类相关专业优先\n2.5年以上项目管理/PMO相关工作经验，有互联网或零售行业背景优先\n二、专业能力\n1.熟悉项目管理方法论，具备项目全生命周期管控能力\n2.具备优秀的风险识别与问题解决能力，能独立推动复杂问题落地\n3.具备较强的总结提炼能力，能将个案经验转化为通用方法论\n三、综合素质\n1.出色的跨团队沟通与协调能力，能有效撮合多方诉求\n2.责任心强，对项目结果有 ownership\n3.能适应多项目并行的工作节奏\n4.工作细致严谨，对盖章等合规事务有高度责任心\n四、加分项\n1.有门拓/IC提报相关经验\n2.有零售、本地生活或电商行业项目运营经验\n3.具备流程优化或体系建设经验","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n一、项目推进与管控\n负责项目全生命周期管理，为项目从线索到开业的时效性负责\n利用专业经验助力门店开发/拓展同事提报项目，确保提报质量与效率\n识别并预警项目商务与时效相关风险，提前制定应对方案\n二、跨方协同与问题解决\n协同项目相关方，推动解决项目中的 corner case 及复杂问题\n建立并维护高效的跨团队沟通机制，确保信息同步顺畅\n三、方法论沉淀与能力建设\n具备总结提炼能力，将项目中遇到的问题转化为通用化解决方案\n持续优化项目管理流程与工具，提升团队整体效能\n四、项目基础事务管理\n完成项目中必要的基础事务性工作（盖章、邮寄等）\n严格遵守公司盖章标准与规则，确保合规操作\n\n岗位基本要求\n一、基本条件\n1.本科及以上学历，项目管理、工商管理、理工类相关专业优先\n2.5年以上项目管理/PMO相关工作经验，有互联网或零售行业背景优先\n二、专业能力\n1.熟悉项目管理方法论，具备项目全生命周期管控能力\n2.具备优秀的风险识别与问题解决能力，能独立推动复杂问题落地\n3.具备较强的总结提炼能力，能将个案经验转化为通用方法论\n三、综合素质\n1.出色的跨团队沟通与协调能力，能有效撮合多方诉求\n2.责任心强，对项目结果有 ownership\n3.能适应多项目并行的工作节奏\n4.工作细致严谨，对盖章等合规事务有高度责任心\n四、加分项\n1.有门拓/IC提报相关经验\n2.有零售、本地生活或电商行业项目运营经验\n3.具备流程优化或体系建设经验\n\n具备以下条件优先\n具备拓展/资产管理岗位工作经验优先\n\n岗位亮点\n1.创新型项目，成长空间广阔；\n2.能够和做事、目标感、使命感强的优秀团队合作，一起拿结果；\n3.公司正全力推进AI化转型，打造极具吸引力的AI-Native工作环境。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4601319929","sourceKey":"meituan_social","company":"美团","title":"Keeta Kuwait — User Growth Operations","city":"科威特城","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4601319929&jobShareType=1","duty":"一、用户生命周期增长策略User Lifecycle Growth Strategy\n\n覆盖用户全生命周期，制定并执行分阶段增长策略，包括新客拉新、老客激活与留存、沉流用户召回及裂变增长，推动用户规模与质量持续提升。\n推动增长策略从策划、上线到复盘的全链路落地，协调设计、产品、数据、投放等团队完成交付。\nDevelop and execute growth strategies across the full user lifecycle, including new user acquisition, active user retention, churned user reactivation, and referral growth, continuously improving user scale and quality.\nDrive end-to-end execution from strategy design through launch to retrospective, coordinating with Design, Product, Data, and Marketing teams.\n\n二、流量运营与流量分发Traffic Operations & Traffic Distribution\n\n负责全链路流量运营，统筹站内资源位（首页 Banner、弹窗、Push 推送、频道页、搜索结果页、推荐位等）的规划、排期与效果评估，提升站内流量利用效率。\n负责合作业务流量分发，广告流量运营、与合作业务建立流量合作机制，通过联合运营、资源互换等方式获取优质用户流量。\n建立流量分级评估体系（站内 / 付费 / 合作/ 触达），持续优化流量结构，降低对单一来源的依赖。\nOwn full-funnel traffic operations, managing in-app resource placements (homepage banners, pop-ups, Push notifications, channel pages, search results, recommendation slots, etc.) including planning, scheduling, and performance evaluation to improve in-app traffic utilization.\nDrive traffic distribution through advertisement or strategic partnerships with external partners , acquiring high-quality user traffic through co-marketing, resource exchange, and joint operations.\nBuild a traffic tier evaluation framework (in-app / paid / partnerships) to continuously optimize traffic mix and reduce dependency on any single source.\n\n三、用户增长工具与产品运营User Growth Tools & Product Operations\n\n负责用户增长工具体系的设计、搭建与运营，打造可持续的用户增长产品能力：设计会员等级、权益与成长路径，提升用户忠诚度与 LTV；搭建积分获取与兑换机制，驱动用户高频互动与复购；设计签到、任务、排行榜等游戏化玩法，提升用户参与度与活跃度\n与产品团队紧密协作，推动增长工具的需求落地、功能迭代与数据优化。\nDesign, build, and operate user growth tool systems to create sustainable growth product capabilities: Design membership tiers, benefits, and progression paths to improve user loyalty and LTV; Build points earning and redemption mechanisms to drive high-frequency engagement and reorder; Design gamified experiences including check-ins, tasks, leaderboards, etc., to boost user participation and activity\nWork closely with Product teams to drive growth tool requirements, feature iterations, and data optimization.\n\n四、数据驱动增长优化Data-Driven Growth Optimization\n\n与数据团队紧密合作，建立增长核心指标监控体系（DAU、新客转化率、复购率、留存率、LTV、补贴效率、裂变系数等），搭建增长数据看板。通过 A/B 测试等方式验证运营策略效果，基于数据反馈快速迭代优化。定期输出用户增长专题分析，为策略决策提供数据支持。\nCollaborate closely with the Data team to establish core growth metrics dashboards (DAU, new-user conversion rate, reorder rate, retention rate, LTV, subsidy efficiency, referral coefficient, etc.).Validate strategies through A/B testing and iterate rapidly based on data feedback.Produce regular user growth analysis reports to support strategic decision-making.\n\n五、本地化用户洞察与市场洞察Localization & Market Intelligence\n\n深入理解科威特本地用户行为、文化偏好、消费习惯及社交媒体生态，提升运营策略本地化程度。关注竞争对手用户策略动态，定期输出市场分析报告。结合本地社交媒体热点、节日氛围与用户兴趣，策划具有传播性的增长玩法。\nDeeply understand Kuwait's local user behavior, cultural preferences, consumption habits, and social media ecosystem to enhance strategy localization.Track competitor user growth strategies and provide regular competitive intelligence reports.Leverage local social trends, festival atmosphere, and user interests to design shareable and viral growth initiatives.","requirements":"本科及以上学历，Marketing、Business、Management 等相关专业优先。5 年以上互联网、本地生活、电商或餐饮行业营销运营经验。有 Campaign Operations / Growth Marketing / Brand Marketing 经验优先。熟悉营销活动全流程，有较强项目管理与跨团队协同能力。数据敏感度高，能够基于数据分析优化营销策略。英文可作为工作语言，阿拉伯语能力加分。具备较强 owner mindset、执行力。\n• Proficient in AI tools (e.g., ChatGPT, Copilot, or equivalent); able to integrate AI into daily workflows to drive tangible efficiency gains.\n• Proactively explores new AI tools; strong AI learning mindset — comfortable experimenting and documenting best practices in real business contexts. owner mindset。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n一、用户生命周期增长策略User Lifecycle Growth Strategy\n\n覆盖用户全生命周期，制定并执行分阶段增长策略，包括新客拉新、老客激活与留存、沉流用户召回及裂变增长，推动用户规模与质量持续提升。\n推动增长策略从策划、上线到复盘的全链路落地，协调设计、产品、数据、投放等团队完成交付。\nDevelop and execute growth strategies across the full user lifecycle, including new user acquisition, active user retention, churned user reactivation, and referral growth, continuously improving user scale and quality.\nDrive end-to-end execution from strategy design through launch to retrospective, coordinating with Design, Product, Data, and Marketing teams.\n\n二、流量运营与流量分发Traffic Operations & Traffic Distribution\n\n负责全链路流量运营，统筹站内资源位（首页 Banner、弹窗、Push 推送、频道页、搜索结果页、推荐位等）的规划、排期与效果评估，提升站内流量利用效率。\n负责合作业务流量分发，广告流量运营、与合作业务建立流量合作机制，通过联合运营、资源互换等方式获取优质用户流量。\n建立流量分级评估体系（站内 / 付费 / 合作/ 触达），持续优化流量结构，降低对单一来源的依赖。\nOwn full-funnel traffic operations, managing in-app resource placements (homepage banners, pop-ups, Push notifications, channel pages, search results, recommendation slots, etc.) including planning, scheduling, and performance evaluation to improve in-app traffic utilization.\nDrive traffic distribution through advertisement or strategic partnerships with external partners , acquiring high-quality user traffic through co-marketing, resource exchange, and joint operations.\nBuild a traffic tier evaluation framework (in-app / paid / partnerships) to continuously optimize traffic mix and reduce dependency on any single source.\n\n三、用户增长工具与产品运营User Growth Tools & Product Operations\n\n负责用户增长工具体系的设计、搭建与运营，打造可持续的用户增长产品能力：设计会员等级、权益与成长路径，提升用户忠诚度与 LTV；搭建积分获取与兑换机制，驱动用户高频互动与复购；设计签到、任务、排行榜等游戏化玩法，提升用户参与度与活跃度\n与产品团队紧密协作，推动增长工具的需求落地、功能迭代与数据优化。\nDesign, build, and operate user growth tool systems to create sustainable growth product capabilities: Design membership tiers, benefits, and progression paths to improve user loyalty and LTV; Build points earning and redemption mechanisms to drive high-frequency engagement and reorder; Design gamified experiences including check-ins, tasks, leaderboards, etc., to boost user participation and activity\nWork closely with Product teams to drive growth tool requirements, feature iterations, and data optimization.\n\n四、数据驱动增长优化Data-Driven Growth Optimization\n\n与数据团队紧密合作，建立增长核心指标监控体系（DAU、新客转化率、复购率、留存率、LTV、补贴效率、裂变系数等），搭建增长数据看板。通过 A/B 测试等方式验证运营策略效果，基于数据反馈快速迭代优化。定期输出用户增长专题分析，为策略决策提供数据支持。\nCollaborate closely with the Data team to establish core growth metrics dashboards (DAU, new-user conversion rate, reorder rate, retention rate, LTV, subsidy efficiency, referral coefficient, etc.).Validate strategies through A/B testing and iterate rapidly based on data feedback.Produce regular user growth analysis reports to support strategic decision-making.\n\n五、本地化用户洞察与市场洞察Localization & Market Intelligence\n\n深入理解科威特本地用户行为、文化偏好、消费习惯及社交媒体生态，提升运营策略本地化程度。关注竞争对手用户策略动态，定期输出市场分析报告。结合本地社交媒体热点、节日氛围与用户兴趣，策划具有传播性的增长玩法。\nDeeply understand Kuwait's local user behavior, cultural preferences, consumption habits, and social media ecosystem to enhance strategy localization.Track competitor user growth strategies and provide regular competitive intelligence reports.Leverage local social trends, festival atmosphere, and user interests to design shareable and viral growth initiatives.\n\n岗位基本要求\n本科及以上学历，Marketing、Business、Management 等相关专业优先。5 年以上互联网、本地生活、电商或餐饮行业营销运营经验。有 Campaign Operations / Growth Marketing / Brand Marketing 经验优先。熟悉营销活动全流程，有较强项目管理与跨团队协同能力。数据敏感度高，能够基于数据分析优化营销策略。英文可作为工作语言，阿拉伯语能力加分。具备较强 owner mindset、执行力。\n• Proficient in AI tools (e.g., ChatGPT, Copilot, or equivalent); able to integrate AI into daily workflows to drive tangible efficiency gains.\n• Proactively explores new AI tools; strong AI learning mindset — comfortable experimenting and documenting best practices in real business contexts. owner mindset。\n\n岗位亮点\n公司发展潜力高，国际化氛围充足个人成长空间\n• Full AI toolkit at your fingertips — you won't just use AI; you'll define what AI-driven operations look like in your market.\n• Pioneer AI-enhanced workflows with cutting-edge tools, shaping the future of your function.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4735710220","sourceKey":"meituan_social","company":"美团","title":"美团企业版-方案交付顾问（北京）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4735710220&jobShareType=1","duty":"1.负责企业福利用餐、招待用餐、差旅、供应链分销等企业消费场景，大中型客户的需求调研、方案咨询、系统规划、和系统实施上线工作；\n2.配合销售团队，提供售前阶段的系统方案咨询服务，借助AI工具分析企业数据，生成个性化方案建议，提升方案输出效率，提高项目赢单效率和成功率，为企业客户提供企业消费优质解决方案；签约后完成系统配置、系统集成相关工作，保障项目如期、顺利上线，对项目交付的效率和质量负责；\n3.负责内部组织能力建设项目的执行落地，包括基础方案库建设，重点聚类方案、客户案例的编写、市场活动宣讲、销售团队培训、内部方案交付流程优化、效能提升等；\n4.持续关注用户与行业，提炼通用需求和方案，推动底层解决方案能力提升。","requirements":"1.本科及以上学历，3年以上工作经验；\n2.学习能力优秀，能够快速学习、转化、吸收、输出新的业务知识；\n3.优秀的逻辑性，具备较强的结构化思考和结构化表达能力；\n4.有较强的成长意愿和成就动机，能够积极主动推进工作落地，拿到结果；\n5.认真严谨，做事踏实，重视专业基本功、通用基本功的提升；\n6.具备数据驱动决策意识，了解并能使用至少一种AI辅助工具，能将AI能力融入日常工作；\n7.良好的工作、学习、生活习惯。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.负责企业福利用餐、招待用餐、差旅、供应链分销等企业消费场景，大中型客户的需求调研、方案咨询、系统规划、和系统实施上线工作；\n2.配合销售团队，提供售前阶段的系统方案咨询服务，借助AI工具分析企业数据，生成个性化方案建议，提升方案输出效率，提高项目赢单效率和成功率，为企业客户提供企业消费优质解决方案；签约后完成系统配置、系统集成相关工作，保障项目如期、顺利上线，对项目交付的效率和质量负责；\n3.负责内部组织能力建设项目的执行落地，包括基础方案库建设，重点聚类方案、客户案例的编写、市场活动宣讲、销售团队培训、内部方案交付流程优化、效能提升等；\n4.持续关注用户与行业，提炼通用需求和方案，推动底层解决方案能力提升。\n\n岗位基本要求\n1.本科及以上学历，3年以上工作经验；\n2.学习能力优秀，能够快速学习、转化、吸收、输出新的业务知识；\n3.优秀的逻辑性，具备较强的结构化思考和结构化表达能力；\n4.有较强的成长意愿和成就动机，能够积极主动推进工作落地，拿到结果；\n5.认真严谨，做事踏实，重视专业基本功、通用基本功的提升；\n6.具备数据驱动决策意识，了解并能使用至少一种AI辅助工具，能将AI能力融入日常工作；\n7.良好的工作、学习、生活习惯。\n\n具备以下条件优先\n1.对于银行、运营商、电力等行业有丰富的项目经验和认知。\n2.解决方案专家、售前顾问、解决方案工程师、解决方案架构师、业务咨询顾问、项目经理、产品经理、实施顾问、实施经理从业经验者优先；\n3.经历过一些失败和挫折，仍然保持乐观心态，并从中汲取经验教训，收获个人成长加分\n\n岗位亮点\n【广阔市场】 企业消费线上化万亿级市场，广阔空间，大有可为；\n【优质供给】 依托美团强大的自建多品类供应链以及本地化配送履约能力，能够满足企业多场景、多品类一站式企业消费管理需求，拥有核心竞争力和强大护城河；\n【靠谱业务】 业务成熟稳健，已有众多行业标杆客户，持续高速健康增长，前途光明；\n【友好团队】 团队氛围和谐有爱、积极上进、正直诚信、实事求是、讲究科学，重视业务、团队与个人的共赢发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4736564146","sourceKey":"meituan_social","company":"美团","title":"AI 产品经理（FDE）","city":"成都市/北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4736564146&jobShareType=1","duty":"1、负责餐饮 SaaS AI 数字员工方向的产品能力建设，探索 AI Agent 在商家经营场景中的落地，对产品的使用效果和用户满意度负责\n2、根据市场需求和资源状况，深入研究目标商户需求，挖掘商户经营过程中可由 AI 承担的工作场景，并持续进行迭代及优化\n3、持续跟踪业务指标，根据数据和反馈，验证 AI 能力在实际经营中的价值，推动项目落地，为项目成果负责\n4、研究用户行为以及行业动态，不断优化产品，保持所负责产品在市场上的竞争力\n5、持续关注 AI 领域先进理念和技术发展，发掘新思路、新方法、新技术与业务结合的机会点，实现产品创新\n6、针对客户一些需求可以现场提供FDE的开发部署能力。","requirements":"1、本科及以上学历，3 年以上 B 端产品经验，有 SaaS 或 AI 产品（Agent/大模型应用）落地经验者优先\n2、具备清晰的产品思路，良好的业务需求分析、产品需求分解、产品设计及项目管理能力\n3、有良好的数据分析能力和逻辑思维能力，能够通过数据判断业务现状和问题\n4、了解 AI Agent 产品的技术边界，能判断能力可行性与落地成本，分清演示效果与生产可用的差距\n5、对餐饮/零售/供应链行业有了解或有从业经验者优先\n6、擅长调研和行业知识积累，包括不限于日常观察、实地调研、行业调研等；对 AI 与产业结合有独立思考者是加分项","description":"部门介绍\n美团餐饮系统为餐饮企业提供一站式IT解决方案，帮助餐饮商户实现从供应链管理、生产管理、前厅管理到外卖的数字化经营。美团餐饮系统不仅打通了餐厅和平台，更帮助餐厅连接客人，让商户更了解顾客需求，在帮助商户做商业决策的同时给顾客带来更好的消费体验。\n我们持续建设和提升产研、销售、服务的核心能力，通过全新升级的美团餐饮系统一体化软硬件产品，助力餐饮商户进行线上化经营，帮助商户在推广新店、提升效率、降低成本、会员营销、流量扶持、智慧选址、供应链管理等方面强化经营能力。团队汇集了餐饮和SaaS领域的优秀人才，秉持着“以客户为中心”的初心和“长期有耐心”的耕耘精神，求真、敬畏、敢于自我否定、善于快速学习。期待同样愿意长期致力于餐饮产业数字化、智能化的你加入我们的团队，共同进步共同成长！\n\n岗位职责\n1、负责餐饮 SaaS AI 数字员工方向的产品能力建设，探索 AI Agent 在商家经营场景中的落地，对产品的使用效果和用户满意度负责\n2、根据市场需求和资源状况，深入研究目标商户需求，挖掘商户经营过程中可由 AI 承担的工作场景，并持续进行迭代及优化\n3、持续跟踪业务指标，根据数据和反馈，验证 AI 能力在实际经营中的价值，推动项目落地，为项目成果负责\n4、研究用户行为以及行业动态，不断优化产品，保持所负责产品在市场上的竞争力\n5、持续关注 AI 领域先进理念和技术发展，发掘新思路、新方法、新技术与业务结合的机会点，实现产品创新\n6、针对客户一些需求可以现场提供FDE的开发部署能力。\n\n岗位基本要求\n1、本科及以上学历，3 年以上 B 端产品经验，有 SaaS 或 AI 产品（Agent/大模型应用）落地经验者优先\n2、具备清晰的产品思路，良好的业务需求分析、产品需求分解、产品设计及项目管理能力\n3、有良好的数据分析能力和逻辑思维能力，能够通过数据判断业务现状和问题\n4、了解 AI Agent 产品的技术边界，能判断能力可行性与落地成本，分清演示效果与生产可用的差距\n5、对餐饮/零售/供应链行业有了解或有从业经验者优先\n6、擅长调研和行业知识积累，包括不限于日常观察、实地调研、行业调研等；对 AI 与产业结合有独立思考者是加分项\n\n具备以下条件优先\n有To B行业的FDE的经验、开发过AI产品经历优先。\n\n岗位亮点\n广阔的职业发展空间和成长机会：参与公司级创新方向最早期建设，与行业优秀团队合作，有真实业务场景和数据做产品验证，具有竞争力的薪酬和福利待遇。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4096887596","sourceKey":"meituan_social","company":"美团","title":"美团骑行-运营主管（深圳）","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4096887596&jobShareType=1","duty":"1.负责所属区域的车辆运营管理工作，对运营车辆的资产健康和效率指标负责；\n2.通过实地调研和数据分析，掌握区域的车辆供需状况，制定合理的车辆投放及调度策略并有效落地；\n3.根据故障车辆及未骑行车辆的数量及分布数据，制定并优化车辆干预管理的策略，不断提升资产有效性；\n4.配合政府部门对城市运营问题进行管理，主动联动政府部门举行共建活动；\n5.协助运营经理管理运营团队和推动项目落地，提升团队工作效率和获得杰出结果。","requirements":"1.本科及以上学历，1年以上团队管理经验，善于用开拓性思维解决问题；\n2.性格外向和开朗，有目标感。具备快消品区域覆盖或互联网城市地推管理经验者优先；\n3.有数据思维，善于数据分析并驱动业务，并能通过数据分析的结果不断优化调整工作，为结果负责；\n4.具备岗位灵活度，接受组织调动\\异地轮岗。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.负责所属区域的车辆运营管理工作，对运营车辆的资产健康和效率指标负责；\n2.通过实地调研和数据分析，掌握区域的车辆供需状况，制定合理的车辆投放及调度策略并有效落地；\n3.根据故障车辆及未骑行车辆的数量及分布数据，制定并优化车辆干预管理的策略，不断提升资产有效性；\n4.配合政府部门对城市运营问题进行管理，主动联动政府部门举行共建活动；\n5.协助运营经理管理运营团队和推动项目落地，提升团队工作效率和获得杰出结果。\n\n岗位基本要求\n1.本科及以上学历，1年以上团队管理经验，善于用开拓性思维解决问题；\n2.性格外向和开朗，有目标感。具备快消品区域覆盖或互联网城市地推管理经验者优先；\n3.有数据思维，善于数据分析并驱动业务，并能通过数据分析的结果不断优化调整工作，为结果负责；\n4.具备岗位灵活度，接受组织调动\\异地轮岗。\n\n具备以下条件优先\n1.具备团队管理或项目负责人经验，互联网线下重资产运营经验；\n2.具备政府事务对接工作经验，了解体系内工作规则；\n3.具备出行行业工作经历，从0-1开拓业务的。\n\n岗位亮点\n1.完善的培训机制及清晰的晋升发展路径，活跃积极的团队氛围；\n2.不过于卷的办公节奏，使个人获得稳定成长的工作岗位；\n3.具备竞争力的薪酬福利待遇。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3623477930","sourceKey":"meituan_social","company":"美团","title":"美团企业版-大客户销售经理（华南区-base深圳）","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3623477930&jobShareType=1","duty":"1.负责华南区域企业客户的开拓与经营，围绕企业用餐、员工福利、差旅等场景，完成个人及团队销售目标，持续提升区域市场覆盖与业务规模。\n\n2.面向大型企业客户，主动挖掘商机，识别客户在员工消费、费用管理、采购、行政与财务协同等方面的需求，制定客户分层与销售策略，推动从线索获取、需求诊断、方案呈现、商务谈判到合同签约的完整销售闭环。\n\n3.聚焦高端制造、国央企、金融证券、零售快消、科技等重点行业，主导或参与大型企业解决方案项目，推动头部客户突破和行业标杆案例打造。\n\n4.与交付、客户成功及产品团队高效协同，推动已签约客户顺利上线、持续使用与业务规模增长，为客户创造长期价值。\n\n5.沉淀区域市场洞察、行业解决方案及客户经营方法论，持续探索新的增长行业、客户群体和合作模式。","requirements":"1.有 SaaS、企业服务、费控、商旅、员工福利、行政采购或企业消费相关产品销售经验。\n\n2.有顾问式销售、解决方案销售或复杂项目销售经验，曾主导过大型企业、500 强企业、国央企、制造业、金融证券、零售快消或科技企业项目。\n\n3.在华南区域拥有较强的企业客户开拓能力，熟悉财务、行政、采购、人力资源等关键决策链路，具备优质行业渠道或客户资源。\n\n4.有从 0 到 1 开拓新行业、新区域或打造标杆客户案例的经验。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.负责华南区域企业客户的开拓与经营，围绕企业用餐、员工福利、差旅等场景，完成个人及团队销售目标，持续提升区域市场覆盖与业务规模。\n\n2.面向大型企业客户，主动挖掘商机，识别客户在员工消费、费用管理、采购、行政与财务协同等方面的需求，制定客户分层与销售策略，推动从线索获取、需求诊断、方案呈现、商务谈判到合同签约的完整销售闭环。\n\n3.聚焦高端制造、国央企、金融证券、零售快消、科技等重点行业，主导或参与大型企业解决方案项目，推动头部客户突破和行业标杆案例打造。\n\n4.与交付、客户成功及产品团队高效协同，推动已签约客户顺利上线、持续使用与业务规模增长，为客户创造长期价值。\n\n5.沉淀区域市场洞察、行业解决方案及客户经营方法论，持续探索新的增长行业、客户群体和合作模式。\n\n岗位基本要求\n1.有 SaaS、企业服务、费控、商旅、员工福利、行政采购或企业消费相关产品销售经验。\n\n2.有顾问式销售、解决方案销售或复杂项目销售经验，曾主导过大型企业、500 强企业、国央企、制造业、金融证券、零售快消或科技企业项目。\n\n3.在华南区域拥有较强的企业客户开拓能力，熟悉财务、行政、采购、人力资源等关键决策链路，具备优质行业渠道或客户资源。\n\n4.有从 0 到 1 开拓新行业、新区域或打造标杆客户案例的经验。\n\n具备以下条件优先\n1.有较强的商机自拓策略及渠道和客户储备优先。\n2.有Tob顾问式销售、解决方案销售和SaaS产品销售以及费控销售，并在华南区域有主导过500强企业包括但不限于国央企、证券、保险、零售快消、科技、制造企业等大型SaaS项目销售和实施背景者优先；\n3.在华南区域有一定的财务、行政、采购等人脉关系者优先；\n\n岗位亮点\n企业消费市场仍处于快速线上化阶段，企业客户在消费合规、降本增效和数字化管理上的需求持续增长。美团企业版已服务超过 30000 家企业客户，拥有覆盖企业用餐、员工福利、差旅等多场景的一体化产品与供给能力。\n\n在这里，你将有机会参与华南重点行业和头部客户的突破，接触复杂的大客户解决方案项目，与销售、行业、产品、实施和客户成功团队共同打造标杆案例。团队务实、直接、结果导向，也愿意为真正能开拓市场、拿下客户、创造增量的人提供充分的发展和上升空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4676267515","sourceKey":"meituan_social","company":"美团","title":"美团骑行-产品经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4676267515&jobShareType=1","duty":"1. 负责骑行双业务线（单车、电单车）资产健康与作业效率产品整体规划，包括：资产状态监控、故障识别与干预、维修资源调度、运维作业工具等方向的分析、规划、落地；\n2. 深入洞察资产全生命周期中的健康度痛点与作业提效空间，构建覆盖资产监控→故障识别→干预派发→维修闭环的产品体系，提升资产可用率和运维作业效率；\n3. 通过工具建设和策略建设，提升城市供需匹配度，提高资产周转效率和运维作业效率，与城市运营团队共同探索可行的资产管理和作业方式；\n4. 结合AI技术，探索资产管理和运维作业场景中的AI应用方案，推动AI能力在故障识别、作业提效、资源调度等环节的落地验证与规模化应用；\n5. 建立数据驱动的效果评估体系，量化产品对资产健康指标和作业效率指标的提升效果，持续优化。","requirements":"1. 硕士及以上学历，3年以上互联网产品工作经验，有管理经验优先；\n2. 具备优秀的B端产品专业能力，3年以上支撑大规模作业的工具产品经验，熟悉B端工具类产品的工作方法；\n3. 具备AI产品规划及落地能力，有AI产品从0到1的实际案例，对主流AI技术（大语言模型、Agent、RAG等）有清晰认知，能判断技术方案的适用场景和落地可行性；\n4. 能够独当一面，良好的跨部门沟通、协调能力，通过和业务团队、研发团队的共同协作达成业绩目标；\n5. 具备O2O业务实战经验，理解线上线下结合的复杂业务场景，能从业务痛点出发设计产品方案；\n6. 目标导向强，有良好的责任心，积极主动拿结果；长期有耐心，与业务共同成长。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1. 负责骑行双业务线（单车、电单车）资产健康与作业效率产品整体规划，包括：资产状态监控、故障识别与干预、维修资源调度、运维作业工具等方向的分析、规划、落地；\n2. 深入洞察资产全生命周期中的健康度痛点与作业提效空间，构建覆盖资产监控→故障识别→干预派发→维修闭环的产品体系，提升资产可用率和运维作业效率；\n3. 通过工具建设和策略建设，提升城市供需匹配度，提高资产周转效率和运维作业效率，与城市运营团队共同探索可行的资产管理和作业方式；\n4. 结合AI技术，探索资产管理和运维作业场景中的AI应用方案，推动AI能力在故障识别、作业提效、资源调度等环节的落地验证与规模化应用；\n5. 建立数据驱动的效果评估体系，量化产品对资产健康指标和作业效率指标的提升效果，持续优化。\n\n岗位基本要求\n1. 硕士及以上学历，3年以上互联网产品工作经验，有管理经验优先；\n2. 具备优秀的B端产品专业能力，3年以上支撑大规模作业的工具产品经验，熟悉B端工具类产品的工作方法；\n3. 具备AI产品规划及落地能力，有AI产品从0到1的实际案例，对主流AI技术（大语言模型、Agent、RAG等）有清晰认知，能判断技术方案的适用场景和落地可行性；\n4. 能够独当一面，良好的跨部门沟通、协调能力，通过和业务团队、研发团队的共同协作达成业绩目标；\n5. 具备O2O业务实战经验，理解线上线下结合的复杂业务场景，能从业务痛点出发设计产品方案；\n6. 目标导向强，有良好的责任心，积极主动拿结果；长期有耐心，与业务共同成长。\n\n岗位亮点\n1. 真实场景：骑行是典型O2O业务，覆盖全国数百城市、数百万辆车辆资产。资产健康管理和作业效率优化涉及故障识别、干预派发、维修闭环等决策链条长、可优化空间大的场景。Agent 可以真正深入物理世界，端到端解决复杂业务流程，实现对传统运维模式的全面重塑。\n2. 技术优势：美团具备成熟AI基建（Agent平台、Vibe Coding平台、多样且充足的LLM、MCP&Skill市场等），业务问题本身有技术纵深——涉及多Agent协作、运筹优化、决策闭环，而非简单的大模型功能封装。\n3. 成长环境：美团AI战略坚决、资源投入力度大，团队已积累丰富的前沿探索经验，有开放的学习氛围和高质量的技术交流环境。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4734897634","sourceKey":"meituan_social","company":"美团","title":"小象事业部-华东计划专家","city":"上海市/北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4734897634&jobShareType=1","duty":"1、负责供应链品类计划：基于用户需求预测，输出品类备货计划，并通过持续提升计划准确度及备货弹性，保障商品稳定供给，提升用户体验；\n2、负责供应链产品优化：根据不同品类的独特发展需求及特点，建立全链路供应链优化及解决方案，沉淀策略并推进产品化，提升供应链计划自动化进程；\n3、负责供应链运营提效：通过管控输入及输出指标，监控库存现货率、周转、库龄，及时提出滞销、断货预警，识别风险点及机会点，提升现有供给链路效率；\n4、结合AI/大模型工具，持续优化需求预测模型和算法，推动计划决策从人工经验向数据智能演进；\n5、与算法、产品团队协同，探索AI Agent在库存预警、异常处置等场景的落地应用。","requirements":"1、具备创业精神，积极主动，有较强的自驱力和韧性；\n2、熟练掌握各类办公软件，具有较强的逻辑思考能力、数据分析能力、复杂问题的拆解能力；\n3、具备较强责任心、沟通、协同、推动影响力；\n4、2年以上供应计划工作经验；\n5、有大数据分析平台（如Spark/SQL）或AI工具（如ChatGPT/Copilot等）实际使用经验优先；对智能化供应链有探索热情","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责供应链品类计划：基于用户需求预测，输出品类备货计划，并通过持续提升计划准确度及备货弹性，保障商品稳定供给，提升用户体验；\n2、负责供应链产品优化：根据不同品类的独特发展需求及特点，建立全链路供应链优化及解决方案，沉淀策略并推进产品化，提升供应链计划自动化进程；\n3、负责供应链运营提效：通过管控输入及输出指标，监控库存现货率、周转、库龄，及时提出滞销、断货预警，识别风险点及机会点，提升现有供给链路效率；\n4、结合AI/大模型工具，持续优化需求预测模型和算法，推动计划决策从人工经验向数据智能演进；\n5、与算法、产品团队协同，探索AI Agent在库存预警、异常处置等场景的落地应用。\n\n岗位基本要求\n1、具备创业精神，积极主动，有较强的自驱力和韧性；\n2、熟练掌握各类办公软件，具有较强的逻辑思考能力、数据分析能力、复杂问题的拆解能力；\n3、具备较强责任心、沟通、协同、推动影响力；\n4、2年以上供应计划工作经验；\n5、有大数据分析平台（如Spark/SQL）或AI工具（如ChatGPT/Copilot等）实际使用经验优先；对智能化供应链有探索热情\n\n具备以下条件优先\n1、具备较强数据统计以及分析能力，熟练使用SQL；\n2、参与过同类型业务，具备多门店库存管理经验优先；\n3、供应链管理、物流管理专业优先；\n4、乐观向上正能量者优先。\n\n岗位亮点\n1、供应链能力建设价值高：供给侧需要有无限接近和满足消费者的能力，对于需求计划，库存计划，补货管理专业能力建设；以及通过供应链条的整体优化最大化供给的弹性。这种能力区别于现在的远场电商/线下电商已有的供应链能力，也会成为未来即时零售的核心竞争力；\n2、小象供应链场景的复杂度能帮助在供应链专业上的深度拓展：供应链链路上的节点多，品类复杂，异常场景多等，都对供应链规划/计划/执行能力上有更高的要求，是很好的专业深度挑战；\n3、构建更宽广的职业发展图景：有机会全身心地参与新零售业态，在急速发展的业务当中，从0到1地建立对业务和产业的认知，能和电商、O2O、物流、零售、人工智能等多元化背景的团队一起，综合学习，共同进步；\n4、深度参与美团供应链AI化升级：在AI重塑供应链的关键窗口期，与算法/产品/技术团队共同探索智能计划体系，既有深度的供应链专业修炼，也有AI转型浪潮的先行视角。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4686310892","sourceKey":"meituan_social","company":"美团","title":"快乐猴-广告投放专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4686310892&jobShareType=1","duty":"1、投放策略与用户增长：负责快乐猴超市在地面广告及线上广告的投放策略制定与执行，对年度获客规模、获客成本（CAC）及投放ROI负责；\n2、数据驱动优化：建立广告投放的完整数据监控与分析体系，实时监控各渠道投放表现，通过数据分析发现优化机会，产出投放复盘报告与策略迭代方案；\n3、渠道管理与算法应用：深入理解各类广告的报价与算法效果评估逻辑，结合门店生命周期和业务场景制定差异化投放策略，运用智能出价、程序化投放等工具提升投放效率；\n4、AI赋能投放全流程：运用AI工具辅助广告策略优化，包括AI辅助素材生成与审核、智能人群定向策略、自动化投放调优、投放效果归因分析等，推动AI在投放工作流中的落地应用；\n5、创意与素材协同：基于投放数据洞察，提出广告创意优化方向，协同设计团队打磨高转化素材，持续提升点击率、转化率和ROI；\n6、新渠道探索与测试：持续关注新兴媒体渠道和投放玩法（如AI广告、本地推、搜索意图广告等），评估并测试新渠道的投放效果，沉淀可复用的投放方法论；\n7、跨部门协作与项目推动：与产品、数据、市场等团队紧密协作，推动投放策略与产品功能联动优化，以项目制方式推进重点投放项目落地。","requirements":"1、本科及以上学历，市场营销、广告学、统计学、经济学、计算机等相关专业优先；\n2、5年以上互联网效果广告投放经验，有电商/即时零售/本地生活行业经验优先；\n3、熟悉抖音、快手、广告等平台投放逻辑与工具，具备信息流广告和搜索广告实操经验；\n4、数据驱动意识强，具备较强的数据分析与建模能力，能通过数据发现问题、制定策略、验证效果。熟练使用SQL、Python或类似数据工具者优先；\n5、对AI在广告领域的应用有认知或实践经验，包括但不限于AI辅助创意生成、智能投放策略、自动化数据报告等，能主动探索AI工具在工作中的落地场景；\n6、逻辑清晰，结构化思维能力强，能够独立完成复杂业务问题的拆解与策略设计；\n7、具备优秀的沟通协调能力和跨部门项目推动能力，自驱力强，能在快速变化的业务环境中独立推进工作；\n8、对广告行业趋势敏感，关注AI技术对广告投放的影响，有持续学习和探索的习惯。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1、投放策略与用户增长：负责快乐猴超市在地面广告及线上广告的投放策略制定与执行，对年度获客规模、获客成本（CAC）及投放ROI负责；\n2、数据驱动优化：建立广告投放的完整数据监控与分析体系，实时监控各渠道投放表现，通过数据分析发现优化机会，产出投放复盘报告与策略迭代方案；\n3、渠道管理与算法应用：深入理解各类广告的报价与算法效果评估逻辑，结合门店生命周期和业务场景制定差异化投放策略，运用智能出价、程序化投放等工具提升投放效率；\n4、AI赋能投放全流程：运用AI工具辅助广告策略优化，包括AI辅助素材生成与审核、智能人群定向策略、自动化投放调优、投放效果归因分析等，推动AI在投放工作流中的落地应用；\n5、创意与素材协同：基于投放数据洞察，提出广告创意优化方向，协同设计团队打磨高转化素材，持续提升点击率、转化率和ROI；\n6、新渠道探索与测试：持续关注新兴媒体渠道和投放玩法（如AI广告、本地推、搜索意图广告等），评估并测试新渠道的投放效果，沉淀可复用的投放方法论；\n7、跨部门协作与项目推动：与产品、数据、市场等团队紧密协作，推动投放策略与产品功能联动优化，以项目制方式推进重点投放项目落地。\n\n岗位基本要求\n1、本科及以上学历，市场营销、广告学、统计学、经济学、计算机等相关专业优先；\n2、5年以上互联网效果广告投放经验，有电商/即时零售/本地生活行业经验优先；\n3、熟悉抖音、快手、广告等平台投放逻辑与工具，具备信息流广告和搜索广告实操经验；\n4、数据驱动意识强，具备较强的数据分析与建模能力，能通过数据发现问题、制定策略、验证效果。熟练使用SQL、Python或类似数据工具者优先；\n5、对AI在广告领域的应用有认知或实践经验，包括但不限于AI辅助创意生成、智能投放策略、自动化数据报告等，能主动探索AI工具在工作中的落地场景；\n6、逻辑清晰，结构化思维能力强，能够独立完成复杂业务问题的拆解与策略设计；\n7、具备优秀的沟通协调能力和跨部门项目推动能力，自驱力强，能在快速变化的业务环境中独立推进工作；\n8、对广告行业趋势敏感，关注AI技术对广告投放的影响，有持续学习和探索的习惯。\n\n具备以下条件优先\n有互联网公司、LBS类业务效果投放经验者优先，具备多业务场景投放经验者优先。\n\n岗位亮点\n1、加入快速发展的新零售业务，参与千万级用户规模的产品运营；\n2、获得丰富的业务实战与成长机会；\n3、扁平化管理，拥有充分的自主权与创新空间； \n4、AI+投放前沿：美团正在推进AI技术在广告投放领域的深度应用，加入后有机会参与AI辅助投放策略、智能素材生成等前沿项目，成为AI时代广告运营的先驱者。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4736205465","sourceKey":"meituan_social","company":"美团","title":"物流仓配运营专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4736205465&jobShareType=1","duty":"1. 负责仓储与配送运营体系的0-1规划、搭建与优化，确保仓配效率与服务质量持续提升。  \n2. 管理20人运营团队，制定团队目标、绩效考核机制，并进行日常培训与人才梯队建设。  \n3. 监控仓配关键指标（如订单履约时效、库存准确率、配送达成率等），分析数据并推动问题闭环解决。  \n4. 协同供应链、技术、客服等跨部门资源，推动系统流程优化与运营标准化落地。  \n5. 应对大促及突发业务高峰，制定应急预案并保障仓配运营稳定运行。","requirements":"1. 大学专科及以上学历，物流、供应链或相关专业优先。  \n2. 具备5年以上物流仓配运营经验，有电商、快消或零售行业背景者优先。  \n3. 有团队管理经验，曾带领10人以上团队，具备较强的组织协调与领导能力。  \n4. 熟悉WMS、TMS等物流系统，具备数据分析能力，能基于数据驱动运营决策。  \n5. 具备较强的协同能力与问题解决能力，能适应快节奏工作环境。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. 负责仓储与配送运营体系的0-1规划、搭建与优化，确保仓配效率与服务质量持续提升。  \n2. 管理20人运营团队，制定团队目标、绩效考核机制，并进行日常培训与人才梯队建设。  \n3. 监控仓配关键指标（如订单履约时效、库存准确率、配送达成率等），分析数据并推动问题闭环解决。  \n4. 协同供应链、技术、客服等跨部门资源，推动系统流程优化与运营标准化落地。  \n5. 应对大促及突发业务高峰，制定应急预案并保障仓配运营稳定运行。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、供应链或相关专业优先。  \n2. 具备5年以上物流仓配运营经验，有电商、快消或零售行业背景者优先。  \n3. 有团队管理经验，曾带领10人以上团队，具备较强的组织协调与领导能力。  \n4. 熟悉WMS、TMS等物流系统，具备数据分析能力，能基于数据驱动运营决策。  \n5. 具备较强的协同能力与问题解决能力，能适应快节奏工作环境。\n\n岗位亮点\n1. 参与核心物流业务运营，直接影响用户体验与公司履约能力。  \n2. 团队规模适中，管理纵深清晰，有充分的管理实践与成长空间。  \n3. 公司提供完善的培训体系与职业发展通道，支持长期职业成长。  \n4. 工作地点位于北京核心区域，交通便利，办公环境优良。  \n5. 与行业技术平台深度协同，接触前沿物流运营模式与工具。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4736247951","sourceKey":"meituan_social","company":"美团","title":"供应链规划-需求预测优化","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4736247951&jobShareType=1","duty":"1、需求预测：和产品、算法团队搭建并优化销售预测模型，输出精准长/中/短期需求预测；\n2、预测偏差管理：持续跟踪每月/周/日销售达成，构建和完善覆盖城市、仓等多维度的预测监控与数据分析体系，复盘预测偏差，迭代优化预测逻辑，提升整体预测准确率；\n3、数据沉淀：负责活动、节假日日历、促销等知识库的管理与异常影响因子量化，运用智能分析工具完成影响评估与参数调整决策，在复杂业务场景中精进数据驱动决策能力，为订货及库存计划提供核心数据支持；\n4、业务协同：深度融入运营模式，理解商品运营策略、促销规划及库存管理逻辑，通过AI赋能的精准预测协同供应链等团队保障商品供给，降低滞销风险，提升周转效率；","requirements":"1、经验背景：大学本科及以上学历，5年及以上大型零售企业供应链计划或者需求预测相关经验，熟悉零售业务运作流程和关键指标，有生鲜运营经验者优先；\n2、数据能力：具备扎实的数据统计和分析能力，熟练使用SQL、Python等工具进行数据提取、清洗和分析，熟悉常用预测模型及AI工具，有自动化预测体系搭建者加分；\n3、业务与逻辑思维：具备严谨的逻辑分析和系统性思维能力，对零售业务高度敏感，能洞察内外部因素对销量的影响；\n4、沟通与推动力：具备出色的跨部门沟通协同能力和AI工具推广并赋能团队的意愿与能力；","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1、需求预测：和产品、算法团队搭建并优化销售预测模型，输出精准长/中/短期需求预测；\n2、预测偏差管理：持续跟踪每月/周/日销售达成，构建和完善覆盖城市、仓等多维度的预测监控与数据分析体系，复盘预测偏差，迭代优化预测逻辑，提升整体预测准确率；\n3、数据沉淀：负责活动、节假日日历、促销等知识库的管理与异常影响因子量化，运用智能分析工具完成影响评估与参数调整决策，在复杂业务场景中精进数据驱动决策能力，为订货及库存计划提供核心数据支持；\n4、业务协同：深度融入运营模式，理解商品运营策略、促销规划及库存管理逻辑，通过AI赋能的精准预测协同供应链等团队保障商品供给，降低滞销风险，提升周转效率；\n\n岗位基本要求\n1、经验背景：大学本科及以上学历，5年及以上大型零售企业供应链计划或者需求预测相关经验，熟悉零售业务运作流程和关键指标，有生鲜运营经验者优先；\n2、数据能力：具备扎实的数据统计和分析能力，熟练使用SQL、Python等工具进行数据提取、清洗和分析，熟悉常用预测模型及AI工具，有自动化预测体系搭建者加分；\n3、业务与逻辑思维：具备严谨的逻辑分析和系统性思维能力，对零售业务高度敏感，能洞察内外部因素对销量的影响；\n4、沟通与推动力：具备出色的跨部门沟通协同能力和AI工具推广并赋能团队的意愿与能力；\n\n具备以下条件优先\n1、生鲜需求计划优先；\n2、有产品或者算法相关经验优先；\n\n岗位亮点\n1、深入核心业务，全面掌握新零售背景下的运作逻辑与挑战，直接参与Al预测体系的从0到1搭建；\n2、在真实复杂业务场景中，以AI工具为杠杆，锤炼兼具广度和深度的供应链计划与预测能力；\n3、与多元背景的专业团队协作，共同推动零售行业的AI化、智能化升级，站在行业变革前沿；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4136362246","sourceKey":"meituan_social","company":"美团","title":"快乐猴-宁波门店副店长","city":"宁波市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4136362246&jobShareType=1","duty":"1、确保公司营运标准高效在门店落地，提升销售与毛利；\n2、理解商圈和用户，据此对门店品类和商品经营方向有清晰的认知，通过品类/商品经营、拉新、营销、门店布局、商品订货、陈列、服务，售后，库存管控等；\n3、管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4、对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5、对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴；","requirements":"1、具有传统大型零售运营的思维模式，5年以上工作经验，担任过2年以上传统实体零售门店生鲜副店长及以上级别的管理岗,关注客户价值和客户体验;\n2、诚实正直、品行端正、责任心强、肯吃苦、有激情且执行力强，有商人视角；\n3、勇于承担，乐于分享，指导与培养团队各项能力，能够打造高绩效团队，形成阶梯化人才成长模式；\n4、具备建设组织和体系搭建能力，可以制定并落实各环节的流程；具备建设组织和体系搭建能力，可以制定并落实各环节的流程；\n5、掌握基本的AI工具，具备数字化运营思维，能快速学习并应用AI辅助工具提升工作效率。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1、确保公司营运标准高效在门店落地，提升销售与毛利；\n2、理解商圈和用户，据此对门店品类和商品经营方向有清晰的认知，通过品类/商品经营、拉新、营销、门店布局、商品订货、陈列、服务，售后，库存管控等；\n3、管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4、对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5、对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴；\n\n岗位基本要求\n1、具有传统大型零售运营的思维模式，5年以上工作经验，担任过2年以上传统实体零售门店生鲜副店长及以上级别的管理岗,关注客户价值和客户体验;\n2、诚实正直、品行端正、责任心强、肯吃苦、有激情且执行力强，有商人视角；\n3、勇于承担，乐于分享，指导与培养团队各项能力，能够打造高绩效团队，形成阶梯化人才成长模式；\n4、具备建设组织和体系搭建能力，可以制定并落实各环节的流程；具备建设组织和体系搭建能力，可以制定并落实各环节的流程；\n5、掌握基本的AI工具，具备数字化运营思维，能快速学习并应用AI辅助工具提升工作效率。\n\n具备以下条件优先\n有硬折扣门店店长经验，传统超商连锁门店营运中层管理经验优先；\n\n岗位亮点\n1、创新型重点项目，从0-1，成长空间广阔，共同推动门店高效营运\n2、AI数据看板、智能补货预测、数字化稽核系统全面赋能，让你用互联网公司的工具做零售管理。告别凭感觉管店，AI数据告诉你哪里出了问题、该怎么改。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4476349672","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-整车可靠性试验工程师","city":"上海市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4476349672&jobShareType=1","duty":"1、负责无人车道路可靠性试验策划，编写相关试验大纲并审核报告；\n\n2、负责无人车整车、系统、零部件及可靠性试验策划，实施落地、计划管控；\n\n3、负责编写无人车道路试验项目技术要求，寻找合格的外部资源，管控试验成本;\n\n4、负责无人车试验方法创新，保证试验方法准确性同时提升效率；\n\n5、负责试验数据、结果、及试验报告的准出;\n\n6、管理无人车硬件测试车队，构建规章流程保证日常测试安全；\n\n7、负责无人车项目DVP策划及编写，同时保证试验的覆盖度。\n\n8、善用 AI 工具辅助行业产品方案分析与需求洞察，提升调研效率。","requirements":"1、本科及以上学历,车辆、机械、材料、力学相关专业;\n\n2、具备10年以上整车耐久、可靠性、环境适应性试验经验；\n\n3、有自动驾驶或云控测试经验优先；\n\n4、了解线控底盘或滑板底盘工作原理和E/E架构，有线控底盘标定及测试经验者优先；\n\n5.、熟悉道路试验工作，熟悉适合无人车的场地资源，能过根据无人车特点设计方法；\n\n6、 熟练使用Vbox、Kistler、CANOE等设备及传感器；\n\n7、具备问题识别能力，熟悉各部件的常见失效模式，具备常见质量问题的分析能力。\n\n8、具备 AI 工具实际应用能力，能熟练使用大模型（如 ChatGPT、Kimi、通义等）辅助需求分析、文档撰写和行业产品研究；有 AI 辅助产品决策经验者优先。\n\n9、良好的 AI工具使用环境，鼓励并支持将大模型与 AI Agent 能力融入日常产品工作，提升整体研发和决策效率。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1、负责无人车道路可靠性试验策划，编写相关试验大纲并审核报告；\n\n2、负责无人车整车、系统、零部件及可靠性试验策划，实施落地、计划管控；\n\n3、负责编写无人车道路试验项目技术要求，寻找合格的外部资源，管控试验成本;\n\n4、负责无人车试验方法创新，保证试验方法准确性同时提升效率；\n\n5、负责试验数据、结果、及试验报告的准出;\n\n6、管理无人车硬件测试车队，构建规章流程保证日常测试安全；\n\n7、负责无人车项目DVP策划及编写，同时保证试验的覆盖度。\n\n8、善用 AI 工具辅助行业产品方案分析与需求洞察，提升调研效率。\n\n岗位基本要求\n1、本科及以上学历,车辆、机械、材料、力学相关专业;\n\n2、具备10年以上整车耐久、可靠性、环境适应性试验经验；\n\n3、有自动驾驶或云控测试经验优先；\n\n4、了解线控底盘或滑板底盘工作原理和E/E架构，有线控底盘标定及测试经验者优先；\n\n5.、熟悉道路试验工作，熟悉适合无人车的场地资源，能过根据无人车特点设计方法；\n\n6、 熟练使用Vbox、Kistler、CANOE等设备及传感器；\n\n7、具备问题识别能力，熟悉各部件的常见失效模式，具备常见质量问题的分析能力。\n\n8、具备 AI 工具实际应用能力，能熟练使用大模型（如 ChatGPT、Kimi、通义等）辅助需求分析、文档撰写和行业产品研究；有 AI 辅助产品决策经验者优先。\n\n9、良好的 AI工具使用环境，鼓励并支持将大模型与 AI Agent 能力融入日常产品工作，提升整体研发和决策效率。\n\n具备以下条件优先\n具备AI使用结合能力优先\n\n岗位亮点\n参与自动驾驶新技术开发落地，实现无人车规模化应用","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3243509712","sourceKey":"meituan_social","company":"美团","title":"KV 存储管控平台开发工程师","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3243509712&jobShareType=1","duty":"管控平台研发：负责美团自研万亿级分布式KV存储系统（Cellar/Squirrel）智能化管控平台的设计与核心模块开发，覆盖资源管控、智能容量评估、自动化容灾等关键能力。\n\n基于Agent技术的智能运维：基于 LLM 和 AI Agent 技术，构建智能巡检、故障根因分析、自愈决策、容量趋势预测等自治化能力，推动运维从\"人工+脚本\"向\"AI驱动\"演进。\n\n稳定性、成本与用户体验的持续运营提升：结合时序数据分析、异常检测、预测模型构建智能决策中枢（自动扩缩容、热点预警、成本优化建议），持续提升稳定性、降低成本、优化用户体验。\n\n系统架构演进：结合业界发展趋势和美团的实际业务需求，推动管控平台在自动化→智能化→自治化方向持续演进。","requirements":"扎实的编程功底与AI Coding能力：精通 Java，熟悉常见数据结构与算法；能熟练使用 AI 进行方案设计、代码开发与重构，求解有一定技术深度的复杂问题。\n\nAI Coding工程化落地经验：熟悉主流 AI Coding 工具（如 Opencode、Claude Code），有 AI 在代码生成、 Code Review、自动化测试与文档生成等全流程的工程化实践。\n\n数据库与存储系统深度认知：对主流数据库架构（MySQL、Redis、MongoDB）及分布式存储原理有深入理解，熟悉KV存储的内部机制、一致性模型及运维挑战。。\n\n平台化与工程化经验：有大型PaaS平台、数据库服务管控平台或分布式系统开发经验。\n\n技术前瞻性：持续跟踪 AI 在基础设施领域的前沿趋势，并能转化为工程实践。\n\n软素质：具备良好的沟通表达与团队协作能力，对技术有热情与好奇心，具备较强的主人翁意识。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n管控平台研发：负责美团自研万亿级分布式KV存储系统（Cellar/Squirrel）智能化管控平台的设计与核心模块开发，覆盖资源管控、智能容量评估、自动化容灾等关键能力。\n\n基于Agent技术的智能运维：基于 LLM 和 AI Agent 技术，构建智能巡检、故障根因分析、自愈决策、容量趋势预测等自治化能力，推动运维从\"人工+脚本\"向\"AI驱动\"演进。\n\n稳定性、成本与用户体验的持续运营提升：结合时序数据分析、异常检测、预测模型构建智能决策中枢（自动扩缩容、热点预警、成本优化建议），持续提升稳定性、降低成本、优化用户体验。\n\n系统架构演进：结合业界发展趋势和美团的实际业务需求，推动管控平台在自动化→智能化→自治化方向持续演进。\n\n岗位基本要求\n扎实的编程功底与AI Coding能力：精通 Java，熟悉常见数据结构与算法；能熟练使用 AI 进行方案设计、代码开发与重构，求解有一定技术深度的复杂问题。\n\nAI Coding工程化落地经验：熟悉主流 AI Coding 工具（如 Opencode、Claude Code），有 AI 在代码生成、 Code Review、自动化测试与文档生成等全流程的工程化实践。\n\n数据库与存储系统深度认知：对主流数据库架构（MySQL、Redis、MongoDB）及分布式存储原理有深入理解，熟悉KV存储的内部机制、一致性模型及运维挑战。。\n\n平台化与工程化经验：有大型PaaS平台、数据库服务管控平台或分布式系统开发经验。\n\n技术前瞻性：持续跟踪 AI 在基础设施领域的前沿趋势，并能转化为工程实践。\n\n软素质：具备良好的沟通表达与团队协作能力，对技术有热情与好奇心，具备较强的主人翁意识。\n\n岗位亮点\n团队氛围好， 扁平、透明、结果说话， 不卷时长； 鼓励探索和创新。 技术有挑战， 万亿级真实业务场景： \n\nCellar/Squirrel是美团自研的KV存储底座，万亿级调用规模。\n\n团队有较强的AI coding工作氛围，AI Coding工具链丰富， 有配套的token与AI工具保障开发效率和工作体验。\n\n核心模块owner制，可同时接触存储引擎内核与上层管控平台，纵向深度与横向视野兼顾。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4679970160","sourceKey":"meituan_social","company":"美团","title":"数据库研发工程（中间件方向）","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4679970160&jobShareType=1","duty":"1、负责美团ES数据库内核、以及配套的生态（SDK、Agent）代码开发，性能优化和系统稳定性保障等；\n2、负责美团数据库访问中间件Zebra/Zebra-proxy代码开发，性能优化和系统稳定性保障等；\n3、负责对接业务需求，充分理解业务，并持续优化架构和提升性能以支撑公司业务系统的发展要求；\n4、跟踪行业发展趋势并保持与业界进度同步；","requirements":"1、熟悉Elasticsearch，MySQL、TIDB、PolarDB-X、TDSQL等数据库，具备深度的使用经验优先；\n2、熟悉负债均衡、连接池、分库分别、流量调度、读写分离、SQL协议等，有工程实践经验优先；\n3、对具备扎实的编程功底、熟练掌握高并发编程、良好的设计能力和编程习惯，有高性能高并发开发经验优先；\n4、熟悉使用至少一门开发语言（Java/Golang/C++），对各种常用数据结构及算法有深入的理解，善于问题排查和性能调优；\n5、积极主动，沟通顺畅，有快速学习能力，乐于探索未知领域，对新技术敏感，追求卓越，能快速学习并具备较强的技术领悟能力；","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1、负责美团ES数据库内核、以及配套的生态（SDK、Agent）代码开发，性能优化和系统稳定性保障等；\n2、负责美团数据库访问中间件Zebra/Zebra-proxy代码开发，性能优化和系统稳定性保障等；\n3、负责对接业务需求，充分理解业务，并持续优化架构和提升性能以支撑公司业务系统的发展要求；\n4、跟踪行业发展趋势并保持与业界进度同步；\n\n岗位基本要求\n1、熟悉Elasticsearch，MySQL、TIDB、PolarDB-X、TDSQL等数据库，具备深度的使用经验优先；\n2、熟悉负债均衡、连接池、分库分别、流量调度、读写分离、SQL协议等，有工程实践经验优先；\n3、对具备扎实的编程功底、熟练掌握高并发编程、良好的设计能力和编程习惯，有高性能高并发开发经验优先；\n4、熟悉使用至少一门开发语言（Java/Golang/C++），对各种常用数据结构及算法有深入的理解，善于问题排查和性能调优；\n5、积极主动，沟通顺畅，有快速学习能力，乐于探索未知领域，对新技术敏感，追求卓越，能快速学习并具备较强的技术领悟能力；\n\n具备以下条件优先\n1、有基础组件开发经验；\n2、有云计算基础设施开发经验；\n\n岗位亮点\n深度参与大规模、高并发、低延时的分布式中间件系统开发，接触到一线的大规模业务系统。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4526182915","sourceKey":"meituan_social","company":"美团","title":"物资设备管理专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4526182915&jobShareType=1","duty":"1.供应管理：负责物资设备的选型和跨境采购的供应管理，包含需求预测、订单履约管理和上下游部门协作，有零售业务采购经验和供应链管理经验优先；\n2.成本管理：负责一线物资的用量分析和成本治理，包含管理包材用量、周转物资循环效率、设备故障治理、门店能耗管理，具备问题诊断和项目管理制的改善能力；\n3.流程和产品运营：推动预算管理、补货计划、交付效率提升、验收入库、审计盘点、设备报修和报废等流程的持续精进改善和线上化；\n4.质量管理：能够体系化输出物资及服务的技术标准要求，包含理化性质，设备养护标准，在门店消杀、清洁和用水等服务，能深入研究服务商的管理和门店环境治理策略；\n5.创新设备/物资探索：通过行业最佳实践调研及业务需求诊断，持续引入创新型物资及设备，提升业务运营水平及降低成本；","requirements":"1. 本科及以上学历；\n2. 曾在互联网或者大型商超零售行业有业务中台经验者优先；\n3. 较强的跨团队沟通能力和进度管理能力；\n4. 需要适配海外工作时间，每周日到每周四上班，周五和周六休息。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1.供应管理：负责物资设备的选型和跨境采购的供应管理，包含需求预测、订单履约管理和上下游部门协作，有零售业务采购经验和供应链管理经验优先；\n2.成本管理：负责一线物资的用量分析和成本治理，包含管理包材用量、周转物资循环效率、设备故障治理、门店能耗管理，具备问题诊断和项目管理制的改善能力；\n3.流程和产品运营：推动预算管理、补货计划、交付效率提升、验收入库、审计盘点、设备报修和报废等流程的持续精进改善和线上化；\n4.质量管理：能够体系化输出物资及服务的技术标准要求，包含理化性质，设备养护标准，在门店消杀、清洁和用水等服务，能深入研究服务商的管理和门店环境治理策略；\n5.创新设备/物资探索：通过行业最佳实践调研及业务需求诊断，持续引入创新型物资及设备，提升业务运营水平及降低成本；\n\n岗位基本要求\n1. 本科及以上学历；\n2. 曾在互联网或者大型商超零售行业有业务中台经验者优先；\n3. 较强的跨团队沟通能力和进度管理能力；\n4. 需要适配海外工作时间，每周日到每周四上班，周五和周六休息。\n\n岗位亮点\n可参与海外快速发展的零售业务，积累仓储流程标准和产品建设能力，见证中国人的出海fighting！","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4629119885","sourceKey":"meituan_social","company":"美团","title":"全球签证专家- Global Visa Manager","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4629119885&jobShareType=1","duty":"承接公司全球出入境服务业务策略落地，负责制定区域出入境业务策略;本区域/国家出入境解决方案的设计者，客户关系的构建者和管理者，区域/国家出入境服务中心组织运作、服务交付质量监控、能力提升的责任人，对区域/国家出签结果负责。\n具体职责包括：\n1.负责所辖区域内政策洞察与规划:负责洞察区域外部环境和内部业务发展战略以及人才流动需求，设计区域内出入境服务解决方案，保障出签率，提升出签效率;\n2.承担区域出入境客户关系建设规划、工作策略及落地执行，持续优化外部出入境渠道和办理环境，促进组织目标达成，支撑关键事件;\n3.负责区域出入境服务运营管理，加强运营质量和知识管理，提升区域服务质量和合规遵从性;\n4.管理区域出入境服务团队、氛围建设和人员能力提升;\n5.负责区域供应商合作与管理;\n6.协助机关制定全球出入境业务策略，跨区域重点项目保障协同;\n7.管理区域内国家出入境服务业务交付，包括但不限于客户关系、服务流程重塑、人员赋能、系统需求梳理与适配、服务内控体系建设。","requirements":"1.本科及以上学历，人力资源管理或相关专业背景优先；\n2.具备3年以上签证运营的实际工作经验，具有合规意识，有海外的学习生活经历或相关工作经验优先；\n3.快速学习掌握知识、责任心强，胆大心细，善于解决问题；\n4.具备较好的英语能力，听说读写流利，同时具备跨文化沟通的敏感度和适应性；\n5.具备较强责任感和工作主动性，具备一定的灵活度，善于发现和解决问题；\n6.具备良好的数据分析能力，能够熟练使用办公软件;\n7.具备良好的沟通协调能力和团队合作精神，以及良好的书面文字功底;\n8. 具备团队管理经验，包括外包员工的管理;\n9. 具备供应商管理经验，包括并不限于供应商资源拓展及引入，服务监督及优化，绩效及结算;\n10.具备较强的合规意识，可以识别&评估运营的风险;","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n承接公司全球出入境服务业务策略落地，负责制定区域出入境业务策略;本区域/国家出入境解决方案的设计者，客户关系的构建者和管理者，区域/国家出入境服务中心组织运作、服务交付质量监控、能力提升的责任人，对区域/国家出签结果负责。\n具体职责包括：\n1.负责所辖区域内政策洞察与规划:负责洞察区域外部环境和内部业务发展战略以及人才流动需求，设计区域内出入境服务解决方案，保障出签率，提升出签效率;\n2.承担区域出入境客户关系建设规划、工作策略及落地执行，持续优化外部出入境渠道和办理环境，促进组织目标达成，支撑关键事件;\n3.负责区域出入境服务运营管理，加强运营质量和知识管理，提升区域服务质量和合规遵从性;\n4.管理区域出入境服务团队、氛围建设和人员能力提升;\n5.负责区域供应商合作与管理;\n6.协助机关制定全球出入境业务策略，跨区域重点项目保障协同;\n7.管理区域内国家出入境服务业务交付，包括但不限于客户关系、服务流程重塑、人员赋能、系统需求梳理与适配、服务内控体系建设。\n\n岗位基本要求\n1.本科及以上学历，人力资源管理或相关专业背景优先；\n2.具备3年以上签证运营的实际工作经验，具有合规意识，有海外的学习生活经历或相关工作经验优先；\n3.快速学习掌握知识、责任心强，胆大心细，善于解决问题；\n4.具备较好的英语能力，听说读写流利，同时具备跨文化沟通的敏感度和适应性；\n5.具备较强责任感和工作主动性，具备一定的灵活度，善于发现和解决问题；\n6.具备良好的数据分析能力，能够熟练使用办公软件;\n7.具备良好的沟通协调能力和团队合作精神，以及良好的书面文字功底;\n8. 具备团队管理经验，包括外包员工的管理;\n9. 具备供应商管理经验，包括并不限于供应商资源拓展及引入，服务监督及优化，绩效及结算;\n10.具备较强的合规意识，可以识别&评估运营的风险;\n\n具备以下条件优先\n1. 具备海外工签经验者优先 2. 具备甲乙方签证工作经验优先\n\n岗位亮点\n提供专业的培训和发展机会，帮助员工不断提升签证管理技能和团队管理能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4508658215","sourceKey":"meituan_social","company":"美团","title":"物流规划","city":"利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4508658215&jobShareType=1","duty":"1. 负责Keemart物流网络规划及优化，提升整体运营效率。\n2. 完成开搬扩的规划与实施需求，不断提升效率和交付结果。\n3. 基于SKU特性设计差异化分仓，优化库存分布与周转效率。\n4. 跟踪行业趋势，引入先进物流技术和管理方法。","requirements":"1. 大学本科及以上学历，物流、供应链或相关专业优先。  \n2. 8年以上物流规划或相关领域工作经验，具备国际化项目经验。  \n3. 熟悉中东地区物流环境及政策法规，有沙特本地经验优先。  \n4. 具备较强的数据分析能力和项目管理能力。  \n5. 英语流利，阿拉伯语能力为加分项。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. 负责Keemart物流网络规划及优化，提升整体运营效率。\n2. 完成开搬扩的规划与实施需求，不断提升效率和交付结果。\n3. 基于SKU特性设计差异化分仓，优化库存分布与周转效率。\n4. 跟踪行业趋势，引入先进物流技术和管理方法。\n\n岗位基本要求\n1. 大学本科及以上学历，物流、供应链或相关专业优先。  \n2. 8年以上物流规划或相关领域工作经验，具备国际化项目经验。  \n3. 熟悉中东地区物流环境及政策法规，有沙特本地经验优先。  \n4. 具备较强的数据分析能力和项目管理能力。  \n5. 英语流利，阿拉伯语能力为加分项。\n\n岗位亮点\n1. Keemart海外业务快速发展，持续深耕零售行业。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4736527116","sourceKey":"meituan_social","company":"美团","title":"大模型/Agent 评测工程师（AI 研发方向）","city":"上海市/北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4736527116&jobShareType=1","duty":"1. 负责通用 Agent、Code Agent 及 AI 研发工具的评测体系设计与建设，支撑模型、Prompt、工具和 Agent 工作流的持续迭代。\n 2. 深入需求分析、技术方案设计、代码生成与修改、测试生成、代码评审、缺陷修复和故障诊断等研发场景，将真实研发流程抽象为可复现、可扩展的评测任务。\n 3. 建立覆盖任务完成度、需求符合度、代码正确性、工具调用、规划执行、稳定性、安全性、成本和时延等维度的评测指标体系。\n 4. 负责评测数据和样本建设，持续沉淀真实任务、典型失败案例、线上反馈及核心回归用例，保障评测数据的代表性、区分度和可维护性。\n 5. 设计和研发自动化评测框架及平台，支持任务批量执行、过程数据采集、自动评分、版本对比、回归分析、异常告警和结果可视化。\n 6. 分析 Agent 的执行轨迹，定位其在需求理解、任务规划、上下文使用、工具调用、代码修改、测试执行和错误恢复等环节的问题，判断问题来源并提出改进建议。\n 7. 建立线上反馈与离线评测之间的闭环，将用户反馈、任务失败、人工接管和异常行为转化为可复现的评测与回归用例。\n 8. 与产品、算法、研发、测试及平台团队协作，推动评测结果应用于模型选择、Agent 优化、版本验收和发布决策。","requirements":"1. 计算机科学、软件工程、人工智能或相关专业本科及以上学历，具备 3 年及以上软件研发、测试开发、质量工程、研发效能或 AI 工程经验。\n 2. 熟练掌握 Python、Go、Java 或 TypeScript 中至少一种编程语言，具备良好的工程实现能力，能够独立完成评测工具、服务或平台模块的设计与开发。\n 3. 熟悉软件研发流程，了解 Git、CI/CD、自动化测试、容器化环境以及常见的软件构建、测试和发布方式。\n 4. 对大语言模型和 Agent 有较深入理解，熟悉 Prompt、上下文管理、任务规划、工具调用、多轮交互、代码执行及错误恢复等基本机制。\n 5. 具备评测方案设计能力，能够将模糊的质量问题转化为明确的评测任务、指标、评分规则和验收标准。\n 6. 具备良好的数据分析和实验能力，能够从评测数据和执行轨迹中发现规律、归纳失败类型并定位问题根因。\n 7. 具备较强的业务理解、逻辑分析和跨团队协作能力，能够推动评测方案在真实研发场景中落地。\n 8. 对 AI 编程和 Agent 技术保持高度关注，愿意持续探索新模型、新工具和新的评测方法。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1. 负责通用 Agent、Code Agent 及 AI 研发工具的评测体系设计与建设，支撑模型、Prompt、工具和 Agent 工作流的持续迭代。\n 2. 深入需求分析、技术方案设计、代码生成与修改、测试生成、代码评审、缺陷修复和故障诊断等研发场景，将真实研发流程抽象为可复现、可扩展的评测任务。\n 3. 建立覆盖任务完成度、需求符合度、代码正确性、工具调用、规划执行、稳定性、安全性、成本和时延等维度的评测指标体系。\n 4. 负责评测数据和样本建设，持续沉淀真实任务、典型失败案例、线上反馈及核心回归用例，保障评测数据的代表性、区分度和可维护性。\n 5. 设计和研发自动化评测框架及平台，支持任务批量执行、过程数据采集、自动评分、版本对比、回归分析、异常告警和结果可视化。\n 6. 分析 Agent 的执行轨迹，定位其在需求理解、任务规划、上下文使用、工具调用、代码修改、测试执行和错误恢复等环节的问题，判断问题来源并提出改进建议。\n 7. 建立线上反馈与离线评测之间的闭环，将用户反馈、任务失败、人工接管和异常行为转化为可复现的评测与回归用例。\n 8. 与产品、算法、研发、测试及平台团队协作，推动评测结果应用于模型选择、Agent 优化、版本验收和发布决策。\n\n岗位基本要求\n1. 计算机科学、软件工程、人工智能或相关专业本科及以上学历，具备 3 年及以上软件研发、测试开发、质量工程、研发效能或 AI 工程经验。\n 2. 熟练掌握 Python、Go、Java 或 TypeScript 中至少一种编程语言，具备良好的工程实现能力，能够独立完成评测工具、服务或平台模块的设计与开发。\n 3. 熟悉软件研发流程，了解 Git、CI/CD、自动化测试、容器化环境以及常见的软件构建、测试和发布方式。\n 4. 对大语言模型和 Agent 有较深入理解，熟悉 Prompt、上下文管理、任务规划、工具调用、多轮交互、代码执行及错误恢复等基本机制。\n 5. 具备评测方案设计能力，能够将模糊的质量问题转化为明确的评测任务、指标、评分规则和验收标准。\n 6. 具备良好的数据分析和实验能力，能够从评测数据和执行轨迹中发现规律、归纳失败类型并定位问题根因。\n 7. 具备较强的业务理解、逻辑分析和跨团队协作能力，能够推动评测方案在真实研发场景中落地。\n 8. 对 AI 编程和 Agent 技术保持高度关注，愿意持续探索新模型、新工具和新的评测方法。\n\n具备以下条件优先\n1. 有大模型或 Agent 评测体系、评测平台建设经验；\n 2. 有 Code Agent、AI 编程工具或研发智能化相关实践；\n 3. 熟悉 Agent 的规划、工具调用和代码执行机制；\n 4. 有评测数据集或 Benchmark 建设经验。\n\n岗位亮点\n1. 聚焦大模型与 Agent 前沿方向，参与通用 Agent、Code Agent 评测体系从设计到落地的完整建设；\n 2. 深入需求分析、技术设计、编码、测试和代码评审等真实研发流程，探索 AI 在复杂软件研发场景中的能力边界；\n 3. 参与评测框架、评测平台、指标体系及评测数据建设，形成从用例构建、自动执行到结果分析的完整实践；\n 4. 与模型、Agent、研发工具及业务团队紧密协作，通过评测发现问题并推动模型与智能体持续迭代；\n 5. 面向大规模、可复现的 Agent 评测挑战，积累 AI 评测、研发效能和平台工程等复合领域经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4728247570","sourceKey":"meituan_social","company":"美团","title":"小象超市-服务体验运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4728247570&jobShareType=1","duty":"1、服务策略设计：负责小象超市服务体验策略设计，深入了解自营即时零售业务全链路，制定对标行业高水平的售后服务标准和体验指标体系；\n2、服务流程优化：协同产品、技术、客服团队，通过服务流程再造、智能能力应用和解决方案升级，持续优化运营效率，确保关键场景下用户求助小象时获得高效、有温度的服务体验；\n3、主动服务探索：基于用户行为数据和投诉模式分析，探索从\"被动响应\"到\"主动预防\"的服务新模式，推动服务前置化，将用户粘性提升作为核心目标；\n4、数据驱动洞察：通过工单分析、用户反馈挖掘、满意度数据追踪等方式，定期输出体验诊断报告和优化方案，用数据说话，推动服务运营成本效率和用户体验的双重提升；\n5、AI工具赋能：熟练使用AI工具辅助数据分析、洞察挖掘、方案撰写等工作，探索AI在服务运营场景的创新应用（如智能工单分类、投诉主题聚类、用户画像分析等），持续提升工作效率；\n6、行业对标与创新：持续关注即时零售行业服务体验趋势和动态，借鉴行业最佳实践，为业务带来前沿的服务运营思路和创新方案。","requirements":"1、本科及以上学历，有3年以上体验优化或服务运营工作经验；\n2、有良好的服务运营及用户体验改善意识，数据分析能力强，能够通过数据洞察问题；\n3、有较强的目标感和拿结果意识，自驱力强，具备坚韧性；\n4、对新事物有较强的学习能力，可以快速抓住事物规律并举一反三；\n5、较好的沟通能力、合作共赢的意识和反向驱动能力；\n6、掌握基本的AI工具，使用工具提升工作流程效率；\n7、有AI工具实际应用经验（如大模型辅助分析、AI自动化流程等）优先；\n8、有智能客服、AI客服相关项目经验优先。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、服务策略设计：负责小象超市服务体验策略设计，深入了解自营即时零售业务全链路，制定对标行业高水平的售后服务标准和体验指标体系；\n2、服务流程优化：协同产品、技术、客服团队，通过服务流程再造、智能能力应用和解决方案升级，持续优化运营效率，确保关键场景下用户求助小象时获得高效、有温度的服务体验；\n3、主动服务探索：基于用户行为数据和投诉模式分析，探索从\"被动响应\"到\"主动预防\"的服务新模式，推动服务前置化，将用户粘性提升作为核心目标；\n4、数据驱动洞察：通过工单分析、用户反馈挖掘、满意度数据追踪等方式，定期输出体验诊断报告和优化方案，用数据说话，推动服务运营成本效率和用户体验的双重提升；\n5、AI工具赋能：熟练使用AI工具辅助数据分析、洞察挖掘、方案撰写等工作，探索AI在服务运营场景的创新应用（如智能工单分类、投诉主题聚类、用户画像分析等），持续提升工作效率；\n6、行业对标与创新：持续关注即时零售行业服务体验趋势和动态，借鉴行业最佳实践，为业务带来前沿的服务运营思路和创新方案。\n\n岗位基本要求\n1、本科及以上学历，有3年以上体验优化或服务运营工作经验；\n2、有良好的服务运营及用户体验改善意识，数据分析能力强，能够通过数据洞察问题；\n3、有较强的目标感和拿结果意识，自驱力强，具备坚韧性；\n4、对新事物有较强的学习能力，可以快速抓住事物规律并举一反三；\n5、较好的沟通能力、合作共赢的意识和反向驱动能力；\n6、掌握基本的AI工具，使用工具提升工作流程效率；\n7、有AI工具实际应用经验（如大模型辅助分析、AI自动化流程等）优先；\n8、有智能客服、AI客服相关项目经验优先。\n\n具备以下条件优先\n零售行业客户体验、服务体验、体验运营经验优先；有用户洞察、策略运营、经营分析、SQL能力优先；\n\n岗位亮点\n零售行业是重点发展领域，用户体验又是重点关注范畴，具有长期可发展和成长性。\n美团2025年提出AI三大策略，\"AI at Work\"已渗透到工作的每个角落——从CatPaw AI编程到NoCode零代码平台，从美境MeiGen图像生成到LongCat视频生成。你不仅会用AI工具辅助日常工作，更有机会探索AI在服务运营场景的落地应用，成为AI+零售服务的先行者。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4109755395","sourceKey":"meituan_social","company":"美团","title":"策略运营专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4109755395&jobShareType=1","duty":"负责火石项目的整体运营策略制定与执行，结合AI数据分析工具洞察业务趋势，驱动项目目标达成。\n协调跨部门资源，运用项目管理工具及AI辅助决策手段，推动关键节点高效落地，持续优化运营流程。\n搭建并维护项目数据看板，善用AI分析工具进行深度数据挖掘，定期输出运营报告并推动改进措施实施。\n对接内外部合作伙伴，维护项目相关方关系，探索AI在合作伙伴管理及沟通协同中的应用场景。\n主动探索AI驱动的创新运营模式，推动运营流程智能化升级，提升项目效率及用户满意度。","requirements":"大学本科及以上学历，专业不限。\n具备资深运营经验，熟悉项目管理全流程，有将AI工具融入日常运营的实践经验者优先。\n优秀的沟通协调能力，能高效推动跨部门协作。\n数据敏感，具备较强的分析能力和问题解决能力，熟悉至少一种AI辅助分析工具。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n负责火石项目的整体运营策略制定与执行，结合AI数据分析工具洞察业务趋势，驱动项目目标达成。\n协调跨部门资源，运用项目管理工具及AI辅助决策手段，推动关键节点高效落地，持续优化运营流程。\n搭建并维护项目数据看板，善用AI分析工具进行深度数据挖掘，定期输出运营报告并推动改进措施实施。\n对接内外部合作伙伴，维护项目相关方关系，探索AI在合作伙伴管理及沟通协同中的应用场景。\n主动探索AI驱动的创新运营模式，推动运营流程智能化升级，提升项目效率及用户满意度。\n\n岗位基本要求\n大学本科及以上学历，专业不限。\n具备资深运营经验，熟悉项目管理全流程，有将AI工具融入日常运营的实践经验者优先。\n优秀的沟通协调能力，能高效推动跨部门协作。\n数据敏感，具备较强的分析能力和问题解决能力，熟悉至少一种AI辅助分析工具。\n\n具备以下条件优先\n有研究分析背景、项目成功经验、销售/运营管理经验，会sql者优先；\n\n岗位亮点\n深度参与AI+运营的前沿实践，接触创新业务模式。\n扁平化管理，直接与核心团队共事，快速获得AI应用落地经验。\n团队氛围开放，鼓励用AI提效和创新试错。\n有机会参与公司战略级项目规划，推动AI在业务场景的规模化应用。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3699347001","sourceKey":"meituan_social","company":"美团","title":"硬件产品技术项目经理-TPM","city":"深圳市/北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3699347001&jobShareType=1","duty":"主要负责美团末端配送机器人产品的研发管理工作，涵盖产品研发的全生命周期管理：从研发到量产交付，制定计划、分解任务、监控进度与风险。\n\n主导技术方案评审，解决硬件-软件协同问题（如传感器融合、建图/定位/路径规划），推动高风险项闭环。\n\n协调研发、供应链、测试及外部供应商，确保资源匹配项目节奏，平衡技术深度与交付效率。\n\n优化硬件开发流程（IPD经验优先），通过复盘与培训提升团队技术能力与协作效率。\n\n​跟踪机器人领域前沿技术发展（如具身智能、灵巧手操作、端到端学习、视觉-语言-动作模型VLA等），评估其在产品中的应用潜力，推动技术预研与创新落地。​​","requirements":"本科及以上学历，自动化/机器人/计算机等相关专业。\n\n5年以上硬件项目管理经验，至少1款量产产品交付，有移动机器人/无人车/AGV/AMR/服务机器人等产品量产经验优先。\n\n熟悉机器人核心技术（建图、定位、运动控制、传感器集成、ROS/ROS2），能主导评审技术方案。\n\n掌握IPD流程，有PMP/NPDP/Scrum认证优先。\n\n​核心能力\n\n技术翻译能力：清晰传递技术边界与业务需求，协调技术团队与业务方目标。\n\n风险管控：快速解决技术难题，适应高强度节奏，确保项目按时交付。\n\n跨团队协作：强沟通与领导力，推动多部门（嵌软、硬件、算法、系统、质量等部门）高效合作。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n主要负责美团末端配送机器人产品的研发管理工作，涵盖产品研发的全生命周期管理：从研发到量产交付，制定计划、分解任务、监控进度与风险。\n\n主导技术方案评审，解决硬件-软件协同问题（如传感器融合、建图/定位/路径规划），推动高风险项闭环。\n\n协调研发、供应链、测试及外部供应商，确保资源匹配项目节奏，平衡技术深度与交付效率。\n\n优化硬件开发流程（IPD经验优先），通过复盘与培训提升团队技术能力与协作效率。\n\n​跟踪机器人领域前沿技术发展（如具身智能、灵巧手操作、端到端学习、视觉-语言-动作模型VLA等），评估其在产品中的应用潜力，推动技术预研与创新落地。​​\n\n岗位基本要求\n本科及以上学历，自动化/机器人/计算机等相关专业。\n\n5年以上硬件项目管理经验，至少1款量产产品交付，有移动机器人/无人车/AGV/AMR/服务机器人等产品量产经验优先。\n\n熟悉机器人核心技术（建图、定位、运动控制、传感器集成、ROS/ROS2），能主导评审技术方案。\n\n掌握IPD流程，有PMP/NPDP/Scrum认证优先。\n\n​核心能力\n\n技术翻译能力：清晰传递技术边界与业务需求，协调技术团队与业务方目标。\n\n风险管控：快速解决技术难题，适应高强度节奏，确保项目按时交付。\n\n跨团队协作：强沟通与领导力，推动多部门（嵌软、硬件、算法、系统、质量等部门）高效合作。\n\n具备以下条件优先\n有移动机器人/无人车/AGV/AMR/服务机器人等产品研发经验。\n\n熟悉常见的传感器，如激光雷达/IMU/视觉/TOF等传感器调试，具备成本管控与产品思维。\n\n​对机器人前沿技术（如具身智能、灵巧手、端到端学习、VLA等）有深入理解或实践经历，具备技术前瞻性与创新整合能力。​​\n\n岗位亮点\n前沿技术场景：参与配送机器人从算法、软件、硬件到量产的全栈开发，挑战复杂业务落地；深入探索具身智能、VLA等前沿技术在实际场景中的赋能与应用。​​\n\n快速成长团队：与行业优秀人才共事，主导从0到1产品孵化。\n\n高价值回报：直接影响千万级用户场景，成果可见度高。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4722120355","sourceKey":"meituan_social","company":"美团","title":"商品产品经理","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4722120355&jobShareType=1","duty":"1.负责服务零售商品领域中商品应用管理能力的建设，包括商品生产工具、商品信息应用等；\n2.深入业务场景，挖掘运营痛点并抽象共性需求，设计通用化平台能力，协同业务团队推动核心指标达成；\n3.以数据驱动为核心，构建商品数据化运营体系，优化供货与控货系统流程，提升供给规模与质量；\n4.提升商品领域AI友好度，扩展多角色的商品应用。","requirements":"1.本科及以上学历，2年以上O2O或电商行业产品设计经验；\n2.熟悉商品领域或商户端工具设计，理解商品信息模型（SPU/SKU/属性体系）或库存管理的底层逻辑；\n3.数据敏感性强，能通过数据分析指导产品迭代与决策；\n4.具备优秀的学习能力和独立思考能力，能快速理解复杂业务；\n5.良好的表达和沟通能力，擅长跨团队协作，能推动项目高效落地；\n6.对AI新技术抱有浓厚兴趣，乐于探索AI可能，积极实践。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1.负责服务零售商品领域中商品应用管理能力的建设，包括商品生产工具、商品信息应用等；\n2.深入业务场景，挖掘运营痛点并抽象共性需求，设计通用化平台能力，协同业务团队推动核心指标达成；\n3.以数据驱动为核心，构建商品数据化运营体系，优化供货与控货系统流程，提升供给规模与质量；\n4.提升商品领域AI友好度，扩展多角色的商品应用。\n\n岗位基本要求\n1.本科及以上学历，2年以上O2O或电商行业产品设计经验；\n2.熟悉商品领域或商户端工具设计，理解商品信息模型（SPU/SKU/属性体系）或库存管理的底层逻辑；\n3.数据敏感性强，能通过数据分析指导产品迭代与决策；\n4.具备优秀的学习能力和独立思考能力，能快速理解复杂业务；\n5.良好的表达和沟通能力，擅长跨团队协作，能推动项目高效落地；\n6.对AI新技术抱有浓厚兴趣，乐于探索AI可能，积极实践。\n\n具备以下条件优先\nAI应用工具或商品领域从事经验。\n\n岗位亮点\n1. 聚焦零售核心环节，直接参与千万级商品管理系统的优化与创新；\n2. 深度结合AI技术，探索智能商品管理的前沿应用场景；\n3. 扁平化协作模式，拥有产品决策权与快速成长空间； \n4. 团队氛围友好简单，鼓励深入思考成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4692331901","sourceKey":"meituan_social","company":"美团","title":"Admin Specialist-Asia&Europe","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4692331901&jobShareType=1","duty":"1.负责制定和执行海外办公室行政支持策略，为客户提供标准化和定制化行政服务方案，不断提升服务满意度；\n2.负责搭建海外办公室全生命周期流程制度体系和质量运营标准，并实施落地跟踪，包括但不限于办公室交付、5S管理、办公安全、突发事件应急处置；\n3.负责对海外办公室行政费用、工位空间等数据进行整合分析，监控异常数据并推动解决，实现行政成本的合理管控、降本增效；\n4.针对客户需求提供相应供应商解决方案，并制定对第三方供应商的管理要求和考核评估方案；\n5.负责统筹海外办公室行政的各项培训工作，赋能提升海外行政员工的整体能力；\n6.负责协助进行员工入离职和办公室内氛围营造工作；\n7.协同职能部门支持公司各项工作在海外的落地。\n\nResponsibilities\n1.Develop and execute administrative support strategies for overseas offices, delivering standardized and customized service solutions to enhance client satisfaction.\n2.Establish full lifecycle process systems and quality operational standards for overseas offices, including but not limited to:\n0ffice delivery and setup,5S management,Workplace safety,Emergency response protocols.Ensure implementation and continuous monitoring of these standards.\n3.Consolidate and analyze data on administrative costs, workspace utilization, etc. Monitor anomalies, drive resolutions, and achieve cost-effective management through optimization and efficiency improvements.\n4.Design vendor solutions tailored to client needs, and develop management requirements and performance evaluation frameworks for third-party suppliers.\n5.Oversee training programs for overseas administrative staff to enhance competencies and drive team empowerment.\n6.Assist with employee onboarding/offboarding procedures and foster a positive workplace atmosphere.\n7.Coordinate with functional departments to support the implementation of the company's overseas operations.","requirements":"1.本科及以上学历；\n2.具有5年以上行政工作经验；且至少有2年国外工作或生活经验。\n3.在办公室运营和维护方面拥有丰富经验。\n4.熟悉空间管理及空间成本优化。\n5.具备出色的职业道德和卓越的能力。\n6.具有强烈的客户服务意识，出色的沟通能力和创新精神。\n7.英语阅读、口语和听力理解能力流利。\n8.能够接受不少于1年的国外出差。\n\n1.Bachelor's degree or higher.\n2.Minimum 5 years of administrative experience in an office environment, including at least 2 years of international work or residency experience.\n3.Extensive expertise in office operations and facility management.\n4.Proficiency in space planning and occupancy cost optimization.\n5.Demonstrated professional integrity and exceptional performance capabilities.\n6.Strong customer service orientation, outstanding communication skills, and innovative problem-solving mindset.\n7.Fluency in English (reading, speaking, and listening comprehension).\n8.Advanced proficiency in Ms 0ffice Suite.\n9.Willing and able to accept overseas business trips for a duration of more than one year.","description":"部门介绍\n公司事务平台负责构建公司的公共战略体系，助力业务可持续发展及公司对外影响力的提升。通过内外部风险管理，确保公司合规发展；通过深耕公共战略，推动内外良好沟通，连接公司发展与社会期待，助力业务高质量发展；通过管理社会责任议题、公益投入等，助力公司创造更多社会价值；同时为公司提供行政、采购等基础服务。我们坚持“懂业务、拿结果，勇担当、善协同，不唯上、只唯真”的工作理念，期待具有公共战略素养、了解公司治理逻辑的你加入！\n\n岗位职责\n1.负责制定和执行海外办公室行政支持策略，为客户提供标准化和定制化行政服务方案，不断提升服务满意度；\n2.负责搭建海外办公室全生命周期流程制度体系和质量运营标准，并实施落地跟踪，包括但不限于办公室交付、5S管理、办公安全、突发事件应急处置；\n3.负责对海外办公室行政费用、工位空间等数据进行整合分析，监控异常数据并推动解决，实现行政成本的合理管控、降本增效；\n4.针对客户需求提供相应供应商解决方案，并制定对第三方供应商的管理要求和考核评估方案；\n5.负责统筹海外办公室行政的各项培训工作，赋能提升海外行政员工的整体能力；\n6.负责协助进行员工入离职和办公室内氛围营造工作；\n7.协同职能部门支持公司各项工作在海外的落地。\n\nResponsibilities\n1.Develop and execute administrative support strategies for overseas offices, delivering standardized and customized service solutions to enhance client satisfaction.\n2.Establish full lifecycle process systems and quality operational standards for overseas offices, including but not limited to:\n0ffice delivery and setup,5S management,Workplace safety,Emergency response protocols.Ensure implementation and continuous monitoring of these standards.\n3.Consolidate and analyze data on administrative costs, workspace utilization, etc. Monitor anomalies, drive resolutions, and achieve cost-effective management through optimization and efficiency improvements.\n4.Design vendor solutions tailored to client needs, and develop management requirements and performance evaluation frameworks for third-party suppliers.\n5.Oversee training programs for overseas administrative staff to enhance competencies and drive team empowerment.\n6.Assist with employee onboarding/offboarding procedures and foster a positive workplace atmosphere.\n7.Coordinate with functional departments to support the implementation of the company's overseas operations.\n\n岗位基本要求\n1.本科及以上学历；\n2.具有5年以上行政工作经验；且至少有2年国外工作或生活经验。\n3.在办公室运营和维护方面拥有丰富经验。\n4.熟悉空间管理及空间成本优化。\n5.具备出色的职业道德和卓越的能力。\n6.具有强烈的客户服务意识，出色的沟通能力和创新精神。\n7.英语阅读、口语和听力理解能力流利。\n8.能够接受不少于1年的国外出差。\n\n1.Bachelor's degree or higher.\n2.Minimum 5 years of administrative experience in an office environment, including at least 2 years of international work or residency experience.\n3.Extensive expertise in office operations and facility management.\n4.Proficiency in space planning and occupancy cost optimization.\n5.Demonstrated professional integrity and exceptional performance capabilities.\n6.Strong customer service orientation, outstanding communication skills, and innovative problem-solving mindset.\n7.Fluency in English (reading, speaking, and listening comprehension).\n8.Advanced proficiency in Ms 0ffice Suite.\n9.Willing and able to accept overseas business trips for a duration of more than one year.\n\n具备以下条件优先\n1.拥有扎实的租赁谈判和管理/项目管理技能；\n2.熟练掌握与消防系统和环境安全相关的法律、法规和标准。\n1.Solid lease negotiation and management/project management skills.\n2.Well grasp of laws, regulations and standard related to fire protection system and environment safety.\n\n岗位亮点\n1.多元文化环境和国际化团队协作经验\n2.国际化视野和多样性的发展机会\n\n1.Multicultural environment and international team collaboration experience.\n2.International perspectives and diverse development opportunities.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4223713449","sourceKey":"meituan_social","company":"美团","title":"Keeta技术-资深架构师（稳定性与AI平台方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4223713449&jobShareType=1","duty":"1. [稳定性方向]容量保障与核心链路方向：建设服务及核心链路容量保障体系，推动单机压测、全链路压测、容量水位探测、弹性、限流和容量托管等能力落地；建立核心链路持续运营机制，系统识别依赖、调用关系和流量变化，提升容量风险发现与应对效率。\n2. [稳定性方向]变更防御与提效：面向 Keeta 多控制面等复杂变更场景，建设变更风险识别、检查和拦截能力，推动变更流程标准化、自动化，提升变更效率并降低稳定性风险。\n3. [AI平台方向]AI运维与架构元数据方向：建设统一的架构元数据底座，沉淀服务、链路、依赖、告警、变更、容量、部署和预案等基础数据；基于知识库和 Agent，打造稳定性运营、变更防御、告警降噪、根因分析和故障应急能力。\n4. [AI平台方向]AI技术落地与赋能： 紧跟 AI 技术前沿，探索 LLM/Agent 在研发效能、SRE 运维场景下的实际应用。将复杂的稳定性排障流程转化为与 AI 协同的自动化工具，极大降低人工介入成本。","requirements":"1. 扎实的技术基本功：本科及以上学历，计算机相关专业。3年以上后端研发或架构经验，精通 Java/Go，对高并发、分布式系统、微服务架构有深刻理解和实战经验。\n2. 至少具备以下一个方向的深入经验：\n   - 稳定性方向： 熟悉国内/国际化稳定性保障方法论。对可观测性、混沌工程、容量保障有落地经验。\n   - AI运维与元数据方向：具备良好的数据建模和系统抽象能力，了解 CMDB、服务目录、调用链、元数据治理或知识图谱；了解 LLM、RAG、知识库、工作流和 Agent 等技术。\n   - AI实战能力：对AI技术发展有浓厚兴趣，熟悉并跟进AI/Agent技术，有将 AI 技术应用于实际工程问题解决的经验或意愿。\n3. 好奇心与学习力： 具备技术自驱力和快速学习的能力。\n加分项\n1. 有 AIOps、稳定性平台、CMDB、服务目录、架构元数据或容量平台从0到1建设经验。\n2. 有 LLM/Agent 在研发效能、智能运维、故障诊断、变更分析或容量规划场景中的实际落地经验。\n3. 有可观测性、混沌工程、稳定性工具或 AI 相关开源项目贡献经验。\n4. 有大规模压测、容量托管、弹性限流、流量治理或核心链路持续运营经验。\n5. 有全球化、多 Region、多云或多控制面系统建设经验。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1. [稳定性方向]容量保障与核心链路方向：建设服务及核心链路容量保障体系，推动单机压测、全链路压测、容量水位探测、弹性、限流和容量托管等能力落地；建立核心链路持续运营机制，系统识别依赖、调用关系和流量变化，提升容量风险发现与应对效率。\n2. [稳定性方向]变更防御与提效：面向 Keeta 多控制面等复杂变更场景，建设变更风险识别、检查和拦截能力，推动变更流程标准化、自动化，提升变更效率并降低稳定性风险。\n3. [AI平台方向]AI运维与架构元数据方向：建设统一的架构元数据底座，沉淀服务、链路、依赖、告警、变更、容量、部署和预案等基础数据；基于知识库和 Agent，打造稳定性运营、变更防御、告警降噪、根因分析和故障应急能力。\n4. [AI平台方向]AI技术落地与赋能： 紧跟 AI 技术前沿，探索 LLM/Agent 在研发效能、SRE 运维场景下的实际应用。将复杂的稳定性排障流程转化为与 AI 协同的自动化工具，极大降低人工介入成本。\n\n岗位基本要求\n1. 扎实的技术基本功：本科及以上学历，计算机相关专业。3年以上后端研发或架构经验，精通 Java/Go，对高并发、分布式系统、微服务架构有深刻理解和实战经验。\n2. 至少具备以下一个方向的深入经验：\n   - 稳定性方向： 熟悉国内/国际化稳定性保障方法论。对可观测性、混沌工程、容量保障有落地经验。\n   - AI运维与元数据方向：具备良好的数据建模和系统抽象能力，了解 CMDB、服务目录、调用链、元数据治理或知识图谱；了解 LLM、RAG、知识库、工作流和 Agent 等技术。\n   - AI实战能力：对AI技术发展有浓厚兴趣，熟悉并跟进AI/Agent技术，有将 AI 技术应用于实际工程问题解决的经验或意愿。\n3. 好奇心与学习力： 具备技术自驱力和快速学习的能力。\n加分项\n1. 有 AIOps、稳定性平台、CMDB、服务目录、架构元数据或容量平台从0到1建设经验。\n2. 有 LLM/Agent 在研发效能、智能运维、故障诊断、变更分析或容量规划场景中的实际落地经验。\n3. 有可观测性、混沌工程、稳定性工具或 AI 相关开源项目贡献经验。\n4. 有大规模压测、容量托管、弹性限流、流量治理或核心链路持续运营经验。\n5. 有全球化、多 Region、多云或多控制面系统建设经验。\n\n岗位亮点\nKeeta业务运行在多国家、多 Region、多控制面的全球化架构之上。面对复杂的网络环境和快速发展的业务场景，稳定性是支撑业务持续发展的关键技术能力。\n我们正在从0到1建设下一代 AI智能化稳定性平台，建设统一、在线、持续保鲜的架构元数据底座和稳定性知识库，探索 LLM、RAG、智能工作流和 Agent 在稳定性运营、风险分析、故障定位、变更防御及应急处置等场景中的应用。\n你也将参与全球化稳定性能力建设，覆盖核心链路、单机及全链路压测、弹性限流、容量托管、变更管控和故障应急等方向，推动稳定性保障逐步走向标准化、自动化和智能化。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4735188446","sourceKey":"meituan_social","company":"美团","title":"小象超市-西安水产品控主管","city":"西安市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4735188446&jobShareType=1","duty":"1. 梳理水产养殖的各流程环节，建立标准操作流程和技术手册，梳理形成操作技术规范赋能到服务站团队进行使用，持续降低损耗率和死亡率；\n2. 跟踪活鲜养殖领域的核心技术，包括水产收货、养殖、制冷、供氧、过滤、海水配置、宰杀、配送等，并通过专业赋能公司；\n3. 通过日常巡店，不断完善操作流程和技术手册，定期对服务站培训输出，提升服务站团队运营能力；\n4. 具备兽残检测能力优先考虑，如：孔雀石绿、呋喃系列、氯霉素、磺胺类等。","requirements":"1.大专及以上学历，熟悉水产供应链路，有水产管理经验或水产养殖相关工作经验；\n2.责任心强，有推动问题解决的魄力和担当；\n3.具备较好的跨部门沟通表达及协作能力，能有效沟通并达成一致，并推行落地；\n4.能主动跟进闭环管理数据分析异动，据指标并执行落地。有较强的质量管理方法论且可以快速结合业务特点落地能力；\n5.坚持正直诚信原则底线。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 梳理水产养殖的各流程环节，建立标准操作流程和技术手册，梳理形成操作技术规范赋能到服务站团队进行使用，持续降低损耗率和死亡率；\n2. 跟踪活鲜养殖领域的核心技术，包括水产收货、养殖、制冷、供氧、过滤、海水配置、宰杀、配送等，并通过专业赋能公司；\n3. 通过日常巡店，不断完善操作流程和技术手册，定期对服务站培训输出，提升服务站团队运营能力；\n4. 具备兽残检测能力优先考虑，如：孔雀石绿、呋喃系列、氯霉素、磺胺类等。\n\n岗位基本要求\n1.大专及以上学历，熟悉水产供应链路，有水产管理经验或水产养殖相关工作经验；\n2.责任心强，有推动问题解决的魄力和担当；\n3.具备较好的跨部门沟通表达及协作能力，能有效沟通并达成一致，并推行落地；\n4.能主动跟进闭环管理数据分析异动，据指标并执行落地。有较强的质量管理方法论且可以快速结合业务特点落地能力；\n5.坚持正直诚信原则底线。\n\n具备以下条件优先\n有熟知活鲜水产行业，全球渔业生产分布，工业化活鲜养殖技术等。具有较强的快速学习能力以及解决问题能力。\n\n岗位亮点\n1. 加入快速发展的美团小象平台，参与核心品控环节。\n2. 接触多元生鲜品类，积累行业深度经验。\n3. 扁平化管理，直接对接业务核心团队。\n4. 提供系统化品控培训及职业发展支持。\n5. 候选人的才华将直接对行业产生影响。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4635518858","sourceKey":"meituan_social","company":"美团","title":"产品体验设计专家","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4635518858&jobShareType=1","duty":"1. 负责产品用户体验设计，包括用户研究、交互设计、视觉设计及原型制作。  \n2. 深入理解业务需求，结合用户反馈与数据洞察，持续优化产品体验。  \n3. 协同产品经理、开发团队及用研团队，推动设计方案落地并跟踪效果。  \n4. 建立并维护设计规范与组件库，提升设计一致性与团队效率。  \n5. 关注行业趋势与动态，探索创新设计解决方案。","requirements":"1. 大学本科及以上学历，设计类相关专业背景。  \n2. 5年以上产品体验设计经验，具备完整项目落地经验。  \n3. 熟练使用各类设计及AI工具。  \n4. 具备良好的用户思维与逻辑分析能力，能独立完成设计闭环。  \n5. 优秀的沟通协作能力，能与跨职能团队高效配合。","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1. 负责产品用户体验设计，包括用户研究、交互设计、视觉设计及原型制作。  \n2. 深入理解业务需求，结合用户反馈与数据洞察，持续优化产品体验。  \n3. 协同产品经理、开发团队及用研团队，推动设计方案落地并跟踪效果。  \n4. 建立并维护设计规范与组件库，提升设计一致性与团队效率。  \n5. 关注行业趋势与动态，探索创新设计解决方案。\n\n岗位基本要求\n1. 大学本科及以上学历，设计类相关专业背景。  \n2. 5年以上产品体验设计经验，具备完整项目落地经验。  \n3. 熟练使用各类设计及AI工具。  \n4. 具备良好的用户思维与逻辑分析能力，能独立完成设计闭环。  \n5. 优秀的沟通协作能力，能与跨职能团队高效配合。\n\n岗位亮点\n1. 参与核心产品创新，直接影响千万级用户的产品体验。  \n2. 扁平化管理，开放的设计文化，鼓励创新与专业成长。  \n3. 提供行业内有竞争力的薪酬与完善的职业发展通道。  \n4. 位于上海核心区域，办公环境优越，团队氛围活跃。  \n5. 定期组织设计分享与培训，支持个人能力提升与行业交流。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4723881001","sourceKey":"meituan_social","company":"美团","title":"生鲜生产主管","city":"济南市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4723881001&jobShareType=1","duty":"1. 负责生鲜产品的生产计划制定与执行，确保生产任务按时完成。  \n2. 管理并指导50人团队，优化生产流程，提升作业效率与产品质量。  \n3. 监控生鲜作业过程标准及质量。  \n4.人员健康度管理，入离职管理。","requirements":"1. 大学本科及以上学历，物流、供应链管理或相关专业优先。  \n2. 具备3年以上生鲜物流或生产运营相关工作经验。  \n3. 熟悉生鲜产品特性及冷链物流管理流程。  \n4. 具备较强的团队管理与沟通协调能力。  \n5. 工作责任心强，能适应快节奏工作环境。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责生鲜产品的生产计划制定与执行，确保生产任务按时完成。  \n2. 管理并指导50人团队，优化生产流程，提升作业效率与产品质量。  \n3. 监控生鲜作业过程标准及质量。  \n4.人员健康度管理，入离职管理。\n\n岗位基本要求\n1. 大学本科及以上学历，物流、供应链管理或相关专业优先。  \n2. 具备3年以上生鲜物流或生产运营相关工作经验。  \n3. 熟悉生鲜产品特性及冷链物流管理流程。  \n4. 具备较强的团队管理与沟通协调能力。  \n5. 工作责任心强，能适应快节奏工作环境。\n\n岗位亮点\n1. 工作地点位于济南市；  \n2. 提供完善的培训体系与职业发展通道。  \n3. 团队规模较大，具备丰富的管理实践机会。  \n4. 行业前景广阔，生鲜电商与冷链物流快速发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4732047158","sourceKey":"meituan_social","company":"美团","title":"快驴-进向-杭州运营主管","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4732047158&jobShareType=1","duty":"1、负责城市进向物流业务经营与运营管理，包括上门揽收，数量清点、运输短驳、成本管控等工作\n2、负责管辖区域内的渗透率，负责卖家维护、卖家拜访、招商协同，对接下游的运营需求\n3、卖家客情维护，定期拜访/回访卖家，收集并理解卖家需求，做好服务产品的优化迭代\n4、负责司机招募，大车型占比提升降低运营成本，提升进向物流运营成本，改善经营损益\n5、根据卖家的日常反馈，协助经理推动优化运营流程和产品能力，提升客户体验","requirements":"1、大专及以上学历，具备良好的学习能力\n2、有出色的沟通表达能力，具备良好的客户关系管理和谈判能力\n3、2年以上市场推广或销售经验更佳\n4、熟悉物流行业、生鲜零售行业","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1、负责城市进向物流业务经营与运营管理，包括上门揽收，数量清点、运输短驳、成本管控等工作\n2、负责管辖区域内的渗透率，负责卖家维护、卖家拜访、招商协同，对接下游的运营需求\n3、卖家客情维护，定期拜访/回访卖家，收集并理解卖家需求，做好服务产品的优化迭代\n4、负责司机招募，大车型占比提升降低运营成本，提升进向物流运营成本，改善经营损益\n5、根据卖家的日常反馈，协助经理推动优化运营流程和产品能力，提升客户体验\n\n岗位基本要求\n1、大专及以上学历，具备良好的学习能力\n2、有出色的沟通表达能力，具备良好的客户关系管理和谈判能力\n3、2年以上市场推广或销售经验更佳\n4、熟悉物流行业、生鲜零售行业\n\n岗位亮点\n1.在初创期投入生鲜电商领域，作为先驱者和公司共同摸索成长，锤炼对仓储管理的认识。\n2.知名互联网公司与传统物流行业的深度结合，与来自供应链领域的精英共事。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4727978510","sourceKey":"meituan_social","company":"美团","title":"美甲行业运营（STO）","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4727978510&jobShareType=1","duty":"1、深度参与 AI 应用探索与落地：结合业务场景，在用户增长、选品选店选款、商家赋能及商业化等方向，梳理工作流，主动发现 AI 应用机会，设计并验证新的业务模式与效率工具，快速将业务需求转化为可运行的解决方案，缩短从想法到落地的路径；\n\n2、深潜行业并为业务结果负责：深刻理解垂直行业，从复杂的业务场景/数据中挖掘用户/商户痛点和本质需求，发现平台机会点，制定产品/运营/商业化策略，快速验证策略可行性；\n\n3、持续学习与输出：持续学习跟进行业趋势变化及 AI 前沿动态，将模型能力、工具链快速转化为业务价值，在团队内部沉淀方法论与最佳实践。","requirements":"1、行业Owner：直接为行业目标和结果负责，理解商户生态、用户心智和竞争格局，能从行业视角发现问题和机会，具备业务节奏感。\n\n2、产品设计力： 能从业务问题出发拆解需求、设计解决方案，具备用户体验思维和数据验证意识，会正确评估结果，评估长短期影响。\n\n3、AI工具力： 能用Vibe Coding/FDE/AI Agent等工具，自主完成轻量功能搭建、数据看板、自动化工作流，不依赖研发排期解决自闭环层问题。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1、深度参与 AI 应用探索与落地：结合业务场景，在用户增长、选品选店选款、商家赋能及商业化等方向，梳理工作流，主动发现 AI 应用机会，设计并验证新的业务模式与效率工具，快速将业务需求转化为可运行的解决方案，缩短从想法到落地的路径；\n\n2、深潜行业并为业务结果负责：深刻理解垂直行业，从复杂的业务场景/数据中挖掘用户/商户痛点和本质需求，发现平台机会点，制定产品/运营/商业化策略，快速验证策略可行性；\n\n3、持续学习与输出：持续学习跟进行业趋势变化及 AI 前沿动态，将模型能力、工具链快速转化为业务价值，在团队内部沉淀方法论与最佳实践。\n\n岗位基本要求\n1、行业Owner：直接为行业目标和结果负责，理解商户生态、用户心智和竞争格局，能从行业视角发现问题和机会，具备业务节奏感。\n\n2、产品设计力： 能从业务问题出发拆解需求、设计解决方案，具备用户体验思维和数据验证意识，会正确评估结果，评估长短期影响。\n\n3、AI工具力： 能用Vibe Coding/FDE/AI Agent等工具，自主完成轻量功能搭建、数据看板、自动化工作流，不依赖研发排期解决自闭环层问题。\n\n岗位亮点\n1、行业高速发展：美甲行业处于高速发展期，GTV规模大（乐生活TOP5行业），有机会主导行业变革，机会与挑战并存。\n\n2、站在 AI 应用最前沿：你将在一个真实的千亿级业务场景中，探索 AI 改变行业的无限可能，重新定义工作方式，打破岗位边界，成为真正意义上的超级个体。\n\n3、组织保障：无论你是产品/运营，加入该岗位将保留原序列不动，职级/薪酬不变。在未来的职级评审和成长发展中，将拥有行业策略及结果、AI应用及产品设计的复合型能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4500756104","sourceKey":"meituan_social","company":"美团","title":"数字化内控","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4500756104&jobShareType=1","duty":"依据公司业务战略和产品规划，建设风险管理业务策略，包括数仓管理、需求管理、策略管理、skills设计、AI产品构建；\n1、数仓管理：数据资产盘点、字段含义及口径梳理、数据质量评估等，同时建设配套的数据安全监督体系；\n2、需求管理：支持业务风险分析的需求，含数据接入、指标加工、数据分析、看板搭建；\n3、策略管理：从众多业务需求中提炼通用解决方案，并实现自动化处理，提升效率，通用模型，提升准召。\n4、skills设计：围绕场景定义AI的功能逻辑与交互方式，设计内控内审相关skills使其能精准执行任务并解决特定问题。\n5、AI产品构建：整合模型与业务场景，通过vibecoding将其工程化，打造智能应用，实现从技术到产品的落地闭环。","requirements":"1、本科及以上学历，5年以上企业风险管理和数据分析相关的项目经验；\n2、熟悉流程、权限、客商、人员、合规、安全等一个或多个风险相关领域，能和不同部门沟通并完成数据分析任务;\n3、有很强的owner意识，良好的自我管理能力、逻辑思维、抽象、沟通协调能力，学习能力强，愿意接受挑战，能较大压力下保持工作激情；\n4、富有创业激情、简单开放、良好的团队协作意愿。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n依据公司业务战略和产品规划，建设风险管理业务策略，包括数仓管理、需求管理、策略管理、skills设计、AI产品构建；\n1、数仓管理：数据资产盘点、字段含义及口径梳理、数据质量评估等，同时建设配套的数据安全监督体系；\n2、需求管理：支持业务风险分析的需求，含数据接入、指标加工、数据分析、看板搭建；\n3、策略管理：从众多业务需求中提炼通用解决方案，并实现自动化处理，提升效率，通用模型，提升准召。\n4、skills设计：围绕场景定义AI的功能逻辑与交互方式，设计内控内审相关skills使其能精准执行任务并解决特定问题。\n5、AI产品构建：整合模型与业务场景，通过vibecoding将其工程化，打造智能应用，实现从技术到产品的落地闭环。\n\n岗位基本要求\n1、本科及以上学历，5年以上企业风险管理和数据分析相关的项目经验；\n2、熟悉流程、权限、客商、人员、合规、安全等一个或多个风险相关领域，能和不同部门沟通并完成数据分析任务;\n3、有很强的owner意识，良好的自我管理能力、逻辑思维、抽象、沟通协调能力，学习能力强，愿意接受挑战，能较大压力下保持工作激情；\n4、富有创业激情、简单开放、良好的团队协作意愿。\n\n具备以下条件优先\n1、为人工智能、商业分析、金融工程、计算机、信息管理相关专业；\n2、持有财务、内控内审领域专业资质；\n3、会计师事务所、互联网平台企业、管理咨询公司经验。\n\n岗位亮点\n1、专业团队、海量数据、丰富场景，且有配套的上下游团队，可将数字化的价值充分挖掘发挥；\n2、互联网进入下半场,业务更多地提出精细化治理的诉求,适合风险管理更好地对业务带去价值；\n3、有较多 0-1和 1-10 的项目开展,对于个人专业成长有较多选择和帮助；\n4、公司内部AI工具完善，且积极鼓励AI创新。\n5、工作中能和内控 BP、业务团队紧密协作,参与到公司重点风险治理，共同推动很多事情的进步,和业务一起成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4698828519","sourceKey":"meituan_social","company":"美团","title":"中间件Java研发工程师","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4698828519&jobShareType=1","duty":"1、主要参与美团微服务治理平台的架构演进以及稳定性保障工作。\n2、参与微服务基础组件的相关性能优化、DevOps能力建设、容灾能力提升、质量建设等，不断提升组件的质量、稳定性以及扩展性等。\n3、研究中间件新技术以及行业动态，不断提升团队技术水平和工作效率。","requirements":"1、大学本科及以上学历，计算机相关专业，具备扎实的计算机基础知识。\n2、具备3年以上Java开发经验，熟悉常用的软件开发框架和工具，比如Spring、MyBatis。\n3、具备良好的分析和解决问题能力，能够独立完成项目开发任务。\n4、具备熟练的 AI Coding、AI 办公和借助 AI 解决问题的意识和能力","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1、主要参与美团微服务治理平台的架构演进以及稳定性保障工作。\n2、参与微服务基础组件的相关性能优化、DevOps能力建设、容灾能力提升、质量建设等，不断提升组件的质量、稳定性以及扩展性等。\n3、研究中间件新技术以及行业动态，不断提升团队技术水平和工作效率。\n\n岗位基本要求\n1、大学本科及以上学历，计算机相关专业，具备扎实的计算机基础知识。\n2、具备3年以上Java开发经验，熟悉常用的软件开发框架和工具，比如Spring、MyBatis。\n3、具备良好的分析和解决问题能力，能够独立完成项目开发任务。\n4、具备熟练的 AI Coding、AI 办公和借助 AI 解决问题的意识和能力\n\n具备以下条件优先\n1、学习能力强，对中间件开发充满热情。\n2、有中间件研发经验，熟悉Dubbo、Nacos、Spring Cloud 等开源项目。\n3、同时具有丰富的 C++ 编程经验者优先。\n\n岗位亮点\n1、参与日均10万亿次调用的微服务治理核心体系建设，技术挑战性强，成长空间大。\n2、支撑全美团业务线，有机会扩展自己的技术影响力。\n3、团队技术氛围浓厚，鼓励技术创新与分享。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4711735877","sourceKey":"meituan_social","company":"美团","title":"设施和聚合策略组—外卖柜经营策略","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4711735877&jobShareType=1","duty":"①外卖柜是连接用户、骑手、物业和平台的重要末端基础设施，既影响骑手配送效率，也影响用户取餐体验。涉及从市场判断、投放规划、经营诊断、定价设计到目标管理的完整决策链路。具体岗位职责为：\n\n②5目标投放策略：根据人口/外卖密度、写字楼/社区管控程度等识别高潜力增量市场与待深耕的存量市场，为柜机投放规划提供决策依据。\n\n③市场专项分析：针对布柜点位构建多维度监控体系，完成专项分析和洞察并输出市场拓展策略，为资源配置提供决策依据。\n\n④定价策略：追踪行业定价动态，结合不同城市场景制定差异化价格方案。通过价格敏感度研究，实验测试和分析，评估不同用户、城市和场景下的价格弹性。\n\n⑤绩效管理：根据业务发展不同阶段的策略重点，迭代绩效考核方案和目标制定逻辑，保障考核的公正、公平以及牵引性和有效性。\n\n⑥AI应用：具备AI工具应用能力，能熟练使用大语言模型辅助完成策略分析、目标和绩效管理等工作。","requirements":"①大学本科及以上学历，具有4年以上商业分析、经营策略、咨询、战略、用户增长或相关工作经验。\n\n②具备较强的结构化思考和数据分析能力，能够完成从问题定义、假设提出、数据验证到策略落地的完整分析过程。\n\n③熟练运用各办公软件、SQL等数据分析工具，对数据敏感，能够从复杂信息中识别关键问题。\n\n④能够熟练使用AI辅助研究、分析和方案产出；有AI业务场景落地经验者优先。\n\n⑤具备较强的沟通能力和团队合作精神，能够有效协调各部门合作。","description":"部门介绍\n美团配送是以科技为内核的即时物流品牌，利用高效、稳定、广阔的配送网络和前沿科技能力为各行业客户提供涵盖商流物流一体化、流量赋能、行业定制化即时配送、末端配送、前置仓等服务在内的全方位同城物流综合解决方案。\n作为科技创新和智慧物流的实践者，美团配送在人工智能（AI）、5G应用、物联网（IoT）、云计算等多维度不断探索科创蓝海，让同城物流进入数智化时代。美团配送在IoT智能设备、外卖柜、换电网络、无人配送体系等硬件设施与服务上不断推陈出新，持续优化骑手、消费者、商家体验；自研同城物流系统，通过智能分析为用户提供更便捷的生活方式，为商家提供更高效的履约服务。\n加入我们，一起把世界送到消费者手中！\n\n岗位职责\n①外卖柜是连接用户、骑手、物业和平台的重要末端基础设施，既影响骑手配送效率，也影响用户取餐体验。涉及从市场判断、投放规划、经营诊断、定价设计到目标管理的完整决策链路。具体岗位职责为：\n\n②5目标投放策略：根据人口/外卖密度、写字楼/社区管控程度等识别高潜力增量市场与待深耕的存量市场，为柜机投放规划提供决策依据。\n\n③市场专项分析：针对布柜点位构建多维度监控体系，完成专项分析和洞察并输出市场拓展策略，为资源配置提供决策依据。\n\n④定价策略：追踪行业定价动态，结合不同城市场景制定差异化价格方案。通过价格敏感度研究，实验测试和分析，评估不同用户、城市和场景下的价格弹性。\n\n⑤绩效管理：根据业务发展不同阶段的策略重点，迭代绩效考核方案和目标制定逻辑，保障考核的公正、公平以及牵引性和有效性。\n\n⑥AI应用：具备AI工具应用能力，能熟练使用大语言模型辅助完成策略分析、目标和绩效管理等工作。\n\n岗位基本要求\n①大学本科及以上学历，具有4年以上商业分析、经营策略、咨询、战略、用户增长或相关工作经验。\n\n②具备较强的结构化思考和数据分析能力，能够完成从问题定义、假设提出、数据验证到策略落地的完整分析过程。\n\n③熟练运用各办公软件、SQL等数据分析工具，对数据敏感，能够从复杂信息中识别关键问题。\n\n④能够熟练使用AI辅助研究、分析和方案产出；有AI业务场景落地经验者优先。\n\n⑤具备较强的沟通能力和团队合作精神，能够有效协调各部门合作。\n\n岗位亮点\n业务视角完整：能看到业务全貌，且商分在业务侧影响力强，策略可落地可闭环，个人施展空间大。\n\n决策影响直接：工作成果将直接应用于市场投放、定价、资源配置和绩效管理等核心决策。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4733017142","sourceKey":"meituan_social","company":"美团","title":"快驴-温州驻仓\\前置揽收品控","city":"温州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4733017142&jobShareType=1","duty":"1. 主要对生鲜、速食熟食、标品类等到货进行验收抽检、识别商品质量问题，对合作商进行前置检查识别商品货源、加工、运输等方面的问题，对以上问题推动改善解决。\n2. 执行日常巡检、抽检及问题商品处理，及时反馈并推动供应商改进。  \n3. 协助制定并优化生鲜品控流程，提升品控效率与准确性。  \n4. 收集并分析品控数据，输出质量报告并提出改进建议。  \n5. 协同采购、仓储及物流团队，确保生鲜商品从源头到终端的质量稳定性。","requirements":"1. 大学专科及以上学历，食品科学、质量管理或相关专业优先。  \n2. 2年以上生鲜、快消品或供应链品控相关工作经验。  \n3. 熟悉生鲜商品特性及国家食品安全法规，具备基础检测能力。  \n4. 熟练使用办公软件，具备数据分析及报告撰写能力。  \n5. 工作细致，责任心强，能适应高频次现场巡检及突发问题处理。\n6. 能接受晚班，能接受调岗。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 主要对生鲜、速食熟食、标品类等到货进行验收抽检、识别商品质量问题，对合作商进行前置检查识别商品货源、加工、运输等方面的问题，对以上问题推动改善解决。\n2. 执行日常巡检、抽检及问题商品处理，及时反馈并推动供应商改进。  \n3. 协助制定并优化生鲜品控流程，提升品控效率与准确性。  \n4. 收集并分析品控数据，输出质量报告并提出改进建议。  \n5. 协同采购、仓储及物流团队，确保生鲜商品从源头到终端的质量稳定性。\n\n岗位基本要求\n1. 大学专科及以上学历，食品科学、质量管理或相关专业优先。  \n2. 2年以上生鲜、快消品或供应链品控相关工作经验。  \n3. 熟悉生鲜商品特性及国家食品安全法规，具备基础检测能力。  \n4. 熟练使用办公软件，具备数据分析及报告撰写能力。  \n5. 工作细致，责任心强，能适应高频次现场巡检及突发问题处理。\n6. 能接受晚班，能接受调岗。\n\n岗位亮点\n1. 加入快速发展的生鲜供应链平台，参与核心品控环节。  \n2. 接触多元生鲜品类，积累行业深度经验。  \n3. 扁平化管理，直接对接业务核心团队。  \n4. 提供系统化品控培训及职业发展支持。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4669501173","sourceKey":"meituan_social","company":"美团","title":"供应链商家履约策略（偏业务/链路分析）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4669501173&jobShareType=1","duty":"聚焦3P卖家在平台经营中的履约体验痛点与经营成本负担，通过结构化的问题诊断、规则重构、流程优化，系统性提升卖家履约满意度并降低卖家进向成本。该岗位是连接平台规则、物流履约、售后服务与卖家经营的核心策略角色，需要在复杂的多方利益中找到最优解并推动跨部门落地。\n1、履约流程优化与基建\n负责流程的线上化改造以及供给中心覆盖链路关系梳理和指标体系搭建，为团队提供清晰的业务全景视图。\n2、卖家交付成本优化\n围绕多波次/分批交货模式下卖家面临的加工效率损失与交货成本增加，从交接网络布局、交接流程标准化、分流向合理化等维度，识别成本优化空间并制定改善策略，推动卖家交付环节的降本增效。\n3、卖家成本与体验的结构化分析与规划\n建立卖家经营成本的全景分析框架（生产成本、交付成本、售后罚款、逆向损失等），绘制优化路径规划图，量化各优化项的ROI，为团队和管理层提供清晰的优先级排序和资源投入建议。定期输出卖家体验与成本优化的进展报告和策略迭代方案。","requirements":"1、结构化思维与规划能力：能够将复杂业务问题抽象为结构化框架，具备绘制系统性规划图、建立分析模型的能力；善于从纷繁的业务现象中提炼核心矛盾，并给出有优先级的解决路径。\n2、量化分析与ROI测算：具备扎实的数据分析基础，能独立完成成本结构拆解、收益测算和方案量化评估；习惯用数据驱动决策。\n3、跨部门推动与落地能力：有过推动涉及多个业务方（如物流、履约、售后、产品、技术）协同落地的项目经验；能在没有直接管理权的情况下，通过影响力和项目管理能力推动复杂方案执行。4、过往经验：具备平台型公司的商业分析或策略分析经验，熟悉平台与商家之间的经营关系和利益博弈。有物流、供应链、仓储、履约等领域的业务分析或策略规划经验，理解交付链路中的成本构成和体验痛点；或具备招商采购背景，熟悉卖家/供应商的经营视角。\n5、沟通与文档输出能力：能将分析结论和规划方案清晰地表达为可执行的文档和汇报材料，能面向不同层级的受众进行有效沟通。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n聚焦3P卖家在平台经营中的履约体验痛点与经营成本负担，通过结构化的问题诊断、规则重构、流程优化，系统性提升卖家履约满意度并降低卖家进向成本。该岗位是连接平台规则、物流履约、售后服务与卖家经营的核心策略角色，需要在复杂的多方利益中找到最优解并推动跨部门落地。\n1、履约流程优化与基建\n负责流程的线上化改造以及供给中心覆盖链路关系梳理和指标体系搭建，为团队提供清晰的业务全景视图。\n2、卖家交付成本优化\n围绕多波次/分批交货模式下卖家面临的加工效率损失与交货成本增加，从交接网络布局、交接流程标准化、分流向合理化等维度，识别成本优化空间并制定改善策略，推动卖家交付环节的降本增效。\n3、卖家成本与体验的结构化分析与规划\n建立卖家经营成本的全景分析框架（生产成本、交付成本、售后罚款、逆向损失等），绘制优化路径规划图，量化各优化项的ROI，为团队和管理层提供清晰的优先级排序和资源投入建议。定期输出卖家体验与成本优化的进展报告和策略迭代方案。\n\n岗位基本要求\n1、结构化思维与规划能力：能够将复杂业务问题抽象为结构化框架，具备绘制系统性规划图、建立分析模型的能力；善于从纷繁的业务现象中提炼核心矛盾，并给出有优先级的解决路径。\n2、量化分析与ROI测算：具备扎实的数据分析基础，能独立完成成本结构拆解、收益测算和方案量化评估；习惯用数据驱动决策。\n3、跨部门推动与落地能力：有过推动涉及多个业务方（如物流、履约、售后、产品、技术）协同落地的项目经验；能在没有直接管理权的情况下，通过影响力和项目管理能力推动复杂方案执行。4、过往经验：具备平台型公司的商业分析或策略分析经验，熟悉平台与商家之间的经营关系和利益博弈。有物流、供应链、仓储、履约等领域的业务分析或策略规划经验，理解交付链路中的成本构成和体验痛点；或具备招商采购背景，熟悉卖家/供应商的经营视角。\n5、沟通与文档输出能力：能将分析结论和规划方案清晰地表达为可执行的文档和汇报材料，能面向不同层级的受众进行有效沟通。\n\n岗位亮点\n1、驾驭核心杠杆，业务影响力直接：直接负责供应链“成本、体验、效率”的核心交汇点，工作成果将直接作用于公司关键财务与客户体验指标，价值呈现清晰可见。\n2、从“策略”到“体系”的深度建设机会：不仅仅是一个执行岗位，更是将前瞻性业务策略落地为可复制运营体系的关键角色。将亲身参与并主导供应链能力的构建过程。\n3、 高成长环境与清晰路径：加入一个已被验证的、务实进取的成熟团队，与行业优秀的供应链实战专家共事。岗位提供从复杂项目操盘、跨部门战略协同到团队能力建设的完整成长阶梯，支持向更高维度的管理者或领域专家发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4728217671","sourceKey":"meituan_social","company":"美团","title":"点评技术-AI Agent开发工程师","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4728217671&jobShareType=1","duty":"岗位概述\n负责点评业务质量保障体系中AI Agent的技术设计与开发，聚焦验收评测环节，将传统测试工具能力升级为智能化Agent形态，提升测试验证的自动化覆盖率和智能化水平。\n\n1.面向验收评测的 Agent 体系设计\n-深入理解点评各业务线（基础、POI、搜推等）的测试流程、验收标准和质量痛点；\n-设计和建设统一的测试 Agent 基础设施，将评测工具、验收工具、巡检工具等存量能力升级为可自主规划、自主执行的 Agent 形态；\n-推动测试模式从「人驱动工具」向「Agent 驱动测试」转变，覆盖用例理解、环境准备、执行操控、结果判定的全链路。\n\n2.智能评测与结果判定能力建设\n-建设基于 LLM/VLM 的智能判定能力，覆盖意图识别、结果判定、异常检测、标签生成等评测核心环节；\n-设计评测驱动的迭代流程：集中评测发现 badcase → 针对性优化 → 效果回归验证，形成质量能力的持续进化闭环；\n-通过工程 Judge、规则引擎等手段治理模型幻觉和误判，保证判定结果的可信度和稳定性。\n\n3. 知识库与数据体系建设\n-沉淀业务质量知识库：Bug 模式、判定标准、页面结构、业务规则等，为 Agent 提供可依赖的领域知识；\n-建设面向 Agent 友好的测试数据和环境管理能力，支持低成本的用例构造与回放；\n-保证知识无过时、冲突、冗余，构建知识生产-消费-反馈的自动化闭环。\n\n4. 模型评测与效果度量\n-建立覆盖准确性、稳定性、成本、耗时的多维度评测指标体系，量化 Agent 化改造的业务价值；\n-周期性进行 SOTA 模型（LLM/VLM）评测，根据测试场景选择高性价比模型；\n-跟踪业界 AI 验证自动化方向的前沿实践，评估并引入适合点评场景的技术能力。","requirements":"基本要求：\n1. 本科及以上学历，计算机、软件工程、人工智能或相关专业，具备5年及以上软件开发、测试开发、质量工程或AI应用工程经验。\n2. 具备扎实的全栈或服务端工程能力，熟练掌握Python、Java、JavaScript/TypeScript、Go等至少一种编程语言，能够独立完成AI应用、自动化工具、服务或平台能力的设计与开发。\n3. 理解大语言模型、Prompt、RAG、Agent、Tool Calling、MCP等AI应用基本原理，具备Agent或AI应用的开发、集成和落地经验。\n4. 熟悉软件测试理论与质量保障体系，具备接口、服务端、Web或客户端自动化测试经验，理解CI/CD、质量门禁、可观测性及持续交付实践。\n5. 能围绕模型效果、任务成功、稳定性、安全性和成本设计评测方案，并通过数据驱动产品、模型和工程链路的持续优化。\n6. 具备优秀的业务理解、抽象分析与跨团队协作能力，能够将复杂业务目标转化为清晰的技术方案、验收规则、评测数据和自动化验证方案。\n加分项：\n1. 有LLM应用、Agent、RAG或多模态产品的开发、测试、评测、调优或上线保障经验。\n2. 有AI应用平台、AI评测平台、测试平台、质量中台、数据集、Benchmark或A/B实验平台建设经验。\n3. 有Prompt工程、模型输出评估、幻觉检测、安全测试或AI治理相关经验。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n岗位概述\n负责点评业务质量保障体系中AI Agent的技术设计与开发，聚焦验收评测环节，将传统测试工具能力升级为智能化Agent形态，提升测试验证的自动化覆盖率和智能化水平。\n\n1.面向验收评测的 Agent 体系设计\n-深入理解点评各业务线（基础、POI、搜推等）的测试流程、验收标准和质量痛点；\n-设计和建设统一的测试 Agent 基础设施，将评测工具、验收工具、巡检工具等存量能力升级为可自主规划、自主执行的 Agent 形态；\n-推动测试模式从「人驱动工具」向「Agent 驱动测试」转变，覆盖用例理解、环境准备、执行操控、结果判定的全链路。\n\n2.智能评测与结果判定能力建设\n-建设基于 LLM/VLM 的智能判定能力，覆盖意图识别、结果判定、异常检测、标签生成等评测核心环节；\n-设计评测驱动的迭代流程：集中评测发现 badcase → 针对性优化 → 效果回归验证，形成质量能力的持续进化闭环；\n-通过工程 Judge、规则引擎等手段治理模型幻觉和误判，保证判定结果的可信度和稳定性。\n\n3. 知识库与数据体系建设\n-沉淀业务质量知识库：Bug 模式、判定标准、页面结构、业务规则等，为 Agent 提供可依赖的领域知识；\n-建设面向 Agent 友好的测试数据和环境管理能力，支持低成本的用例构造与回放；\n-保证知识无过时、冲突、冗余，构建知识生产-消费-反馈的自动化闭环。\n\n4. 模型评测与效果度量\n-建立覆盖准确性、稳定性、成本、耗时的多维度评测指标体系，量化 Agent 化改造的业务价值；\n-周期性进行 SOTA 模型（LLM/VLM）评测，根据测试场景选择高性价比模型；\n-跟踪业界 AI 验证自动化方向的前沿实践，评估并引入适合点评场景的技术能力。\n\n岗位基本要求\n基本要求：\n1. 本科及以上学历，计算机、软件工程、人工智能或相关专业，具备5年及以上软件开发、测试开发、质量工程或AI应用工程经验。\n2. 具备扎实的全栈或服务端工程能力，熟练掌握Python、Java、JavaScript/TypeScript、Go等至少一种编程语言，能够独立完成AI应用、自动化工具、服务或平台能力的设计与开发。\n3. 理解大语言模型、Prompt、RAG、Agent、Tool Calling、MCP等AI应用基本原理，具备Agent或AI应用的开发、集成和落地经验。\n4. 熟悉软件测试理论与质量保障体系，具备接口、服务端、Web或客户端自动化测试经验，理解CI/CD、质量门禁、可观测性及持续交付实践。\n5. 能围绕模型效果、任务成功、稳定性、安全性和成本设计评测方案，并通过数据驱动产品、模型和工程链路的持续优化。\n6. 具备优秀的业务理解、抽象分析与跨团队协作能力，能够将复杂业务目标转化为清晰的技术方案、验收规则、评测数据和自动化验证方案。\n加分项：\n1. 有LLM应用、Agent、RAG或多模态产品的开发、测试、评测、调优或上线保障经验。\n2. 有AI应用平台、AI评测平台、测试平台、质量中台、数据集、Benchmark或A/B实验平台建设经验。\n3. 有Prompt工程、模型输出评估、幻觉检测、安全测试或AI治理相关经验。\n\n具备以下条件优先\n1. 有AI Coding、Spec Coding或Agent驱动的软件开发生命周期实践，能够完成需求拆解、架构设计、编码、测试和上线的端到端工程交付。\n2. 熟悉主流Agent框架或AI应用开发工具，并有实际项目落地成果。\n3. 有复杂业务流程、内容平台、数据平台或AI工具产品的开发和质量保障经验，能够快速理解关键规则、链路和用户场景。\n\n岗位亮点\n1. 直接参与点评核心业务AI能力的建设与可信交付，覆盖从业务场景识别、AI应用构建到评测验证、生产发布和持续迭代的完整链路。\n2. 与产品、研发、算法和运营团队高频协同，在真实业务规模和复杂用户场景下探索Agent工程、AI验证自动化和评测驱动的AI应用生产方法。\n3. 团队支持技术自主决策和快速迭代，可沉淀可复用的Agent能力、评测资产、质量门禁及AI-SDLC工程方法论。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4684745161","sourceKey":"meituan_social","company":"美团","title":"美团平台-AI产品经理（IM智能客服方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4684745161&jobShareType=1","duty":"1.负责平台级IM基础功能、Agent、工作台等模块的产品建设工作；  \n\n2.梳理商家及用户产品需求，负责需求分析、产出需求说明书并评估优先级，协同算法、产研团队推动功能上线；   \n\n3.同各业务线及运营同学紧密合作，主导业务方需求的产品化实现，分析产品上线后的用户反馈及数据表现，持续迭代优化。","requirements":"1.本科或以上学历，计算机、电子信息、通讯等相关背景专业优先，3年以上产品经验，1年以上AI产品经验；   \n\n2.对互联网产品有浓厚的兴趣，有互联网行业、本地生活或电商领域相关工作经验者优先；   \n\n3.具备卓越的沟通协调能力和逻辑思维能力，责任心、执行力、学习能力强，工作细致有耐心，具备良好的服务意识；   \n\n4.具备出色的数据分析和文档撰写能力，熟练使用SQL等数据分析工具，熟练使用各类产品原型及办公软件；   \n\n5.具备独立负责产品模块的能力，能够承受一定的工作压力。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.负责平台级IM基础功能、Agent、工作台等模块的产品建设工作；  \n\n2.梳理商家及用户产品需求，负责需求分析、产出需求说明书并评估优先级，协同算法、产研团队推动功能上线；   \n\n3.同各业务线及运营同学紧密合作，主导业务方需求的产品化实现，分析产品上线后的用户反馈及数据表现，持续迭代优化。\n\n岗位基本要求\n1.本科或以上学历，计算机、电子信息、通讯等相关背景专业优先，3年以上产品经验，1年以上AI产品经验；   \n\n2.对互联网产品有浓厚的兴趣，有互联网行业、本地生活或电商领域相关工作经验者优先；   \n\n3.具备卓越的沟通协调能力和逻辑思维能力，责任心、执行力、学习能力强，工作细致有耐心，具备良好的服务意识；   \n\n4.具备出色的数据分析和文档撰写能力，熟练使用SQL等数据分析工具，熟练使用各类产品原型及办公软件；   \n\n5.具备独立负责产品模块的能力，能够承受一定的工作压力。\n\n具备以下条件优先\n1.熟悉大模型相关概念和不同模型的能力边界，有搭建Agent应用经验者优先。   \n\n2.有工具类产品建设经验者优先。\n\n岗位亮点\n1.面向美团的广泛目标用户，研究其行为模式和需求，建立深刻的用户洞察；   \n\n2.与美团的业务团队深度合作，高速学习多种业务的经营逻辑；   \n\n3.能够有机会接触复杂问题，做出通盘思考与影响广泛的解决方案；   \n\n4.团队氛围好，工作不设限，有丰富的帮助个人学习、思考、成长的资源与机制。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4727980324","sourceKey":"meituan_social","company":"美团","title":"小象超市-物流城市用工负责人（济南）","city":"济南市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4727980324&jobShareType=1","duty":"1、负责城市招聘目标与需求的达成，并制定对应招聘方向与策略；\n2、深入了解用人部门发展规划与需求，评估需求并提出配置建议； \n3、负责城市招聘团队人员管理，提升城市招聘团队专业能力与效能；\n4、招聘渠道管理与建设，包括渠道的拓展维护，招聘费用管控； \n5、定期与业务部门进行沟通与协作，为招聘提供解决方案；\n6、掌握基本的AI工具，使用工具提升工作流程效率。","requirements":"1、本科以上学历，人力资源管理、心理学专业优先；\n2、5年以上大型企业人力资源招聘工作经验，并能对招聘结果负责；团队管理经验至少1年以上；\n3、有一定的招聘渠道拓展搭建经验及资源；\n4、有互联网、快消零售连锁、物流等大型企业招聘经验优先；\n5、具有优秀的学习能力、主动和开创精神、优秀的文字能力、出色的沟通协调能力；\n6、对AI工具研究和使用经验。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责城市招聘目标与需求的达成，并制定对应招聘方向与策略；\n2、深入了解用人部门发展规划与需求，评估需求并提出配置建议； \n3、负责城市招聘团队人员管理，提升城市招聘团队专业能力与效能；\n4、招聘渠道管理与建设，包括渠道的拓展维护，招聘费用管控； \n5、定期与业务部门进行沟通与协作，为招聘提供解决方案；\n6、掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位基本要求\n1、本科以上学历，人力资源管理、心理学专业优先；\n2、5年以上大型企业人力资源招聘工作经验，并能对招聘结果负责；团队管理经验至少1年以上；\n3、有一定的招聘渠道拓展搭建经验及资源；\n4、有互联网、快消零售连锁、物流等大型企业招聘经验优先；\n5、具有优秀的学习能力、主动和开创精神、优秀的文字能力、出色的沟通协调能力；\n6、对AI工具研究和使用经验。\n\n岗位亮点\n策略落地、全面锻炼自身、从招聘到留存全面参与管理、聚焦单城市成长速度快，前沿AI工具学习与使用。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4726297180","sourceKey":"meituan_social","company":"美团","title":"小象超市-vi设计师","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4726297180&jobShareType=1","duty":"1、负责线下门店品类导视系统的标准建立及场景应用\n2、负责线下门店广告画面、发光灯箱内容的输出\n3、负责线下门店户外、公区、停车场等导视系统的标准建立及场景应用\n4、对接并管理外部供应商落地场景呈现","requirements":"1、VI设计 VIS 系统建设经验,有(如零售、互联网)经验者优先\n2、熟练使用设计软件,掌握三维或动效软件者优先\n3、具备视觉表现力、创新能力、扎实的美术功底(图形、色彩、版式)、品牌策略理解力(能构建和维护VIS)\n4、责任心强、自驱力强、良好的沟通能力和团队协作精神、能适应多任务处理","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责线下门店品类导视系统的标准建立及场景应用\n2、负责线下门店广告画面、发光灯箱内容的输出\n3、负责线下门店户外、公区、停车场等导视系统的标准建立及场景应用\n4、对接并管理外部供应商落地场景呈现\n\n岗位基本要求\n1、VI设计 VIS 系统建设经验,有(如零售、互联网)经验者优先\n2、熟练使用设计软件,掌握三维或动效软件者优先\n3、具备视觉表现力、创新能力、扎实的美术功底(图形、色彩、版式)、品牌策略理解力(能构建和维护VIS)\n4、责任心强、自驱力强、良好的沟通能力和团队协作精神、能适应多任务处理\n\n具备以下条件优先\n具备优秀标识方案、画面设计能力，AI辅助设计能力优先\n\n岗位亮点\n1.新零售行业巨大的发展潜力\n2.参与全国性连锁品牌门店项目建设，发展空间广阔。  \n3.与跨职能团队深度合作，提升综合视野。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4705006709","sourceKey":"meituan_social","company":"美团","title":"美团骑行-运营主管（天津）","city":"天津市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4705006709&jobShareType=1","duty":"1.负责带领团队完成共享单车车辆的日常运维工作，确保车辆正常运行。\n2.负责完成负责区域管理者的对接、沟通与协作。\n3.负责团队人员的招聘、培养、管理等动作。\n4.执行运营计划，协助运营经理完成运营工作，确保团队经营目标的达成。","requirements":"1.大学本科以上学历，专业不限，具备良好的学习能力和团队合作意识。\n2.拥有团队管理经验，可单独完成20人左右团队管理工作。\n3.具备良好的沟通能力和解决问题的能力，能够快速响应并处理紧急情况。\n4.具备一定的数据分析能力，能够通过数据分析提出运维改进方案。\n5.具备较强的责任心，能够适应工作强度较大的环境。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.负责带领团队完成共享单车车辆的日常运维工作，确保车辆正常运行。\n2.负责完成负责区域管理者的对接、沟通与协作。\n3.负责团队人员的招聘、培养、管理等动作。\n4.执行运营计划，协助运营经理完成运营工作，确保团队经营目标的达成。\n\n岗位基本要求\n1.大学本科以上学历，专业不限，具备良好的学习能力和团队合作意识。\n2.拥有团队管理经验，可单独完成20人左右团队管理工作。\n3.具备良好的沟通能力和解决问题的能力，能够快速响应并处理紧急情况。\n4.具备一定的数据分析能力，能够通过数据分析提出运维改进方案。\n5.具备较强的责任心，能够适应工作强度较大的环境。\n\n岗位亮点\n1.可以在共享单车行业中积累丰富的运维经验，了解共享单车运营的各个环节。\n2.有机会参与车辆维护计划的制定和改进，提高车辆的可靠性和使用寿命。\n3.能够与运营团队紧密合作，了解共享单车运营的全过程，为用户提供更好的使用体验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4654220564","sourceKey":"meituan_social","company":"美团","title":"财务科技-AI应用研发工程师","city":"北京市/成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4654220564&jobShareType=1","duty":"1. 专注于财务领域的大模型应用探索及落地工作，与财务专家团队合作，提升财务工作效率、降低人工介入，针对传统财务系统无法解决的模糊场景问题及全业务流程的AI范式变革。\n2. 重点、难点技术预研与攻关，前沿技术探索，持续探索更灵活高效的AI应用落地方案，对系统性能持续优化，不断提升稳定性保障手段，追求卓越。\n3. 深入理解财务业务场景（如月结、审核、对账、报表），将业务需求转化为技术方案并完成端到端交付，负责财务领域AI应用的核心模块开发，包括但不限于 Agent客服问答、知识蒸馏及知识库构建、DataAgent数据分析、Agent财务流程构建，参与AI Agent平台的技术建设，涵盖任务调度、人机协同、质检闭环、运行监控等基础设施能力。","requirements":"1. 计算机相关专业，扎实的计算机专业基本功，扎实的编码能力与工程实践，5年以上开发经验。\n2. 既往工作经验，在前端技术、后端技术、算法技术某一或多种传统工程方向具备精通经验，**要求具备全栈视角，至少精通一端**。\n3. 参与过大型复杂分布式系统设计开发，对高并发、高可用、高性能以及大规模数据处理有实际经验，拥有和工作年限相称的广度和（或）深度。\n4. 具备一定的AI理解和Agent开发经验，同时熟练使用AI Coding工具（Claude Code / Cursor / Codex等）。\n5. 具有较好的沟通能力，思路清晰、善于思考，能独立分析和解决问题。\n6. 有良好的自驱力和学习能力，对解决具有挑战性问题充满激情。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1. 专注于财务领域的大模型应用探索及落地工作，与财务专家团队合作，提升财务工作效率、降低人工介入，针对传统财务系统无法解决的模糊场景问题及全业务流程的AI范式变革。\n2. 重点、难点技术预研与攻关，前沿技术探索，持续探索更灵活高效的AI应用落地方案，对系统性能持续优化，不断提升稳定性保障手段，追求卓越。\n3. 深入理解财务业务场景（如月结、审核、对账、报表），将业务需求转化为技术方案并完成端到端交付，负责财务领域AI应用的核心模块开发，包括但不限于 Agent客服问答、知识蒸馏及知识库构建、DataAgent数据分析、Agent财务流程构建，参与AI Agent平台的技术建设，涵盖任务调度、人机协同、质检闭环、运行监控等基础设施能力。\n\n岗位基本要求\n1. 计算机相关专业，扎实的计算机专业基本功，扎实的编码能力与工程实践，5年以上开发经验。\n2. 既往工作经验，在前端技术、后端技术、算法技术某一或多种传统工程方向具备精通经验，**要求具备全栈视角，至少精通一端**。\n3. 参与过大型复杂分布式系统设计开发，对高并发、高可用、高性能以及大规模数据处理有实际经验，拥有和工作年限相称的广度和（或）深度。\n4. 具备一定的AI理解和Agent开发经验，同时熟练使用AI Coding工具（Claude Code / Cursor / Codex等）。\n5. 具有较好的沟通能力，思路清晰、善于思考，能独立分析和解决问题。\n6. 有良好的自驱力和学习能力，对解决具有挑战性问题充满激情。\n\n具备以下条件优先\n1. 有财务/金融/企业软件领域经验，理解财务运营基本逻辑（如审核、对账、月结等）。\n2. 有开源项目贡献或技术博客，具备技术社区影响力。\n3. 有从0到1构建AI应用产品的经验，或参与过Agent/数字员工类平台的技术建设。\n4. 有全栈开发经验，能独立完成端到端功能交付。\n\n岗位亮点\n1. 团队当前处于AI应用落地加速期，已有AI客服、审核、手工账、报销等成熟场景，新方向空间广阔。\n2. 探索AI技术在财务业务场景化落地的全面解决方案，不止于理论及算法研究。\n3. 工作空间大，不再局限于某一职责范畴，**产研一体**，可全流程把握方向开展。\n4. 鼓励一人课题、一人成军，在AI时代积累\"产品+技术\"双重稀缺能力，结果为王。\n5. 保持前沿AI技术学习，紧跟技术与业界的变化，保持对技术的新鲜敏感。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4611918252","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-快消零售行业KA","city":"北京市/上海市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4611918252&jobShareType=1","duty":"1、负责快消零售行业KA客户的开发与维护，制定客户开发计划，完成销售目标，推动业务规模化增长。\n2、深度拆解快消供应链履约痛点，挖掘客户需求，输出无人配送解决方案并推动签约落地，建立长期稳定的战略合作关系。\n3、统筹项目从试点验证到规模化落地的全流程，把控全项目进度节点，统筹协调产品、研发、交付、技术等内外部资源，保障项目落地和稳定运营，跟进项目回款，对交付质量和客户满意度负责。\n4、定期输出快消行业市场分析报告，根据客户需求和行业特点反向推动产品，解决方案迭代优化。\n5、积极探索并落地 AI 工具在客户拓展、项目管理、方案制作等工作场景中的应用，借助 AI 能力提升销售效率与客户服务质量，推动客户场景化落地合作。","requirements":"1、学历：本科及以上学历，物流管理，供应链管理，市场营销相关专业优先。\n2、经验：5年以上快消/商超/餐饮连锁B端大客户销售经验。\n3、专业能力：具备独立开拓全新市场的实战成功案例，完整操盘过0到1大客户项目，商务谈判、方案宣讲、高层对接能力突出。\n4、综合素质：目标感强，能力优异，工作执行力高效，能够适配业务节奏，接受高频次异地出差。\n5、AI应用：对 AI 技术发展趋势保持持续关注，具备使用 AI 工具辅助日常工作的实践能力。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1、负责快消零售行业KA客户的开发与维护，制定客户开发计划，完成销售目标，推动业务规模化增长。\n2、深度拆解快消供应链履约痛点，挖掘客户需求，输出无人配送解决方案并推动签约落地，建立长期稳定的战略合作关系。\n3、统筹项目从试点验证到规模化落地的全流程，把控全项目进度节点，统筹协调产品、研发、交付、技术等内外部资源，保障项目落地和稳定运营，跟进项目回款，对交付质量和客户满意度负责。\n4、定期输出快消行业市场分析报告，根据客户需求和行业特点反向推动产品，解决方案迭代优化。\n5、积极探索并落地 AI 工具在客户拓展、项目管理、方案制作等工作场景中的应用，借助 AI 能力提升销售效率与客户服务质量，推动客户场景化落地合作。\n\n岗位基本要求\n1、学历：本科及以上学历，物流管理，供应链管理，市场营销相关专业优先。\n2、经验：5年以上快消/商超/餐饮连锁B端大客户销售经验。\n3、专业能力：具备独立开拓全新市场的实战成功案例，完整操盘过0到1大客户项目，商务谈判、方案宣讲、高层对接能力突出。\n4、综合素质：目标感强，能力优异，工作执行力高效，能够适配业务节奏，接受高频次异地出差。\n5、AI应用：对 AI 技术发展趋势保持持续关注，具备使用 AI 工具辅助日常工作的实践能力。\n\n具备以下条件优先\n快消，商超，食品饮料，乳制品头部客户从业背景或客户资源者优先。\n\n岗位亮点\n快消零售是无人车商业化落地核心板块，业务发展空间大。\n沉淀自动驾驶+快消供应链复合经验。\n激励政策优厚，发展空间大、个人能力提升快。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4598159768","sourceKey":"meituan_social","company":"美团","title":"Keeta-用户增长产品经理（老客提频）","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4598159768&jobShareType=1","duty":"1. 基于不同区域业务阶段、用户分层和消费场景，识别老客留存与提频机会，制定并落地频次提升、LTV 提升相关产品方案。\n2. 负责老客提频工具建设与迭代，包括优惠券/券包、任务体系、会员权益、复购召回等，提升用户粘性和消费频次。\n3. 与区域运营、数据、算法等团队协同，推动产品从方案设计、上线落地到效果复盘的完整闭环，并探索AI 在老客运营中的应用，持续提升运营效率。\n任职要求：","requirements":"1. 5 年以上互联网产品经验，具备老客提频方向相关产品经验；有电商、外卖、出行等交易型业务经验者优先。\n2. 熟悉老客留存、复购、提频相关方法论，理解用户分层、权益激励、任务体系等增长产品机制。\n3. 具备较强的结构化思考、数据分析、跨团队协作能力，能在复杂业务环境下独立推进项目并拿到结果。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. 基于不同区域业务阶段、用户分层和消费场景，识别老客留存与提频机会，制定并落地频次提升、LTV 提升相关产品方案。\n2. 负责老客提频工具建设与迭代，包括优惠券/券包、任务体系、会员权益、复购召回等，提升用户粘性和消费频次。\n3. 与区域运营、数据、算法等团队协同，推动产品从方案设计、上线落地到效果复盘的完整闭环，并探索AI 在老客运营中的应用，持续提升运营效率。\n任职要求：\n\n岗位基本要求\n1. 5 年以上互联网产品经验，具备老客提频方向相关产品经验；有电商、外卖、出行等交易型业务经验者优先。\n2. 熟悉老客留存、复购、提频相关方法论，理解用户分层、权益激励、任务体系等增长产品机制。\n3. 具备较强的结构化思考、数据分析、跨团队协作能力，能在复杂业务环境下独立推进项目并拿到结果。\n\n岗位亮点\n1. 全球拓展的机会，国际化视野，也是职业选择的拓宽\n2. 快速发展的业务阶段，更多的实践和决策机会","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4554824580","sourceKey":"meituan_social","company":"美团","title":"闪购歪马业务组-物资质量管理方向","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4554824580&jobShareType=1","duty":"1、建立、实施并优化歪马物资品类质量管理体系，确保符合相关法规和标准\n\n2、主导供应商准入质量审核，评估其质量、生产过程管理等，从源头规避质量风险\n\n3、协同采购在新品开发阶段优化设计方案，提升产品投入可行性和质量稳定性\n\n4、建立物资质量管理标准，定期样品、大货抽检、飞检、三方质检等，并输出质量结论5、主导商端异常质量的处理，分析根因、建立围堵措施和长期改进机制\n\n6、供应商质量管理，定期对现有供应商开展过程审核、产品审核等，识别质量短板制定改进计划，监控质量关键指标，数据驱动鞠策，持续优化商端质量表现，稳定质量供给\n\n7、负责物资品类标签审核\n\n8、主导供应商管理，制定相关SLA、更新相应条款，季度绩效管理等","requirements":"1、本科及以上学历，具有5年以上采购/质量管理相关管理经验\n\n2、对零售行业基本设备设施配置标准，有一定了解，熟悉掌握多品类质量标准，包材管理经验优先，熟悉生产关键质量环节，熟悉质量管理体系\n\n3、有商务沟通谈判能力，能在供应商管理中有效沟通协同\n\n4、有责任心，执行能力强，极强的协作精神和推动力，较强的分析能力、解决问题能力与管理能力\n\n5、可接受出差。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1、建立、实施并优化歪马物资品类质量管理体系，确保符合相关法规和标准\n\n2、主导供应商准入质量审核，评估其质量、生产过程管理等，从源头规避质量风险\n\n3、协同采购在新品开发阶段优化设计方案，提升产品投入可行性和质量稳定性\n\n4、建立物资质量管理标准，定期样品、大货抽检、飞检、三方质检等，并输出质量结论5、主导商端异常质量的处理，分析根因、建立围堵措施和长期改进机制\n\n6、供应商质量管理，定期对现有供应商开展过程审核、产品审核等，识别质量短板制定改进计划，监控质量关键指标，数据驱动鞠策，持续优化商端质量表现，稳定质量供给\n\n7、负责物资品类标签审核\n\n8、主导供应商管理，制定相关SLA、更新相应条款，季度绩效管理等\n\n岗位基本要求\n1、本科及以上学历，具有5年以上采购/质量管理相关管理经验\n\n2、对零售行业基本设备设施配置标准，有一定了解，熟悉掌握多品类质量标准，包材管理经验优先，熟悉生产关键质量环节，熟悉质量管理体系\n\n3、有商务沟通谈判能力，能在供应商管理中有效沟通协同\n\n4、有责任心，执行能力强，极强的协作精神和推动力，较强的分析能力、解决问题能力与管理能力\n\n5、可接受出差。\n\n岗位亮点\n1、 歪马业务聚焦于酒类万亿市场，通过前置仓+中心仓、平台自营、线下店模式，为用户提供 15分钟送达的买酒服务以及便捷打酒服务\n\n2、团队氛围轻松，融洽，个人成长空间大\n\n3、可以全方位深入业务，在全闭环的组织里感受不同职能彼此的输入/输出，你也可以参与业务模式的定义","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4403512937","sourceKey":"meituan_social","company":"美团","title":"航司商务经理","city":"广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4403512937&jobShareType=1","duty":"1. 业务拓展：负责与国内外航空公司的商务合作，拓展航空资源，推动美团与航空公司在机票、服务等领域的深度合作。\n2. 战略合作：制定并执行与航空公司的合作策略，推动双方在流量、产品、技术、营销等方面的协同创新。\n3. 市场分析：分析航空市场动态、竞争格局及用户需求，制定相应的市场策略，提升美团在航空领域的市场份额。\n4. 商务谈判：主导与航空公司的商务谈判，确保合作条款的合理性和竞争力，推动合作协议的签署与落地。\n5. 项目管理：协调内部资源，推动合作项目的顺利实施，确保项目按时交付并达到预期目标。\n6. 客户关系维护：与航空公司保持长期稳定的合作关系，定期拜访客户，了解客户需求，提升客户满意度。\n7. 跨部门协作：与产品、技术、运营、市场等部门紧密合作，推动航空业务的产品优化和用户体验提升。","requirements":"1. 学历背景：本科及以上学历，航空管理、市场营销、商务管理、经济学等相关专业优先。\n2. 工作经验：\n5年以上航空行业或OTA（在线旅游平台）或TO B、政府侧相关大客户工作经验，熟悉国企、航司、体制内企业业务决策流程及行业规则；\n有丰富的商务拓展、合作谈判经验，具备成功的合作案例。\n3. 行业知识：对航空市场有深刻理解，熟悉航空公司运营模式、票务系统、分销渠道及行业政策优先。\n4. 商务能力：具备优秀的商务谈判能力、沟通技巧和客户关系管理能力，能够独立完成商务合作的全流程。\n5. 数据分析：具备较强的数据分析能力，能够通过市场数据和用户行为分析，制定有效的业务策略。\n6. 团队协作：具备良好的跨部门协作能力，能够高效协调内外部资源，推动项目落地。\n7. 高效工作：能够在高强度、快节奏的工作环境中保持高效工作，具备较强的解决问题的能力。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1. 业务拓展：负责与国内外航空公司的商务合作，拓展航空资源，推动美团与航空公司在机票、服务等领域的深度合作。\n2. 战略合作：制定并执行与航空公司的合作策略，推动双方在流量、产品、技术、营销等方面的协同创新。\n3. 市场分析：分析航空市场动态、竞争格局及用户需求，制定相应的市场策略，提升美团在航空领域的市场份额。\n4. 商务谈判：主导与航空公司的商务谈判，确保合作条款的合理性和竞争力，推动合作协议的签署与落地。\n5. 项目管理：协调内部资源，推动合作项目的顺利实施，确保项目按时交付并达到预期目标。\n6. 客户关系维护：与航空公司保持长期稳定的合作关系，定期拜访客户，了解客户需求，提升客户满意度。\n7. 跨部门协作：与产品、技术、运营、市场等部门紧密合作，推动航空业务的产品优化和用户体验提升。\n\n岗位基本要求\n1. 学历背景：本科及以上学历，航空管理、市场营销、商务管理、经济学等相关专业优先。\n2. 工作经验：\n5年以上航空行业或OTA（在线旅游平台）或TO B、政府侧相关大客户工作经验，熟悉国企、航司、体制内企业业务决策流程及行业规则；\n有丰富的商务拓展、合作谈判经验，具备成功的合作案例。\n3. 行业知识：对航空市场有深刻理解，熟悉航空公司运营模式、票务系统、分销渠道及行业政策优先。\n4. 商务能力：具备优秀的商务谈判能力、沟通技巧和客户关系管理能力，能够独立完成商务合作的全流程。\n5. 数据分析：具备较强的数据分析能力，能够通过市场数据和用户行为分析，制定有效的业务策略。\n6. 团队协作：具备良好的跨部门协作能力，能够高效协调内外部资源，推动项目落地。\n7. 高效工作：能够在高强度、快节奏的工作环境中保持高效工作，具备较强的解决问题的能力。\n\n岗位亮点\n团队氛围良好，部门业务发展迅速，给个人充分的成长和晋升通道\n具备以下优先:\n• 有航空公司或OTA行业头部企业工作经验者优先；\n• 具备创新思维，能够提出具有前瞻性的合作模式和业务策略。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4728458624","sourceKey":"meituan_social","company":"美团","title":"CDC运营经理","city":"济南市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4728458624&jobShareType=1","duty":"1. 负责仓储+运输一体化运营，统筹入库、存储、盘点、出库、退换货全流程，落地SOP标准化与6S现场、安全管理，保障库存准确、货损可控。\n2. 负责干线调拨、运力调度、承运商管理，管控运输时效、破损率、在途异常，优化配载与路线，降低整体物流成本。\n3. 负责团队管理、排班考核、技能培训，复盘仓运数据，持续降本增效，保障日常及大促旺季履约稳定。\n4. 需对接业务、供应链计划、供应商等横向协同沟通，问题闭环与流程优化。","requirements":"1. 大学本科及以上学历，物流、供应链、管理类相关专业优先。  \n2. 具备5年以上仓储运营管理经验，有大型CDC仓或电商仓储管理经验者优先。  \n3. 熟悉WMS、TMS系统操作及仓储自动化设备应用，具备流程优化与项目管理能力。  \n4. 具备较强的数据分析能力、沟通协调能力及团队管理经验。  \n5. 工作责任心强，能承受一定工作压力，适应灵活排班与突发任务处理。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责仓储+运输一体化运营，统筹入库、存储、盘点、出库、退换货全流程，落地SOP标准化与6S现场、安全管理，保障库存准确、货损可控。\n2. 负责干线调拨、运力调度、承运商管理，管控运输时效、破损率、在途异常，优化配载与路线，降低整体物流成本。\n3. 负责团队管理、排班考核、技能培训，复盘仓运数据，持续降本增效，保障日常及大促旺季履约稳定。\n4. 需对接业务、供应链计划、供应商等横向协同沟通，问题闭环与流程优化。\n\n岗位基本要求\n1. 大学本科及以上学历，物流、供应链、管理类相关专业优先。  \n2. 具备5年以上仓储运营管理经验，有大型CDC仓或电商仓储管理经验者优先。  \n3. 熟悉WMS、TMS系统操作及仓储自动化设备应用，具备流程优化与项目管理能力。  \n4. 具备较强的数据分析能力、沟通协调能力及团队管理经验。  \n5. 工作责任心强，能承受一定工作压力，适应灵活排班与突发任务处理。\n\n岗位亮点\n1. 加入快速发展的物流平台，参与核心仓储节点运营，成长空间广阔。  \n2. 提供完善的培训体系与职业发展通道，支持专业与管理双路径晋升。  \n3. 团队氛围积极，扁平化管理，鼓励创新与持续改进。  \n4. 工作地点位于济南核心物流园区，交通便利，配套设施完善。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4597359998","sourceKey":"meituan_social","company":"美团","title":"净菜运营专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4597359998&jobShareType=1","duty":"1.参与制定净菜加工中心的发展战略和运营规划，包括产能规划、设备需求、新品开发、质量控制等工作； \n2.负责生产管理的架构搭建、指标运营，发现日常运营中的提升点，制定改善措施并指导落地； \n3.负责加工模块相关的数据链完善和数据看板能力设计，推动实现数据线上化；\n4.搭建经营和运营数据模型，分析数据，提出改进方案并推动落地执行；\n5.依据切品计划，核算指标目标，制定提效降本和品质改善策略，并推动落地和结果达成；\n6.负责协同劳动力和薪资管理、品质和工艺改善、设备管理和设备需求对接。","requirements":"1.大学专科及以上学历，生鲜、食品加工相关专业优先； \n2.具有3年以上央厨运营领域工作经验，有净菜运营和数据分析经验者优先考虑； \n3.熟练使用办公软件及数据分析工具，具备基础报表能力；\n4.具有较强的团队管理能力，对数据有一定的敏感性， 能够通过数据看到问题的本质，并推动现场解决； \n5.良好的沟通能力，能够应对突发情况并及时解决问题。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.参与制定净菜加工中心的发展战略和运营规划，包括产能规划、设备需求、新品开发、质量控制等工作； \n2.负责生产管理的架构搭建、指标运营，发现日常运营中的提升点，制定改善措施并指导落地； \n3.负责加工模块相关的数据链完善和数据看板能力设计，推动实现数据线上化；\n4.搭建经营和运营数据模型，分析数据，提出改进方案并推动落地执行；\n5.依据切品计划，核算指标目标，制定提效降本和品质改善策略，并推动落地和结果达成；\n6.负责协同劳动力和薪资管理、品质和工艺改善、设备管理和设备需求对接。\n\n岗位基本要求\n1.大学专科及以上学历，生鲜、食品加工相关专业优先； \n2.具有3年以上央厨运营领域工作经验，有净菜运营和数据分析经验者优先考虑； \n3.熟练使用办公软件及数据分析工具，具备基础报表能力；\n4.具有较强的团队管理能力，对数据有一定的敏感性， 能够通过数据看到问题的本质，并推动现场解决； \n5.良好的沟通能力，能够应对突发情况并及时解决问题。\n\n具备以下条件优先\n互联网公司经验、中央厨房运营经验、蔬菜深加工经验、数据异常识别和改善\n\n岗位亮点\n1.有机会参与净菜加工中心的发展规划和战略制定，具有较大的发展空间；\n2.可以锻炼自己的精益管理能力和项目推动能力；\n3.参与生鲜供应链核心环节，推动净菜业务标准化与规模化发展；\n4.积累高价值的物流运营实战经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4675068376","sourceKey":"meituan_social","company":"美团","title":"点评技术-搜索算法工程师","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4675068376&jobShareType=1","duty":"1. 负责搜索算法的设计与优化，提升搜索相关性、排序效果及用户体验。  \n2. 深入理解业务需求，结合用户行为数据，持续迭代搜索策略与模型。  \n3. 参与搜索系统的架构设计与技术选型，保障系统高性能与高可用性。  \n4. 与产品、运营团队协作，推动搜索功能的创新与落地。\n5. 主导大语言模型（LLM）在搜索全链路（生成式召回、LLM排序及相关性判断）的深度融合与落地，推动搜索范式从检索式向Agent化演进。","requirements":"1. 硕士研究生学历，计算机、数学、统计学等相关专业。  \n2. 3年以上搜索算法或推荐系统相关工作经验。  \n3. 熟悉机器学习、自然语言处理、信息检索等核心技术，有大规模数据处理经验。  \n4. 熟练掌握Python、Java或C++等编程语言，具备良好的工程实现能力。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1. 负责搜索算法的设计与优化，提升搜索相关性、排序效果及用户体验。  \n2. 深入理解业务需求，结合用户行为数据，持续迭代搜索策略与模型。  \n3. 参与搜索系统的架构设计与技术选型，保障系统高性能与高可用性。  \n4. 与产品、运营团队协作，推动搜索功能的创新与落地。\n5. 主导大语言模型（LLM）在搜索全链路（生成式召回、LLM排序及相关性判断）的深度融合与落地，推动搜索范式从检索式向Agent化演进。\n\n岗位基本要求\n1. 硕士研究生学历，计算机、数学、统计学等相关专业。  \n2. 3年以上搜索算法或推荐系统相关工作经验。  \n3. 熟悉机器学习、自然语言处理、信息检索等核心技术，有大规模数据处理经验。  \n4. 熟练掌握Python、Java或C++等编程语言，具备良好的工程实现能力。\n\n具备以下条件优先\n1. 顶会论文：在 KDD、SIGIR、ACL、ICML、RecSys 等顶级会议或期刊上发表过搜索/推荐相关论文。\n2. RAG应用经验：有基于 LangChain/LlamaIndex 构建检索增强生成（RAG）系统的实践，熟悉知识图谱与向量数据库（Milvus/Pinecone）的结合应用。\n3. 大规模训练：有过千亿级参数稀疏模型在万卡集群上的训练及稳定性调优经验。\n\n岗位亮点\n1. 参与亿级用户规模的搜索系统建设，技术挑战与成长空间大。  \n2. 与行业SOTA技术算法团队共事，技术氛围浓厚。  \n3. 提供有竞争力的薪酬与完善的职业发展通道。  \n4. 工作地点北京上海可选。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4507933767","sourceKey":"meituan_social","company":"美团","title":"闪购-歪马-进口酒自有品牌开发经理","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4507933767&jobShareType=1","duty":"1. 深度了解进口酒品类市场，供应链情况及品控安全，根据公司战略目标，制定具有可行性的选品招商策略和经营规划，设定年度目标并执行完成；\n2. 负责自有品牌的采购策略制定和执行，确保采购活动与公司业务目标相一致。\n3. 负责供应商的筛选、评估和谈判，与供应商建立长期合作关系，确保产品质量和供应稳定性。\n4. 跟进市场动态和行业趋势，制定供应链发展战略，提前预测市场需求，为公司产品提供有竞争力的供应链解决方案。\n5. 协调各部门之间的沟通和协作，确保采购流程的顺畅进行，提高工作效率。\n6. 对供应商履行合同、产品质量、交货时间等进行监督和评估，及时解决供应链相关问题。","requirements":"1. 3年进口酒开发及运营经验，5年从事酒水行业工作经验。\n2. 具备一定的国际视野，了解国际贸易流程。\n3. 具备一定的电商，私域运营意识，副本基本渠道运营经验，较强的逻辑分析和总结能力，良好的市场敏感度，优秀的谈判技巧，供应商管理与商品管理技巧。\n4.有良好的跨部门沟通协调能力，良好的团队协作能力\n5. 需要具备WSET三级等国际品酒师认证。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1. 深度了解进口酒品类市场，供应链情况及品控安全，根据公司战略目标，制定具有可行性的选品招商策略和经营规划，设定年度目标并执行完成；\n2. 负责自有品牌的采购策略制定和执行，确保采购活动与公司业务目标相一致。\n3. 负责供应商的筛选、评估和谈判，与供应商建立长期合作关系，确保产品质量和供应稳定性。\n4. 跟进市场动态和行业趋势，制定供应链发展战略，提前预测市场需求，为公司产品提供有竞争力的供应链解决方案。\n5. 协调各部门之间的沟通和协作，确保采购流程的顺畅进行，提高工作效率。\n6. 对供应商履行合同、产品质量、交货时间等进行监督和评估，及时解决供应链相关问题。\n\n岗位基本要求\n1. 3年进口酒开发及运营经验，5年从事酒水行业工作经验。\n2. 具备一定的国际视野，了解国际贸易流程。\n3. 具备一定的电商，私域运营意识，副本基本渠道运营经验，较强的逻辑分析和总结能力，良好的市场敏感度，优秀的谈判技巧，供应商管理与商品管理技巧。\n4.有良好的跨部门沟通协调能力，良好的团队协作能力\n5. 需要具备WSET三级等国际品酒师认证。\n\n具备以下条件优先\n海外生活和工作经验可以优先。\n葡萄酒种植与酿造专业，葡萄酒市场与营销专业优先。\n\n岗位亮点\n1.作为自有品牌采购专家，将有机会参与公司自有品牌的战略制定和业务拓展，为公司的发展贡献自己的智慧和经验。培养品牌打造能力。\n2.在国际化大都市工作，将接触到各种国内外供应商和市场资源，拥有广阔的发展空间和机会。\n3.作为高级职级，将有更多的自主权和决策权，能够充分发挥自己的专业能力和经验，对品类的采购策略起到重要的推动作用。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4717407290","sourceKey":"meituan_social","company":"美团","title":"客服大模型电话产品岗","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4717407290&jobShareType=1","duty":"1.拆解大模型技术边界，结合亿级C端用户行为数据与客服高频场景，探索大模型在语音客服领域的应用价值​，实现电话时延、对话拟人度和模型效果的平衡\n2.跟进技术前沿，能够了解语音交互类技术前沿进展，并结合业务场景所需推动落地试点，优化对话效果、改善用户体验\n3.负责清晰的探索路径，产品节奏，制定量化目标，输出各阶段价值报告，并对齐业务预期\n4.对美团多业务线，整合用户共性需求与业务个性化诉求\n5.把控落地过程中的能力可行性验证，方案实现、并制定效果指标​和评测方案\n6.跟踪核心指标，收集用户反馈并转化为需求，适配用户行为变化\n岗位要求:","requirements":"1.3年以上互联网产品经理经验，具备大模型项目落地经验，有语音交互类、RAG或AI Agent产品方案设计经验者优先。\n2.较强的业务理解能力，能深入了解用户需求和痛点，将大模型应用落地与用户需求相结合。\n3.有较强的项目管理、沟通表达和跨团队协调能力，能拿结果打胜仗。","description":"部门介绍\n核心本地商业（Core Local Commerce）是美团“零售+科技”战略的重要载体，涵盖了到店餐饮、服务零售、酒店旅行、外卖、履约配送、闪购、医药健康等多个业务，覆盖了超过200个消费场景，致力于通过“随时随地”的商品和服务，满足消费者的多样性需求，帮大家吃得更好，生活更好。核心本地商业扎根本地消费，围绕消费者的“吃、住、行、游、购、娱”进行深度创新，引领发展了即时零售、团购等多种消费业态，并在全国范围内广泛投资发展本地供给、履约平台等设施，助力创造产业、带动就业。基于多年的持续投入，核心本地商业打造了连接全国超过一千万中小微企业的服务体系，以及全球最大的即时配送网络。由核心本地商业所推行的30分钟“万物到家”体系，已覆盖全国2800多个城镇，为数亿用户提供优质的商品与服务。发展过程中，核心本地商业有效助力商超、连锁、本地小店等各类实体经济主体扩大交易规模、降低交易成本。截至目前，核心本地商业日均创造订单量数千万笔，助力千万商户实现了高质量发展。未来，核心本地商业将继续践行美团“零售+科技”战略，通过更大的投资，更多的技术创新，支持、培育消费新业态，为促进消费、服务民生、带动就业作出力所能及的贡献。欢迎优秀的你加入核心本地商业，我们携手助力市场繁荣，为用户创造更好的消费体验。\n\n岗位职责\n1.拆解大模型技术边界，结合亿级C端用户行为数据与客服高频场景，探索大模型在语音客服领域的应用价值​，实现电话时延、对话拟人度和模型效果的平衡\n2.跟进技术前沿，能够了解语音交互类技术前沿进展，并结合业务场景所需推动落地试点，优化对话效果、改善用户体验\n3.负责清晰的探索路径，产品节奏，制定量化目标，输出各阶段价值报告，并对齐业务预期\n4.对美团多业务线，整合用户共性需求与业务个性化诉求\n5.把控落地过程中的能力可行性验证，方案实现、并制定效果指标​和评测方案\n6.跟踪核心指标，收集用户反馈并转化为需求，适配用户行为变化\n岗位要求:\n\n岗位基本要求\n1.3年以上互联网产品经理经验，具备大模型项目落地经验，有语音交互类、RAG或AI Agent产品方案设计经验者优先。\n2.较强的业务理解能力，能深入了解用户需求和痛点，将大模型应用落地与用户需求相结合。\n3.有较强的项目管理、沟通表达和跨团队协调能力，能拿结果打胜仗。\n\n具备以下条件优先\n具备大模型项目落地经验，有语音交互类、大模型Agent类产品经验者优先；\n\n岗位亮点\n塑造未来，你将主导客服场景大模型应用的落地；\n专业深化，你将深度参与美团平台大模型技术STL组织；\n全局视野，你将了解美团所有业务差异化的服务策略；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4288775056","sourceKey":"meituan_social","company":"美团","title":"下沉市场财务FPA","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4288775056&jobShareType=1","duty":"1、负责下沉市场财务综合分析，包含预算及预测模型迭代、对下沉整体损益监控、各业务线对标分析及相关专题分析等；\n2、与业务部门建立良好合作关系，对业务策略和项目进度有理解和判断，输出有价值的关键发现和策略建议；\n3、联动核算、结算、资金、税务等财税的专业团队，建立高效协同合作伙伴关系，推动业财联合；\n4、支持城市经营分析，在LBS维度对下沉各业务损益进行相关监控；\n5、AI工具应用：主动将AI工具融入日常工作，使用Agent优化提效和增加产出，例如：数据处理与分析、报表/看板搭建、测算/分析模型搭建、知识库建设等。","requirements":"1、本科及以上学历，财务相关专业；拥有5年以上财务相关经验，3年以上的财务分析及财务业务支持经验；\n2、善于沟通，具备优秀的数据分析能力和文字表达能力，会sql等取数能力优先；\n3、具备敏锐的业务观察力、良好的结构化思维，以及系统建模能力，能快速理解并设计业务逻辑和流程；\n4、具备优秀的沟通能力，工作责任心强、自我驱动，以及良好的团队合作精神。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1、负责下沉市场财务综合分析，包含预算及预测模型迭代、对下沉整体损益监控、各业务线对标分析及相关专题分析等；\n2、与业务部门建立良好合作关系，对业务策略和项目进度有理解和判断，输出有价值的关键发现和策略建议；\n3、联动核算、结算、资金、税务等财税的专业团队，建立高效协同合作伙伴关系，推动业财联合；\n4、支持城市经营分析，在LBS维度对下沉各业务损益进行相关监控；\n5、AI工具应用：主动将AI工具融入日常工作，使用Agent优化提效和增加产出，例如：数据处理与分析、报表/看板搭建、测算/分析模型搭建、知识库建设等。\n\n岗位基本要求\n1、本科及以上学历，财务相关专业；拥有5年以上财务相关经验，3年以上的财务分析及财务业务支持经验；\n2、善于沟通，具备优秀的数据分析能力和文字表达能力，会sql等取数能力优先；\n3、具备敏锐的业务观察力、良好的结构化思维，以及系统建模能力，能快速理解并设计业务逻辑和流程；\n4、具备优秀的沟通能力，工作责任心强、自我驱动，以及良好的团队合作精神。\n\n具备以下条件优先\n拥抱AI，有AI相关经验者优先。\n\n岗位亮点\n岗位有丰富的机会从事业务和财务分析，涉及核心本地商业众多业务线，能够与专业的业务、财务及商分团队合作，跟一群富有激情又聪颖的小伙伴一起奋斗。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4630056806","sourceKey":"meituan_social","company":"美团","title":"小象超市-配送效率运营专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4630056806&jobShareType=1","duty":"1. 调度规则设计与优化：负责驻店配送场景下的调度策略，围绕波次调度、集单规则、预调度时机等核心环节，持续设计和迭代调度策略，在有效集单时间与骑手工时利用率之间找到最优平衡；对趟次单量和单均配送时长负责。\n2. 骑手成长体系搭建与运营：设计骑手从入职到成熟的完整成长路径，包括背单解锁节奏、等级晋升规则及配套权益体系，通过合理的激励设计和约束机制加快骑手能力成长速度；对骑手等级跃迁和新骑手留存率负责。\n3. 跨团队协同推进：与调度系统产品团队紧密协作，将运营策略转化为系统规则落地；与骑手分层、路区管理等模块协同，确保调度规则与路区结构、骑手能力相互配合；对策略从验证到全量落地的完整交付负责。\n4. 策略验证与迭代：设计调度策略和成长规则的AB测试方案，建立从假设提出、试点执行到数据结论的完整验证链路；对每一次策略迭代的效率增量可量化、可复制负责。","requirements":"1. 本科及以上学历，5年以上工作经验，其中2年以上即时配送运营经验；\n2. 对配送调度逻辑有深入理解，熟悉波次调度、集单机制、骑手派单规则等核心概念，能够从效率视角识别调度链路中的关键做功点；\n3. 具备较强的数据分析能力，能够基于满载率、趟均单量等指标发现问题、制定策略并推动落地；\n4. 有骑手成长体系、权益设计或激励机制相关经验者优先；\n5. 具备跨团队协作与推动能力，能与产品、技术、运营等团队高效协同，推动规则系统化落地。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 调度规则设计与优化：负责驻店配送场景下的调度策略，围绕波次调度、集单规则、预调度时机等核心环节，持续设计和迭代调度策略，在有效集单时间与骑手工时利用率之间找到最优平衡；对趟次单量和单均配送时长负责。\n2. 骑手成长体系搭建与运营：设计骑手从入职到成熟的完整成长路径，包括背单解锁节奏、等级晋升规则及配套权益体系，通过合理的激励设计和约束机制加快骑手能力成长速度；对骑手等级跃迁和新骑手留存率负责。\n3. 跨团队协同推进：与调度系统产品团队紧密协作，将运营策略转化为系统规则落地；与骑手分层、路区管理等模块协同，确保调度规则与路区结构、骑手能力相互配合；对策略从验证到全量落地的完整交付负责。\n4. 策略验证与迭代：设计调度策略和成长规则的AB测试方案，建立从假设提出、试点执行到数据结论的完整验证链路；对每一次策略迭代的效率增量可量化、可复制负责。\n\n岗位基本要求\n1. 本科及以上学历，5年以上工作经验，其中2年以上即时配送运营经验；\n2. 对配送调度逻辑有深入理解，熟悉波次调度、集单机制、骑手派单规则等核心概念，能够从效率视角识别调度链路中的关键做功点；\n3. 具备较强的数据分析能力，能够基于满载率、趟均单量等指标发现问题、制定策略并推动落地；\n4. 有骑手成长体系、权益设计或激励机制相关经验者优先；\n5. 具备跨团队协作与推动能力，能与产品、技术、运营等团队高效协同，推动规则系统化落地。\n\n岗位亮点\n1. 核心业务运营，直接影响千万用户配送体验。  \n2. 快速积累物流与运营实战经验。  \n3. 提供清晰的职业发展路径与专业成长支持。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4654786918","sourceKey":"meituan_social","company":"美团","title":"便利店闪电仓KA商家运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4654786918&jobShareType=1","duty":"一、岗位定位\n作为闪电仓KA品牌的大客户经理，能够深入商家生意逻辑，以商品为最小策略单元，驱动品牌GMV增长与经营改善。不是\"传声筒式\"的客户对接，而是能看得懂账、拆得了品类、诊得了流量、能做取舍的经营型业务顾问。\n\n二、岗位职责：\n1.经营分析诊断。能够识别品牌优劣势，并以货盘-品类-商品的视角洞察机会点与问题点；\n2.业务策略制定。擅长品类运营，以商品为最小策略单元，共建品牌策略方案，驱动品牌GMV增长与经营改善；\n3.多方资源整合。清晰了解品牌、门店、上游厂商、平台的资源空间，并依托业务策略及产品工具整合营销方案。\n4.项目管理能力。基于经营目标及业务策略，以项目制形式拆解、推进、复盘，并识别风险、及时应对。\n\n三、能力要求：\n1. 品类诊断与策略制定：基于商家分品类盈利逻辑，对商家运营能力在结果层（店单产/利润/周转）+和过程层（哪些行为差异导致了结果差异）做两层解构，识别商家的优势类目，并以共建的形式输出差异化策略。\n2.商品运营：结合热搜词趋势、季节/场景变化，指导商家选品上新与货盘结构优化，并推动策略落地，追踪ROI和转化效果。\n3.流量运营与营销资源整合：体系化使用平台流量工具（神券/神价/广告/首页推荐等），以及自营销工具（折扣品/爆品），能够诊断流量机会点并整合多方资源形成合力。\n4.经营目标共识与落地闭环：以服务报告作为沟通载体，与商家共识经营目标（增长/增收/降本/提效等），测算收益空间，并结合业务策略建立常态化追踪复盘机制。","requirements":"四、岗位要求：\n1.本科及以上学历，3年以上零售行业经验。\n2.懂经营：能讲清楚不同品类的毛利结构、周转逻辑、定价策略等；\n3.懂数据：熟练使用BI工具进行经营分析，能独立完成从数据-洞察-策略全链路工作；\n4.懂商家：服务过连锁品牌或区域头部商家，知道怎么跟商家\"谈生意\"而不是\"传通知\"；\n5.优先项：①.有前置仓/便利店/闪电仓等近场零售业态的品类运营/商品经验；②.快消品类（食品饮料/日百/个护）的选品或采购背景；③.有大客户BD或KA管理经验，能独立推进跨部门协作。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n一、岗位定位\n作为闪电仓KA品牌的大客户经理，能够深入商家生意逻辑，以商品为最小策略单元，驱动品牌GMV增长与经营改善。不是\"传声筒式\"的客户对接，而是能看得懂账、拆得了品类、诊得了流量、能做取舍的经营型业务顾问。\n\n二、岗位职责：\n1.经营分析诊断。能够识别品牌优劣势，并以货盘-品类-商品的视角洞察机会点与问题点；\n2.业务策略制定。擅长品类运营，以商品为最小策略单元，共建品牌策略方案，驱动品牌GMV增长与经营改善；\n3.多方资源整合。清晰了解品牌、门店、上游厂商、平台的资源空间，并依托业务策略及产品工具整合营销方案。\n4.项目管理能力。基于经营目标及业务策略，以项目制形式拆解、推进、复盘，并识别风险、及时应对。\n\n三、能力要求：\n1. 品类诊断与策略制定：基于商家分品类盈利逻辑，对商家运营能力在结果层（店单产/利润/周转）+和过程层（哪些行为差异导致了结果差异）做两层解构，识别商家的优势类目，并以共建的形式输出差异化策略。\n2.商品运营：结合热搜词趋势、季节/场景变化，指导商家选品上新与货盘结构优化，并推动策略落地，追踪ROI和转化效果。\n3.流量运营与营销资源整合：体系化使用平台流量工具（神券/神价/广告/首页推荐等），以及自营销工具（折扣品/爆品），能够诊断流量机会点并整合多方资源形成合力。\n4.经营目标共识与落地闭环：以服务报告作为沟通载体，与商家共识经营目标（增长/增收/降本/提效等），测算收益空间，并结合业务策略建立常态化追踪复盘机制。\n\n岗位基本要求\n四、岗位要求：\n1.本科及以上学历，3年以上零售行业经验。\n2.懂经营：能讲清楚不同品类的毛利结构、周转逻辑、定价策略等；\n3.懂数据：熟练使用BI工具进行经营分析，能独立完成从数据-洞察-策略全链路工作；\n4.懂商家：服务过连锁品牌或区域头部商家，知道怎么跟商家\"谈生意\"而不是\"传通知\"；\n5.优先项：①.有前置仓/便利店/闪电仓等近场零售业态的品类运营/商品经验；②.快消品类（食品饮料/日百/个护）的选品或采购背景；③.有大客户BD或KA管理经验，能独立推进跨部门协作。\n\n岗位亮点\n前置仓/闪电仓是零售行业增速最快的业态之一，不是传统电商的红海，而是即时零售的蓝海。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4728581205","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-低压电气/线束采购","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4728581205&jobShareType=1","duty":"1. 负责低压电气及线束类物料的采购策略制定与执行，保障供应链稳定与成本优化。  \n2. 开发、评估和管理供应商资源，建立长期合作关系，确保质量、交期与价格竞争力。  \n3. 跟进采购订单执行，协调解决交付、质量及售后问题，提升采购效率。  \n4. 分析市场行情与成本结构，推动降本措施落地，支持产品成本目标达成。","requirements":"1. 大学本科及以上学历，电气工程、机械、供应链或相关专业优先。  \n2. 3年以上低压电气或线束类物料采购经验，熟悉相关行业标准与供应商生态。  \n3. 具备良好的谈判能力、数据分析能力和跨部门协作能力。  \n4. 工作城市为北京市或上海市，能适应一定频率的出差。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1. 负责低压电气及线束类物料的采购策略制定与执行，保障供应链稳定与成本优化。  \n2. 开发、评估和管理供应商资源，建立长期合作关系，确保质量、交期与价格竞争力。  \n3. 跟进采购订单执行，协调解决交付、质量及售后问题，提升采购效率。  \n4. 分析市场行情与成本结构，推动降本措施落地，支持产品成本目标达成。\n\n岗位基本要求\n1. 大学本科及以上学历，电气工程、机械、供应链或相关专业优先。  \n2. 3年以上低压电气或线束类物料采购经验，熟悉相关行业标准与供应商生态。  \n3. 具备良好的谈判能力、数据分析能力和跨部门协作能力。  \n4. 工作城市为北京市或上海市，能适应一定频率的出差。\n\n岗位亮点\n1. 参与核心物料采购，直接影响产品成本与供应链竞争力。  \n2. 与行业供应商深度合作，积累专业资源与行业洞察。  \n3. 提供清晰的职业发展路径与跨领域学习机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4725282195","sourceKey":"meituan_social","company":"美团","title":"快驴-成都品质管理（补）","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4725282195&jobShareType=1","duty":"1.根据标准完成生鲜、标品的验收工作，对问题商品及时与采购沟通，推进后续处理。\n2.农药残留检测、瘦肉精检测、粮食水分检测。\n3.仓内存储环境检查、投线作业检查、车辆装载检查，并对不标准操作予以纠偏。\n4.客诉分析及跟进协同解决、退货数据分析及质量改善提升。\n5.品控团队成员的专业指导，BD、采购、仓配的业务培训。\n6.专业战队的实验及案例分享。","requirements":"1.大专及以上学历，食品相关专业。\n2.有蔬菜、水果、肉禽、蛋奶相关工作经验，优先蔬菜和鲜肉经验的。\n3.有3年以上QA、QC工作经验（食品、零售、电商等行业）。\n4.有较强的沟通协调能力、联动协同能力，能连接合作伙伴共同解决问题，推动项目。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1.根据标准完成生鲜、标品的验收工作，对问题商品及时与采购沟通，推进后续处理。\n2.农药残留检测、瘦肉精检测、粮食水分检测。\n3.仓内存储环境检查、投线作业检查、车辆装载检查，并对不标准操作予以纠偏。\n4.客诉分析及跟进协同解决、退货数据分析及质量改善提升。\n5.品控团队成员的专业指导，BD、采购、仓配的业务培训。\n6.专业战队的实验及案例分享。\n\n岗位基本要求\n1.大专及以上学历，食品相关专业。\n2.有蔬菜、水果、肉禽、蛋奶相关工作经验，优先蔬菜和鲜肉经验的。\n3.有3年以上QA、QC工作经验（食品、零售、电商等行业）。\n4.有较强的沟通协调能力、联动协同能力，能连接合作伙伴共同解决问题，推动项目。\n\n具备以下条件优先\n-\n\n岗位亮点\n了解生鲜行业，提高品控管理水平，为成长为合格品控管理者打下坚实基础。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4728383602","sourceKey":"meituan_social","company":"美团","title":"用户策略运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4728383602&jobShareType=1","duty":"1.负责美团买药新即时零售业务用户增长，围绕流量获取、转化效率、用户质量三大环节深度做工，扩大新用户规模并提升留存；探索并拓展域内新合作渠道，深入调研外卖主交易链路，基于交易链路与用户分层，构建医药权益外输场景及供给策略，优化用户动线，实现增长目标。\n\n2.深度理解用户需求，构建用户权益与成长体系，持续提升权益吸引力；重点强化会员用户运营能力，拉升老客购买频次。\n\n3.协同多部门推进产品基建与数据链路建设，同时负责外部渠道合作策略制定、数据分析及运营；洞察行业痛点并制定高效方案，建立渠道协同机制，围绕关键问题优化业务策略。\n\n4.深入理解买药用户画像与行为，帮助业务更清晰地看清用户、理解需求，创造增量空间；沉淀用户洞察与增长SOP，构建用户运营产品能力体系。\n\n5.引入AI用户分层模型实现精准推送，借助LLM进行用户洞察与增长SOP的自动化生成，提升运营效率与决策质量。","requirements":"1.本科及以上学历，3年以上互联网用户增长、渠道增长或零售业务相关经验，执着于用户需求理解，偏好动手实践，有扎实的增长实战成果。\n2.具备行业玩法积累与策略评估能力，独立负责过完整项目，对增长运营、用户运营、品类运营均有实战经验与深度理解。\n3.逻辑清晰，结果导向，具备基础数据分析能力，善于发现和挖掘数据价值；创业心态，敢于尝试、直面问题。\n4.了解AI在用户增长中的应用场景（如流失预测模型、智能用户分层），有AI工具辅助运营决策的实践经验者优先。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1.负责美团买药新即时零售业务用户增长，围绕流量获取、转化效率、用户质量三大环节深度做工，扩大新用户规模并提升留存；探索并拓展域内新合作渠道，深入调研外卖主交易链路，基于交易链路与用户分层，构建医药权益外输场景及供给策略，优化用户动线，实现增长目标。\n\n2.深度理解用户需求，构建用户权益与成长体系，持续提升权益吸引力；重点强化会员用户运营能力，拉升老客购买频次。\n\n3.协同多部门推进产品基建与数据链路建设，同时负责外部渠道合作策略制定、数据分析及运营；洞察行业痛点并制定高效方案，建立渠道协同机制，围绕关键问题优化业务策略。\n\n4.深入理解买药用户画像与行为，帮助业务更清晰地看清用户、理解需求，创造增量空间；沉淀用户洞察与增长SOP，构建用户运营产品能力体系。\n\n5.引入AI用户分层模型实现精准推送，借助LLM进行用户洞察与增长SOP的自动化生成，提升运营效率与决策质量。\n\n岗位基本要求\n1.本科及以上学历，3年以上互联网用户增长、渠道增长或零售业务相关经验，执着于用户需求理解，偏好动手实践，有扎实的增长实战成果。\n2.具备行业玩法积累与策略评估能力，独立负责过完整项目，对增长运营、用户运营、品类运营均有实战经验与深度理解。\n3.逻辑清晰，结果导向，具备基础数据分析能力，善于发现和挖掘数据价值；创业心态，敢于尝试、直面问题。\n4.了解AI在用户增长中的应用场景（如流失预测模型、智能用户分层），有AI工具辅助运营决策的实践经验者优先。\n\n岗位亮点\n1.触碰海量零售增长玩法，具备洞察物理世界下真实用户需求的条件与土壤。\n2.足够大的发挥空间，可主导渠道从0到1的搭建与增长，鼓励创新试错。\n3.与一群能长相守的战友同行，共同探索真实、对用户有益的增长路径。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4727060065","sourceKey":"meituan_social","company":"美团","title":"战略管理部-战略研究","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4727060065&jobShareType=1","duty":"【1】洞察长期的消费趋势和行业变化，跟踪国内外重点行业玩家进展，深入分析和理解用户和商户需求，挖掘机会、识别风险，并面向管理者和各业务输出；\n【2】电商、即时零售、广告、生活服务相关的行业分析，完成有一定模糊度、复杂度的专题，发现和探查具有共性的议题，并与核心管理者展开讨论；\n【3】以项目共建的方式，与各业务、商分等深度合作，推动战略议题讨论；\n【4】注重方法论积累和知识沉淀，帮助各业务间拉通行业认知及判断。","requirements":"【1】3-5年以上战略行研及经分经验，能够完成中高复杂度的专题分析；\n【2】具有极强的自驱力和好奇心，优秀的学习能力、逻辑思维和洞察力，行业分析能力强；\n【3】对所在业务/领域的商业逻辑、行业、用户、商家有深刻理解，偏好深潜；\n【4】擅长合作，有良好的利他精神，具备优秀的沟通和协同能力。","description":"部门介绍\n核心本地商业（Core Local Commerce）是美团“零售+科技”战略的重要载体，涵盖了到店餐饮、服务零售、酒店旅行、外卖、履约配送、闪购、医药健康等多个业务，覆盖了超过200个消费场景，致力于通过“随时随地”的商品和服务，满足消费者的多样性需求，帮大家吃得更好，生活更好。核心本地商业扎根本地消费，围绕消费者的“吃、住、行、游、购、娱”进行深度创新，引领发展了即时零售、团购等多种消费业态，并在全国范围内广泛投资发展本地供给、履约平台等设施，助力创造产业、带动就业。基于多年的持续投入，核心本地商业打造了连接全国超过一千万中小微企业的服务体系，以及全球最大的即时配送网络。由核心本地商业所推行的30分钟“万物到家”体系，已覆盖全国2800多个城镇，为数亿用户提供优质的商品与服务。发展过程中，核心本地商业有效助力商超、连锁、本地小店等各类实体经济主体扩大交易规模、降低交易成本。截至目前，核心本地商业日均创造订单量数千万笔，助力千万商户实现了高质量发展。未来，核心本地商业将继续践行美团“零售+科技”战略，通过更大的投资，更多的技术创新，支持、培育消费新业态，为促进消费、服务民生、带动就业作出力所能及的贡献。欢迎优秀的你加入核心本地商业，我们携手助力市场繁荣，为用户创造更好的消费体验。\n\n岗位职责\n【1】洞察长期的消费趋势和行业变化，跟踪国内外重点行业玩家进展，深入分析和理解用户和商户需求，挖掘机会、识别风险，并面向管理者和各业务输出；\n【2】电商、即时零售、广告、生活服务相关的行业分析，完成有一定模糊度、复杂度的专题，发现和探查具有共性的议题，并与核心管理者展开讨论；\n【3】以项目共建的方式，与各业务、商分等深度合作，推动战略议题讨论；\n【4】注重方法论积累和知识沉淀，帮助各业务间拉通行业认知及判断。\n\n岗位基本要求\n【1】3-5年以上战略行研及经分经验，能够完成中高复杂度的专题分析；\n【2】具有极强的自驱力和好奇心，优秀的学习能力、逻辑思维和洞察力，行业分析能力强；\n【3】对所在业务/领域的商业逻辑、行业、用户、商家有深刻理解，偏好深潜；\n【4】擅长合作，有良好的利他精神，具备优秀的沟通和协同能力。\n\n岗位亮点\n【1】打造核心本地商业中既有高专业度又接地气的战略研究特种部队；\n【2】能够对核心本地商业有更全局的视角和洞察，并与业务合作共赢。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4705957782","sourceKey":"meituan_social","company":"美团","title":"小象超市-线下店品质运营主管","city":"北京市/扬州市/宁波市/蚌埠市/武汉市/重庆市/成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4705957782&jobShareType=1","duty":"1.监督抽查店内现场及联营商商品品质，对店内进销存链路管控，做到日管控、周排查、月调度；\n2.现场内部检查问题、顾客不良体验以及外部反馈问题改善跟进；\n3.门店内食安sop培训及考核跟进；\n4.政府/区域食安对接、职业打假、三方对接、客服支持、跨部门沟通协调；\n5.各种专项季节商品、重要节日等门店侧联动/检查与改善等；\n6.门店现场实验室检测，结果公示等。","requirements":"1.本科及以上学历，食品、化学、生物等相关专业。具备至少5年以上卖场商品品质管理、商品质量管理、供应商/供应链管理能力；\n2.熟悉商品品质管理的各项工作和标准，了解制造业及零售企业中在品质管理体系的建立和运行；\n3.具备良好的沟通协作能力和团队管理能力，能够有效推动团队成员的工作及拿到结果；\n4.具备较强的韧性和应变能力，持续保持良好的工作状态；\n5.掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.监督抽查店内现场及联营商商品品质，对店内进销存链路管控，做到日管控、周排查、月调度；\n2.现场内部检查问题、顾客不良体验以及外部反馈问题改善跟进；\n3.门店内食安sop培训及考核跟进；\n4.政府/区域食安对接、职业打假、三方对接、客服支持、跨部门沟通协调；\n5.各种专项季节商品、重要节日等门店侧联动/检查与改善等；\n6.门店现场实验室检测，结果公示等。\n\n岗位基本要求\n1.本科及以上学历，食品、化学、生物等相关专业。具备至少5年以上卖场商品品质管理、商品质量管理、供应商/供应链管理能力；\n2.熟悉商品品质管理的各项工作和标准，了解制造业及零售企业中在品质管理体系的建立和运行；\n3.具备良好的沟通协作能力和团队管理能力，能够有效推动团队成员的工作及拿到结果；\n4.具备较强的韧性和应变能力，持续保持良好的工作状态；\n5.掌握基本的AI工具，使用工具提升工作流程效率。\n\n具备以下条件优先\n有线下零售门店品质管理、联营商管理经验优先。\n\n岗位亮点\n作为店内品控标准专家，将有机会参与公司品控体系的建设和优化，对公司产品质量起到关键作用。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4603842394","sourceKey":"meituan_social","company":"美团","title":"AI Agent 开发工程师","city":"北京市/成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4603842394&jobShareType=1","duty":"1. 负责CatPaw SDK/CLI能力建设，设计并实现Skill/Plugin体系，持续提升开发者体验。  \n2. 基于OpenClaw构建CatClaw集群，负责多智能体运行时、路由调度、会话管理及记忆系统的设计与开发。  \n3. 主导AI编排层开发，包括多模型调度、Prompt工程、Function Calling及上下文管理机制。  \n4. 推动IM/社交/办公等多端渠道的场景接入，支持浏览器自动化能力集成。  \n5. 构建安全隔离体系，实现多租户权限控制与数据沙箱机制，保障系统安全性与稳定性。","requirements":"1. 大学本科及以上学历，3年以上开发经验，精通TypeScript/Node.js或Python。  \n2. 重度AI Coding用户，熟练使用CatPaw/NoCode/Cursor/CC等AI编程工具进行日常开发。  \n3. 深入理解LLM应用开发，掌握Prompt设计、Tool Use、RAG等核心技术。  \n4. 具备平台或框架级系统设计能力，能独立完成复杂模块架构与实现。  \n5. 具备自驱力，善于与AI协作，主动探索技术边界并推动落地。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 负责CatPaw SDK/CLI能力建设，设计并实现Skill/Plugin体系，持续提升开发者体验。  \n2. 基于OpenClaw构建CatClaw集群，负责多智能体运行时、路由调度、会话管理及记忆系统的设计与开发。  \n3. 主导AI编排层开发，包括多模型调度、Prompt工程、Function Calling及上下文管理机制。  \n4. 推动IM/社交/办公等多端渠道的场景接入，支持浏览器自动化能力集成。  \n5. 构建安全隔离体系，实现多租户权限控制与数据沙箱机制，保障系统安全性与稳定性。\n\n岗位基本要求\n1. 大学本科及以上学历，3年以上开发经验，精通TypeScript/Node.js或Python。  \n2. 重度AI Coding用户，熟练使用CatPaw/NoCode/Cursor/CC等AI编程工具进行日常开发。  \n3. 深入理解LLM应用开发，掌握Prompt设计、Tool Use、RAG等核心技术。  \n4. 具备平台或框架级系统设计能力，能独立完成复杂模块架构与实现。  \n5. 具备自驱力，善于与AI协作，主动探索技术边界并推动落地。\n\n具备以下条件优先\n1. 有Agent平台/IDE/CLI工具链开发经验。  \n2. 熟悉浏览器自动化技术（如Playwright/CDP）。  \n3. 搭建过AI助理并投入日常使用。\n\n岗位亮点\n1. 参与构建下一代AI Agent开发框架与运行平台，技术影响力广泛。  \n2. 深度使用AI工具进行开发，鼓励高效人机协作。  \n3. 与前沿AI技术团队共同探索多智能体系统、浏览器自动化等创新方向。  \n4. 扁平化工作环境，支持技术自主决策与快速迭代。  \n5. 工作地点位于成都市，享受优质科技人才生态与生活环境。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4523441658","sourceKey":"meituan_social","company":"美团","title":"品类规划策略专家","city":"利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4523441658&jobShareType=1","duty":"1、商品基盘管理：根据业务的当前发展阶段和未来增长目标，制定和管理核心商品策略。品类商业规划：对指定品类进行商业规划和市场分析，识别市场趋势与消费需求，制定并实施品类商品结构提升策略；商品生命周期管理：明确上新汰旧策略，建立并运营商品全生命周期管理标准化流程；\n2、流程优化及效率提升：牵头商品相关领域的基础信息建设及产品系统迭代，确保经营链路有更高的组织效能和决策质量，提升资源转化效率；\n3、项目管理与效能提升：主导跨部门协作，全程监控项目进展，复盘总结活动成效，推动策略、产品和业务流程的持续改进。\n视角：既能从宏观视角了解行业，也可以从中观视角了解品类发展，策略与业务紧密结合。","requirements":"1、工作经验：具备5年及以上电商、零售或品牌商品运营经验，具备品类规划能力，熟悉生鲜、快消等行业特性及用户需求，有海外（中东地区）运营经验者优先；\n2、数据分析与策略：出色的数据分析能力，熟练使用BA工具，能独立完成经营分析及策略制定，能结合数据优化商品结构，提升转化率；\n3、战略思维与落地：具备体系化思维，能制定长期品类策略；同时具备优秀的跨部门协调能力，能高效整合资源，推动复杂项目落地，对经营结果负责；\n4、逻辑与沉淀：逻辑清晰，具备方法论沉淀能力，擅长复盘总结并输出标准化文档；\n5、有海外市场商品开发或跨境零售经验者优先；英语可作为工作语言者优先。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1、商品基盘管理：根据业务的当前发展阶段和未来增长目标，制定和管理核心商品策略。品类商业规划：对指定品类进行商业规划和市场分析，识别市场趋势与消费需求，制定并实施品类商品结构提升策略；商品生命周期管理：明确上新汰旧策略，建立并运营商品全生命周期管理标准化流程；\n2、流程优化及效率提升：牵头商品相关领域的基础信息建设及产品系统迭代，确保经营链路有更高的组织效能和决策质量，提升资源转化效率；\n3、项目管理与效能提升：主导跨部门协作，全程监控项目进展，复盘总结活动成效，推动策略、产品和业务流程的持续改进。\n视角：既能从宏观视角了解行业，也可以从中观视角了解品类发展，策略与业务紧密结合。\n\n岗位基本要求\n1、工作经验：具备5年及以上电商、零售或品牌商品运营经验，具备品类规划能力，熟悉生鲜、快消等行业特性及用户需求，有海外（中东地区）运营经验者优先；\n2、数据分析与策略：出色的数据分析能力，熟练使用BA工具，能独立完成经营分析及策略制定，能结合数据优化商品结构，提升转化率；\n3、战略思维与落地：具备体系化思维，能制定长期品类策略；同时具备优秀的跨部门协调能力，能高效整合资源，推动复杂项目落地，对经营结果负责；\n4、逻辑与沉淀：逻辑清晰，具备方法论沉淀能力，擅长复盘总结并输出标准化文档；\n5、有海外市场商品开发或跨境零售经验者优先；英语可作为工作语言者优先。\n\n具备以下条件优先\n英语流利\n\n岗位亮点\n1. 国际视野与0-1建设：国际化业务视角，参与项目的从0-1搭建，在高速发展的业务中得到综合的能力锻炼和培养，个人发展空间巨大；\n2. 宏观与中观视角：既能从宏观视角了解行业，也可以从中观视角了解品类发展，策略与业务紧密结合。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4567076867","sourceKey":"meituan_social","company":"美团","title":"活动运营负责人","city":"利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4567076867&jobShareType=1","duty":"1.根据业务需求及运营方向，结合当地市场实际情况，制定站内营销活动的全局策略;\n2.根据营销活动所需的人才画像，进行本地营销活动团队的搭建及选用育励汰；\n3.高效协同市场、B端、配送、产品等部门，推进营销活动的效果增长与运营效率提升;\n4.组织团队探索适配本地市场的创新活动玩法，推动相关营销产品工具的功能更新与迭代；\n5.组织团队进行营销活动的效果跟踪和分析迭代，沉淀营销活动价值评价体系。","requirements":"1.有互联网相关行业背景，至少6年以上活动运营/用户运营/市场营销相关经验，3年以上团队管理经验；\n2.熟悉各类互联网营销活动策略及玩法；\n3.具备较强的逻辑思维能力、框架思考能力，能够有条理地呈现工作产出；\n4.具有团队合作意识，具备项目管理和风险把控能力，善于协同推进，可有效地进行跨部门沟通合作。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1.根据业务需求及运营方向，结合当地市场实际情况，制定站内营销活动的全局策略;\n2.根据营销活动所需的人才画像，进行本地营销活动团队的搭建及选用育励汰；\n3.高效协同市场、B端、配送、产品等部门，推进营销活动的效果增长与运营效率提升;\n4.组织团队探索适配本地市场的创新活动玩法，推动相关营销产品工具的功能更新与迭代；\n5.组织团队进行营销活动的效果跟踪和分析迭代，沉淀营销活动价值评价体系。\n\n岗位基本要求\n1.有互联网相关行业背景，至少6年以上活动运营/用户运营/市场营销相关经验，3年以上团队管理经验；\n2.熟悉各类互联网营销活动策略及玩法；\n3.具备较强的逻辑思维能力、框架思考能力，能够有条理地呈现工作产出；\n4.具有团队合作意识，具备项目管理和风险把控能力，善于协同推进，可有效地进行跨部门沟通合作。\n\n具备以下条件优先\n1.英语可作为工作语言；\n2.有海外工作、生活背景。\n\n岗位亮点\n1.创新业务的操盘手，挑战与机会并存；\n2.能够全方位了解外卖业务模式，有足够的空间和灵活度全面发挥你的才能；\n3.核心业务的核心部门，团队气氛好，学习成长型团队。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4712051665","sourceKey":"meituan_social","company":"美团","title":"PMO项目管理（AI研发效能方向）","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4712051665&jobShareType=1","duty":"1. 大模型生产体系建设与运营： 深入理解大模型从数据、训练、评测、实验迭代到交付上线的完整生产链路，推动关键流程高效运转并解决跨环节协作问题。通过机制设计与数据分析识别生产瓶颈，持续提升模型研发的规模化交付能力；\n2. 研发效能度量与改进： 建设覆盖算力资源利用率、实验吞吐、任务交付周期等核心指标的研发效能体系，以数据看板和专题分析形成生产洞察。推动资源配置、研发流程和协作机制的持续优化；\n3. 研发知识体系建设： 负责实验记录、技术文档、决策过程和最佳实践等信息建设，提升研发信息的结构化、可追溯性与可复用性。推动知识从分散沉淀走向组织级共享，并为智能化应用提供高质量知识底座；\n4. 生产流程智能化建设： 识别大模型生产过程中高频、重复和依赖人工判断的环节，推动流程自动化与Agent化。负责生产效能Agent的设计和持续迭代，使其逐步具备任务追踪、异常识别、风险预警和决策辅助能力。","requirements":"1. 本科及以上学历，具备3年以上AI技术领域（如大模型、机器学习、算法研发）的研发运营经验；\n2. 具备良好的数据敏感度、数据分析能力和可视化呈现能力，能用数据论证观点；\n3. 具备出色的流程分析和问题拆解能力，能够从复杂的现象中定位核心问题；\n4. 对AI技术有好奇心、对工作有自驱性，注重细节，有强烈的责任心和积极主动的态度。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 大模型生产体系建设与运营： 深入理解大模型从数据、训练、评测、实验迭代到交付上线的完整生产链路，推动关键流程高效运转并解决跨环节协作问题。通过机制设计与数据分析识别生产瓶颈，持续提升模型研发的规模化交付能力；\n2. 研发效能度量与改进： 建设覆盖算力资源利用率、实验吞吐、任务交付周期等核心指标的研发效能体系，以数据看板和专题分析形成生产洞察。推动资源配置、研发流程和协作机制的持续优化；\n3. 研发知识体系建设： 负责实验记录、技术文档、决策过程和最佳实践等信息建设，提升研发信息的结构化、可追溯性与可复用性。推动知识从分散沉淀走向组织级共享，并为智能化应用提供高质量知识底座；\n4. 生产流程智能化建设： 识别大模型生产过程中高频、重复和依赖人工判断的环节，推动流程自动化与Agent化。负责生产效能Agent的设计和持续迭代，使其逐步具备任务追踪、异常识别、风险预警和决策辅助能力。\n\n岗位基本要求\n1. 本科及以上学历，具备3年以上AI技术领域（如大模型、机器学习、算法研发）的研发运营经验；\n2. 具备良好的数据敏感度、数据分析能力和可视化呈现能力，能用数据论证观点；\n3. 具备出色的流程分析和问题拆解能力，能够从复杂的现象中定位核心问题；\n4. 对AI技术有好奇心、对工作有自驱性，注重细节，有强烈的责任心和积极主动的态度。\n\n具备以下条件优先\n1. 人工智能、云计算、机器学习、GPU资源管理等相关技术背景；\n2. 具备良好的跨团队沟通、协调能力，能够适应灵活快速的工作模式；\n3. 英语可作为工作语言。\n\n岗位亮点\n1. 获得在业内最前沿的大模型训练全链路工作认知积累；\n2. 统筹公司级重点项目的研发效率运营，成长空间大；\n3. 团队合作氛围好，客观理性、实事求是，以结果为导向。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4500705180","sourceKey":"meituan_social","company":"美团","title":"小象超市-服务站分区经理-西安","city":"西安市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4500705180&jobShareType=1","duty":"1.负责多门店的管理工作，配合总部各项营运策略和专项的实施，推动解决门店所遇到的异常问题；\n2.进行日常营运管理工作，包含对各项运营指标进行监控和分析，确保达成公司要求的业绩指标；\n3.组织开展区域门店日、月、季度的营运工作进度复盘、效率优化和风险治理；\n4.参与监督进行日常损耗管理和设备运营维护工作；\n5.能够统筹新开门店开业前期筹备相关工作；\n6.对区域内人员的招聘，日常培训和人效管理工作。","requirements":"1.五年以上连锁门店/单体大店独立营运管理经验，熟悉新零售优先；\n2.对生鲜商品有一定的认知，熟悉门店运营管理、业务损耗管控、仓储品类管理等；\n3.良好的沟通能力及跨部门团队合作精神，学习能力佳，责任心强，愿意接受挑战，以结果为导向；\n4.善于劳务人员的管理工作，熟悉与零售相关的法律法规；\n5.熟练操作办公软件及智能设备，热爱互联网行业。\n6.掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责多门店的管理工作，配合总部各项营运策略和专项的实施，推动解决门店所遇到的异常问题；\n2.进行日常营运管理工作，包含对各项运营指标进行监控和分析，确保达成公司要求的业绩指标；\n3.组织开展区域门店日、月、季度的营运工作进度复盘、效率优化和风险治理；\n4.参与监督进行日常损耗管理和设备运营维护工作；\n5.能够统筹新开门店开业前期筹备相关工作；\n6.对区域内人员的招聘，日常培训和人效管理工作。\n\n岗位基本要求\n1.五年以上连锁门店/单体大店独立营运管理经验，熟悉新零售优先；\n2.对生鲜商品有一定的认知，熟悉门店运营管理、业务损耗管控、仓储品类管理等；\n3.良好的沟通能力及跨部门团队合作精神，学习能力佳，责任心强，愿意接受挑战，以结果为导向；\n4.善于劳务人员的管理工作，熟悉与零售相关的法律法规；\n5.熟练操作办公软件及智能设备，热爱互联网行业。\n6.掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位亮点\n即时零售前置仓头部企业营运核心岗位，与互联网大咖及零售业专家共同发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4598757679","sourceKey":"meituan_social","company":"美团","title":"无人车-资产维修主管","city":"杭州市/宁波市/温州市/济南市/青岛市/临沂市/深圳市/东莞市/佛山市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4598757679&jobShareType=1","duty":"1.负责团队人员排班考勤管理，保障团队所有成员分工合理，团队目标一致；\n2.针对维修技工的日常工作规范进行监督，并提出有效的改善措施；\n3.根据培训计划，完成对维修技工维修操作及维护保养的培训；\n4.针对组内各项服务指标进行管控，确保数据指标有效达成；\n5.负责设备维护保养，规范使用，技工设备的管理及迭代；\n6.在维修实施及工具设备使用过程中，发现潜在问题，提出改进方案；\n7.维护服务机制，对工作中的协同机制进行对齐并不断完善；\n8.探索和运用AI工具辅助维修问题诊断及工作处置。","requirements":"1.以往工作具备3年以上汽车售后维修一线管理经验：\n2.能够以客户为中心，具备正直诚信的价值观；\n3.学习能力强，乐于接受新事物并善于钻研，有使用AI工具提效个人或团队工作的经验和想法；\n4.主动积极、有较强的进取心和责任心，有团队协作精神；\n5.沟通能力强，能够很好的跨部门沟通协作;\n6.适应能力强，能够适应工作中的节奏和变化；\n7.有一定的结构化思考能力，逻辑清晰，较强的分析、归纳、总结能力；\n8. 本科及以上学历；","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1.负责团队人员排班考勤管理，保障团队所有成员分工合理，团队目标一致；\n2.针对维修技工的日常工作规范进行监督，并提出有效的改善措施；\n3.根据培训计划，完成对维修技工维修操作及维护保养的培训；\n4.针对组内各项服务指标进行管控，确保数据指标有效达成；\n5.负责设备维护保养，规范使用，技工设备的管理及迭代；\n6.在维修实施及工具设备使用过程中，发现潜在问题，提出改进方案；\n7.维护服务机制，对工作中的协同机制进行对齐并不断完善；\n8.探索和运用AI工具辅助维修问题诊断及工作处置。\n\n岗位基本要求\n1.以往工作具备3年以上汽车售后维修一线管理经验：\n2.能够以客户为中心，具备正直诚信的价值观；\n3.学习能力强，乐于接受新事物并善于钻研，有使用AI工具提效个人或团队工作的经验和想法；\n4.主动积极、有较强的进取心和责任心，有团队协作精神；\n5.沟通能力强，能够很好的跨部门沟通协作;\n6.适应能力强，能够适应工作中的节奏和变化；\n7.有一定的结构化思考能力，逻辑清晰，较强的分析、归纳、总结能力；\n8. 本科及以上学历；\n\n具备以下条件优先\n1.汽车机械自动化或汽车检测与维修专业;\n2.具备新能源或自动车维修业务管理经验;\n3.具备PMP项目管理认证;\n\n岗位亮点\n国内知名互联网头部平台，福利完善，晋升机制清晰。智能化自动车业务发展前景可期，期待有志之才加入一同见证。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4724788178","sourceKey":"meituan_social","company":"美团","title":"反洗钱策略专家","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4724788178&jobShareType=1","duty":"1. 具备较好的风控思维，擅长设计多样化风控策略，以完成可疑监测策略的迭代优化，包括不限于类罪、团伙、异常可疑等； \n2. 能根据公司业务和风险管理的变化，设计和优化反洗钱风险策略、流程并监控分析相关风险指标的变化； \n3、迭代优化客户风险评级模，按时完成客户风险等级评估工作； \n4. 管理反洗钱监控名单，包括各类名单的更新和维护、交易监测以及回溯审查等； \n5.与模型、数据分析、安监、合规等团队配合，推进反洗钱系统和反洗钱风险管理体系的建设和持续完善；\n6. 利用AI工具进行风险识别、策略分析和数据分析，提升工作效率和运营效能。","requirements":"基本要求：\n1. 熟悉国内反洗钱法律、法规、合规政策，有国际反洗钱法律法规经验者优先考虑；\n2. 大学本科以上学历，统计、数学、审计、金融、法律、经济类相关专业优先； \n3. 需银行或第三方支付机构3年以上反洗钱或相关工作经验； \n4. 熟练使用常用的办公软件、sql等，至少熟悉python或R中的一种，具有较强的数据分析和逻辑思维能力； \n5. 责任心强，做事认真、仔细，具有良好的沟通协调能力和团队合作精神。\n7. 熟练使用AI工具，有利用AI进行风险识别、策略分析和提效的经验。","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n1. 具备较好的风控思维，擅长设计多样化风控策略，以完成可疑监测策略的迭代优化，包括不限于类罪、团伙、异常可疑等； \n2. 能根据公司业务和风险管理的变化，设计和优化反洗钱风险策略、流程并监控分析相关风险指标的变化； \n3、迭代优化客户风险评级模，按时完成客户风险等级评估工作； \n4. 管理反洗钱监控名单，包括各类名单的更新和维护、交易监测以及回溯审查等； \n5.与模型、数据分析、安监、合规等团队配合，推进反洗钱系统和反洗钱风险管理体系的建设和持续完善；\n6. 利用AI工具进行风险识别、策略分析和数据分析，提升工作效率和运营效能。\n\n岗位基本要求\n基本要求：\n1. 熟悉国内反洗钱法律、法规、合规政策，有国际反洗钱法律法规经验者优先考虑；\n2. 大学本科以上学历，统计、数学、审计、金融、法律、经济类相关专业优先； \n3. 需银行或第三方支付机构3年以上反洗钱或相关工作经验； \n4. 熟练使用常用的办公软件、sql等，至少熟悉python或R中的一种，具有较强的数据分析和逻辑思维能力； \n5. 责任心强，做事认真、仔细，具有良好的沟通协调能力和团队合作精神。\n7. 熟练使用AI工具，有利用AI进行风险识别、策略分析和提效的经验。\n\n岗位亮点\n业务范围广，更广泛的接触反洗钱多领域， 个人能力发展前景好。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4729681390","sourceKey":"meituan_social","company":"美团","title":"高端招聘专家（技术方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4729681390&jobShareType=1","duty":"1.深度运营技术（含AI/自动驾驶/具身/搜推广等方向）领域高阶人才，建立并维护高质量人脉网络，持续跟踪核心人选的职业动态和意向变化，把握人才引入合适时机\n\n2.系统Mapping互联网/科技行业不同技术方向的高阶人才分布，掌握关键公司的组织架构、人才梯队和流动趋势\n\n3.为公司技术研发团队高阶岗位设置、人才引入策略等决策提供信息输入和专业判断，与用人部门、业务HR紧密协同\n\n4.主动寻访并独立完成高管及核心高级技术岗位招聘闭环，重点覆盖AI/Agent、算法、架构、数据平台等方向","requirements":"1.结果导向，能在不确定性中持续推进，有韧性\n\n2.沟通表达清晰，能面向业务负责人输出有价值的人才判断，能梳理出市场上的人才流动趋势\n\n3.有独立运营高阶候选人关系的能力，擅长与VP/SVP级别人选建立信任和长期连接\n\n4.有技术岗位招聘或猎头经验，熟悉互联网/科技行业人才市场\n\n5.能运用AI工具提升招聘工作效率，优化招聘寻访、面试、offer等的工作流","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n1.深度运营技术（含AI/自动驾驶/具身/搜推广等方向）领域高阶人才，建立并维护高质量人脉网络，持续跟踪核心人选的职业动态和意向变化，把握人才引入合适时机\n\n2.系统Mapping互联网/科技行业不同技术方向的高阶人才分布，掌握关键公司的组织架构、人才梯队和流动趋势\n\n3.为公司技术研发团队高阶岗位设置、人才引入策略等决策提供信息输入和专业判断，与用人部门、业务HR紧密协同\n\n4.主动寻访并独立完成高管及核心高级技术岗位招聘闭环，重点覆盖AI/Agent、算法、架构、数据平台等方向\n\n岗位基本要求\n1.结果导向，能在不确定性中持续推进，有韧性\n\n2.沟通表达清晰，能面向业务负责人输出有价值的人才判断，能梳理出市场上的人才流动趋势\n\n3.有独立运营高阶候选人关系的能力，擅长与VP/SVP级别人选建立信任和长期连接\n\n4.有技术岗位招聘或猎头经验，熟悉互联网/科技行业人才市场\n\n5.能运用AI工具提升招聘工作效率，优化招聘寻访、面试、offer等的工作流\n\n岗位亮点\n1.战略级人才影响力：直接参与公司核心技术岗位的人才引入决策，你的判断将影响技术团队的关键人才布局，不是执行者，而是人才策略的共同制定者\n\n2.前沿技术圈层触达：日常工作深度接触 AI/Agent、算法架构、数据平台等领域头部人才，持续积累高质量行业人脉，个人专业壁垒随时间持续加厚\n\n3.AI 赋能的工作方式：团队鼓励并实践 AI 工具在招聘全流程的深度应用，不是传统 HR 的重复劳动，而是用技术手段做高价值的人才洞察与关系经营","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4698597597","sourceKey":"meituan_social","company":"美团","title":"品类运营负责人","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4698597597&jobShareType=1","duty":"1.负责3R行业类目的运营，制定内部的品类规划，整合平台和商家资源，用优选商品服务好消费者，实现行业GMV的健康增长；\n2.负责洞察品类的发展趋势和用户需求，不断完善品类结构和丰富度，制定各区域各品类运营商品池，并对其进行分层定位管理；\n3.负责行业基础运营体系的完善和优化，对接内部多部门，实现新工具新玩法新营销的衔接落地，包括行业品类营销活动策划及推进；\n4.充分了解行业的专业知识，关注前沿发展和市场变化，定期分析行业情况，开展商户和用户调研，寻找市场机会点，成为行业运营专家；探索品类创新业务运营模式，MVP探索到规模化覆盖。\n5.负责团队搭建，团队成长，明确成员分工、流程梳理，绩效沟通，人员培养和团队激励政策等。","requirements":"1.熟悉电商商品营运营，有团队的管理和操盘经验，其中品类运营管理不低于8年；\n2.有较强逻辑思维和洞察力，深刻理解商品，在商超零售、平台商品运营管理经验者优先\n3.善于学习，对新零售变革有充分的理解和见解，对互联网思考和数据赋能有深刻体感；\n4.快速的学习能力，清晰的沟通表达与协同推动解决问题的能力，团队合作意识好，执行力强，积极应对挫折和挑战的心理素质，有韧性，乐观，聪明。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1.负责3R行业类目的运营，制定内部的品类规划，整合平台和商家资源，用优选商品服务好消费者，实现行业GMV的健康增长；\n2.负责洞察品类的发展趋势和用户需求，不断完善品类结构和丰富度，制定各区域各品类运营商品池，并对其进行分层定位管理；\n3.负责行业基础运营体系的完善和优化，对接内部多部门，实现新工具新玩法新营销的衔接落地，包括行业品类营销活动策划及推进；\n4.充分了解行业的专业知识，关注前沿发展和市场变化，定期分析行业情况，开展商户和用户调研，寻找市场机会点，成为行业运营专家；探索品类创新业务运营模式，MVP探索到规模化覆盖。\n5.负责团队搭建，团队成长，明确成员分工、流程梳理，绩效沟通，人员培养和团队激励政策等。\n\n岗位基本要求\n1.熟悉电商商品营运营，有团队的管理和操盘经验，其中品类运营管理不低于8年；\n2.有较强逻辑思维和洞察力，深刻理解商品，在商超零售、平台商品运营管理经验者优先\n3.善于学习，对新零售变革有充分的理解和见解，对互联网思考和数据赋能有深刻体感；\n4.快速的学习能力，清晰的沟通表达与协同推动解决问题的能力，团队合作意识好，执行力强，积极应对挫折和挑战的心理素质，有韧性，乐观，聪明。\n\n岗位亮点\n核心业务，核心部门，带团队，高成长性，综合能力提升。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4720869401","sourceKey":"meituan_social","company":"美团","title":"拼好饭-新供给二组-菜品研发","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4720869401&jobShareType=1","duty":"1. 负责拼好饭新供给方向咖啡饮品研发的整体规划与执行，结合市场需求与用户反馈，设计符合平台定位的创新饮品。  \n2. 协同供应链、采购及生产团队，推动饮品从概念到量产的全流程落地，确保品质与成本可控。  \n3. 分析餐饮行业趋势与动态，持续优化菜品结构，提升供给竞争力与用户满意度。  \n4. 建立并完善饮品研发标准与流程，推动跨部门协作机制，提升研发效率与标准化水平。\n5. 协助梳理门店动线，帮助协同团队实现门店制作操作流程效率最大化。","requirements":"1. 大学专科及以上学历，饮品研发、食品科学、营养学、制作工艺或相关专业优先。  \n2. 具备3年以上饮品或快消品行业饮品研发经验，有连锁餐饮或外卖平台背景者优先。  \n3. 熟悉原料特性、加工工艺及食品安全规范，具备较强的产品创新与项目管理能力。  \n4. 具备良好的数据分析能力与跨团队沟通协作能力，能承受一定工作压力。","description":"部门介绍\n美团外卖秉承“帮大家吃得更好，生活更好”的使命，始终聚焦于消费者用餐需求。我们通过科技连接消费者和商家，依托庞大的骑手团队，以“线上+线下”的业务模式，为消费者提供品质化、精细化、多样化的餐饮外卖服务。\n外卖事业部是为用户与商家提供全链路交易服务的业务组织，围绕餐饮外卖搭建了包含外卖业务与创新孵化业务在内的多个部门。\n我们的目标是帮助商家开源增收、提高经营效率，促进餐饮行业数字化，以及为更多用户提供更便捷更有品质的外卖服务。加入我们，一起为上亿用户提供更好的用餐体验，帮助大家吃得更好，生活更好！\n\n岗位职责\n1. 负责拼好饭新供给方向咖啡饮品研发的整体规划与执行，结合市场需求与用户反馈，设计符合平台定位的创新饮品。  \n2. 协同供应链、采购及生产团队，推动饮品从概念到量产的全流程落地，确保品质与成本可控。  \n3. 分析餐饮行业趋势与动态，持续优化菜品结构，提升供给竞争力与用户满意度。  \n4. 建立并完善饮品研发标准与流程，推动跨部门协作机制，提升研发效率与标准化水平。\n5. 协助梳理门店动线，帮助协同团队实现门店制作操作流程效率最大化。\n\n岗位基本要求\n1. 大学专科及以上学历，饮品研发、食品科学、营养学、制作工艺或相关专业优先。  \n2. 具备3年以上饮品或快消品行业饮品研发经验，有连锁餐饮或外卖平台背景者优先。  \n3. 熟悉原料特性、加工工艺及食品安全规范，具备较强的产品创新与项目管理能力。  \n4. 具备良好的数据分析能力与跨团队沟通协作能力，能承受一定工作压力。\n\n岗位亮点\n1. 参与新业务拓展，直接影响平台供给策略与用户增长。  \n2. 与行业头部供应链资源深度合作，积累端到端产品经验。  \n3. 扁平化管理，创新氛围浓厚，个人成长空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4615758536","sourceKey":"meituan_social","company":"美团","title":"商业广告商家运营（医美行业）","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4615758536&jobShareType=1","duty":"1.广告运营策略体系搭建：基于商家分层和品类分层，设计差异化的广告产品组合、定价策略和投放方案；\n\n2.商家广告效果优化：深入商家细分场景，结合AI智能诊断工具，输出可落地的广告优化方案，提升商家广告ROI；\n\n3.广告产品与玩法创新：探索适合医美行业的广告新玩法，通过产品创新带动主力类目增长和潜力类目培育；\n\n4.销售协同与商家管理：联动销售团队，推动广告策略在商家侧的落地执行，建立商家广告运营的数据反馈闭环。","requirements":"1.5年以上互联网广告运营经验，有平台广告运营经验，熟悉竞价广告/全站广告等不同产品线索广告投放机制；\n\n2.具备「行业及商家视角」——对不同分层分类客户能提供不同的解决方案，站在行业和商家角度思考广告投放的价值；\n\n3.有医美行业/医疗健康行业广告或线索行业广告运营经验者优先；\n\n4.数据分析+策略输出能力：能从广告数据中发现规律，输出清晰可执行的策略建议，并推进产品优化和创新；\n\n5.希望能具备政策敏感度、用户信任构建能力和全链路策略设计能力。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1.广告运营策略体系搭建：基于商家分层和品类分层，设计差异化的广告产品组合、定价策略和投放方案；\n\n2.商家广告效果优化：深入商家细分场景，结合AI智能诊断工具，输出可落地的广告优化方案，提升商家广告ROI；\n\n3.广告产品与玩法创新：探索适合医美行业的广告新玩法，通过产品创新带动主力类目增长和潜力类目培育；\n\n4.销售协同与商家管理：联动销售团队，推动广告策略在商家侧的落地执行，建立商家广告运营的数据反馈闭环。\n\n岗位基本要求\n1.5年以上互联网广告运营经验，有平台广告运营经验，熟悉竞价广告/全站广告等不同产品线索广告投放机制；\n\n2.具备「行业及商家视角」——对不同分层分类客户能提供不同的解决方案，站在行业和商家角度思考广告投放的价值；\n\n3.有医美行业/医疗健康行业广告或线索行业广告运营经验者优先；\n\n4.数据分析+策略输出能力：能从广告数据中发现规律，输出清晰可执行的策略建议，并推进产品优化和创新；\n\n5.希望能具备政策敏感度、用户信任构建能力和全链路策略设计能力。\n\n岗位亮点\n1. 行业深研：深度了解行业，且有全链路C端到B端的视角运营的机会。站在平台视角纵深行业了解从交易到广告，有机会推进行业变化。\n\n2. 自主创新：有机会主导公司重大项目，从0到1探索新商业模式，深度参与AI应用及有机会创造运营工作新范式。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3057805095","sourceKey":"meituan_social","company":"美团","title":"LongCat - 基座大模型评测分析算法研究员","city":"上海市/北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3057805095&jobShareType=1","duty":"负责围绕AI大模型的模型评测与模型研究工作，具体工作内容包括但不限于：\n1. 深入理解大规模语言模型的模型结构、训练过程以及评测方式，根据模型的训练过程以及评测结果，对大语言模型存在的问题进行研究。\n2. 深入分析模型效果不符合认知的异常，根据具体的异常制定完善的研究策略，通过对比、归纳等方法，产出研究分析结论，探索突破性的优化方案，带来模型效果的迭代和突破。\n3. 构建Data-Centric的数据-训练-评测闭环，探索研究包括但不限于下列方向：大模型数据、模型的Scaling Law，研究数据配比、加入方式与时机等对模型效果的影响。\n4. 追踪大模型方向的前沿进展，积极主动地学习和探索新数据分析、模型训练以及模型评测方法。 \n5. 与各相关部门保持良好沟通，深度参与大模型预训练、SFT、RLHF和评测等阶段，共同推动大模型持续优化。","requirements":"1. 硕士及以上学历，计算机、数学、统计学或相关专业； \n2. 熟悉Java/Python/C++等编程语言，良好的编码习惯和一定的工程能力，对每一行代码负责，具备工匠精神；\n3. 具有较强的算法研究经验与能力，熟练掌握自然语言处理、多模态或大模型相关算法和模型； \n4. 具备良好的综合素质，包括沟通能力、团队合作精神以及较强的应对复杂问题的解决能力。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n负责围绕AI大模型的模型评测与模型研究工作，具体工作内容包括但不限于：\n1. 深入理解大规模语言模型的模型结构、训练过程以及评测方式，根据模型的训练过程以及评测结果，对大语言模型存在的问题进行研究。\n2. 深入分析模型效果不符合认知的异常，根据具体的异常制定完善的研究策略，通过对比、归纳等方法，产出研究分析结论，探索突破性的优化方案，带来模型效果的迭代和突破。\n3. 构建Data-Centric的数据-训练-评测闭环，探索研究包括但不限于下列方向：大模型数据、模型的Scaling Law，研究数据配比、加入方式与时机等对模型效果的影响。\n4. 追踪大模型方向的前沿进展，积极主动地学习和探索新数据分析、模型训练以及模型评测方法。 \n5. 与各相关部门保持良好沟通，深度参与大模型预训练、SFT、RLHF和评测等阶段，共同推动大模型持续优化。\n\n岗位基本要求\n1. 硕士及以上学历，计算机、数学、统计学或相关专业； \n2. 熟悉Java/Python/C++等编程语言，良好的编码习惯和一定的工程能力，对每一行代码负责，具备工匠精神；\n3. 具有较强的算法研究经验与能力，熟练掌握自然语言处理、多模态或大模型相关算法和模型； \n4. 具备良好的综合素质，包括沟通能力、团队合作精神以及较强的应对复杂问题的解决能力。\n\n具备以下条件优先\n1. 在计算机领域顶会(如ICLR、NeurIPS、AAAI、WWW、ACL等）上以一作发表过论文者优先；\n2. 具备从事相关行业人工智能开发、算法研究等相关工作经验者优先； \n3. 对ChatGPT等相关大模型有深入了解或丰富的使用经验者优先；\n\n岗位亮点\n1. 紧跟人工智能行业进展，接触到前沿技术和行业趋势，磨练出对人工智能的独到见解；\n2. 参与AI大模型的训练与评测的全流程，了解从理论到工程实践的全面技能；\n3. 与一流的人工智能团队合作，快速成长，提升自身能力；\n4. 有机会参与公司的创新项目，跨足不同领域，拓宽人工智能技术的应用范围；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4685551360","sourceKey":"meituan_social","company":"美团","title":"华中&华西加工中心仓经理","city":"成都市/西安市/武汉市/长沙市/南昌市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4685551360&jobShareType=1","duty":"1、履约保障：全面统筹加工中心日常运营管理，制定并分解生产计划，确保各环节有序推进、按时交付，保障中心整体产能目标达成。\n2、团队建设：负责团队的选用育励汰，为团队成员的成长和发展负责，建设一直高执行、高标准的一线运营团队。\n3、跨部门协同：建立与横向部门高效的协同关系，推动链路卡点解决，善于形成方法论，推动流程制度建设。\n4、持续改善：建立生产数据监控机制，定期分析关键指标（效率、质量、损耗等），识别瓶颈与异常，持续优化加工工艺与作业流程，提升效率，保障加工品质，提出针对性改进方案，推动持续改善。\n5、项目运营：负责新项目的测试进度、结果分析总结，推动新项目落地。","requirements":"1. 大学本科及以上学历，物流、机械、工业工程、食品等相关专业优先。\n2. 具备5年以上加工制造领域工作经验，有团队管理经验。\n3. 熟悉加工中心运作流程及常用设备，具备较强的现场管理能力。\n4. 具备良好的沟通协调能力和问题解决能力。\n5. 工作地点在华中（武汉市、长沙市、南昌市）或西南（成都市、西安市），能够适应一定强度的现场工作节奏。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、履约保障：全面统筹加工中心日常运营管理，制定并分解生产计划，确保各环节有序推进、按时交付，保障中心整体产能目标达成。\n2、团队建设：负责团队的选用育励汰，为团队成员的成长和发展负责，建设一直高执行、高标准的一线运营团队。\n3、跨部门协同：建立与横向部门高效的协同关系，推动链路卡点解决，善于形成方法论，推动流程制度建设。\n4、持续改善：建立生产数据监控机制，定期分析关键指标（效率、质量、损耗等），识别瓶颈与异常，持续优化加工工艺与作业流程，提升效率，保障加工品质，提出针对性改进方案，推动持续改善。\n5、项目运营：负责新项目的测试进度、结果分析总结，推动新项目落地。\n\n岗位基本要求\n1. 大学本科及以上学历，物流、机械、工业工程、食品等相关专业优先。\n2. 具备5年以上加工制造领域工作经验，有团队管理经验。\n3. 熟悉加工中心运作流程及常用设备，具备较强的现场管理能力。\n4. 具备良好的沟通协调能力和问题解决能力。\n5. 工作地点在华中（武汉市、长沙市、南昌市）或西南（成都市、西安市），能够适应一定强度的现场工作节奏。\n\n具备以下条件优先\n具备生鲜行业的加工中心运营管理经验；\n有HM、PP、DD相关的工作经验；\n\n岗位亮点\n1. 提供具有竞争力的薪酬与完善的福利体系。\n2. 拥有清晰的职业发展路径与内部晋升机会。\n3. 团队氛围积极，注重员工成长与技能提升。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4728518506","sourceKey":"meituan_social","company":"美团","title":"Keeta资深战略专家（中东）","city":"多哈/迪拜/利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4728518506&jobShareType=1","duty":"1. 研究全球头部外卖玩家的业务板块、地理布局、资金实力、策略打法，对全球外卖行业格局和竞争形势形成清晰判断，并基于判断提出有效的发展战略和竞争策略，支持Keeta管理层的资源分配、组织架构、资本运作等重大决策；\n2. 参与Keeta开拓新国家的案头研究、实地调研、战略制定，探索并评估公司战略拓展新区域的可行性及实现路径，结合事实和分析，对特定国家的行业、竞争、运营难度等方面给出客观的判断，以协助Keeta管理层做出决策；\n3. 理解餐饮、外卖行业，洞察行业发展规律，对于相关的即时零售、餐饮SaaS等方向的新机会、新模式保持紧密跟踪，探索并评估战略级新方向的可行性及实现路径，以协助Keeta管理层做出决策、协助业务落地。\n\n1. Research the business segments, geographic distribution, financial strength, and strategic approaches of leading global food delivery companies, forming a clear understanding of the industry and competitive landscape. Based on this analysis, propose effective development and competitive strategies to support management in key decisions such as resource allocation, organizational structure, and major corporate actions.\n2. Conduct desk research, field research, and strategy development for expansion into new markets, evaluating the feasibility of strategic growth in new regions. Provide objective assessments of industry dynamics, competition, and operational challenges in specific countries to assist management in decision-making.\n3. Analyze the restaurant and food delivery industries, identify industry trends, and monitor emerging opportunities in related sectors such as quick commerce and restaurant SaaS. Explore and evaluate the feasibility of new strategic directions to support management in decision-making and business implementation.","requirements":"1. 本科及以上学历，工商管理、金融、会计、经济学等商业相关专业优先；\n2. 4年以上互联网战略分析、战略咨询、投资、投行等相关经验，有餐饮、零售、外卖行业研究经历者优先；\n3. 拥有敏锐的商业嗅觉、结构化思维能力、良好的口头和书面表达能力、自我驱动和独立思考能力、良好的数据分析能力、较成熟的项目管理和团队协作经验；\n4. 英文可以作为工作语言。\n\n1. Bachelor's degree or higher, preferably in Business Administration, Finance, Accounting, Economics, or a related field.\n2. Minimum of four years of relevant experience in internet strategy research, strategic consulting, investment, or investment banking; experience in the restaurant, retail, or food delivery industries is preferred.\n3. Strong business acumen, structured thinking, excellent verbal and written communication skills, self-motivation, independent thinking, data analysis capabilities, and proven project management and teamwork experience.\n4. Must have proficiency in Portuguese; fluency in English is required; fluency in Chinese is a plus.","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. 研究全球头部外卖玩家的业务板块、地理布局、资金实力、策略打法，对全球外卖行业格局和竞争形势形成清晰判断，并基于判断提出有效的发展战略和竞争策略，支持Keeta管理层的资源分配、组织架构、资本运作等重大决策；\n2. 参与Keeta开拓新国家的案头研究、实地调研、战略制定，探索并评估公司战略拓展新区域的可行性及实现路径，结合事实和分析，对特定国家的行业、竞争、运营难度等方面给出客观的判断，以协助Keeta管理层做出决策；\n3. 理解餐饮、外卖行业，洞察行业发展规律，对于相关的即时零售、餐饮SaaS等方向的新机会、新模式保持紧密跟踪，探索并评估战略级新方向的可行性及实现路径，以协助Keeta管理层做出决策、协助业务落地。\n\n1. Research the business segments, geographic distribution, financial strength, and strategic approaches of leading global food delivery companies, forming a clear understanding of the industry and competitive landscape. Based on this analysis, propose effective development and competitive strategies to support management in key decisions such as resource allocation, organizational structure, and major corporate actions.\n2. Conduct desk research, field research, and strategy development for expansion into new markets, evaluating the feasibility of strategic growth in new regions. Provide objective assessments of industry dynamics, competition, and operational challenges in specific countries to assist management in decision-making.\n3. Analyze the restaurant and food delivery industries, identify industry trends, and monitor emerging opportunities in related sectors such as quick commerce and restaurant SaaS. Explore and evaluate the feasibility of new strategic directions to support management in decision-making and business implementation.\n\n岗位基本要求\n1. 本科及以上学历，工商管理、金融、会计、经济学等商业相关专业优先；\n2. 4年以上互联网战略分析、战略咨询、投资、投行等相关经验，有餐饮、零售、外卖行业研究经历者优先；\n3. 拥有敏锐的商业嗅觉、结构化思维能力、良好的口头和书面表达能力、自我驱动和独立思考能力、良好的数据分析能力、较成熟的项目管理和团队协作经验；\n4. 英文可以作为工作语言。\n\n1. Bachelor's degree or higher, preferably in Business Administration, Finance, Accounting, Economics, or a related field.\n2. Minimum of four years of relevant experience in internet strategy research, strategic consulting, investment, or investment banking; experience in the restaurant, retail, or food delivery industries is preferred.\n3. Strong business acumen, structured thinking, excellent verbal and written communication skills, self-motivation, independent thinking, data analysis capabilities, and proven project management and teamwork experience.\n4. Must have proficiency in Portuguese; fluency in English is required; fluency in Chinese is a plus.\n\n具备以下条件优先\n具有阿拉伯语背景；有外卖行业经验\nArabic language background; experience in the food delivery industry\n\n岗位亮点\n1. 加入Keeta参与到境外战略布局的宏伟蓝图中，成为全球外卖行业变革的推动者和业务的顶层设计师；\n2. Keeta业务在快速成长期，深度贴近业务，战略可落地性强，能够及时有效的收到反馈，成长曲线陡峭、成长空间广阔；\n3. 加入一支国际化的团队，与全球精英默契配合、并肩合作，积累出海经验。\nKeeta is the international subsidiary of Meituan, a global giant in the delivery sector, and it's on an ambitious mission: to revolutionize the delivery of food and consumer goods worldwide. Our motto is simple yet powerful: “We help people eat better, live better.” Guided by this principle, we bring innovation and technology to the global stage. With over 1,000 team members around the world, Keeta is in full expansion — and you could be part of this journey!\n\n1. Participate in ambitious international strategic development, contributing to transformative initiatives in the global food delivery industry and playing a key role in shaping business strategy.\n2. Join a rapidly growing business with deep operational expertise, strong strategic execution, and opportunities for immediate impact. The company offers significant growth potential and career advancement.\n3. Collaborate with an international team, working alongside global experts to gain hands-on experience in worldwide expansion.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3939789193","sourceKey":"meituan_social","company":"美团","title":"用户产品运营专家（导购方向）","city":"圣保罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3939789193&jobShareType=1","duty":"1.通过优化首页导购与营销模块设计或者交易链路的完善，提升整体访购率；并结合业务发展阶段调整首页布局，以持续提升运营效率。\n\n2.负责App内各模块（包含但不限于搜推、金刚、频道、站内外触达等）流量资源的动态分配与权重调整，提升转化和用户体验\n\n3.监控流量、转化、GMV等核心指标，推动A/B测试和策略优化\n\n4.联合算法团队推动个性化推荐和流量分发效率提升\n\n5.跨部门协作，保障大促、重点活动流量资源高效配置\n\n6.应对突发流量、资源紧张等场景，制定应急调度方案并推动创新机制落地\n\n7.运用AI工具辅助数据分析、策略文档撰写及方案复盘，持续探索AI在流量运营场景的最佳实践\n\n8.借助AI辅助工具提升A/B测试方案设计与结果解读效率，独立对分析质量和结论负责","requirements":"1.5年以上互联网外卖/电商/平台流量运营经验\n\n2.具备较强数据敏感度、数据分析能力强，思考逻辑性与框架性强\n\n3.较强的项目协调能力，与算法、产品合作推动项目经验\n\n4.有首页/频道流量分配或推荐系统协作经验者优先\n\n5.能熟练使用至少一种AI工具辅助日常工作；具备主动探索新AI能力的意愿，能将AI工具落地到实际业务场景","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1.通过优化首页导购与营销模块设计或者交易链路的完善，提升整体访购率；并结合业务发展阶段调整首页布局，以持续提升运营效率。\n\n2.负责App内各模块（包含但不限于搜推、金刚、频道、站内外触达等）流量资源的动态分配与权重调整，提升转化和用户体验\n\n3.监控流量、转化、GMV等核心指标，推动A/B测试和策略优化\n\n4.联合算法团队推动个性化推荐和流量分发效率提升\n\n5.跨部门协作，保障大促、重点活动流量资源高效配置\n\n6.应对突发流量、资源紧张等场景，制定应急调度方案并推动创新机制落地\n\n7.运用AI工具辅助数据分析、策略文档撰写及方案复盘，持续探索AI在流量运营场景的最佳实践\n\n8.借助AI辅助工具提升A/B测试方案设计与结果解读效率，独立对分析质量和结论负责\n\n岗位基本要求\n1.5年以上互联网外卖/电商/平台流量运营经验\n\n2.具备较强数据敏感度、数据分析能力强，思考逻辑性与框架性强\n\n3.较强的项目协调能力，与算法、产品合作推动项目经验\n\n4.有首页/频道流量分配或推荐系统协作经验者优先\n\n5.能熟练使用至少一种AI工具辅助日常工作；具备主动探索新AI能力的意愿，能将AI工具落地到实际业务场景\n\n具备以下条件优先\n熟练掌握英文，可以进行英文工作对话。\n\n岗位亮点\n在Keeta，有快速发展的业务，有更高更远的国际化视野，\n有丰富的工作和生活体验，有志同道合的伙伴并肩前行，\n你将不仅是见证者，更是参与者、创造者！\n你的每一步努力，都将为 Keeta 添上浓墨重彩的一笔；\n你的每一个梦想，都将在这里生根发芽，绽放光彩！","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4544976208","sourceKey":"meituan_social","company":"美团","title":"快乐猴-区域配送运营经理","city":"天津市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4544976208&jobShareType=1","duty":"1、运力合作与成本管控\n监控运力履约质量，定期评估合作方绩效，推动运力体系持续优化。\n多种运力模式的尝试，提升运力体验与成本水平。\n2、订单调度与运力调配\n根据门店订单量、天气、节假日等因素，动态调整发单策略、运力分配及加价机制。\n实时监控运力供给情况，在运力紧张时实施订单流入速度调控，平衡体验与履约压力。\n3、异常订单处理与售后支持\n跟踪配送异常订单（如超时、遗失、损坏等），协调三方运力及时处理。\n负责客诉问题跟进、理赔申请与赔付协调，维护用户满意度。\n4、应急配送管理与门店协同\n提前与各店长沟通，建立极端场景（如运力短缺、恶劣天气）下的店内人员应急配送机制。\n在无人配送或运力不足时，协调店员完成配送任务，确保订单履约。\n5、数据监控与运营优化\n每日分析区域配送数据（准时率、成本、异常率等），输出运营报表。\n结合业务需求，提出流程优化建议，提升配送效率与用户体验。","requirements":"1、学历与经验\n大专及以上学历，物流管理、供应链、电子商务或相关专业优先。\n至少2年以上配送运营、物流协调或第三方运力管理经验，有商超、新零售或即时配送背景者优先。\n2、核心能力\n具备优秀的谈判与沟通能力，能独立完成供应商合作洽谈。\n较强的数据敏感度和分析能力，熟练使用各类办公软件。\n具备多任务处理与应急协调能力，能在复杂场景下下快速响应并解决问题。\n注重细节，责任心强，具备良好的团队协作意识。\n3、其他要求\n能适应弹性工作安排，应对业务高峰期的调度需求。\n有较强的服务意识与用户思维。\n掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1、运力合作与成本管控\n监控运力履约质量，定期评估合作方绩效，推动运力体系持续优化。\n多种运力模式的尝试，提升运力体验与成本水平。\n2、订单调度与运力调配\n根据门店订单量、天气、节假日等因素，动态调整发单策略、运力分配及加价机制。\n实时监控运力供给情况，在运力紧张时实施订单流入速度调控，平衡体验与履约压力。\n3、异常订单处理与售后支持\n跟踪配送异常订单（如超时、遗失、损坏等），协调三方运力及时处理。\n负责客诉问题跟进、理赔申请与赔付协调，维护用户满意度。\n4、应急配送管理与门店协同\n提前与各店长沟通，建立极端场景（如运力短缺、恶劣天气）下的店内人员应急配送机制。\n在无人配送或运力不足时，协调店员完成配送任务，确保订单履约。\n5、数据监控与运营优化\n每日分析区域配送数据（准时率、成本、异常率等），输出运营报表。\n结合业务需求，提出流程优化建议，提升配送效率与用户体验。\n\n岗位基本要求\n1、学历与经验\n大专及以上学历，物流管理、供应链、电子商务或相关专业优先。\n至少2年以上配送运营、物流协调或第三方运力管理经验，有商超、新零售或即时配送背景者优先。\n2、核心能力\n具备优秀的谈判与沟通能力，能独立完成供应商合作洽谈。\n较强的数据敏感度和分析能力，熟练使用各类办公软件。\n具备多任务处理与应急协调能力，能在复杂场景下下快速响应并解决问题。\n注重细节，责任心强，具备良好的团队协作意识。\n3、其他要求\n能适应弹性工作安排，应对业务高峰期的调度需求。\n有较强的服务意识与用户思维。\n掌握基本的AI工具，使用工具提升工作流程效率。\n\n具备以下条件优先\n熟悉主流三方配送平台（如达达、蜂鸟、美团配送等）运营规则。\n\n有门店协调或线下零售业务支持经验。\n\n具备基础的数据分析工具使用能力。\n\n岗位亮点\n该岗位有非常好的岗位前景，同时能够弹性工作，有机会调换城市工作。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4135188103","sourceKey":"meituan_social","company":"美团","title":"歪马送酒-自有品牌品类运营（啤酒）","city":"北京市/广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4135188103&jobShareType=1","duty":"1.负责歪马送酒自有品牌酒类商品在歪马各渠道内的运营工作，包括但不限于商品定价、售卖方式、流量匹配、渠道政策制定等。\n2.负责制定并执行所负责商品的销售策略和运营计划，达成销售和利润目标。\n3.负责监控市场动态和竞争对手情况，及时调整运营策略以保持竞争力。\n4.负责分析销售数据，了解用户消费倾向，提供相应的市场分析和销售报告，为决策提供参考依据。\n5.负责与横向团队的销售协同工作，推动协同方积极参与自有品牌商品销售提升。","requirements":"1.拥有丰富的商品运营或商家运营经验，熟悉酒类行业者优先考虑。\n2.具备良好的商业敏感度和市场洞察力，能够准确把握市场需求和商机。\n3.具备优秀的沟通和协同能力，能够与各协同方进行有效的合作和沟通。\n4.具备较强的数据分析能力，能够对销售数据进行深入分析和挖掘。\n5.工作细致认真，有良好的执行力和责任心。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.负责歪马送酒自有品牌酒类商品在歪马各渠道内的运营工作，包括但不限于商品定价、售卖方式、流量匹配、渠道政策制定等。\n2.负责制定并执行所负责商品的销售策略和运营计划，达成销售和利润目标。\n3.负责监控市场动态和竞争对手情况，及时调整运营策略以保持竞争力。\n4.负责分析销售数据，了解用户消费倾向，提供相应的市场分析和销售报告，为决策提供参考依据。\n5.负责与横向团队的销售协同工作，推动协同方积极参与自有品牌商品销售提升。\n\n岗位基本要求\n1.拥有丰富的商品运营或商家运营经验，熟悉酒类行业者优先考虑。\n2.具备良好的商业敏感度和市场洞察力，能够准确把握市场需求和商机。\n3.具备优秀的沟通和协同能力，能够与各协同方进行有效的合作和沟通。\n4.具备较强的数据分析能力，能够对销售数据进行深入分析和挖掘。\n5.工作细致认真，有良好的执行力和责任心。\n\n岗位亮点\n1.作为歪马送酒自有品牌的商家及供给运营经理，可以参与品牌的塑造和发展，具备较大的发展空间和挑战性。\n2.可以与供应商、商家等各方建立广泛的合作关系，拓展人脉资源。\n3.可以通过分析销售数据和市场情况，为决策提供重要依据，参与企业战略规划和决策。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4697972015","sourceKey":"meituan_social","company":"美团","title":"小象超市 - 品类规划策略专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4697972015&jobShareType=1","duty":"1. 品类策略制定：负责小象超市餐饮相关的选品策略与品类结构优化，提升品类竞争力与用户渗透率；\n\n2. 用户需求洞察：深入分析目标用户群体的消费行为与需求变化，挖掘高潜力品类与爆款机会，驱动品类增长；\n\n3. 商品结构优化：定期评估品类销售表现，制定商品汰换、价格策略、库存周转等优化方案，提升品类整体毛利率与动销率；\n\n4. 行业分析与市场调研：持续跟踪行业头部玩家市场动态，研究品类趋势，为选品与定价提供决策支持；\n\n5. 经营工具搭建：搭建商品经营仪表盘，监控销售趋势、品类结构变化、季节性波动等关键指标，基于数据做经营判断与策略调整；\n\n6. 跨部门协同：与运营、市场等部门紧密协作，确保品类策略高效落地，推动业务目标达成。","requirements":"1. 学历经验：本科及以上学历，5年以上零售/电商/快消行业品类规划、选品或商品运营经验，有预制菜或餐饮相关背景优先；\n\n2. 专业能力：具备系统的品类管理方法论，熟悉品类分析工具与数据模型，能独立完成品类诊断与策略输出；\n\n3. 数据敏感度：数据逻辑清晰，能通过销售数据、用户数据等多维度分析发现问题并提出可落地的优化方案；\n\n4. 行业认知：对生鲜零售、预制菜或厨房经济有深入理解，对消费趋势与用户需求有敏锐洞察；\n\n5. 综合素质：沟通协作能力强，具备项目推动力与结果导向，能适应快速变化的业务环境。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 品类策略制定：负责小象超市餐饮相关的选品策略与品类结构优化，提升品类竞争力与用户渗透率；\n\n2. 用户需求洞察：深入分析目标用户群体的消费行为与需求变化，挖掘高潜力品类与爆款机会，驱动品类增长；\n\n3. 商品结构优化：定期评估品类销售表现，制定商品汰换、价格策略、库存周转等优化方案，提升品类整体毛利率与动销率；\n\n4. 行业分析与市场调研：持续跟踪行业头部玩家市场动态，研究品类趋势，为选品与定价提供决策支持；\n\n5. 经营工具搭建：搭建商品经营仪表盘，监控销售趋势、品类结构变化、季节性波动等关键指标，基于数据做经营判断与策略调整；\n\n6. 跨部门协同：与运营、市场等部门紧密协作，确保品类策略高效落地，推动业务目标达成。\n\n岗位基本要求\n1. 学历经验：本科及以上学历，5年以上零售/电商/快消行业品类规划、选品或商品运营经验，有预制菜或餐饮相关背景优先；\n\n2. 专业能力：具备系统的品类管理方法论，熟悉品类分析工具与数据模型，能独立完成品类诊断与策略输出；\n\n3. 数据敏感度：数据逻辑清晰，能通过销售数据、用户数据等多维度分析发现问题并提出可落地的优化方案；\n\n4. 行业认知：对生鲜零售、预制菜或厨房经济有深入理解，对消费趋势与用户需求有敏锐洞察；\n\n5. 综合素质：沟通协作能力强，具备项目推动力与结果导向，能适应快速变化的业务环境。\n\n具备以下条件优先\n具备产品运营、商品运营相关经验优先\n\n岗位亮点\n探索零售行业最前沿业务的第二增长曲线，在解决业务问题的同时，可以充分提升思考深度、认知高度。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4696504617","sourceKey":"meituan_social","company":"美团","title":"小象超市 - 商品运营专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4696504617&jobShareType=1","duty":"1. 商品采购与选品：负责小象超市相关商品的选品与采购决策，搭建有竞争力的商品池\n\n2. 交易业绩负责：对所负责商品的销售额、毛利率等核心指标负责，制定并达成月度/季度/年度交易目标\n\n3. 定价与促销策略：根据市场竞争环境、成本结构与用户需求，制定商品定价策略与促销方案，提升商品动销率与盈利能力\n\n4. 库存管理：监控库存结构，及时处理滞销与缺货问题，确保商品供应稳定\n\n5. 项目管理：拉通采购、运营、品控等跨模块协作，主导从选品、定价、生产到上架销售的全链路项目管理，确保经营目标按期达成\n\n6. 市场分析：跟踪行业趋势与发展动态，挖掘潜力商品与新品机会，为业务决策提供数据支撑","requirements":"1. 学历经验：本科及以上学历，5年以上零售/电商/快消行业采购、采销或商品运营经验，有生鲜或食品相关背景优先\n\n2. 专业能力：熟悉采购全流程管理，具备较强的成本意识与商务谈判能力，能独立完成选品决策\n\n3. 数据驱动：具备较强的数据分析能力，能通过销售数据、库存数据等多维度分析发现问题并推动优化\n\n4. 责任驱动：结果导向强，能扛业绩压力，有明确的目标意识与执行力\n\n5. 行业认知：对生鲜零售、预制菜或厨房经济有一定了解，对市场趋势与用户需求有敏感度\n\n6. 综合素质：沟通协调能力强，具备跨部门协作能力与项目推动力，适应快节奏业务环境","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 商品采购与选品：负责小象超市相关商品的选品与采购决策，搭建有竞争力的商品池\n\n2. 交易业绩负责：对所负责商品的销售额、毛利率等核心指标负责，制定并达成月度/季度/年度交易目标\n\n3. 定价与促销策略：根据市场竞争环境、成本结构与用户需求，制定商品定价策略与促销方案，提升商品动销率与盈利能力\n\n4. 库存管理：监控库存结构，及时处理滞销与缺货问题，确保商品供应稳定\n\n5. 项目管理：拉通采购、运营、品控等跨模块协作，主导从选品、定价、生产到上架销售的全链路项目管理，确保经营目标按期达成\n\n6. 市场分析：跟踪行业趋势与发展动态，挖掘潜力商品与新品机会，为业务决策提供数据支撑\n\n岗位基本要求\n1. 学历经验：本科及以上学历，5年以上零售/电商/快消行业采购、采销或商品运营经验，有生鲜或食品相关背景优先\n\n2. 专业能力：熟悉采购全流程管理，具备较强的成本意识与商务谈判能力，能独立完成选品决策\n\n3. 数据驱动：具备较强的数据分析能力，能通过销售数据、库存数据等多维度分析发现问题并推动优化\n\n4. 责任驱动：结果导向强，能扛业绩压力，有明确的目标意识与执行力\n\n5. 行业认知：对生鲜零售、预制菜或厨房经济有一定了解，对市场趋势与用户需求有敏感度\n\n6. 综合素质：沟通协调能力强，具备跨部门协作能力与项目推动力，适应快节奏业务环境\n\n具备以下条件优先\n具备商品采销、商品运营相关经验优先\n\n岗位亮点\n探索零售行业最前沿业务的第二增长曲线，在解决业务问题的同时，可以充分提升思考深度、认知高度。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4698074187","sourceKey":"meituan_social","company":"美团","title":"小象超市 - 频道运营专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4698074187&jobShareType=1","duty":"1. 频道定位与展销运营：负责小象超市核心频道的日常运营，基于频道定位和经营主张，持续迭代频道展销方案、商品准入准出规则及页面呈现策略，提升频道整体表现；\n\n2. 选品与流量策略制定：制定频道的核心品类选品规则、流量分配策略与促销策略，协同品类规划和商品运营团队，确保频道商品结构健康并达成销售目标；\n\n3. 促销工具与资源管理：完善频道内促销工具的使用规则与投放策略，对钱效和用户体验指标负责，确保营销资源合理配置与用户满意度提升；\n\n4. 数据驱动运营优化：搭建频道级数据看板，持续监控流量、转化、客单价、用户留存等核心运营指标，通过数据分析发现业务机会与问题，输出数据驱动的策略建议并推动迭代优化；\n\n5. 用户增长与活跃提升：围绕频道用户拉新、激活、留存、复购全链路，设计并实施用户运营策略，通过活动运营、内容运营等手段实现用户规模与活跃度的持续提升；\n\n6. 跨部门项目管理：与产品、技术、品类、采购、市场等多部门横向沟通协作，推动频道运营项目落地，确保跨部门资源高效配置并拿到业务成果。","requirements":"1. 学历经验：本科及以上学历，5年以上互联网运营经验，有电商/即时零售/生鲜零售/本地生活背景优先；\n\n2. 频道运营能力：熟悉电商平台频道运营逻辑，具备选品、流量分配、促销策略制定及页面展销优化能力；\n\n3. 数据分析能力：具备扎实的数据分析能力，熟练使用数据分析工具，能够通过数据发现问题、提出假设、验证方案并推动落地；\n\n4. AI工具应用：熟练通过AI辅助提升工作效率，对AI在运营场景的应用有探索精神；\n\n5. 跨部门推动力：具备优秀的沟通协调能力和跨部门项目推动力，自驱力强，结果导向，能从全局视角制定运营解决方案；\n\n6. 综合素质：逻辑思维清晰，具备处理复杂问题的分析能力，有强烈的好奇心和韧性。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 频道定位与展销运营：负责小象超市核心频道的日常运营，基于频道定位和经营主张，持续迭代频道展销方案、商品准入准出规则及页面呈现策略，提升频道整体表现；\n\n2. 选品与流量策略制定：制定频道的核心品类选品规则、流量分配策略与促销策略，协同品类规划和商品运营团队，确保频道商品结构健康并达成销售目标；\n\n3. 促销工具与资源管理：完善频道内促销工具的使用规则与投放策略，对钱效和用户体验指标负责，确保营销资源合理配置与用户满意度提升；\n\n4. 数据驱动运营优化：搭建频道级数据看板，持续监控流量、转化、客单价、用户留存等核心运营指标，通过数据分析发现业务机会与问题，输出数据驱动的策略建议并推动迭代优化；\n\n5. 用户增长与活跃提升：围绕频道用户拉新、激活、留存、复购全链路，设计并实施用户运营策略，通过活动运营、内容运营等手段实现用户规模与活跃度的持续提升；\n\n6. 跨部门项目管理：与产品、技术、品类、采购、市场等多部门横向沟通协作，推动频道运营项目落地，确保跨部门资源高效配置并拿到业务成果。\n\n岗位基本要求\n1. 学历经验：本科及以上学历，5年以上互联网运营经验，有电商/即时零售/生鲜零售/本地生活背景优先；\n\n2. 频道运营能力：熟悉电商平台频道运营逻辑，具备选品、流量分配、促销策略制定及页面展销优化能力；\n\n3. 数据分析能力：具备扎实的数据分析能力，熟练使用数据分析工具，能够通过数据发现问题、提出假设、验证方案并推动落地；\n\n4. AI工具应用：熟练通过AI辅助提升工作效率，对AI在运营场景的应用有探索精神；\n\n5. 跨部门推动力：具备优秀的沟通协调能力和跨部门项目推动力，自驱力强，结果导向，能从全局视角制定运营解决方案；\n\n6. 综合素质：逻辑思维清晰，具备处理复杂问题的分析能力，有强烈的好奇心和韧性。\n\n岗位亮点\n探索零售行业最前沿业务的第二增长曲线，在解决业务问题的同时，可以充分提升思考深度、认知高度。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4689190515","sourceKey":"meituan_social","company":"美团","title":"培训LP","city":"上海市/北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4689190515&jobShareType=1","duty":"1.根据业务部门的业务重点及策略，诊断业务需求，识别重点人群，对齐培训目标，设计针对性的培训培养方案，并完成规划、实施、跟进和检核；\n2.销售专业能力提升类项目的设计、内容开发及运营实施，结合业务模式的转型与升级，能不断地更新销售专业力的培养内核，助力业务更好转型升级；\n3.在培训项目推进中，发现与业务管理动作、人才管理动作的协同点，并形成有序推进的协作模式；\n4.把控各项目实施进展及效果，制定和完善培训考评标准及培训效果评估的跟踪反馈，通过项目复盘，运用多种培训运营形式，不断优化迭代学习项目。\n5.应用agent工具优化现有培训链路，形成skill等工具包促进工作提效。","requirements":"1. 大学本科及以上学历，人力资源管理、心理学、教育学或相关专业优先。  \n2. 5年以上企业培训或人才发展相关工作经验，具备大型项目落地经验。  \n3. 熟悉培训体系搭建、课程开发及学习平台运营，具备较强的课程设计能力。  \n4. 优秀的沟通协调能力与跨部门协作能力，能独立推动项目执行。  \n5. 常驻城市为上海市，能适应阶段性出差。","description":"部门介绍\n核心本地商业（Core Local Commerce）是美团“零售+科技”战略的重要载体，涵盖了到店餐饮、服务零售、酒店旅行、外卖、履约配送、闪购、医药健康等多个业务，覆盖了超过200个消费场景，致力于通过“随时随地”的商品和服务，满足消费者的多样性需求，帮大家吃得更好，生活更好。核心本地商业扎根本地消费，围绕消费者的“吃、住、行、游、购、娱”进行深度创新，引领发展了即时零售、团购等多种消费业态，并在全国范围内广泛投资发展本地供给、履约平台等设施，助力创造产业、带动就业。基于多年的持续投入，核心本地商业打造了连接全国超过一千万中小微企业的服务体系，以及全球最大的即时配送网络。由核心本地商业所推行的30分钟“万物到家”体系，已覆盖全国2800多个城镇，为数亿用户提供优质的商品与服务。发展过程中，核心本地商业有效助力商超、连锁、本地小店等各类实体经济主体扩大交易规模、降低交易成本。截至目前，核心本地商业日均创造订单量数千万笔，助力千万商户实现了高质量发展。未来，核心本地商业将继续践行美团“零售+科技”战略，通过更大的投资，更多的技术创新，支持、培育消费新业态，为促进消费、服务民生、带动就业作出力所能及的贡献。欢迎优秀的你加入核心本地商业，我们携手助力市场繁荣，为用户创造更好的消费体验。\n\n岗位职责\n1.根据业务部门的业务重点及策略，诊断业务需求，识别重点人群，对齐培训目标，设计针对性的培训培养方案，并完成规划、实施、跟进和检核；\n2.销售专业能力提升类项目的设计、内容开发及运营实施，结合业务模式的转型与升级，能不断地更新销售专业力的培养内核，助力业务更好转型升级；\n3.在培训项目推进中，发现与业务管理动作、人才管理动作的协同点，并形成有序推进的协作模式；\n4.把控各项目实施进展及效果，制定和完善培训考评标准及培训效果评估的跟踪反馈，通过项目复盘，运用多种培训运营形式，不断优化迭代学习项目。\n5.应用agent工具优化现有培训链路，形成skill等工具包促进工作提效。\n\n岗位基本要求\n1. 大学本科及以上学历，人力资源管理、心理学、教育学或相关专业优先。  \n2. 5年以上企业培训或人才发展相关工作经验，具备大型项目落地经验。  \n3. 熟悉培训体系搭建、课程开发及学习平台运营，具备较强的课程设计能力。  \n4. 优秀的沟通协调能力与跨部门协作能力，能独立推动项目执行。  \n5. 常驻城市为上海市，能适应阶段性出差。\n\n岗位亮点\n1. 参与业务侧AI转型核心项目，推动组织能力建设与人才能力升级。  \n2. 拥有广阔的职业发展空间，可向培训专家或人才发展负责人方向晋升。  \n3. 公司提供完善的培训资源与学习平台，支持个人专业能力提升。  \n4. 团队氛围开放包容，鼓励创新与持续学习。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4684204088","sourceKey":"meituan_social","company":"美团","title":"乐生活行业产品","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4684204088&jobShareType=1","duty":"1.负责乐生活行业（洗浴、宠物、运动健身等）用户决策信息建设，包括智能采集、治理与调优，运用AI能力实现信息建设的自动化与智能化闭环。\n\n2.设计智能化决策流，监控店铺信息覆盖、质量与用户端价值关系，建立智能化评测体系，持续优化各行业决策信息结构与展示形态。\n\n3.协同联动上下游资源，推动实现优质商户在平台内流量正向循环，助力平台长期深度行业运营。\n\n4.参与信息方向业产研AI新范式，运用catpaw、catdesk等AI工具快速验证MVP，运用AI能力完成部分需求和业务场景自闭环建设。","requirements":"1.本科及以上学历，具备3年以上C端产品经验，本地生活服务、电商或零售行业经验者优先。\n\n2.以用户体验为核心，对需求有敏锐洞察，逻辑清晰、思考缜密，具备优秀的结构化思维和快速学习能力，能抽象思考及归纳。\n\n3.强烈的Builder心态，喜欢动手做东西，不只是写PRD；具备AI Coding的实战经验，能熟练使用AI辅助工具快速验证产品方案。\n\n4.善于跨团队沟通协作，有良好的表达和沟通能力，能协同上下游资源推动项目落地拿到结果；有跨团队推动技术标准化落地经验者优先。\n\n5.有韧性和责任心，对行业有热情，积极主动的心态，能快速学习并在工作中持续寻求突破。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1.负责乐生活行业（洗浴、宠物、运动健身等）用户决策信息建设，包括智能采集、治理与调优，运用AI能力实现信息建设的自动化与智能化闭环。\n\n2.设计智能化决策流，监控店铺信息覆盖、质量与用户端价值关系，建立智能化评测体系，持续优化各行业决策信息结构与展示形态。\n\n3.协同联动上下游资源，推动实现优质商户在平台内流量正向循环，助力平台长期深度行业运营。\n\n4.参与信息方向业产研AI新范式，运用catpaw、catdesk等AI工具快速验证MVP，运用AI能力完成部分需求和业务场景自闭环建设。\n\n岗位基本要求\n1.本科及以上学历，具备3年以上C端产品经验，本地生活服务、电商或零售行业经验者优先。\n\n2.以用户体验为核心，对需求有敏锐洞察，逻辑清晰、思考缜密，具备优秀的结构化思维和快速学习能力，能抽象思考及归纳。\n\n3.强烈的Builder心态，喜欢动手做东西，不只是写PRD；具备AI Coding的实战经验，能熟练使用AI辅助工具快速验证产品方案。\n\n4.善于跨团队沟通协作，有良好的表达和沟通能力，能协同上下游资源推动项目落地拿到结果；有跨团队推动技术标准化落地经验者优先。\n\n5.有韧性和责任心，对行业有热情，积极主动的心态，能快速学习并在工作中持续寻求突破。\n\n具备以下条件优先\n1.对AI/LLM/Agent有深度理解和实操经验，理解大模型基础机制（上下文、幻觉、能力边界），能将模型局限性转化为工程约束设计。\n\n2.评测治理能力：熟悉智能化产品的评估方法论，具备数据标注方案制定、效果评估及模型迭代的闭环管理能力。\n\n3.自动化流程经验：具备设计智能化决策流（Agentic Workflow）或自动化工作流的实操经验，提升复杂业务的自动化率。\n\n岗位亮点\n1.前沿场景：美团海量真实业务 × AI技术的交叉地带，可深入了解服务零售行业，构建广而深的业务领域知识体系。\n\n2.技术资源：内部大模型能力、算力支持、工程团队配合，有机会参与大模型技术在零售领域的前沿应用，积累丰富实战经验。\n\n3.通过工作实践，提升大模型领域综合能力，实现个人能力跃迁；学习型组织，能不断突破成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4705573048","sourceKey":"meituan_social","company":"美团","title":"华北一大区中台","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4705573048&jobShareType=1","duty":"1.负责大区中台相关标准化管理和运营管理工作，承接RDC仓内（商品入库、在库、出库）等环节的标准体系搭建、流程设计及优化，项目推进等工作，持续进行体系优化，对核心指标结果负责；\n2.识别业务关键问题，通过数据分析、策略输出、系统建设、流程设计等，协同一线团队拿到业务结果；\n3.仓储流程进行诊断、分析和优化，对使用的WMS信息系统需要改进优化的功能进行需求调研，推动系统化和数字化建设。\n4.协同上下游部门进行全链路优化，提升业务效率。","requirements":"1.大学本科及以上学历，物流管理、仓储管理或相关专业优先考虑。\n2.具备10年以上物流仓储管理经验，熟悉仓储管理流程和操作规范。\n3.具备良好的团队合作和沟通能力，能够有效协调仓库内外部的工作。\n4.熟悉仓储作业收、存、分、发、逆向流程；\n5.有较强的跨部门沟通能力、压力管理、适应能力；\n6.高度的敬业精神及高涨的工作激情，能接受高强度的工作，工作态度积极乐观，可接受短期出差。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责大区中台相关标准化管理和运营管理工作，承接RDC仓内（商品入库、在库、出库）等环节的标准体系搭建、流程设计及优化，项目推进等工作，持续进行体系优化，对核心指标结果负责；\n2.识别业务关键问题，通过数据分析、策略输出、系统建设、流程设计等，协同一线团队拿到业务结果；\n3.仓储流程进行诊断、分析和优化，对使用的WMS信息系统需要改进优化的功能进行需求调研，推动系统化和数字化建设。\n4.协同上下游部门进行全链路优化，提升业务效率。\n\n岗位基本要求\n1.大学本科及以上学历，物流管理、仓储管理或相关专业优先考虑。\n2.具备10年以上物流仓储管理经验，熟悉仓储管理流程和操作规范。\n3.具备良好的团队合作和沟通能力，能够有效协调仓库内外部的工作。\n4.熟悉仓储作业收、存、分、发、逆向流程；\n5.有较强的跨部门沟通能力、压力管理、适应能力；\n6.高度的敬业精神及高涨的工作激情，能接受高强度的工作，工作态度积极乐观，可接受短期出差。\n\n具备以下条件优先\n有相关超市，物流大型仓储经验者\n\n岗位亮点\n1.全链路视角：深入仓储运营环节，并从最上游的供应端，到贴近消费者的履约端，了解全链路运营及链路协同关系。\n2.构建更宽广的职业发展图景：有机会全身心地参与新零售业态，在急速发展的业务当中建立对业务和产业的认知，综合学习，共同进步。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4706968104","sourceKey":"meituan_social","company":"美团","title":"华北一RDC仓经","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4706968104&jobShareType=1","duty":"负责大仓仓储现场运营管理工作，通过履约能力提升降低仓储运营成本。\n负责仓储商品及生产物资的收、发、存、退、理货补货等基础运营流程及作业流程精益改善，持续推动仓储管理标准化。\n根据仓储运营整体策略，持续提升仓储作业人效，降低件均仓储人力成本，控制到店差异。\n根据货量预测和产能需求，持续优化一线岗位人员配置，合理排班排产，优化员工结构，提升有效工时率，保障产能弹性。\n对质量、效率、成本等关键KPI指标负责，归因分析达成偏差，持续改善。\n根据安全防损要求，落实现场安全与防损管理工作，识别安全风险，保障商品及资材安全。\n负责一线仓储团队建设、人才梯队搭建、人员选用育励汰实施。","requirements":"专科及以上学历，供应链管理、物流管理相关专业优先。\n8年及以上仓储物流运营经验，有同行业单仓管理经验优先。 \n精通入库管理、出库管理、库存管理、员工能力提升、仓储标准化。\n关注细节、有成本意识，对工作热情，善于思考及总结，对仓运营流程熟悉，善于发现问题并优化。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n负责大仓仓储现场运营管理工作，通过履约能力提升降低仓储运营成本。\n负责仓储商品及生产物资的收、发、存、退、理货补货等基础运营流程及作业流程精益改善，持续推动仓储管理标准化。\n根据仓储运营整体策略，持续提升仓储作业人效，降低件均仓储人力成本，控制到店差异。\n根据货量预测和产能需求，持续优化一线岗位人员配置，合理排班排产，优化员工结构，提升有效工时率，保障产能弹性。\n对质量、效率、成本等关键KPI指标负责，归因分析达成偏差，持续改善。\n根据安全防损要求，落实现场安全与防损管理工作，识别安全风险，保障商品及资材安全。\n负责一线仓储团队建设、人才梯队搭建、人员选用育励汰实施。\n\n岗位基本要求\n专科及以上学历，供应链管理、物流管理相关专业优先。\n8年及以上仓储物流运营经验，有同行业单仓管理经验优先。 \n精通入库管理、出库管理、库存管理、员工能力提升、仓储标准化。\n关注细节、有成本意识，对工作热情，善于思考及总结，对仓运营流程熟悉，善于发现问题并优化。\n\n具备以下条件优先\n具有相关大型物流仓储从业者优先\n\n岗位亮点\n美团正编，五险一金，我们有一群来自知名零售，物流公司的伙伴一起成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4712172606","sourceKey":"meituan_social","company":"美团","title":"果蔬加工经理","city":"济南市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4712172606&jobShareType=1","duty":"1、履约保障：全面统筹加工中心日常运营管理，制定并分解生产计划，确保各环节有序推进、按时交付，保障中心整体产能目标达成。\n2、团队建设：负责团队的选用育励汰，为团队成员的成长和发展负责，建设一直高执行、高标准的一线运营团队。\n3、跨部门协同：建立与横向部门高效的协同关系，推动链路卡点解决，善于形成方法论，推动流程制度建设。\n4、持续改善：建立生产数据监控机制，定期分析关键指标（效率、质量、损耗等），识别瓶颈与异常，持续优化加工工艺与作业流程，提升效率，保障加工品质，提出针对性改进方案，推动持续改善。\n5、项目运营：负责新项目的测试进度、结果分析总结，推动新项目落地。","requirements":"1. 大学专科及以上学历，物流、机械、工业工程、食品等相关专业优先。  \n2. 具备5年以上加工制造领域工作经验，有团队管理经验。\n3. 熟悉加工中心运作流程及常用设备，具备较强的现场管理能力。\n4. 具备良好的沟通协调能力和问题解决能力。\n5. 能够适应一定强度的现场工作节奏。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、履约保障：全面统筹加工中心日常运营管理，制定并分解生产计划，确保各环节有序推进、按时交付，保障中心整体产能目标达成。\n2、团队建设：负责团队的选用育励汰，为团队成员的成长和发展负责，建设一直高执行、高标准的一线运营团队。\n3、跨部门协同：建立与横向部门高效的协同关系，推动链路卡点解决，善于形成方法论，推动流程制度建设。\n4、持续改善：建立生产数据监控机制，定期分析关键指标（效率、质量、损耗等），识别瓶颈与异常，持续优化加工工艺与作业流程，提升效率，保障加工品质，提出针对性改进方案，推动持续改善。\n5、项目运营：负责新项目的测试进度、结果分析总结，推动新项目落地。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、机械、工业工程、食品等相关专业优先。  \n2. 具备5年以上加工制造领域工作经验，有团队管理经验。\n3. 熟悉加工中心运作流程及常用设备，具备较强的现场管理能力。\n4. 具备良好的沟通协调能力和问题解决能力。\n5. 能够适应一定强度的现场工作节奏。\n\n具备以下条件优先\n具备生鲜行业的加工中心运营管理经验。\n有HM、PP、DD、MC相关的工作经验。\n\n岗位亮点\n1. 提供具有竞争力的薪酬与完善的福利体系。\n2. 拥有清晰的职业发展路径与内部晋升机会。  \n3. 团队氛围积极，注重员工成长与技能提升。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4717944024","sourceKey":"meituan_social","company":"美团","title":"小象超市-物流城市用工负责人（天津）","city":"天津市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4717944024&jobShareType=1","duty":"1、负责城市招聘目标与需求的达成，并制定对应招聘方向与策略；\n2、深入了解用人部门发展规划与需求，评估需求并提出配置建议； \n3、负责城市招聘团队人员管理，提升城市招聘团队专业能力与效能；\n4、招聘渠道管理与建设，包括渠道的拓展维护，招聘费用管控； \n5、定期与业务部门进行沟通与协作，为招聘提供解决方案；\n6、掌握基本的AI工具，使用工具提升工作流程效率。","requirements":"1、本科以上学历，人力资源管理、心理学专业优先；\n2、3年以上大型企业人力资源招聘工作经验，并能对招聘结果负责；团队管理经验至少1年以上；\n3、有一定的招聘渠道拓展搭建经验及资源；\n4、有互联网、快消零售连锁、物流等大型企业招聘经验优先；\n5、具有优秀的学习能力、主动和开创精神、优秀的文字能力、出色的沟通协调能力；\n6、对AI工具研究和使用经验。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责城市招聘目标与需求的达成，并制定对应招聘方向与策略；\n2、深入了解用人部门发展规划与需求，评估需求并提出配置建议； \n3、负责城市招聘团队人员管理，提升城市招聘团队专业能力与效能；\n4、招聘渠道管理与建设，包括渠道的拓展维护，招聘费用管控； \n5、定期与业务部门进行沟通与协作，为招聘提供解决方案；\n6、掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位基本要求\n1、本科以上学历，人力资源管理、心理学专业优先；\n2、3年以上大型企业人力资源招聘工作经验，并能对招聘结果负责；团队管理经验至少1年以上；\n3、有一定的招聘渠道拓展搭建经验及资源；\n4、有互联网、快消零售连锁、物流等大型企业招聘经验优先；\n5、具有优秀的学习能力、主动和开创精神、优秀的文字能力、出色的沟通协调能力；\n6、对AI工具研究和使用经验。\n\n岗位亮点\n策略落地、全面锻炼自身、从招聘到留存全面参与管理、聚焦单城市成长速度快，前沿AI工具学习与使用。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4711799436","sourceKey":"meituan_social","company":"美团","title":"商家营销产品经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4711799436&jobShareType=1","duty":"1. 搭产品体系：负责商家营销产品体系的规划与建设，围绕商家经营全链路打造可自助使用的增长工具与数据服务；\n\n2. 解商家诉求：深入调研商家在营销与经营中的核心诉求，设计AI驱动的商家增长解决方案，降低使用门槛、提升经营效率；\n\n3. 推能力外化：推动内部增长能力（广告投放、AIGC创意、GEO营销等）向商家侧开放与产品化，让美团商家用上AI增长工具；\n\n4. 拿增长结果：与C端增长团队、算法团队、业务线紧密协作，构建从数据到效果的闭环链路，让营销有结果、让商家能信赖。","requirements":"1. 本科及以上学历，5年以上互联网产品经理经验，有B端/商家侧/平台型产品经验者优先；\n\n2. 对大模型/AI搜索/生成式AI有深入理解，有AI产品落地经验者优先；能独立完成AI场景的需求拆解与方案设计；\n\n3. 优秀的跨团队协作与沟通能力，能在复杂业务场景中推动多方达成共识、拿到结果；\n\n4. 对AI变革充满热情，有强烈的探索欲和自驱力，能在不确定环境中主动定义问题、找到方向。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1. 搭产品体系：负责商家营销产品体系的规划与建设，围绕商家经营全链路打造可自助使用的增长工具与数据服务；\n\n2. 解商家诉求：深入调研商家在营销与经营中的核心诉求，设计AI驱动的商家增长解决方案，降低使用门槛、提升经营效率；\n\n3. 推能力外化：推动内部增长能力（广告投放、AIGC创意、GEO营销等）向商家侧开放与产品化，让美团商家用上AI增长工具；\n\n4. 拿增长结果：与C端增长团队、算法团队、业务线紧密协作，构建从数据到效果的闭环链路，让营销有结果、让商家能信赖。\n\n岗位基本要求\n1. 本科及以上学历，5年以上互联网产品经理经验，有B端/商家侧/平台型产品经验者优先；\n\n2. 对大模型/AI搜索/生成式AI有深入理解，有AI产品落地经验者优先；能独立完成AI场景的需求拆解与方案设计；\n\n3. 优秀的跨团队协作与沟通能力，能在复杂业务场景中推动多方达成共识、拿到结果；\n\n4. 对AI变革充满热情，有强烈的探索欲和自驱力，能在不确定环境中主动定义问题、找到方向。\n\n岗位亮点\n处于AI驱动增长的核心位置，操盘亿级预算的商家营销产品体系，主导GEO等增长新能力向商家侧产品化输出。团队扁平、决策快，能同时积累AI Agent真实落地经验和跨业务线平台架构能力，是AI PM方向中少有的技术深度与商业广度兼备的成长机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4656056702","sourceKey":"meituan_social","company":"美团","title":"工程内控专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4656056702&jobShareType=1","duty":"1.负责公司各业务线营建类工程项目的内控体系建设，牵头编制工程管理底线和检查标准，覆盖选址、设计、招标、施工、验收、交付全链路，输出SOP和checklist；\n2.协助业务线建立自检能力，开展培训交底，指导业务侧人员按要求执行自检并留痕；\n3.组织开展工程飞检和专项检查，对施工质量、合规性及安全管理进行现场核查，输出检查报告并提出管理建议；\n4.跟踪整改落实情况，对未按要求整改或未开展自检的情形收集佐证，支撑绩效考核落地；\n5.管理外包检查团队，统筹飞检排期及点位覆盖，把控检查质量和预算执行；\n6.参与工程风险智控平台的规划与推广，推动系统在业务侧落地，持续迭代检查节点、数据看板等功能。","requirements":"1.本科及以上学历，工程管理、土木工程、工程造价等相关专业，5年以上工程审计或工程内控经验；\n2.有体系搭建经验，能从0到1搭建管控框架和制度流程；\n3.熟悉装修改造、机电安装(强弱电、监控系统、冷库工程等)等施工工艺，具备现场问题识别和判断能力，能独立编制检查方案和检查清单；\n4.具备较强的跨部门沟通和推动能力，能与业务、HR、财务等有效协作；\n5.能适应较高频率出差。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1.负责公司各业务线营建类工程项目的内控体系建设，牵头编制工程管理底线和检查标准，覆盖选址、设计、招标、施工、验收、交付全链路，输出SOP和checklist；\n2.协助业务线建立自检能力，开展培训交底，指导业务侧人员按要求执行自检并留痕；\n3.组织开展工程飞检和专项检查，对施工质量、合规性及安全管理进行现场核查，输出检查报告并提出管理建议；\n4.跟踪整改落实情况，对未按要求整改或未开展自检的情形收集佐证，支撑绩效考核落地；\n5.管理外包检查团队，统筹飞检排期及点位覆盖，把控检查质量和预算执行；\n6.参与工程风险智控平台的规划与推广，推动系统在业务侧落地，持续迭代检查节点、数据看板等功能。\n\n岗位基本要求\n1.本科及以上学历，工程管理、土木工程、工程造价等相关专业，5年以上工程审计或工程内控经验；\n2.有体系搭建经验，能从0到1搭建管控框架和制度流程；\n3.熟悉装修改造、机电安装(强弱电、监控系统、冷库工程等)等施工工艺，具备现场问题识别和判断能力，能独立编制检查方案和检查清单；\n4.具备较强的跨部门沟通和推动能力，能与业务、HR、财务等有效协作；\n5.能适应较高频率出差。\n\n具备以下条件优先\n持有一级建造师、造价工程师等执业资格者优先；具备AI工具应用意识，能将AI辅助工具运用于数据分析、报告撰写及日常工作效率提升，有实际使用经验者优先。\n\n岗位亮点\n1.覆盖公司核心业务线营建类工程板块，业态多元，跨业态经验积累快；\n2.参与工程内控系统的规划与推广，工程+数字化双线发展，成长空间大；\n3.团队积极应用AI工具提升工作效率，鼓励用技术手段解决传统工程管理问题。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4689080232","sourceKey":"meituan_social","company":"美团","title":"招聘经理-快乐猴业务","city":"北京市/杭州市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4689080232&jobShareType=1","duty":"1.制定和执行所负责区域或业务方向的招聘策略，确保招聘效率和质量达到公司要求。\n2.结合AI对岗位进行深度分析，通过有效的招聘实施高效满足用人部门的需求。\n3.通过mapping等方法了解行业内信息，给业务部门行业内信息输入，梳理对应的寻访目标公司，构建人才地图，完善人才储备，提升招聘效率，促进业务发展。","requirements":"1.卓越的招聘交付能力，特别是在零售行业高阶人才招聘经验或前线岗位招聘经验。\n2.熟悉各类招聘渠道和招聘工具，具备较强的数据分析能力。\n4.有深度思考能力和求知好学精神，坚持高标准，对招聘有热情。\n5.在AI工具对招聘工作进行优化和提效方面有成功的案例。","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n1.制定和执行所负责区域或业务方向的招聘策略，确保招聘效率和质量达到公司要求。\n2.结合AI对岗位进行深度分析，通过有效的招聘实施高效满足用人部门的需求。\n3.通过mapping等方法了解行业内信息，给业务部门行业内信息输入，梳理对应的寻访目标公司，构建人才地图，完善人才储备，提升招聘效率，促进业务发展。\n\n岗位基本要求\n1.卓越的招聘交付能力，特别是在零售行业高阶人才招聘经验或前线岗位招聘经验。\n2.熟悉各类招聘渠道和招聘工具，具备较强的数据分析能力。\n4.有深度思考能力和求知好学精神，坚持高标准，对招聘有热情。\n5.在AI工具对招聘工作进行优化和提效方面有成功的案例。\n\n岗位亮点\n加入快速发展的组织，拥有广阔的职业发展空间与晋升机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4719257091","sourceKey":"meituan_social","company":"美团","title":"美团团购-食品生鲜-品类负责人","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4719257091&jobShareType=1","duty":"1. 业务管理：带领团队推进食品生鲜品类连锁品牌与美团在线上经营增长、品牌营销、用户运营等领域的深度商务合作，包括创新项目验证等；能对供给进行有效分层分类，制定不同的供给策略；\n2. 团队管理：团队目标管理， 接收、拆解并向团队成员传达业绩指标同时做好相关解读，能带领团队完成和超越目标，制定团队中长期目标的规划、过程监控和方向指引，负责团队战斗能力提升、文化氛围打造和人才梯队建设；\n3. 项目管理：能够带领团队完成模糊度较高、复杂度高的项目，协同推进跨部门多项目的实施和运作；能充分调用和整合内外部的资源，在团队内外部统筹高效协同；\n4. 复盘沉淀探索：具备长业务链条的复盘能力；能沉淀出切实有效的方法论；通过不断复盘总结寻找更优解，能够有创新业务模式输出，支持效率提升。","requirements":"1. 基本要求：本科及以上学历，5年以上工作经验，2年以上团队管理经验，有大型互联网公司大客户管理经验或者零食生鲜、超市便利连锁企业经验优先；\n2. 专业能力：具备较强的品牌经营思维和定策略的能力，具备大客户维护管理和精益运营能力；\n3. 管理能力：有较强的团队管理能力，善于跨部门沟通和协调资源；\n4. 通用能力：结果导向有韧性，学习能力强，逻辑思维清晰，能够在数据中洞察问题，提出解决方案，善于抓重点，成熟度高。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1. 业务管理：带领团队推进食品生鲜品类连锁品牌与美团在线上经营增长、品牌营销、用户运营等领域的深度商务合作，包括创新项目验证等；能对供给进行有效分层分类，制定不同的供给策略；\n2. 团队管理：团队目标管理， 接收、拆解并向团队成员传达业绩指标同时做好相关解读，能带领团队完成和超越目标，制定团队中长期目标的规划、过程监控和方向指引，负责团队战斗能力提升、文化氛围打造和人才梯队建设；\n3. 项目管理：能够带领团队完成模糊度较高、复杂度高的项目，协同推进跨部门多项目的实施和运作；能充分调用和整合内外部的资源，在团队内外部统筹高效协同；\n4. 复盘沉淀探索：具备长业务链条的复盘能力；能沉淀出切实有效的方法论；通过不断复盘总结寻找更优解，能够有创新业务模式输出，支持效率提升。\n\n岗位基本要求\n1. 基本要求：本科及以上学历，5年以上工作经验，2年以上团队管理经验，有大型互联网公司大客户管理经验或者零食生鲜、超市便利连锁企业经验优先；\n2. 专业能力：具备较强的品牌经营思维和定策略的能力，具备大客户维护管理和精益运营能力；\n3. 管理能力：有较强的团队管理能力，善于跨部门沟通和协调资源；\n4. 通用能力：结果导向有韧性，学习能力强，逻辑思维清晰，能够在数据中洞察问题，提出解决方案，善于抓重点，成熟度高。\n\n岗位亮点\n1. 高速发展的业务机会：进场零售业务（美团到店零售板块）目前处于快速发展期，业务机会大，成长空间足；\n2. 优质客户的合作机会：主要对接食品生鲜核心连锁企业，基于美团生态这些品牌的数字化营销策略与交易增长玩法，切中最集中的品牌经营痛点；\n3. 成熟的职业培养体系：公司提供良好的学习和发展平台，能够不断提升专业能力和职业素养，以及成熟的后续发展路径。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4685778818","sourceKey":"meituan_social","company":"美团","title":"净菜加工主管--深圳","city":"深圳市/广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4685778818&jobShareType=1","duty":"1. 负责PC加工中心的日常运营管理，确保生产计划按时完成。  \n2. 制定并优化加工工艺流程，提升生产效率与产品质量。  \n3. 管理并指导团队，包括人员培训、绩效考核与团队建设。  \n4. 协调仓储、物流与生产部门，保障原材料供应与成品出库顺畅。  \n5. 监控成本与预算执行情况，推动降本增效措施落地。","requirements":"1、大专以上学历，具备生鲜类商品相关知识(蔬果、熟食、水产、海鲜类、肉类、禽类等)，食品类相关专业优先考虑；\n2、5年以上食品制造或生鲜加工行业运营管理的经验，熟悉生鲜生产的作业流程；\n3、具备较强的团队管理能力与跨部门沟通协调能力。  \n4、责任心强，专注细节，勇于持续改善并寻求更好解决方法；\n5、熟悉使用各类电脑办公软件，具备良好的数据分析能力，能熟练操作办公软件；\n6、具备数据分析能力，懂得零售业理论并能正确地落实到工作中。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责PC加工中心的日常运营管理，确保生产计划按时完成。  \n2. 制定并优化加工工艺流程，提升生产效率与产品质量。  \n3. 管理并指导团队，包括人员培训、绩效考核与团队建设。  \n4. 协调仓储、物流与生产部门，保障原材料供应与成品出库顺畅。  \n5. 监控成本与预算执行情况，推动降本增效措施落地。\n\n岗位基本要求\n1、大专以上学历，具备生鲜类商品相关知识(蔬果、熟食、水产、海鲜类、肉类、禽类等)，食品类相关专业优先考虑；\n2、5年以上食品制造或生鲜加工行业运营管理的经验，熟悉生鲜生产的作业流程；\n3、具备较强的团队管理能力与跨部门沟通协调能力。  \n4、责任心强，专注细节，勇于持续改善并寻求更好解决方法；\n5、熟悉使用各类电脑办公软件，具备良好的数据分析能力，能熟练操作办公软件；\n6、具备数据分析能力，懂得零售业理论并能正确地落实到工作中。\n\n具备以下条件优先\n具备中央厨房、净菜、物流经营经验优先。\n\n岗位亮点\n1、大平台，成长空间大；\n2、社团、生鲜行业早期进入者","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4697902848","sourceKey":"meituan_social","company":"美团","title":"生产主管","city":"青岛市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4697902848&jobShareType=1","duty":"1. 负责青岛仓日常生产运营管理工作，确保生产计划按时完成。  \n2. 组织协调80人团队的工作安排，监督生产流程的执行与优化。  \n3. 监控生产质量与效率，及时发现并解决现场问题，提升作业标准化水平。  \n4. 落实安全生产制度，开展员工培训与绩效考核，提升团队整体能力。  \n5. 与仓储、物流、采购等部门协同，保障供应链高效运转。","requirements":"1. 大学专科及以上学历，物流、仓储、供应链管理等相关专业优先。  \n2. 具备5年以上仓储或生产管理经验，有带团队经验者优先。  \n3. 熟悉仓储作业流程及生产管理体系，具备较强的现场管理能力。  \n4. 具备良好的沟通协调能力，能适应快节奏工作环境。  \n5. 熟练使用办公软件，具备基础数据分析能力。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责青岛仓日常生产运营管理工作，确保生产计划按时完成。  \n2. 组织协调80人团队的工作安排，监督生产流程的执行与优化。  \n3. 监控生产质量与效率，及时发现并解决现场问题，提升作业标准化水平。  \n4. 落实安全生产制度，开展员工培训与绩效考核，提升团队整体能力。  \n5. 与仓储、物流、采购等部门协同，保障供应链高效运转。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、仓储、供应链管理等相关专业优先。  \n2. 具备5年以上仓储或生产管理经验，有带团队经验者优先。  \n3. 熟悉仓储作业流程及生产管理体系，具备较强的现场管理能力。  \n4. 具备良好的沟通协调能力，能适应快节奏工作环境。  \n5. 熟练使用办公软件，具备基础数据分析能力。\n\n具备以下条件优先\n1.电商物流企业及新零售企业生产计划管理经验；\n2.能熟练使用常用办公软件工具，具有数据处理和业务分析能力，有数据分析经验者优先。\n\n岗位亮点\n1. 稳定的平台发展机会，完善的晋升机制与培训体系。  \n2. 团队规模大，管理挑战与成长空间并存。  \n3. 工作地点位于青岛，交通便利，生活配套完善。  \n4. 提供具有竞争力的薪酬福利与绩效激励机制。  \n5. 参与智能化仓储升级项目，积累前沿行业经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4688979972","sourceKey":"meituan_social","company":"美团","title":"小象超市-华东蔬菜采购","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4688979972&jobShareType=1","duty":"1、负责蔬菜类目的商品规划、采购管理、供应链管理等，为经营结果负责；\n2、负责采购的供应商资源开发及管理，通过供应商谈判获得地采&销售渠道的供应链优化，效能提升；\n3、通过资源整合、品牌谈判、供应链优化等行为综合提升达到利润及效能的提升；\n4、把握市场动态，及时调整资源配置、确保采购的竞争处于优势。具备行业信息收集及行业经验获取能力；\n5、内外部沟通，确保履约稳定，以客户为中心，确保商品标准符合行业标准达到客户质量要求。","requirements":"1、大专以上学历，有5年以上蔬菜采购经验，有电商、线上业务经验者优先；\n2、对采购业务流程及体系有清晰的认识，对零售行业有很强的预判能力；\n3、擅长供应商寻找和开发经验，可有效管理供应商；\n4、买手型采购专家，具有较强的分析判断、前瞻思维、承压能力和团队合作意识，有采购管理经验；\n5、具备项目统筹能力，能够协调和推进公司各支持部门完成项目落地及后续效率优化。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责蔬菜类目的商品规划、采购管理、供应链管理等，为经营结果负责；\n2、负责采购的供应商资源开发及管理，通过供应商谈判获得地采&销售渠道的供应链优化，效能提升；\n3、通过资源整合、品牌谈判、供应链优化等行为综合提升达到利润及效能的提升；\n4、把握市场动态，及时调整资源配置、确保采购的竞争处于优势。具备行业信息收集及行业经验获取能力；\n5、内外部沟通，确保履约稳定，以客户为中心，确保商品标准符合行业标准达到客户质量要求。\n\n岗位基本要求\n1、大专以上学历，有5年以上蔬菜采购经验，有电商、线上业务经验者优先；\n2、对采购业务流程及体系有清晰的认识，对零售行业有很强的预判能力；\n3、擅长供应商寻找和开发经验，可有效管理供应商；\n4、买手型采购专家，具有较强的分析判断、前瞻思维、承压能力和团队合作意识，有采购管理经验；\n5、具备项目统筹能力，能够协调和推进公司各支持部门完成项目落地及后续效率优化。\n\n具备以下条件优先\n具备产地采购经验、线上线下C端供应链经验优先考虑。\n\n岗位亮点\n1、上市公司，平台大，行业整合能力强；\n2、自营重点项目，清晰的晋升路径，发展空间大；\n3、与各类供应商建立广泛的合作关系，拓展行业视角与资源积累。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4650339440","sourceKey":"meituan_social","company":"美团","title":"乐生活用户增长运营","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4650339440&jobShareType=1","duty":"1. 负责乐生活用户增长策略的制定与执行，通过数据分析和用户洞察优化拉新、留存及转化路径。  \n2. 协同产品、市场及商家团队，设计并落地用户增长活动，提升平台活跃用户规模与用户生命周期价值。  \n3. 搭建并优化用户分层运营体系，针对不同用户群体制定精细化运营方案。  \n4. 监控核心增长指标，定期输出分析报告，推动运营策略迭代与效果提升。\n5.能运用AI工具驱动用户增长策略，覆盖用户分层、数据分析、内容生成及活动提效，持续优化拉新、留存与转化效果。","requirements":"1. 大学本科及以上学历，3年以上用户增长或产品运营相关工作经验。  \n2. 熟悉互联网用户增长方法论，具备较强的数据分析能力和逻辑思维能力。  \n3. 具备良好的跨团队协作能力，能独立推动项目落地并达成目标。  \n4. 有本地生活、电商或O2O平台运营经验者优先。\n5. 熟练使用AI辅助办公工具，基于工作流完成AI提效，有AI赋能运营提效的实践经验。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1. 负责乐生活用户增长策略的制定与执行，通过数据分析和用户洞察优化拉新、留存及转化路径。  \n2. 协同产品、市场及商家团队，设计并落地用户增长活动，提升平台活跃用户规模与用户生命周期价值。  \n3. 搭建并优化用户分层运营体系，针对不同用户群体制定精细化运营方案。  \n4. 监控核心增长指标，定期输出分析报告，推动运营策略迭代与效果提升。\n5.能运用AI工具驱动用户增长策略，覆盖用户分层、数据分析、内容生成及活动提效，持续优化拉新、留存与转化效果。\n\n岗位基本要求\n1. 大学本科及以上学历，3年以上用户增长或产品运营相关工作经验。  \n2. 熟悉互联网用户增长方法论，具备较强的数据分析能力和逻辑思维能力。  \n3. 具备良好的跨团队协作能力，能独立推动项目落地并达成目标。  \n4. 有本地生活、电商或O2O平台运营经验者优先。\n5. 熟练使用AI辅助办公工具，基于工作流完成AI提效，有AI赋能运营提效的实践经验。\n\n具备以下条件优先\n有谈判能力、对演出、赛事、体育业态、IP变现有自己的见解者优先。\nAI Builder相关能力或经验丰富者优先。\n\n岗位亮点\n1. 参与核心业务增长，直接影响平台用户规模与商业价值。  \n2. 扁平化管理，高效协作的团队氛围，快速成长空间大。  \n3. 位于上海核心区域，办公环境优越，福利待遇完善。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4718768450","sourceKey":"meituan_social","company":"美团","title":"运输主管","city":"佛山市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4718768450&jobShareType=1","duty":"1. 负责运输团队日常运营管理，确保运输任务按时完成。  \n2. 制定并优化运输路线及配送计划，提升运输效率。  \n3. 监督运输过程中的安全规范执行，降低运输风险。  \n4. 协调内外部资源，处理运输异常及客户反馈问题。","requirements":"1. 大学本科及以上学历，物流、运输或相关专业优先。  \n2. 具备5年以上物流运输相关工作经验，有团队管理经验者优先。  \n3. 熟悉运输操作流程及行业法规，具备较强的数据分析能力。  \n4. 具备良好的沟通协调能力，能适应阶段性高强度工作。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责运输团队日常运营管理，确保运输任务按时完成。  \n2. 制定并优化运输路线及配送计划，提升运输效率。  \n3. 监督运输过程中的安全规范执行，降低运输风险。  \n4. 协调内外部资源，处理运输异常及客户反馈问题。\n\n岗位基本要求\n1. 大学本科及以上学历，物流、运输或相关专业优先。  \n2. 具备5年以上物流运输相关工作经验，有团队管理经验者优先。  \n3. 熟悉运输操作流程及行业法规，具备较强的数据分析能力。  \n4. 具备良好的沟通协调能力，能适应阶段性高强度工作。\n\n岗位亮点\n1. 工作地点位于佛山市，交通便利，生活配套完善。  \n2. 提供完善的培训体系和职业发展通道。  \n3. 团队氛围积极，注重员工成长与工作生活平衡。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4723202181","sourceKey":"meituan_social","company":"美团","title":"点评技术-增长算法工程师","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4723202181&jobShareType=1","duty":"1. 负责外投场景下的算法策略设计与优化，提升广告投放效率与ROI。    \n2. 构建用户激励模型，通过个性化策略提高用户活跃度与留存率。    \n3. 开发基于Agent的自动化决策系统，用于外投流量分配与激励成本控制。\n4. 协同工程与产品团队，推动算法策略的线上部署与效果验证。","requirements":"1. 硕士研究生学历，计算机科学、统计学、数学或相关专业背景。  \n2. 具备1年以上算法相关工作经验，熟悉广告出价、深度学习序列建模或因果推断等方向。  \n3. 熟练掌握Python、C++等编程语言，熟悉TensorFlow、PyTorch等深度学习框架。\n4. 具备良好的逻辑思维与沟通能力，能够独立分析和解决问题。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1. 负责外投场景下的算法策略设计与优化，提升广告投放效率与ROI。    \n2. 构建用户激励模型，通过个性化策略提高用户活跃度与留存率。    \n3. 开发基于Agent的自动化决策系统，用于外投流量分配与激励成本控制。\n4. 协同工程与产品团队，推动算法策略的线上部署与效果验证。\n\n岗位基本要求\n1. 硕士研究生学历，计算机科学、统计学、数学或相关专业背景。  \n2. 具备1年以上算法相关工作经验，熟悉广告出价、深度学习序列建模或因果推断等方向。  \n3. 熟练掌握Python、C++等编程语言，熟悉TensorFlow、PyTorch等深度学习框架。\n4. 具备良好的逻辑思维与沟通能力，能够独立分析和解决问题。\n\n具备以下条件优先\n有广告投放/用户激励算法相关项目经验者优先\n\n岗位亮点\n1. 参与核心增长业务，直接影响千万级用户的产品体验与平台增长。  \n2. 与资深算法团队共同成长，获得技术深度与业务理解的双重提升。  \n3. 参与AI Agent在增长领域的创新应用，探索动态出价、智能激励等前沿场景\n4. 完善的职业发展路径和具有竞争力的薪酬福利。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4723318194","sourceKey":"meituan_social","company":"美团","title":"点评技术-iOS研发工程师","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4723318194&jobShareType=1","duty":"1. 负责大众点评App跨端容器框架建设\n2. 负责容器性能体验优化和稳定性保障\n3. 负责AI工具建设和应用，提升业务研发效率","requirements":"1. 扎实的计算机专业基本功，强大的编程能力\n2. 精通跨端框架或React框架，能进行跨端架构设计优化和生态建设。\n3. 熟练运用各类AI能力，有AI工具建设经验且在研发流程中实际应用的优先。\n4. 有较强的逻辑/概率思维能力，善于分析、归纳、描述、沟通和解决问题\n5. 具备业务敏感度和技术投入度，致力于用技术手段促进业务发展","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1. 负责大众点评App跨端容器框架建设\n2. 负责容器性能体验优化和稳定性保障\n3. 负责AI工具建设和应用，提升业务研发效率\n\n岗位基本要求\n1. 扎实的计算机专业基本功，强大的编程能力\n2. 精通跨端框架或React框架，能进行跨端架构设计优化和生态建设。\n3. 熟练运用各类AI能力，有AI工具建设经验且在研发流程中实际应用的优先。\n4. 有较强的逻辑/概率思维能力，善于分析、归纳、描述、沟通和解决问题\n5. 具备业务敏感度和技术投入度，致力于用技术手段促进业务发展\n\n具备以下条件优先\n1. 有较大用户量APP设计/开发/持续改善经验者优先\n2. 对底层框架、内核有所理解和探究，对于系统层有优化经验者优先\n\n岗位亮点\n1. 良好的技术氛围，有定期的技术分享和培训\n2. 工程师文化，技术能充分参与到产品设计里\n3. 弹性的工作时间和良好的工作环境\n4. 完备的开发环境，依托于美团云和公司内部的工具系统，让开发更专注、有效","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4680163665","sourceKey":"meituan_social","company":"美团","title":"AI Builder-商家用户运营方向","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4680163665&jobShareType=1","duty":"1. 负责服务零售场景下商家用户运营解决方案设计。\n2. 结合AI、大模型及Agent能力，探索其在商家用户转化、营销提效等场景的应用。\n3. 深入商家挖掘痛点，将商家运营模式抽象为通用化、规模化的产品能力。\n4. 建立数据化运营及效果评估体系，对核心业务指标和落地结果负责。","requirements":"1. 本科及以上学历，3年以上本地生活、电商或商家产品经验，对商家用户运营体系有较深入理解。\n2. 对AI、大模型及Agent产品有一定实践，能够结合业务场景快速设计和验证智能化方案。\n3. 具备敏锐的商业意识和较强的逻辑能力，能够快速切入不同行业并设计解决方案。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1. 负责服务零售场景下商家用户运营解决方案设计。\n2. 结合AI、大模型及Agent能力，探索其在商家用户转化、营销提效等场景的应用。\n3. 深入商家挖掘痛点，将商家运营模式抽象为通用化、规模化的产品能力。\n4. 建立数据化运营及效果评估体系，对核心业务指标和落地结果负责。\n\n岗位基本要求\n1. 本科及以上学历，3年以上本地生活、电商或商家产品经验，对商家用户运营体系有较深入理解。\n2. 对AI、大模型及Agent产品有一定实践，能够结合业务场景快速设计和验证智能化方案。\n3. 具备敏锐的商业意识和较强的逻辑能力，能够快速切入不同行业并设计解决方案。\n\n具备以下条件优先\n1. 有AI产品、智能营销或Agent应用项目经验者优先。\n2. 有CRM、会员、营销或用户运营产品成功案例者优先。\n\n岗位亮点\n1. AI与真实商家经营场景深度结合，业务价值明确。\n2. 面向百万级商家，产品覆盖规模和操盘空间大。\n3. 学习型组织，能够持续探索AI在商家用户运营中的应用。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4601649503","sourceKey":"meituan_social","company":"美团","title":"Keeta-中东外卖供给策略商业分析师","city":"科威特城/北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4601649503&jobShareType=1","duty":"1. 经营监测与问题诊断：监测供给侧经营指标异动，识别商家运营中的问题及瓶颈，输出周期性监测报告与专题分析。\n\n2. 供给匹配分析：从品类、商家和商品等不同层面，分析供给与需求的匹配情况，制定供给策略，提升供需匹配效率。\n\n3. BML（Beat/Meet/Lose）竞争态势分析：从品牌、供给、区域等维度进行竞争态势判断与过程拆解，定位我方 Beat/Meet/Lose 的细分市场，识别关键差距环节并推动改善。\n\n4. 商家运营策略建议：基于数据分析，对平台商家进行运营分层，提出资源分配导向建议，为商家运营改善提供数据支撑和策略方向。","requirements":"1. 5年以上工作经验，零售、电商、本地生活等领域供给规划、经营分析、策略分析等方面的工作经验优先。\n\n2. 能独立思考，主动通过数据探寻业务趋势规律、发现问题，有协同各方推进项目落地的经验。\n\n3. 熟练掌握SQL等数据提取、处理及分析工具，熟练使用各种常见办公软件。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. 经营监测与问题诊断：监测供给侧经营指标异动，识别商家运营中的问题及瓶颈，输出周期性监测报告与专题分析。\n\n2. 供给匹配分析：从品类、商家和商品等不同层面，分析供给与需求的匹配情况，制定供给策略，提升供需匹配效率。\n\n3. BML（Beat/Meet/Lose）竞争态势分析：从品牌、供给、区域等维度进行竞争态势判断与过程拆解，定位我方 Beat/Meet/Lose 的细分市场，识别关键差距环节并推动改善。\n\n4. 商家运营策略建议：基于数据分析，对平台商家进行运营分层，提出资源分配导向建议，为商家运营改善提供数据支撑和策略方向。\n\n岗位基本要求\n1. 5年以上工作经验，零售、电商、本地生活等领域供给规划、经营分析、策略分析等方面的工作经验优先。\n\n2. 能独立思考，主动通过数据探寻业务趋势规律、发现问题，有协同各方推进项目落地的经验。\n\n3. 熟练掌握SQL等数据提取、处理及分析工具，熟练使用各种常见办公软件。\n\n具备以下条件优先\n1. 具有国际化经验者优先；\n\n2. 英语可以作为工作语言者优先。\n\n岗位亮点\n1. 参与美团战略级出海业务，与全球优秀玩家正面交手；拓宽全球视野，感受多元化团队；\n\n2. 从0到1开拓新市场，体验创业激情；有足够的空间和灵活度发挥才能，实现职业生涯快速成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4639967033","sourceKey":"meituan_social","company":"美团","title":"沙特配送策略分析","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4639967033&jobShareType=1","duty":"1、承接周报、月报相关指标异动分析工作，总结业务规律，发现业务问题，提出解决策略，推进业务问题改善；\n2、制定和跟进业务目标，拆解目标达成路径，持续跟进及复盘；\n3、根据业务发展和分析需求，推动相关数据基建，搭建和迭代监控看板及指标体系；\n4、进行市场研究，深入了解配送行业规则和市场态势，紧跟市场动向，为业务管理者提供行业预判。","requirements":"1、3年以上工作经验，有互联网/即时配送物流等相关行业商业分析经验优先；\n2、项目管理和跨部门合作能力，能够完成项目的规划和执行； \n3、逻辑清晰，思维框架完整，具备优秀的数据分析能力，熟悉常用统计理论与分析方法，从数据中发现业务痛点并提出应对策略； \n4、自我驱动力极强，韧性极强，积极主动，且善于团队合作;\n5、善于独立思考，喜欢钻研，拥有较强的学习兴趣，能快速熟悉陌生工作领域； \n6、具备较好的口头和书面沟通能力。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1、承接周报、月报相关指标异动分析工作，总结业务规律，发现业务问题，提出解决策略，推进业务问题改善；\n2、制定和跟进业务目标，拆解目标达成路径，持续跟进及复盘；\n3、根据业务发展和分析需求，推动相关数据基建，搭建和迭代监控看板及指标体系；\n4、进行市场研究，深入了解配送行业规则和市场态势，紧跟市场动向，为业务管理者提供行业预判。\n\n岗位基本要求\n1、3年以上工作经验，有互联网/即时配送物流等相关行业商业分析经验优先；\n2、项目管理和跨部门合作能力，能够完成项目的规划和执行； \n3、逻辑清晰，思维框架完整，具备优秀的数据分析能力，熟悉常用统计理论与分析方法，从数据中发现业务痛点并提出应对策略； \n4、自我驱动力极强，韧性极强，积极主动，且善于团队合作;\n5、善于独立思考，喜欢钻研，拥有较强的学习兴趣，能快速熟悉陌生工作领域； \n6、具备较好的口头和书面沟通能力。\n\n岗位亮点\n境外业务为美团探索境外市场的先锋力量，配送商业分析组主要负责境外外卖配送业务的商业分析工作。在这里既可以快速学习到国内先进外卖配送经验、经历新业务从0到1的过程，还可以积累宝贵的境外业务经验。个人能力积累方向更为全面，且未来职业发展的机会更多。欢迎对外卖配送、O2O、境外业务感兴趣的人才加入~","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4600985708","sourceKey":"meituan_social","company":"美团","title":"Keeta-阿联酋商业分析专家","city":"北京市/迪拜","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4600985708&jobShareType=1","duty":"1）建设并完善经营管理体系，覆盖指标体系搭建、目标管理、数据监控、结果复盘、专题分析等；\n2）支持国家进行用户增长分析和讨论，结合数据分析及物理世界用户、商家调研，识别机会和风险，沉淀业务认知，并形成关键判断；\n3）针对业务经营的重点、难点展开专题研究，输出有洞察力的分析结论，推动关键策略落地及效果衡量，以业务价值创造为导向开展工作","requirements":"1）大学本科以上学历，有大型互联网企业工作经验，英文可作为工作语言者优先考虑。\n2）至少3年以上商业分析领域工作经验，交易类业务、用户分析、数据科学经验者优先\n3）具备很强的商业认知和跨团队协同能力，丰富的团队管理经验和问题解决能力","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1）建设并完善经营管理体系，覆盖指标体系搭建、目标管理、数据监控、结果复盘、专题分析等；\n2）支持国家进行用户增长分析和讨论，结合数据分析及物理世界用户、商家调研，识别机会和风险，沉淀业务认知，并形成关键判断；\n3）针对业务经营的重点、难点展开专题研究，输出有洞察力的分析结论，推动关键策略落地及效果衡量，以业务价值创造为导向开展工作\n\n岗位基本要求\n1）大学本科以上学历，有大型互联网企业工作经验，英文可作为工作语言者优先考虑。\n2）至少3年以上商业分析领域工作经验，交易类业务、用户分析、数据科学经验者优先\n3）具备很强的商业认知和跨团队协同能力，丰富的团队管理经验和问题解决能力\n\n岗位亮点\n1） 境外业务发展快，空间大\n2） 核心岗位影响力大，直接参与到业务目标策略制定，贴近业务，落地性强\n3） 深度了解外卖业务运作机制，跨部门协同作战，提升综合能力","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4669381387","sourceKey":"meituan_social","company":"美团","title":"美团骑行-电单秩序管理策略","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4669381387&jobShareType=1","duty":"负责推进电单业务在秩序方面的问题监控、诊断、策略和能力建设，提升治理者满意度\n1、负责电单业务在秩序清摆&防扣方面的预算、管理、考核等规划，逐步提升秩序成本使用效率；\n2、负责推进电单业务在秩序清淤、摆车、防扣和治理者响应等方面的线上化能力建设，提高各类经营指标；\n3、从指标异常入手，定期走访一线，了解业务真实痛点并输出解决方案。联动发展部等部门获取治理者满意度并反馈至策略及考核。\n4、运用AI工具提升治理效率，把个人洞察能力沉淀用可复制的AI能力。","requirements":"本科及以上学历，3年以上互联网运营或数据分析相关工作经验\n• 能独立做数据分析，从数据中识别异常并做多层归因拆解\n• 有策略落地的完整闭环经验——从\"发现问题\"到\"设计方案\"到\"推动执行\"到\"验证效果","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n负责推进电单业务在秩序方面的问题监控、诊断、策略和能力建设，提升治理者满意度\n1、负责电单业务在秩序清摆&防扣方面的预算、管理、考核等规划，逐步提升秩序成本使用效率；\n2、负责推进电单业务在秩序清淤、摆车、防扣和治理者响应等方面的线上化能力建设，提高各类经营指标；\n3、从指标异常入手，定期走访一线，了解业务真实痛点并输出解决方案。联动发展部等部门获取治理者满意度并反馈至策略及考核。\n4、运用AI工具提升治理效率，把个人洞察能力沉淀用可复制的AI能力。\n\n岗位基本要求\n本科及以上学历，3年以上互联网运营或数据分析相关工作经验\n• 能独立做数据分析，从数据中识别异常并做多层归因拆解\n• 有策略落地的完整闭环经验——从\"发现问题\"到\"设计方案\"到\"推动执行\"到\"验证效果\n\n具备以下条件优先\n有AI工具使用经验优先，愿意在治理场景中探索AI应用，用技术手段提升工作效率\n\n岗位亮点\n1、能够深入参与业务关键环节，直接为业务结果负责。\n2、面临复杂问题各类特殊场景，快速沉淀个人能力","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4428189649","sourceKey":"meituan_social","company":"美团","title":"Agent 开发工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4428189649&jobShareType=1","duty":"1. 负责 AI Agent 系统的架构设计与核心模块开发，包括任务规划、工具调用（Tool Use / MCP）、记忆管理、多 Agent 协同等能力建设\n2. 深度参与 LLM 集成与推理链路优化，研究 Prompt Engineering、Function Calling、RAG 等关键技术在生产环境的落地\n3. 设计并实现 Agent 框架的核心组件（Planner、Executor、Evaluator），保障系统的稳定性、可观测性和可扩展性\n4. 与业务团队密切合作，将 Agent 能力落地到具体场景，推动从 demo 到生产环境的全流程工程化\n5. 持续跟踪 AI Agent 领域前沿进展，将有价值的技术方案引入团队任职要求","requirements":"1. 本科及以上学历，计算机相关专业，3年以上后端或 AI 工程开发经验\n2. 扎实的工程基础，熟悉 Python / Java / Go 至少一门，能写出高质量、可维护的代码\n3. 有 LLM 应用开发实际经验，熟悉 OpenAI / Anthropic / 主流开源模型的 API 使用，了解 Function Calling、Tool Use 机制\n4. 有 Agent 框架开发或使用经验（LangGraph、AutoGen、CrewAI、或自研框架），理解 ReAct / Plan-and-Execute 等 Agent 范式\n5. 熟悉 RAG 系统设计，包括向量检索、知识库构建、上下文管理等\n6. 有生产级 AI 系统落地经验，了解 Prompt 版本管理、Trace/Log 可观测性、评估体系建设等工程实践","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 负责 AI Agent 系统的架构设计与核心模块开发，包括任务规划、工具调用（Tool Use / MCP）、记忆管理、多 Agent 协同等能力建设\n2. 深度参与 LLM 集成与推理链路优化，研究 Prompt Engineering、Function Calling、RAG 等关键技术在生产环境的落地\n3. 设计并实现 Agent 框架的核心组件（Planner、Executor、Evaluator），保障系统的稳定性、可观测性和可扩展性\n4. 与业务团队密切合作，将 Agent 能力落地到具体场景，推动从 demo 到生产环境的全流程工程化\n5. 持续跟踪 AI Agent 领域前沿进展，将有价值的技术方案引入团队任职要求\n\n岗位基本要求\n1. 本科及以上学历，计算机相关专业，3年以上后端或 AI 工程开发经验\n2. 扎实的工程基础，熟悉 Python / Java / Go 至少一门，能写出高质量、可维护的代码\n3. 有 LLM 应用开发实际经验，熟悉 OpenAI / Anthropic / 主流开源模型的 API 使用，了解 Function Calling、Tool Use 机制\n4. 有 Agent 框架开发或使用经验（LangGraph、AutoGen、CrewAI、或自研框架），理解 ReAct / Plan-and-Execute 等 Agent 范式\n5. 熟悉 RAG 系统设计，包括向量检索、知识库构建、上下文管理等\n6. 有生产级 AI 系统落地经验，了解 Prompt 版本管理、Trace/Log 可观测性、评估体系建设等工程实践\n\n具备以下条件优先\n• 有 MCP（Model Context Protocol）协议开发或集成经验\n• 有多 Agent 协同、Agent 编排系统设计经验\n• 对大数据或数据开发工具链有了解（了解即可，非必要）\n• 参与过开源 Agent 项目，或有自己的相关作品\n\n岗位亮点\n1. 参与前沿AI Agent技术研发，推动智能化应用落地。  \n2. 与高水平团队共同成长，提供广阔的技术发展空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4711626275","sourceKey":"meituan_social","company":"美团","title":"闪电仓CKA商家运营-东部","city":"上海市/杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4711626275&jobShareType=1","duty":"1.经营分析诊断。能够识别品牌优劣势，并以货盘-品类-商品的视角洞察机会点与问题点；\n2.业务策略制定。擅长品类运营，以商品为最小策略单元，共建品牌策略方案，驱动品牌GMV增长与经营改善；\n3.多方资源整合。清晰了解品牌、门店、上游厂商、平台的资源空间，并依托业务策略及产品工具整合营销方案。\n4.项目管理能力。基于经营目标及业务策略，以项目制形式拆解、推进、复盘，并识别风险、及时应对。\n\n能力要求：\n1. 品类诊断与策略制定：基于商家分品类盈利逻辑，对商家运营能力在结果层（店单产/利润/周转）+和过程层（哪些行为差异导致了结果差异）做两层解构，识别商家的优势类目，并以共建的形式输出差异化策略。\n2.商品运营：结合热搜词趋势、季节/场景变化，指导商家选品上新与货盘结构优化，并推动策略落地，追踪ROI和转化效果。\n3.流量运营与营销资源整合：体系化使用平台流量工具（神券/神价/广告/首页推荐等），以及自营销工具（折扣品/爆品），能够诊断流量机会点并整合多方资源形成合力。\n4.经营目标共识与落地闭环：以服务报告作为沟通载体，与商家共识经营目标（增长/增收/降本/提效等），测算收益空间，并结合业务策略建立常态化追踪复盘机制。","requirements":"1.本科及以上学历，3年以上零售行业经验。\n2.懂经营：能讲清楚不同品类的毛利结构、周转逻辑、定价策略等；\n3.懂数据：熟练使用BI工具进行经营分析，能独立完成从数据-洞察-策略全链路工作；\n4.懂商家：服务过连锁品牌或区域头部商家，知道怎么跟商家\"谈生意\"而不是\"传通知\"；\n5.优先项：①.有前置仓/便利店/闪电仓等近场零售业态的品类运营/商品经验；②.快消品类（食品饮料/日百/个护）的选品或采购背景；③.有大客户BD或KA管理经验，能独立推进跨部门协作。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.经营分析诊断。能够识别品牌优劣势，并以货盘-品类-商品的视角洞察机会点与问题点；\n2.业务策略制定。擅长品类运营，以商品为最小策略单元，共建品牌策略方案，驱动品牌GMV增长与经营改善；\n3.多方资源整合。清晰了解品牌、门店、上游厂商、平台的资源空间，并依托业务策略及产品工具整合营销方案。\n4.项目管理能力。基于经营目标及业务策略，以项目制形式拆解、推进、复盘，并识别风险、及时应对。\n\n能力要求：\n1. 品类诊断与策略制定：基于商家分品类盈利逻辑，对商家运营能力在结果层（店单产/利润/周转）+和过程层（哪些行为差异导致了结果差异）做两层解构，识别商家的优势类目，并以共建的形式输出差异化策略。\n2.商品运营：结合热搜词趋势、季节/场景变化，指导商家选品上新与货盘结构优化，并推动策略落地，追踪ROI和转化效果。\n3.流量运营与营销资源整合：体系化使用平台流量工具（神券/神价/广告/首页推荐等），以及自营销工具（折扣品/爆品），能够诊断流量机会点并整合多方资源形成合力。\n4.经营目标共识与落地闭环：以服务报告作为沟通载体，与商家共识经营目标（增长/增收/降本/提效等），测算收益空间，并结合业务策略建立常态化追踪复盘机制。\n\n岗位基本要求\n1.本科及以上学历，3年以上零售行业经验。\n2.懂经营：能讲清楚不同品类的毛利结构、周转逻辑、定价策略等；\n3.懂数据：熟练使用BI工具进行经营分析，能独立完成从数据-洞察-策略全链路工作；\n4.懂商家：服务过连锁品牌或区域头部商家，知道怎么跟商家\"谈生意\"而不是\"传通知\"；\n5.优先项：①.有前置仓/便利店/闪电仓等近场零售业态的品类运营/商品经验；②.快消品类（食品饮料/日百/个护）的选品或采购背景；③.有大客户BD或KA管理经验，能独立推进跨部门协作。\n\n具备以下条件优先\n有品类/商品运营、中台供给运营相关能力的优先\n\n岗位亮点\n闪电仓是美团即时零售战略的核心业态，行业年增速超30%，正处于从\"跑马圈地\"到\"精细化运营\"的黄金窗口期","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4703276025","sourceKey":"meituan_social","company":"美团","title":"鲜蛋和蛋制品-招商采购","city":"西安市/重庆市/南宁市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4703276025&jobShareType=1","duty":"1. 负责鲜蛋及蛋制品类商品的招商工作，开发并维护优质供应商资源。  \n2. 根据市场需求和采购计划，执行商品采购、价格谈判及合同签订。  \n3. 监控商品库存、销售数据及市场动态，优化采购策略与供应链效率。  \n4. 协同品控、物流等团队，确保商品质量与交付时效符合公司标准。","requirements":"1. 大学专科及以上学历，专业不限，有生鲜或快消品行业背景优先。  \n2. 具备3年以上采购或招商相关工作经验，熟悉鲜蛋及蛋制品供应链。  \n3. 具备良好的商务谈判能力、数据分析能力和跨部门沟通协作能力。  \n4. 能适应在西安、重庆、南宁等城市灵活办公或出差。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责鲜蛋及蛋制品类商品的招商工作，开发并维护优质供应商资源。  \n2. 根据市场需求和采购计划，执行商品采购、价格谈判及合同签订。  \n3. 监控商品库存、销售数据及市场动态，优化采购策略与供应链效率。  \n4. 协同品控、物流等团队，确保商品质量与交付时效符合公司标准。\n\n岗位基本要求\n1. 大学专科及以上学历，专业不限，有生鲜或快消品行业背景优先。  \n2. 具备3年以上采购或招商相关工作经验，熟悉鲜蛋及蛋制品供应链。  \n3. 具备良好的商务谈判能力、数据分析能力和跨部门沟通协作能力。  \n4. 能适应在西安、重庆、南宁等城市灵活办公或出差。\n\n具备以下条件优先\n具有美菜,盒马，京东等平台经验优先。\n\n岗位亮点\n1. 加入快速发展的生鲜零售平台，参与核心品类供应链建设。  \n2. 提供完善的培训体系与清晰的职业发展路径。  \n3. 团队氛围开放，鼓励创新与结果导向的工作方式。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4724097702","sourceKey":"meituan_social","company":"美团","title":"小象超市-体验优化专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4724097702&jobShareType=1","duty":"1、洞察用户体验的痛点和需求，诊断问题并提出系统性的解决方案，通过优化规则、流程和产品功能等方式，提升用户体验；\n2、基于对业务和用户的理解，针对核心问题开展体验专项，结合走查、调研、分析等形式，完成深入洞察和优化建议，并推动优化策略落地；\n3、与业务建立良好的合作关系，通过建立有效的运营机制，驱动上下游改善体验问题；\n4、主动探索AI在体验优化领域的应用场景（如智能NPS分析、评论情感挖掘、用户行为预测等），推动团队AI工具的应用和效率提升，建立AI赋能的体验优化方法论；\n5、运用AI工具（NPS分析、文本挖掘、用户行为建模等）系统性诊断用户体验痛点与机会点，构建量化评估指标体系，实现体验问题的自动发现与优先级排序。","requirements":"1、5年以上用户体验、零售运营、服务管理相关经验，有即时零售/同城电商/O2O背景优先。具备多项目并行管理并有效落地的能力；\n2、具备数据驱动思维，能借助AI工具（NPS分析、文本挖掘、用户行为建模等）发现规律、量化问题，有实际AI应用经验者优先；\n3、系统性思维与破局能力，能识别复杂业务中体验与效率的平衡点，找到可落地的优化路径；\n4、优秀的跨部门协作能力，推动力强，能从全局最优出发驱动跨团队合作与策略落地；\n5、具备AI提效意识，主动将AI工具融入日常工作，持续探索用技术手段提升体验运营效率；\n6、精通NPS分析、文本挖掘、用户行为建模等AI工具，有实际AI应用经验，能够独立完成从数据采集到洞察输出的全流程工作。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、洞察用户体验的痛点和需求，诊断问题并提出系统性的解决方案，通过优化规则、流程和产品功能等方式，提升用户体验；\n2、基于对业务和用户的理解，针对核心问题开展体验专项，结合走查、调研、分析等形式，完成深入洞察和优化建议，并推动优化策略落地；\n3、与业务建立良好的合作关系，通过建立有效的运营机制，驱动上下游改善体验问题；\n4、主动探索AI在体验优化领域的应用场景（如智能NPS分析、评论情感挖掘、用户行为预测等），推动团队AI工具的应用和效率提升，建立AI赋能的体验优化方法论；\n5、运用AI工具（NPS分析、文本挖掘、用户行为建模等）系统性诊断用户体验痛点与机会点，构建量化评估指标体系，实现体验问题的自动发现与优先级排序。\n\n岗位基本要求\n1、5年以上用户体验、零售运营、服务管理相关经验，有即时零售/同城电商/O2O背景优先。具备多项目并行管理并有效落地的能力；\n2、具备数据驱动思维，能借助AI工具（NPS分析、文本挖掘、用户行为建模等）发现规律、量化问题，有实际AI应用经验者优先；\n3、系统性思维与破局能力，能识别复杂业务中体验与效率的平衡点，找到可落地的优化路径；\n4、优秀的跨部门协作能力，推动力强，能从全局最优出发驱动跨团队合作与策略落地；\n5、具备AI提效意识，主动将AI工具融入日常工作，持续探索用技术手段提升体验运营效率；\n6、精通NPS分析、文本挖掘、用户行为建模等AI工具，有实际AI应用经验，能够独立完成从数据采集到洞察输出的全流程工作。\n\n具备以下条件优先\n用户体验、零售运营、服务管理相关经验，有即时零售/同城电商/O2O背景优先。有AI工具（如Python数据分析、NLP文本处理、机器学习建模）的实际应用经验优先。\n\n岗位亮点\n1、机遇挑战：深度参与业务核心链路的关键环节；\n2、团队氛围：开放和直接的沟通环境，结果导向，强调合作共赢；\n3、个人成长：不设限的工作空间，开放的学习平台。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3926805755","sourceKey":"meituan_social","company":"美团","title":"KSA-站长Dark Store Manager","city":"利雅得/吉达/麦加/麦地那/达曼/塔伊夫/胡富夫/胡拜尔/朱拜勒","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3926805755&jobShareType=1","duty":"1. Responsible for the day-to-day operational management of the Riyadh Service Station, including the receipt and dispatch of goods, and warehouse management.\n2. Ensures timely delivery of goods, coordinates interdepartmental collaboration, and enhances fulfilment efficiency.\n3. Manages and guides team members, develops work plans and procedures, and improves team performance.\n4. Oversee warehouse management, encompassing goods receipt and dispatch, inventory control, and loss prevention.\n5. Analyse and resolve operational issues arising during logistics processes to guarantee seamless supply chain operations.","requirements":"1. Bachelor's degree or higher, preferably in Logistics Management or Retail Operations Management.\n2. Minimum 3 years' experience in logistics operations and retail store management; candidates with team management experience preferred.\n3. Thorough understanding of logistics operational procedures and relevant regulations, with strong problem-solving capabilities.\n4. Excellent communication skills and teamwork ethos, with the ability to effectively coordinate interdepartmental collaboration.\n5. Strong adaptability and capacity to maintain a positive work attitude in high-pressure environments.\n6. English proficiency sufficient for workplace communication.","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. Responsible for the day-to-day operational management of the Riyadh Service Station, including the receipt and dispatch of goods, and warehouse management.\n2. Ensures timely delivery of goods, coordinates interdepartmental collaboration, and enhances fulfilment efficiency.\n3. Manages and guides team members, develops work plans and procedures, and improves team performance.\n4. Oversee warehouse management, encompassing goods receipt and dispatch, inventory control, and loss prevention.\n5. Analyse and resolve operational issues arising during logistics processes to guarantee seamless supply chain operations.\n\n岗位基本要求\n1. Bachelor's degree or higher, preferably in Logistics Management or Retail Operations Management.\n2. Minimum 3 years' experience in logistics operations and retail store management; candidates with team management experience preferred.\n3. Thorough understanding of logistics operational procedures and relevant regulations, with strong problem-solving capabilities.\n4. Excellent communication skills and teamwork ethos, with the ability to effectively coordinate interdepartmental collaboration.\n5. Strong adaptability and capacity to maintain a positive work attitude in high-pressure environments.\n6. English proficiency sufficient for workplace communication.\n\n岗位亮点\n1. Offer extensive experience in logistics, warehousing and retail operations management, providing an excellent platform for personal career development.\n2. Contribute to the stable growth of logistics operations in the Riyadh region, driving business expansion for the enterprise.\n3. Lead team members in achieving individual and collective objectives, fostering mutual growth and development.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4474257706","sourceKey":"meituan_social","company":"美团","title":"收单线上渠道经理","city":"成都市/北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4474257706&jobShareType=1","duty":"1. 负责收单业务渠道（线上or线下）线索的拓展，并驱动线索端到端转化。\n2. 制定渠道合作策略，并落地拿到结果，推动业务落地与增长。  \n3.了解AI at work的基本模式和底层逻辑，能够利用AI 工具提效。","requirements":"1. 大学本科及以上学历，有AI应用经验优先。  \n2. 具备3年渠道拓展如地推、电销等相关工作经验。  \n3. 熟悉收单业务模式及行业生态，拥有良好的商务谈判与资源整合能力。  \n4. 具备较强的数据分析能力与跨部门协作能力，能独立推动项目落地。","description":"部门介绍\n美团餐饮系统为餐饮企业提供一站式IT解决方案，帮助餐饮商户实现从供应链管理、生产管理、前厅管理到外卖的数字化经营。美团餐饮系统不仅打通了餐厅和平台，更帮助餐厅连接客人，让商户更了解顾客需求，在帮助商户做商业决策的同时给顾客带来更好的消费体验。\n我们持续建设和提升产研、销售、服务的核心能力，通过全新升级的美团餐饮系统一体化软硬件产品，助力餐饮商户进行线上化经营，帮助商户在推广新店、提升效率、降低成本、会员营销、流量扶持、智慧选址、供应链管理等方面强化经营能力。团队汇集了餐饮和SaaS领域的优秀人才，秉持着“以客户为中心”的初心和“长期有耐心”的耕耘精神，求真、敬畏、敢于自我否定、善于快速学习。期待同样愿意长期致力于餐饮产业数字化、智能化的你加入我们的团队，共同进步共同成长！\n\n岗位职责\n1. 负责收单业务渠道（线上or线下）线索的拓展，并驱动线索端到端转化。\n2. 制定渠道合作策略，并落地拿到结果，推动业务落地与增长。  \n3.了解AI at work的基本模式和底层逻辑，能够利用AI 工具提效。\n\n岗位基本要求\n1. 大学本科及以上学历，有AI应用经验优先。  \n2. 具备3年渠道拓展如地推、电销等相关工作经验。  \n3. 熟悉收单业务模式及行业生态，拥有良好的商务谈判与资源整合能力。  \n4. 具备较强的数据分析能力与跨部门协作能力，能独立推动项目落地。\n\n具备以下条件优先\n有借助AI agent 驱动线索运营自动化实践者优先\n\n岗位亮点\n1. 参与公司核心支付业务，成长空间广阔。  \n2. 工作地点覆盖成都、北京，灵活性强。  \n3. 团队氛围开放，注重创新与结果导向。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4707466438","sourceKey":"meituan_social","company":"美团","title":"供应计划-数据专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4707466438&jobShareType=1","duty":"1、搭建供应链计划相关指标体系，深入供应链各环节，梳理需求及指标口径，包括计划、库存、履约等模块；\n2、业务分析与洞察：深入理解供应链业务流程，协同城市计划和品类计划对全盘计划进行统筹，制定和运营库存指标。通过日常监控、归因分析，联动协同方解决问题，并提出改进方案和有效措施，不断挖掘数据产品的潜在应用场景；\n3、看板开发与流程优化：针对数据相关需求，承接需求梳理->上线->运营的交付相关工作；\n4、项目支持，供应计划相关项目支持，挖掘有价值的业务建议；\n5、跨团队协作，与部门内外部协同方密切合作，推动数据能力的落地。","requirements":"1、本科及以上学历，3年以上供应链计划领域相关经验，熟练使用SQL、Python等工具优先；\n2、具备电商、快消行业从业经历者优先，掌握端到端的供应链管理方法；\n3、具备业务敏感度、结构化思维与数据分析能力；\n4、具备项目管理经验，能基于计划执行推动相关方完成相关动作的落地；\n5、出色的跨团队沟通能力，能清晰传递分析结论，并推动项目落地。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、搭建供应链计划相关指标体系，深入供应链各环节，梳理需求及指标口径，包括计划、库存、履约等模块；\n2、业务分析与洞察：深入理解供应链业务流程，协同城市计划和品类计划对全盘计划进行统筹，制定和运营库存指标。通过日常监控、归因分析，联动协同方解决问题，并提出改进方案和有效措施，不断挖掘数据产品的潜在应用场景；\n3、看板开发与流程优化：针对数据相关需求，承接需求梳理->上线->运营的交付相关工作；\n4、项目支持，供应计划相关项目支持，挖掘有价值的业务建议；\n5、跨团队协作，与部门内外部协同方密切合作，推动数据能力的落地。\n\n岗位基本要求\n1、本科及以上学历，3年以上供应链计划领域相关经验，熟练使用SQL、Python等工具优先；\n2、具备电商、快消行业从业经历者优先，掌握端到端的供应链管理方法；\n3、具备业务敏感度、结构化思维与数据分析能力；\n4、具备项目管理经验，能基于计划执行推动相关方完成相关动作的落地；\n5、出色的跨团队沟通能力，能清晰传递分析结论，并推动项目落地。\n\n岗位亮点\n具有挑战性的业务场景，利于专业沉淀；有机会完成0-1的新能力建设。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4707496370","sourceKey":"meituan_social","company":"美团","title":"供应链计划规划专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4707496370&jobShareType=1","duty":"1、计划管理体系的迭代及运营：长期及短期的进销存计划制定，协同物流和计划，对计划偏差进行分析，持续改善计划的可执行性，提升全链路的运营效率；\n2、需求管理和产品协同：负责供应计划业务逻辑和产品逻辑迭代，承接相关的项目需求并协同各方进行进行需求梳理、可行性分析、上线验收及落地运营等；\n3、建立监测指标体系，及时发现并联动物流解决问题，提出改进方案和措施；\n4、协同城市计划和品类计划对全盘计划进行统筹，制定和运营库存指标；\n5、产品和流程优化：承接需求预测、库存策略、库存仿真、订货系统等计划相关产品/数据/应用需求，并承接需求梳理->上线->运营的相关工作；通过流程优化、专题项目、系统构建等方式提高链路的协同效率；\n5、上下游拉通，拉通算法、产品、计划运营、业务等各方共识，类项目管理的方式推进需求落地和产品功能上线。","requirements":"1、供应链计划产品实施经验，熟悉需求计划、库存计划、供应计划、s&op流程并具备实际运营经验，掌握端到端的供应链管理方法；\n2、能够明确对应模块关键业务的诉求，进行需求编写、流程设计、独立完成BRD并能将需求准确的传递后后端产品和研发部门；\n3、较好的项目管理能力和风险管理能力，保障实施交付落地；能基于计划执行推动相关方完成相关动作的落地；\n4、良好的数据处理能力；\n5、熟练使用SQL等数据提取工具；\n6、具备一定的团队管理相关经验。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、计划管理体系的迭代及运营：长期及短期的进销存计划制定，协同物流和计划，对计划偏差进行分析，持续改善计划的可执行性，提升全链路的运营效率；\n2、需求管理和产品协同：负责供应计划业务逻辑和产品逻辑迭代，承接相关的项目需求并协同各方进行进行需求梳理、可行性分析、上线验收及落地运营等；\n3、建立监测指标体系，及时发现并联动物流解决问题，提出改进方案和措施；\n4、协同城市计划和品类计划对全盘计划进行统筹，制定和运营库存指标；\n5、产品和流程优化：承接需求预测、库存策略、库存仿真、订货系统等计划相关产品/数据/应用需求，并承接需求梳理->上线->运营的相关工作；通过流程优化、专题项目、系统构建等方式提高链路的协同效率；\n5、上下游拉通，拉通算法、产品、计划运营、业务等各方共识，类项目管理的方式推进需求落地和产品功能上线。\n\n岗位基本要求\n1、供应链计划产品实施经验，熟悉需求计划、库存计划、供应计划、s&op流程并具备实际运营经验，掌握端到端的供应链管理方法；\n2、能够明确对应模块关键业务的诉求，进行需求编写、流程设计、独立完成BRD并能将需求准确的传递后后端产品和研发部门；\n3、较好的项目管理能力和风险管理能力，保障实施交付落地；能基于计划执行推动相关方完成相关动作的落地；\n4、良好的数据处理能力；\n5、熟练使用SQL等数据提取工具；\n6、具备一定的团队管理相关经验。\n\n岗位亮点\n具有挑战性的业务场景，利于专业沉淀；有机会完成0-1的新能力建设。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4654383070","sourceKey":"meituan_social","company":"美团","title":"小象超市-品类计划专家（即食计划）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4654383070&jobShareType=1","duty":"1、负责供应链品类计划：基于用户需求预测，输出品类备货计划，并通过持续提升计划准确度及备货弹性，保障商品稳定供给，提升用户体验；\n2、负责供应链产品优化：根据不同品类的独特发展需求及特点，建立全链路供应链优化及解决方案，沉淀策略并推进产品化，提升供应链计划自动化进程；\n3、负责供应链运营提效：通过管控输入及输出指标，监控库存现货率、周转、库龄，及时提出滞销、断货预警，识别风险点及机会点，提升现有供给链路效率；\n4、结合AI/大模型工具，持续优化需求预测模型和算法，推动计划决策从人工经验向数据智能演进；\n5、与算法、产品团队协同，探索AI Agent在库存预警、异常处置等场景的落地应用。","requirements":"1、具备创业精神，积极主动，有较强的自驱力和韧性；\n2、熟练掌握各类办公软件，具有较强的逻辑思考能力、数据分析能力、复杂问题的拆解能力；\n3、具备较强责任心、沟通、协同、推动影响力；\n4、2年以上供应计划工作经验；\n5、有大数据分析平台（如Spark/SQL）或AI工具（如ChatGPT/Copilot等）实际使用经验优先；对智能化供应链有探索热情。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责供应链品类计划：基于用户需求预测，输出品类备货计划，并通过持续提升计划准确度及备货弹性，保障商品稳定供给，提升用户体验；\n2、负责供应链产品优化：根据不同品类的独特发展需求及特点，建立全链路供应链优化及解决方案，沉淀策略并推进产品化，提升供应链计划自动化进程；\n3、负责供应链运营提效：通过管控输入及输出指标，监控库存现货率、周转、库龄，及时提出滞销、断货预警，识别风险点及机会点，提升现有供给链路效率；\n4、结合AI/大模型工具，持续优化需求预测模型和算法，推动计划决策从人工经验向数据智能演进；\n5、与算法、产品团队协同，探索AI Agent在库存预警、异常处置等场景的落地应用。\n\n岗位基本要求\n1、具备创业精神，积极主动，有较强的自驱力和韧性；\n2、熟练掌握各类办公软件，具有较强的逻辑思考能力、数据分析能力、复杂问题的拆解能力；\n3、具备较强责任心、沟通、协同、推动影响力；\n4、2年以上供应计划工作经验；\n5、有大数据分析平台（如Spark/SQL）或AI工具（如ChatGPT/Copilot等）实际使用经验优先；对智能化供应链有探索热情。\n\n具备以下条件优先\n1、具备较强数据统计以及分析能力，熟练使用SQL；\n2、参与过同类型业务，具备多门店库存管理经验优先；\n3、供应链管理、物流管理专业优先；\n4、乐观向上正能量者优先。\n\n岗位亮点\n1、供应链能力建设价值高：供给侧需要有无限接近和满足消费者的能力，对于需求计划，库存计划，补货管理专业能力建设；以及通过供应链条的整体优化最大化供给的弹性。这种能力区别于现在的远场电商/线下电商已有的供应链能力，也会成为未来即时零售的核心竞争力；\n2、小象供应链场景的复杂度能帮助在供应链专业上的深度拓展：供应链链路上的节点多，品类复杂，异常场景多等，都对供应链规划/计划/执行能力上有更高的要求，是很好的专业深度挑战；\n3、构建更宽广的职业发展图景：有机会全身心地参与新零售业态，在急速发展的业务当中，从0到1地建立对业务和产业的认知，能和电商、O2O、物流、零售、人工智能等多元化背景的团队一起，综合学习，共同进步；\n4、深度参与美团供应链AI化升级：在AI重塑供应链的关键窗口期，与算法/产品/技术团队共同探索智能计划体系，既有深度的供应链专业修炼，也有AI转型浪潮的先行视角。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4724398596","sourceKey":"meituan_social","company":"美团","title":"国际风控策略分析师","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4724398596&jobShareType=1","duty":"1、探索和落实AI及大模型技术在策略场景的应用，包括AI辅助特征挖掘、策略生成与仿真评估，推动策略体系向智能化演进；\n\n2、负责国际支付欺诈风险防控，减少公司资金损失，基于历史数据和专家经验，通过数据分析、数据挖掘和大模型能力，设计针对盗卡、盗账户等欺诈场景的风控策略并持续优化； \n\n3、平衡支付的体验和资损，设计、实施、监控风险-收益最大化的安全策略，保障业务健康发展； \n\n4、建立策略监控指标体系与数据报表体系，完善风险监控与预警机制，进行日常风险指标与策略、模型性能监控； \n\n5、联动产品、技术、算法等团队，建设风险引擎中台能力，设计和构建体系化的风控策略、流程与机制。","requirements":"1、熟悉大模型应用场景，能够将AI能力融入风控策略设计与迭代，具有AI+风控策略实践落地经验者优先；\n\n2、3年以上风控策略/数据分析经验，有国际支付或跨境风控经验者优先；本科及以上学历，计算机、数学、统计学、金融等相关专业，可使用中英文作为工作语言；\n\n3、熟练使用至少一种分析工具（SQL、Python、R等），具备扎实的策略分析与数据挖掘能力，熟悉盗卡、盗账户、拒付等反欺诈策略设计，了解国际卡组织与支付网络运作机制踪业界前沿动态并快速评估其在反欺诈场景的适用性；\n\n4、突出的分析问题和解决问题能力，自我驱动，具备较强的学习能力、创新应用能力及沟通协调能力。","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n1、探索和落实AI及大模型技术在策略场景的应用，包括AI辅助特征挖掘、策略生成与仿真评估，推动策略体系向智能化演进；\n\n2、负责国际支付欺诈风险防控，减少公司资金损失，基于历史数据和专家经验，通过数据分析、数据挖掘和大模型能力，设计针对盗卡、盗账户等欺诈场景的风控策略并持续优化； \n\n3、平衡支付的体验和资损，设计、实施、监控风险-收益最大化的安全策略，保障业务健康发展； \n\n4、建立策略监控指标体系与数据报表体系，完善风险监控与预警机制，进行日常风险指标与策略、模型性能监控； \n\n5、联动产品、技术、算法等团队，建设风险引擎中台能力，设计和构建体系化的风控策略、流程与机制。\n\n岗位基本要求\n1、熟悉大模型应用场景，能够将AI能力融入风控策略设计与迭代，具有AI+风控策略实践落地经验者优先；\n\n2、3年以上风控策略/数据分析经验，有国际支付或跨境风控经验者优先；本科及以上学历，计算机、数学、统计学、金融等相关专业，可使用中英文作为工作语言；\n\n3、熟练使用至少一种分析工具（SQL、Python、R等），具备扎实的策略分析与数据挖掘能力，熟悉盗卡、盗账户、拒付等反欺诈策略设计，了解国际卡组织与支付网络运作机制踪业界前沿动态并快速评估其在反欺诈场景的适用性；\n\n4、突出的分析问题和解决问题能力，自我驱动，具备较强的学习能力、创新应用能力及沟通协调能力。\n\n具备以下条件优先\n1、具备AI风控实践落地经验的互联网风险产品人才；\n2、英语可作为工作语言优先。\n\n岗位亮点\n1、AI机会：深度参与AI技术在国际风控策略场景的落地，接触大模型、智能决策等前沿AI应用，具备AI与策略复合能力的候选人将获得优先发展机会；\n\n2、业务基本盘：国际化业务是美团重要战略方向，参与美团国际化业务高速发展，深度参与国际支付风控策略体系和风控体系建设，成长空间广阔；\n\n3、成长与资源：团队学习氛围好，与风控产品、算法专家协作，快速积累国际化风控策略与全链路风控能力，美团国际丰富的数据资源与技术平台为策略创新提供有力支撑；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4047275798","sourceKey":"meituan_social","company":"美团","title":"Senior Legal Counsel (Kuwait)","city":"科威特城","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4047275798&jobShareType=1","duty":"Job Description\n\nKey Responsibilities\n\n1. Conduct legal research and provide comprehensive legal advice and support on transactions and commercial matters in Kuwait and the broader GCC region, including cross-border transactions, joint ventures, franchising, and licensing arrangements.\n\n2. Draft, review, and negotiate contracts, agreements, and other legal documents in both English and Arabic, ensuring compliance with Kuwaiti and applicable international laws.\n\n3. Advise on compliance with Kuwaiti local laws and regulations; identify and assess legal risks, and develop strategies to mitigate them.\n\n4. Assist business team, GA team in applying for and obtaining license and permit necessary for the operation of the retail, logistic, warehousing and other areas of the company.\n\n5. Work closely with senior management and business units to ensure legal requirements are met in all business operations across Kuwait.\n\n6. Support business units in communicating with relevant Kuwaiti authorities and external stakeholders, to maintain a business-friendly regulatory environment.\n\n7. Represent the company in legal proceedings, negotiations, and dispute resolution matters in Kuwaiti courts and alternative dispute resolution forums.\n\n8. Stay up-to-date with changes in the Kuwaiti legal landscape, GCC regulatory developments, and industry trends; proactively communicate updates to relevant internal stakeholders.\n\n9. Develop and maintain an adequate and high-quality resource pool of external law firms and legal advisors in Kuwait, and maintain strong relationships with external legal advisors and partners.\n\n10. Collaborate with the global legal team to ensure consistency in legal frameworks and compliance standards across jurisdictions.","requirements":"Mandatory Requirements\n\n1. A bachelor's degree in law from a recognized university. An advanced degree is preferred.\n\n2. A minimum of 7 years of relevant legal work experience, among which at least 5 years in Kuwait.\n\n3. Extensive knowledge of Kuwaiti corporate law, contract law, commercial law, labor law, and regulatory frameworks applicable to foreign-invested enterprises.\n\n4. Strong analytical, problem-solving, and communication skills with the ability to present complex legal matters clearly to non-legal stakeholders.\n\n5. Native Arabic speaker, with fluent English proficiency (both written and spoken) as a working language.\n\n6. Ability to work independently and as part of a cross-functional team.\n\n7. Proven track record of managing complex legal projects, transactions, and deadlines in a fast-paced environment.\n\n8. Familiarity with Kuwaiti regulatory authorities, licensing procedures, and government approval mechanisms.\n\n9. Experience in the retail, logistics, warehousing or food delivery industry, with understanding of supply chain, warehouse operations, dark store leasing, merchant contracts, and logistics service agreements.","description":"部门介绍\n公司事务平台负责构建公司的公共战略体系，助力业务可持续发展及公司对外影响力的提升。通过内外部风险管理，确保公司合规发展；通过深耕公共战略，推动内外良好沟通，连接公司发展与社会期待，助力业务高质量发展；通过管理社会责任议题、公益投入等，助力公司创造更多社会价值；同时为公司提供行政、采购等基础服务。我们坚持“懂业务、拿结果，勇担当、善协同，不唯上、只唯真”的工作理念，期待具有公共战略素养、了解公司治理逻辑的你加入！\n\n岗位职责\nJob Description\n\nKey Responsibilities\n\n1. Conduct legal research and provide comprehensive legal advice and support on transactions and commercial matters in Kuwait and the broader GCC region, including cross-border transactions, joint ventures, franchising, and licensing arrangements.\n\n2. Draft, review, and negotiate contracts, agreements, and other legal documents in both English and Arabic, ensuring compliance with Kuwaiti and applicable international laws.\n\n3. Advise on compliance with Kuwaiti local laws and regulations; identify and assess legal risks, and develop strategies to mitigate them.\n\n4. Assist business team, GA team in applying for and obtaining license and permit necessary for the operation of the retail, logistic, warehousing and other areas of the company.\n\n5. Work closely with senior management and business units to ensure legal requirements are met in all business operations across Kuwait.\n\n6. Support business units in communicating with relevant Kuwaiti authorities and external stakeholders, to maintain a business-friendly regulatory environment.\n\n7. Represent the company in legal proceedings, negotiations, and dispute resolution matters in Kuwaiti courts and alternative dispute resolution forums.\n\n8. Stay up-to-date with changes in the Kuwaiti legal landscape, GCC regulatory developments, and industry trends; proactively communicate updates to relevant internal stakeholders.\n\n9. Develop and maintain an adequate and high-quality resource pool of external law firms and legal advisors in Kuwait, and maintain strong relationships with external legal advisors and partners.\n\n10. Collaborate with the global legal team to ensure consistency in legal frameworks and compliance standards across jurisdictions.\n\n岗位基本要求\nMandatory Requirements\n\n1. A bachelor's degree in law from a recognized university. An advanced degree is preferred.\n\n2. A minimum of 7 years of relevant legal work experience, among which at least 5 years in Kuwait.\n\n3. Extensive knowledge of Kuwaiti corporate law, contract law, commercial law, labor law, and regulatory frameworks applicable to foreign-invested enterprises.\n\n4. Strong analytical, problem-solving, and communication skills with the ability to present complex legal matters clearly to non-legal stakeholders.\n\n5. Native Arabic speaker, with fluent English proficiency (both written and spoken) as a working language.\n\n6. Ability to work independently and as part of a cross-functional team.\n\n7. Proven track record of managing complex legal projects, transactions, and deadlines in a fast-paced environment.\n\n8. Familiarity with Kuwaiti regulatory authorities, licensing procedures, and government approval mechanisms.\n\n9. Experience in the retail, logistics, warehousing or food delivery industry, with understanding of supply chain, warehouse operations, dark store leasing, merchant contracts, and logistics service agreements.\n\n具备以下条件优先\nPreferred Qualifications (Will Be a Plus but Not a Must)\n\n- Diverse professional background, including experience in law firms, in-house legal teams, government, and/or judicial institutions (e.g., courts or prosecutorial bodies)\n\n- Overseas education experience in an English-speaking country\n\n- Experience working with or advising multinational companies in the technology or delivery industry\n\n-Professional legal qualification recognized in Kuwait (e.g., Kuwait Bar Association eligibility or equivalent)\n\n- Knowledge of Sharia law principles as they relate to commercial transactions\n\n- Knowledge with i) Kuwait's legal requirements for foreign investment and joint ventures under Kuwaiti Companies Law, ii) e-commerce, fintech, or digital services regulation in Kuwait, and iii) Kuwait's Public Tender Law and procurement frameworks\n\n岗位亮点\n1. Opportunities for professional growth and development.\n2. A challenging and rewarding work environment.\n3. The chance to work with a transnational team of experts.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4473719060","sourceKey":"meituan_social","company":"美团","title":"Senior Legal Counsel-Kuwait中方法务","city":"科威特城","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4473719060&jobShareType=1","duty":"1.负责公司在中东国家的本地法律事务，确保公司业务合规运营。\n\n2.起草、审核、翻译中英文合同、协议及法律文件，协助业务部门处理各类法律问题。\n\n3.处理日常法务咨询、合规检查、政府问询沟通等事项。\n\n4.协助建立和完善子公司合规体系、法律风险防控机制，落实总部合规制度政策。与本地法务和全球法务团队协作，确保跨司法管辖区法律框架和合规标准的一致性。\n\n5.开发、维护外部律师、律所及其他法律服务供应商资源池。\n\n6.支持公司内部培训、法律宣传及员工合规意识提升。","requirements":"1.法律相关专业本科及以上学历。\n\n2.7年以上涉外业务法务工作经验，有跨境法律事务处理背景或有英语国家海外教育经历。\n\n3.英语流利，具备法律文件中英双语起草、翻译和沟通能力。\n\n4.具备分析能力、解决问题能力以及向非法律人员解释复杂法律问题的能力。\n\n5.熟悉政府流程，有政府沟通能力及政府调查、问询应对经验，能够处理政府合规、调查等相关事务。\n\n6.良好的沟通协调能力、团队合作精神及跨文化适应能力。\n\n7.工作细致严谨，责任心强，能承受一定工作压力、在快节奏环境中管理复杂法律项目，乐于接受新鲜事物、迎接挑战。","description":"部门介绍\n公司事务平台负责构建公司的公共战略体系，助力业务可持续发展及公司对外影响力的提升。通过内外部风险管理，确保公司合规发展；通过深耕公共战略，推动内外良好沟通，连接公司发展与社会期待，助力业务高质量发展；通过管理社会责任议题、公益投入等，助力公司创造更多社会价值；同时为公司提供行政、采购等基础服务。我们坚持“懂业务、拿结果，勇担当、善协同，不唯上、只唯真”的工作理念，期待具有公共战略素养、了解公司治理逻辑的你加入！\n\n岗位职责\n1.负责公司在中东国家的本地法律事务，确保公司业务合规运营。\n\n2.起草、审核、翻译中英文合同、协议及法律文件，协助业务部门处理各类法律问题。\n\n3.处理日常法务咨询、合规检查、政府问询沟通等事项。\n\n4.协助建立和完善子公司合规体系、法律风险防控机制，落实总部合规制度政策。与本地法务和全球法务团队协作，确保跨司法管辖区法律框架和合规标准的一致性。\n\n5.开发、维护外部律师、律所及其他法律服务供应商资源池。\n\n6.支持公司内部培训、法律宣传及员工合规意识提升。\n\n岗位基本要求\n1.法律相关专业本科及以上学历。\n\n2.7年以上涉外业务法务工作经验，有跨境法律事务处理背景或有英语国家海外教育经历。\n\n3.英语流利，具备法律文件中英双语起草、翻译和沟通能力。\n\n4.具备分析能力、解决问题能力以及向非法律人员解释复杂法律问题的能力。\n\n5.熟悉政府流程，有政府沟通能力及政府调查、问询应对经验，能够处理政府合规、调查等相关事务。\n\n6.良好的沟通协调能力、团队合作精神及跨文化适应能力。\n\n7.工作细致严谨，责任心强，能承受一定工作压力、在快节奏环境中管理复杂法律项目，乐于接受新鲜事物、迎接挑战。\n\n具备以下条件优先\n有互联网、平台、物流、仓储、外卖等行业法务经验者优先。\n\n有科威特或卡塔尔工作经历优先。\n\n具有中国或其他国家法律执业资格优先。\n\n会阿拉伯语者优先。\n\n岗位亮点\n海外业务蓬勃发展，熟悉业务能力的同事发展空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4724280631","sourceKey":"meituan_social","company":"美团","title":"快驴水果——买手负责人（南京）","city":"南京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4724280631&jobShareType=1","duty":"1.负责所辖区域的水果招商团队的管理及商家管理工作；\n2.完成每个月设定的经营指标（交易、客诉率）；\n3.具备水果全品类规划能力、供应链建设和成本优化；\n4.针对类目供应链和货品需求情况，进行定向招商，合同谈判及合作条款；\n5.商家管理：管理供应商入场后行为，与供应商建立长期稳定的合作关系；\n6.基于市场和用户，敏锐的了解行业动态，及时调整商品配置，价格，策略\n7.过程指标监控及问题定位；\n8.团队建设及管理","requirements":"1.5年以上水果品类采购及管理经历；\n2.具备较强的商务谈判和采购成本管理能力；\n3.具有较强的业务分析能力、解决复杂问题能力及团队合作意识；\n4.具备线下零售业和电商品类管理的知识和经营，具备业务的中长期规划能力；\n5.具备项目统筹能力，能够协调和推进公司各支持部门完成项目落地及后续效率优化；","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1.负责所辖区域的水果招商团队的管理及商家管理工作；\n2.完成每个月设定的经营指标（交易、客诉率）；\n3.具备水果全品类规划能力、供应链建设和成本优化；\n4.针对类目供应链和货品需求情况，进行定向招商，合同谈判及合作条款；\n5.商家管理：管理供应商入场后行为，与供应商建立长期稳定的合作关系；\n6.基于市场和用户，敏锐的了解行业动态，及时调整商品配置，价格，策略\n7.过程指标监控及问题定位；\n8.团队建设及管理\n\n岗位基本要求\n1.5年以上水果品类采购及管理经历；\n2.具备较强的商务谈判和采购成本管理能力；\n3.具有较强的业务分析能力、解决复杂问题能力及团队合作意识；\n4.具备线下零售业和电商品类管理的知识和经营，具备业务的中长期规划能力；\n5.具备项目统筹能力，能够协调和推进公司各支持部门完成项目落地及后续效率优化；\n\n具备以下条件优先\n有水果B端采购供应管理经验者优先\n\n岗位亮点\n1.带领团队实现城市水果需求全结构经营；\n2.熟悉不同商业模式下不同的品类玩法和中长期业务规划 ；\n3.锻炼业务的框架性思维；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4137426224","sourceKey":"meituan_social","company":"美团","title":"医药-B2C-采购专家（药品方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4137426224&jobShareType=1","duty":"1.从事美团买药自营业务的采购工作，深入分析产品及其库存特征，制定合理采购计划和库存管控措施并跟进执行；保证各项库存指标达标，如周转、滞销、现货率等，并持续改善优化；\n2.对上游供应链现状进行梳理和诊断，识别判断最优采购路径，不断优化采购成本，提升低成本结构竞争力；\n3.推进采购流程系统建设，包括但不限于智能补货、采购看板、工作台、多仓运营采购体系等，推进系统规划建设并落地应用，运用AI数据分析工具对美团买药自营业务进行智能诊断，促进提升采购效率；\n4.引入优质供应商资源，与负责的供应商不断深入合作，做好供应商资源管理，为公司争取更多的供应链资源；\n5.部门内部、跨部门交流分享，牵头跨部门的整体项目，通过横向沟通获得必要的支持和高效协同，对项目结果负责，通过交流分享帮助他人和自身迅速成长。","requirements":"1.本科或以上学历，5年及以上电商平台快消行业采购经验，有医药行业采购经验者优先；\n2.对数据敏感度高，具备精细化商品分析经验，具备AI工具学习意识、独立思考能力强；\n3.乐于沟通，语言表达和感染说服能力突出，可应对复杂情形的商业谈判、组织协调；\n4.积极乐观，充满正能量，认同美团价值观并努力践行。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1.从事美团买药自营业务的采购工作，深入分析产品及其库存特征，制定合理采购计划和库存管控措施并跟进执行；保证各项库存指标达标，如周转、滞销、现货率等，并持续改善优化；\n2.对上游供应链现状进行梳理和诊断，识别判断最优采购路径，不断优化采购成本，提升低成本结构竞争力；\n3.推进采购流程系统建设，包括但不限于智能补货、采购看板、工作台、多仓运营采购体系等，推进系统规划建设并落地应用，运用AI数据分析工具对美团买药自营业务进行智能诊断，促进提升采购效率；\n4.引入优质供应商资源，与负责的供应商不断深入合作，做好供应商资源管理，为公司争取更多的供应链资源；\n5.部门内部、跨部门交流分享，牵头跨部门的整体项目，通过横向沟通获得必要的支持和高效协同，对项目结果负责，通过交流分享帮助他人和自身迅速成长。\n\n岗位基本要求\n1.本科或以上学历，5年及以上电商平台快消行业采购经验，有医药行业采购经验者优先；\n2.对数据敏感度高，具备精细化商品分析经验，具备AI工具学习意识、独立思考能力强；\n3.乐于沟通，语言表达和感染说服能力突出，可应对复杂情形的商业谈判、组织协调；\n4.积极乐观，充满正能量，认同美团价值观并努力践行。\n\n岗位亮点\n1.公司福利优厚：定期团建、带薪年假、定期体检；\n2.业务发展广阔前景，是公司重点突破业务；\n3.电商品类运营核心岗位，参与建设美团医药业务从小到大的发展阶段，并从中收获宝贵的经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4723335725","sourceKey":"meituan_social","company":"美团","title":"高级网安专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4723335725&jobShareType=1","duty":"1.推进网络安全主管部门朋友圈建设，覆盖部、省、市各级，建立与主管单位、行业协会、科研院所及头部厂商的战略合作关系。\n2.统筹网络安全合规事务，应对安全检查、合规审查及专项治理，协调内部资源完成整改、报告与数据报送。\n3.牵头处置公司级网络安全事件，制定应急预案并组织演练，对接主管部门事件报告与后续跟进。\n4.跟踪研判网络安全法律法规及政策动态，输出政策简报，为公司合规运营提供风险预警与策略建议。","requirements":"1.大学本科及以上学历，信息安全、网络安全、计算机、法律等相关专业。\n2.具备5年以上互联网企业或相关机构网络安全工作经历。\n3.具备高阶沟通能力和主管部门朋友圈建设经验，能独立承担日常维护工作。\n4.熟悉网络安全，信息安全等相关合规体系，具备敏锐的政策敏感度。\n5.具备较强的资源整合能力和危机处理能力，能有效协调内外部资源应对突发事件。","description":"部门介绍\n公司事务平台负责构建公司的公共战略体系，助力业务可持续发展及公司对外影响力的提升。通过内外部风险管理，确保公司合规发展；通过深耕公共战略，推动内外良好沟通，连接公司发展与社会期待，助力业务高质量发展；通过管理社会责任议题、公益投入等，助力公司创造更多社会价值；同时为公司提供行政、采购等基础服务。我们坚持“懂业务、拿结果，勇担当、善协同，不唯上、只唯真”的工作理念，期待具有公共战略素养、了解公司治理逻辑的你加入！\n\n岗位职责\n1.推进网络安全主管部门朋友圈建设，覆盖部、省、市各级，建立与主管单位、行业协会、科研院所及头部厂商的战略合作关系。\n2.统筹网络安全合规事务，应对安全检查、合规审查及专项治理，协调内部资源完成整改、报告与数据报送。\n3.牵头处置公司级网络安全事件，制定应急预案并组织演练，对接主管部门事件报告与后续跟进。\n4.跟踪研判网络安全法律法规及政策动态，输出政策简报，为公司合规运营提供风险预警与策略建议。\n\n岗位基本要求\n1.大学本科及以上学历，信息安全、网络安全、计算机、法律等相关专业。\n2.具备5年以上互联网企业或相关机构网络安全工作经历。\n3.具备高阶沟通能力和主管部门朋友圈建设经验，能独立承担日常维护工作。\n4.熟悉网络安全，信息安全等相关合规体系，具备敏锐的政策敏感度。\n5.具备较强的资源整合能力和危机处理能力，能有效协调内外部资源应对突发事件。\n\n岗位亮点\n平台大，资源多，可触达全国各层级网安朋友圈；\n成长空间大，管理者储备或资深专家方向均可；\n团队氛围好，不内卷，协同顺畅。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4721367330","sourceKey":"meituan_social","company":"美团","title":"歪马送酒直营主管【昆明】","city":"昆明市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4721367330&jobShareType=1","duty":"1. 负责昆明地区歪马送酒直营业务的日常运营管理，确保配送效率与服务质量达标。  \n2. 带领10余人团队完成销售目标，制定并执行运营策略，优化业务流程。  \n3. 监控关键运营指标，分析数据并输出改进方案，提升用户满意度与复购率。  \n4. 协调仓储、配送、客服等环节，保障订单履约顺畅，处理突发问题。  \n5. 定期培训团队成员，提升业务能力与服务意识，营造高效协作氛围。","requirements":"1. 大学本科及以上学历，具备3年以上运营管理或销售运营相关经验。  \n2. 熟悉本地生活服务或即时零售行业，有酒水、快消品运营背景者优先。  \n3. 具备较强的数据分析能力与逻辑思维，能独立制定运营策略。  \n4. 优秀的团队管理与沟通协调能力，结果导向。  \n5. 熟练使用办公软件及基础数据分析工具。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1. 负责昆明地区歪马送酒直营业务的日常运营管理，确保配送效率与服务质量达标。  \n2. 带领10余人团队完成销售目标，制定并执行运营策略，优化业务流程。  \n3. 监控关键运营指标，分析数据并输出改进方案，提升用户满意度与复购率。  \n4. 协调仓储、配送、客服等环节，保障订单履约顺畅，处理突发问题。  \n5. 定期培训团队成员，提升业务能力与服务意识，营造高效协作氛围。\n\n岗位基本要求\n1. 大学本科及以上学历，具备3年以上运营管理或销售运营相关经验。  \n2. 熟悉本地生活服务或即时零售行业，有酒水、快消品运营背景者优先。  \n3. 具备较强的数据分析能力与逻辑思维，能独立制定运营策略。  \n4. 优秀的团队管理与沟通协调能力，结果导向。  \n5. 熟练使用办公软件及基础数据分析工具。\n\n岗位亮点\n1. 加入快速发展的酒水即时零售平台，业务增长空间大。  \n2. 拥有明确的晋升通道与完善的培训体系，助力个人成长。  \n3. 团队氛围年轻有活力，扁平化管理，决策高效。  \n4. 提供具有竞争力的薪酬与绩效激励，多劳多得。  \n5. 工作地点位于昆明市核心区域，交通便利。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4698196771","sourceKey":"meituan_social","company":"美团","title":"快乐猴-杭州门店店长","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4698196771&jobShareType=1","duty":"1、确保公司营运标准高效在门店落地，提升销售与毛利；\n2、理解商圈和用户，据此对门店品类和商品经营方向有清晰的认知，通过品类/商品经营、拉新、营销、门店布局、商品订货、陈列、服务，售后，库存管控等；\n3、管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4、对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5、对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴；","requirements":"1、具有传统大型零售运营的思维模式，5年以上工作经验，担任过2年以上传统实体零售门店生鲜副店长及以上级别的管理岗,关注客户价值和客户体验;\n2、诚实正直、品行端正、责任心强、肯吃苦、有激情且执行力强，有商人视角；\n3、勇于承担，乐于分享，指导与培养团队各项能力，能够打造高绩效团队，形成阶梯化人才成长模式；\n4、具备建设组织和体系搭建能力，可以制定并落实各环节的流程；\n5、掌握基本的AI工具，具备数字化运营思维，能快速学习并应用AI辅助工具提升工作效率。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1、确保公司营运标准高效在门店落地，提升销售与毛利；\n2、理解商圈和用户，据此对门店品类和商品经营方向有清晰的认知，通过品类/商品经营、拉新、营销、门店布局、商品订货、陈列、服务，售后，库存管控等；\n3、管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4、对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5、对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴；\n\n岗位基本要求\n1、具有传统大型零售运营的思维模式，5年以上工作经验，担任过2年以上传统实体零售门店生鲜副店长及以上级别的管理岗,关注客户价值和客户体验;\n2、诚实正直、品行端正、责任心强、肯吃苦、有激情且执行力强，有商人视角；\n3、勇于承担，乐于分享，指导与培养团队各项能力，能够打造高绩效团队，形成阶梯化人才成长模式；\n4、具备建设组织和体系搭建能力，可以制定并落实各环节的流程；\n5、掌握基本的AI工具，具备数字化运营思维，能快速学习并应用AI辅助工具提升工作效率。\n\n具备以下条件优先\n有主流线下硬折扣门店店长经验，传统超商连锁门店营运中层管理经验优先。\n\n岗位亮点\n1、创新型重点项目，从0-1，成长空间广阔，共同推动门店高效营运\n2、AI数据看板、智能补货预测、数字化稽核系统全面赋能，让你用互联网公司的工具做零售管理。告别凭感觉管店，AI数据告诉你哪里出了问题、该怎么改。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4698251034","sourceKey":"meituan_social","company":"美团","title":"快乐猴-杭州门店副店长","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4698251034&jobShareType=1","duty":"1、确保公司营运标准高效在门店落地，提升销售与毛利；\n2、理解商圈和用户，据此对门店品类和商品经营方向有清晰的认知，通过品类/商品经营、拉新、营销、门店布局、商品订货、陈列、服务，售后，库存管控等；\n3、管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4、对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5、对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴；","requirements":"1、具有传统大型零售运营的思维模式，5年以上工作经验，担任过2年以上传统实体零售门店生鲜副店长及以上级别的管理岗,关注客户价值和客户体验;\n2、诚实正直、品行端正、责任心强、肯吃苦、有激情且执行力强，有商人视角；\n3、勇于承担，乐于分享，指导与培养团队各项能力，能够打造高绩效团队，形成阶梯化人才成长模式；\n4、具备建设组织和体系搭建能力，可以制定并落实各环节的流程；\n5、掌握基本的AI工具，具备数字化运营思维，能快速学习并应用AI辅助工具提升工作效率。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1、确保公司营运标准高效在门店落地，提升销售与毛利；\n2、理解商圈和用户，据此对门店品类和商品经营方向有清晰的认知，通过品类/商品经营、拉新、营销、门店布局、商品订货、陈列、服务，售后，库存管控等；\n3、管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4、对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5、对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴；\n\n岗位基本要求\n1、具有传统大型零售运营的思维模式，5年以上工作经验，担任过2年以上传统实体零售门店生鲜副店长及以上级别的管理岗,关注客户价值和客户体验;\n2、诚实正直、品行端正、责任心强、肯吃苦、有激情且执行力强，有商人视角；\n3、勇于承担，乐于分享，指导与培养团队各项能力，能够打造高绩效团队，形成阶梯化人才成长模式；\n4、具备建设组织和体系搭建能力，可以制定并落实各环节的流程；\n5、掌握基本的AI工具，具备数字化运营思维，能快速学习并应用AI辅助工具提升工作效率。\n\n具备以下条件优先\n有硬折扣门店店长经验，传统超商连锁门店营运中层管理经验优先。\n\n岗位亮点\n1、创新型重点项目，从0-1，成长空间广阔，共同推动门店高效营运\n2、AI数据看板、智能补货预测、数字化稽核系统全面赋能，让你用互联网公司的工具做零售管理。告别凭感觉管店，AI数据告诉你哪里出了问题、该怎么改。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4641502799","sourceKey":"meituan_social","company":"美团","title":"快乐猴-嘉兴门店副店长","city":"嘉兴市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4641502799&jobShareType=1","duty":"1、确保公司营运标准高效在门店落地，提升销售与毛利；\n2、理解商圈和用户，据此对门店品类和商品经营方向有清晰的认知，通过品类/商品经营、拉新、营销、门店布局、商品订货、陈列、服务，售后，库存管控等；\n3、管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4、对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5、对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴。","requirements":"1、具有传统大型零售运营的思维模式，5年以上工作经验，担任过2年以上传统实体零售门店生鲜副店长及以上级别的管理岗,关注客户价值和客户体验;\n2、诚实正直、品行端正、责任心强、肯吃苦、有激情且执行力强，有商人视角；\n3、勇于承担，乐于分享，指导与培养团队各项能力，能够打造高绩效团队，形成阶梯化人才成长模式；\n4、具备建设组织和体系搭建能力，可以制定并落实各环节的流程。\n5、掌握基本的AI工具，具备数字化运营思维，能快速学习并应用AI辅助工具提升工作效率。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1、确保公司营运标准高效在门店落地，提升销售与毛利；\n2、理解商圈和用户，据此对门店品类和商品经营方向有清晰的认知，通过品类/商品经营、拉新、营销、门店布局、商品订货、陈列、服务，售后，库存管控等；\n3、管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4、对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5、对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴。\n\n岗位基本要求\n1、具有传统大型零售运营的思维模式，5年以上工作经验，担任过2年以上传统实体零售门店生鲜副店长及以上级别的管理岗,关注客户价值和客户体验;\n2、诚实正直、品行端正、责任心强、肯吃苦、有激情且执行力强，有商人视角；\n3、勇于承担，乐于分享，指导与培养团队各项能力，能够打造高绩效团队，形成阶梯化人才成长模式；\n4、具备建设组织和体系搭建能力，可以制定并落实各环节的流程。\n5、掌握基本的AI工具，具备数字化运营思维，能快速学习并应用AI辅助工具提升工作效率。\n\n具备以下条件优先\n有硬折扣门店店长经验，传统超商连锁门店营运中层管理经验优先。\n\n岗位亮点\n1、创新型重点项目，从0-1，成长空间广阔，共同推动门店高效营运。\n2、AI数据看板、智能补货预测、数字化稽核系统全面赋能，让你用互联网公司的工具做零售管理。告别凭感觉管店，AI数据告诉你哪里出了问题、该怎么改。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3021622793","sourceKey":"meituan_social","company":"美团","title":"AI产品负责人","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3021622793&jobShareType=1","duty":"1.负责企业办公管理领域下一代AI产品的设计、开发和优化。\n2.领导和管理团队，制定团队目标并监督团队成员的工作进展。\n3.与产品经理、开发团队和其他相关部门密切合作，确保产品按时交付并满足客户需求。\n4.负责产品的市场调研和竞争分析，提供产品改进的建议和策略。\n5.跟踪和分析产品的使用情况和用户反馈，及时解决问题并改进产品体验。\n6.跟进新技术和行业趋势，为产品创新提供支持和建议。","requirements":"1.本科及以上学历，计算机科学、软件工程或相关专业优先。\n2.至少8年以上产品开发或相关工作经验，具备丰富的产品设计和开发经验。\n3.熟悉AI技术和人工智能办公工具，对人机交互、自然语言处理等领域有深入了解。\n4.具备良好的团队管理和领导能力，有成功带领团队完成项目的经验。\n5.具备较强的沟通和协调能力，能有效与不同部门和团队进行合作。\n6.具备敏锐的市场洞察力和商业意识，能够理解客户需求并提供相应解决方案。\n7.具备良好的分析和解决问题的能力，能够快速响应和处理紧急情况。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1.负责企业办公管理领域下一代AI产品的设计、开发和优化。\n2.领导和管理团队，制定团队目标并监督团队成员的工作进展。\n3.与产品经理、开发团队和其他相关部门密切合作，确保产品按时交付并满足客户需求。\n4.负责产品的市场调研和竞争分析，提供产品改进的建议和策略。\n5.跟踪和分析产品的使用情况和用户反馈，及时解决问题并改进产品体验。\n6.跟进新技术和行业趋势，为产品创新提供支持和建议。\n\n岗位基本要求\n1.本科及以上学历，计算机科学、软件工程或相关专业优先。\n2.至少8年以上产品开发或相关工作经验，具备丰富的产品设计和开发经验。\n3.熟悉AI技术和人工智能办公工具，对人机交互、自然语言处理等领域有深入了解。\n4.具备良好的团队管理和领导能力，有成功带领团队完成项目的经验。\n5.具备较强的沟通和协调能力，能有效与不同部门和团队进行合作。\n6.具备敏锐的市场洞察力和商业意识，能够理解客户需求并提供相应解决方案。\n7.具备良好的分析和解决问题的能力，能够快速响应和处理紧急情况。\n\n岗位亮点\n1.拥有丰富的产品设计和开发经验，能够参与和推动高阶AI办公产品的创新和发展。\n2.能够带领团队完成复杂项目，提升团队的技术能力和工作效率。\n3.跟踪和应用新技术，紧跟行业发展趋势，为产品创新提供支持和建议。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4721277378","sourceKey":"meituan_social","company":"美团","title":"高级测试开发工程师","city":"北京市/成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4721277378&jobShareType=1","duty":"1. 负责基于测试Agent的全流程质量保障工作，覆盖需求分析、测试设计、执行及缺陷闭环管理。  \n2. 构建并优化测试Agent能力，实现测试任务自主规划、用例生成、执行及结果分析的端到端自动化。  \n3. 探索测试Agent在复杂场景下的应用，如智能回归测试、异常路径挖掘及多模态交互验证。  \n4. 协同研发团队将测试Agent集成至CI/CD流程，提升测试效率与覆盖率。  \n5. 跟踪AI测试技术趋势，推动测试Agent在性能测试、安全测试等领域的创新落地。","requirements":"1. 硕士研究生学历，计算机、人工智能或相关专业背景。  \n2. 5年以上测试开发经验，具备AI应用或智能测试工具实战经验。  \n3. 熟悉测试Agent技术栈（如LLM、RPA、AutoML），有自主测试系统建设经验者优先。  \n4. 精通Python/Java等语言，掌握主流测试框架及DevOps工具链。  \n5. 具备优秀的系统思维和跨团队协作能力，能推动测试Agent规模化应用。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 负责基于测试Agent的全流程质量保障工作，覆盖需求分析、测试设计、执行及缺陷闭环管理。  \n2. 构建并优化测试Agent能力，实现测试任务自主规划、用例生成、执行及结果分析的端到端自动化。  \n3. 探索测试Agent在复杂场景下的应用，如智能回归测试、异常路径挖掘及多模态交互验证。  \n4. 协同研发团队将测试Agent集成至CI/CD流程，提升测试效率与覆盖率。  \n5. 跟踪AI测试技术趋势，推动测试Agent在性能测试、安全测试等领域的创新落地。\n\n岗位基本要求\n1. 硕士研究生学历，计算机、人工智能或相关专业背景。  \n2. 5年以上测试开发经验，具备AI应用或智能测试工具实战经验。  \n3. 熟悉测试Agent技术栈（如LLM、RPA、AutoML），有自主测试系统建设经验者优先。  \n4. 精通Python/Java等语言，掌握主流测试框架及DevOps工具链。  \n5. 具备优秀的系统思维和跨团队协作能力，能推动测试Agent规模化应用。\n\n具备以下条件优先\n有AI Agent测试经验\n\n岗位亮点\n1. 主导测试Agent从0到1的落地，打造行业先进的智能测试体系。  \n2. 深度参与AI驱动的测试革命，技术成长与行业影响力双重提升。  \n3. 弹性工作制，配备高性能算力资源支持创新实验。  \n4. 成都AI产业生态完善，提供持续的技术交流与学习机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4721968881","sourceKey":"meituan_social","company":"美团","title":"资深招聘经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4721968881&jobShareType=1","duty":"1、全流程招聘交付 ：主导从需求诊断、面试评估设计、Offer 谈判到入职跟进的全流程，确保招聘质量与候选人体验；针对紧急、稀缺或跨区域疑难岗位，制定专项招聘计划，推动跨部门、跨区域协作；\n2、能够与业务管理者定期对话，深入理解业务战略与组织规划，主动输出人才市场洞察与招聘策略建议\n3、人才 Mapping 与智能寻访 ：能够定义目标公司与人才画像，通过Mapping等方法了解行业内信息，给业务部门行业内信息输入，梳理对应的寻访目标公司，构建人才地图，完善人才储备，提升招聘效率；\n4、候选人深度经营 ：能够精准洞察高端候选人的职业诉求与决策逻辑，通过持续的关系维护建立长期人才网络；在关键节点（薪酬谈判、犹豫期）提供个性化沟通策略\n5、数据驱动持续优化： 基于 AI 输出的招聘漏斗分析，诊断瓶颈环节并提出改进方案；定期复盘招聘效果，推动流程优化","requirements":"1、本科及以上学历，招聘领域有扎实的实战积累（不设硬性年限门槛，以能力和成果为评估标准）\n2、高端岗位招聘经验：有独立完成从需求诊断到 Offer 关单全流程的成功案例，有高管猎聘经验者优先\n3、候选人经营能力：擅长与高端候选人建立深度信任，有成熟的人脉网络管理方法论\n5、商业敏感度：能快速理解业务战略并转化为招聘策略，不只是执行需求而是主动输出洞察\n6、AI 工具应用意识：愿意拥抱 AI 工具，善于利用技术手段提升工作效率；至少有使用 AI 辅助工作的实际经验（如 ChatGPT、Copilot 或类似工具）","description":"部门介绍\n核心本地商业（Core Local Commerce）是美团“零售+科技”战略的重要载体，涵盖了到店餐饮、服务零售、酒店旅行、外卖、履约配送、闪购、医药健康等多个业务，覆盖了超过200个消费场景，致力于通过“随时随地”的商品和服务，满足消费者的多样性需求，帮大家吃得更好，生活更好。核心本地商业扎根本地消费，围绕消费者的“吃、住、行、游、购、娱”进行深度创新，引领发展了即时零售、团购等多种消费业态，并在全国范围内广泛投资发展本地供给、履约平台等设施，助力创造产业、带动就业。基于多年的持续投入，核心本地商业打造了连接全国超过一千万中小微企业的服务体系，以及全球最大的即时配送网络。由核心本地商业所推行的30分钟“万物到家”体系，已覆盖全国2800多个城镇，为数亿用户提供优质的商品与服务。发展过程中，核心本地商业有效助力商超、连锁、本地小店等各类实体经济主体扩大交易规模、降低交易成本。截至目前，核心本地商业日均创造订单量数千万笔，助力千万商户实现了高质量发展。未来，核心本地商业将继续践行美团“零售+科技”战略，通过更大的投资，更多的技术创新，支持、培育消费新业态，为促进消费、服务民生、带动就业作出力所能及的贡献。欢迎优秀的你加入核心本地商业，我们携手助力市场繁荣，为用户创造更好的消费体验。\n\n岗位职责\n1、全流程招聘交付 ：主导从需求诊断、面试评估设计、Offer 谈判到入职跟进的全流程，确保招聘质量与候选人体验；针对紧急、稀缺或跨区域疑难岗位，制定专项招聘计划，推动跨部门、跨区域协作；\n2、能够与业务管理者定期对话，深入理解业务战略与组织规划，主动输出人才市场洞察与招聘策略建议\n3、人才 Mapping 与智能寻访 ：能够定义目标公司与人才画像，通过Mapping等方法了解行业内信息，给业务部门行业内信息输入，梳理对应的寻访目标公司，构建人才地图，完善人才储备，提升招聘效率；\n4、候选人深度经营 ：能够精准洞察高端候选人的职业诉求与决策逻辑，通过持续的关系维护建立长期人才网络；在关键节点（薪酬谈判、犹豫期）提供个性化沟通策略\n5、数据驱动持续优化： 基于 AI 输出的招聘漏斗分析，诊断瓶颈环节并提出改进方案；定期复盘招聘效果，推动流程优化\n\n岗位基本要求\n1、本科及以上学历，招聘领域有扎实的实战积累（不设硬性年限门槛，以能力和成果为评估标准）\n2、高端岗位招聘经验：有独立完成从需求诊断到 Offer 关单全流程的成功案例，有高管猎聘经验者优先\n3、候选人经营能力：擅长与高端候选人建立深度信任，有成熟的人脉网络管理方法论\n5、商业敏感度：能快速理解业务战略并转化为招聘策略，不只是执行需求而是主动输出洞察\n6、AI 工具应用意识：愿意拥抱 AI 工具，善于利用技术手段提升工作效率；至少有使用 AI 辅助工作的实际经验（如 ChatGPT、Copilot 或类似工具）\n\n具备以下条件优先\n1、有 AI 工具在招聘场景的落地实践经验（如 AI 简历筛选、智能外呼、自动化 sourcing 等）\n2、有系统化的人才 Mapping / 市场情报搜集方法论/项目运营经验\n3、具备良好的沟通表达能力，逻辑思考能力和项目管理能力（含进程推进能力），拥有良好的客户需求沟通和管理能力；4、具备较强的自驱力，责任心，学习能力强，良好的团队协作精神、主动学习、积极驱动的能力、反应灵敏等。\n\n岗位亮点\n1.可以参与新业务从0-1搭建的过程；既能支持后线职位，也可以深入一线了解业务，拥有一线视角，提升全局观和对业务的深度理解。\n2.能力发展全面：目前所支持业务基本属于闭环业务，职位类型齐全，涵盖美团乃至互联网行业大部分职位类型，可以全面发展也可以专精几个方向；可以锻炼招聘运营的思路，用“运营”的思路做招聘。\n3.团队氛围好：友爱，有活力，目标感强，可以共同进步，协作共赢。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4684712919","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-车辆交付主管","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4684712919&jobShareType=1","duty":"1.主导重点客户物流项目从签约到稳定运营的全周期交付，统筹交付计划制定与关键里程碑验收；\n2.负责项目现场交付管理，完成作业环境评估与交付条件建设，推动项目具备落地运营条件；\n3.参与技术能力验收，确保核心功能与业务系统对接能力达到交付标准；\n4.统筹测试与试跑阶段运营管理，建立监控机制、跟踪关键指标，开展客户培训，推动客户独立运营并保障履约；\n5.统筹交付所需车辆、人力等资源配置，承担车辆全生命周期管理，保障资产安全。","requirements":"1.本科及以上学历，物流管理、交通运输、自动化、车辆工程等相关专业优先；\n2.3年以上物流运营、项目管理或相关领域交付经验，有末端配送、仓配一体化项目经验者优先；\n3.善于运用AI工具辅助数据分析与策略研究；\n4.具备较强的项目交付意识、现场执行力与跨部门协调能力，有数据敏感度和客户视角；\n5.适应高频出差，持有C1及以上驾驶证。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1.主导重点客户物流项目从签约到稳定运营的全周期交付，统筹交付计划制定与关键里程碑验收；\n2.负责项目现场交付管理，完成作业环境评估与交付条件建设，推动项目具备落地运营条件；\n3.参与技术能力验收，确保核心功能与业务系统对接能力达到交付标准；\n4.统筹测试与试跑阶段运营管理，建立监控机制、跟踪关键指标，开展客户培训，推动客户独立运营并保障履约；\n5.统筹交付所需车辆、人力等资源配置，承担车辆全生命周期管理，保障资产安全。\n\n岗位基本要求\n1.本科及以上学历，物流管理、交通运输、自动化、车辆工程等相关专业优先；\n2.3年以上物流运营、项目管理或相关领域交付经验，有末端配送、仓配一体化项目经验者优先；\n3.善于运用AI工具辅助数据分析与策略研究；\n4.具备较强的项目交付意识、现场执行力与跨部门协调能力，有数据敏感度和客户视角；\n5.适应高频出差，持有C1及以上驾驶证。\n\n具备以下条件优先\n有物流/出行、自动驾驶等行业经验者优先\n\n岗位亮点\n1. 深度参与前沿无人车技术研发与商业化探索，站在行业创新最前线；\n2. 与核心技术团队和业务专家协作，快速提升技术与商业复合能力；\n3. 提供具有竞争力的薪酬与职业发展通道。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4698736063","sourceKey":"meituan_social","company":"美团","title":"医药健康-用户体验","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4698736063&jobShareType=1","duty":"1.负责医药健康的用户体验管理工作，通过数据分析、客诉分析、行业分析等形式，洞察当前业务体验问题与机会点；\n2.与业务、产品、治理、履约、客服等组织合作，从根源探查体验问题与解决思路，制定长期方案；\n3.负责制定并跟踪用户体验提升执行方案，并跟踪指标变化，评估方案效果，确保结果符合预期。","requirements":"1.大学本科及以上学历，具有即时零售、快递电商、到店服务行业相关背景，了解业务模式特点和用户需求。\n2.具有3年以上用户体验相关经验，能够制定运营策略和执行方案。\n3.具备SQL取数能力，有良好的数据分析能力和数据驱动思维，能够根据数据结果做出相应的决策和调整。\n4.具备优秀的沟通能力和团队合作能力，能够与产品团队、技术团队等部门紧密协作，推动项目的顺利进行。\n5.具备医药、医疗、医美等行业经验优先。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.负责医药健康的用户体验管理工作，通过数据分析、客诉分析、行业分析等形式，洞察当前业务体验问题与机会点；\n2.与业务、产品、治理、履约、客服等组织合作，从根源探查体验问题与解决思路，制定长期方案；\n3.负责制定并跟踪用户体验提升执行方案，并跟踪指标变化，评估方案效果，确保结果符合预期。\n\n岗位基本要求\n1.大学本科及以上学历，具有即时零售、快递电商、到店服务行业相关背景，了解业务模式特点和用户需求。\n2.具有3年以上用户体验相关经验，能够制定运营策略和执行方案。\n3.具备SQL取数能力，有良好的数据分析能力和数据驱动思维，能够根据数据结果做出相应的决策和调整。\n4.具备优秀的沟通能力和团队合作能力，能够与产品团队、技术团队等部门紧密协作，推动项目的顺利进行。\n5.具备医药、医疗、医美等行业经验优先。\n\n具备以下条件优先\n学习能力强，有探索欲\n\n岗位亮点\n1.多业务模式与业态，探索空间充足，不仅有巨大的成长空间，更有机会做出改变行业的事；\n2.有机会与各个团队紧密合作，包括产品团队、技术团队等，拓宽自身的工作经验和技能。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4484938472","sourceKey":"meituan_social","company":"美团","title":"机器人-资深嵌入式软件工程师/专家","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4484938472&jobShareType=1","duty":"1. 负责美团无人机硬件嵌入式系统的全生命周期管理，包括设计、开发、交付与维护，确保系统安全可靠、高性能、易维护以及可观测；\n2. 热爱嵌入式领域，紧跟全球嵌入式领域前沿技术与工程实践，注重架构设计。凭借优秀架构能力和品味赋能极度高效的工程开发以及高质量的交付。关注新型MCU/SoC、嵌入式CI/CD、仿真测试框架，安全加固等技术，推动应用落地；\n3. 从架构上实现可规模化的数据驱动的工程方法，对于产品监测以及工程迭代提供客观科学的指引，并将数据驱动的意识落实到工程的细节实践中；\n4. 制定嵌入式系统技术方向，负责芯片选型与架构设计，推动实践落地，通过代码审查（C/C++、Rust）、文档规范和试设计提升工程质量；\n5. 制定MTUAV操作系统/平台技术路线图，统筹工程优先级规划、scoping、planning及交付成果管理；\n6. 对于嵌入式工作端到端负责，并主动高效的进行跨团队的沟通协同，将模糊的产品问题收敛为明确的需求，并转化为可执行的工程语言和计划，统筹项目优先级与交付成果管理；\n7. 发挥嵌入式领域技术影响力，与硬件、Linux平台及云端团队紧密协作，确保软硬件集成与产品功能一致性；\n8. 熟练使用AI工具，融入开发设计流程，探索提升团队效率的方法，输出可复用的实践案例；\n9. 指导培养初级工程师，在设计实现、代码审查、测试验证、部署维护全流程中展现优秀的工程能力与技术领导力。","requirements":"1. 计算机科学、计算机工程、电子工程或相关专业，5年以上嵌入式软件开发经验，精通C/C++，具备RTOS（FreeRTOS/Zephyr/RT-Thread等）及裸机开发实战经验；\n2. 作为核心开发者或技术负责人，完整主导过嵌入式产品化项目，包括上市后迭代优化；\n3. 具有产品级架构设计影响力，能独立调试软硬件复杂系统，有可验证的业绩成果；\n4. 深耕工程专业，兼具产品与全局系统化思维，关注工作如何与业务和产品结合，确保专业工作的统筹、优先级和方向与业务目标一致；\n5. 拥有通过优秀工程实践推动团队技术提升的成功案例；\n6. 具备优秀的跨部门沟通能力、系统化思维及复杂问题解决能力；\n7. 具备成熟健康的职业素养，开放学习心态，高度自驱，兼具技术领导力与强烈的结果责任感；\n8. 熟练使用AI主流工具，能将AI工具有效融入开发日常工作流。","description":"部门介绍\n为了更好地提升城市即时配送的效率与体验，2017年，美团启动了无人机配送服务的探索，通过科技创新推动履约工具变革，加快建设空地协同的本地即时配送网络。\n在过去的六年里，美团无人机完成了飞行器、自动化机场及智能调度系统的研发工作，实现了研发设计、生产制造、运营运维全链条布局，达成了城市复杂场景物流无人机高频次、高密度、多天时、多天侯运行。\n2023年7月，美团无人机在上海发布了自主研发的第四代无人机，跟此前机型相比，新机型升级了环境适应能力，可在“零下20度至50度”的中雨、中雪、6级风、弱光等环境中稳定飞行，能够适应97%以上国内城市的自然环境要求。\n截至2024年12月，美团无人机已在深圳、北京、上海、广州、南京、迪拜等城市开通53条航线，并累计完成订单超40万单。即时零售配送服务覆盖了办公、社区、景区、市政公园、校园、医疗、图书馆等多种场景。在医疗场景中，美团无人机可围绕医疗血液、检验样本、院前急救物资、特殊药品等医疗物资配送需求建设端到端的全天时急送网络。\n\n岗位职责\n1. 负责美团无人机硬件嵌入式系统的全生命周期管理，包括设计、开发、交付与维护，确保系统安全可靠、高性能、易维护以及可观测；\n2. 热爱嵌入式领域，紧跟全球嵌入式领域前沿技术与工程实践，注重架构设计。凭借优秀架构能力和品味赋能极度高效的工程开发以及高质量的交付。关注新型MCU/SoC、嵌入式CI/CD、仿真测试框架，安全加固等技术，推动应用落地；\n3. 从架构上实现可规模化的数据驱动的工程方法，对于产品监测以及工程迭代提供客观科学的指引，并将数据驱动的意识落实到工程的细节实践中；\n4. 制定嵌入式系统技术方向，负责芯片选型与架构设计，推动实践落地，通过代码审查（C/C++、Rust）、文档规范和试设计提升工程质量；\n5. 制定MTUAV操作系统/平台技术路线图，统筹工程优先级规划、scoping、planning及交付成果管理；\n6. 对于嵌入式工作端到端负责，并主动高效的进行跨团队的沟通协同，将模糊的产品问题收敛为明确的需求，并转化为可执行的工程语言和计划，统筹项目优先级与交付成果管理；\n7. 发挥嵌入式领域技术影响力，与硬件、Linux平台及云端团队紧密协作，确保软硬件集成与产品功能一致性；\n8. 熟练使用AI工具，融入开发设计流程，探索提升团队效率的方法，输出可复用的实践案例；\n9. 指导培养初级工程师，在设计实现、代码审查、测试验证、部署维护全流程中展现优秀的工程能力与技术领导力。\n\n岗位基本要求\n1. 计算机科学、计算机工程、电子工程或相关专业，5年以上嵌入式软件开发经验，精通C/C++，具备RTOS（FreeRTOS/Zephyr/RT-Thread等）及裸机开发实战经验；\n2. 作为核心开发者或技术负责人，完整主导过嵌入式产品化项目，包括上市后迭代优化；\n3. 具有产品级架构设计影响力，能独立调试软硬件复杂系统，有可验证的业绩成果；\n4. 深耕工程专业，兼具产品与全局系统化思维，关注工作如何与业务和产品结合，确保专业工作的统筹、优先级和方向与业务目标一致；\n5. 拥有通过优秀工程实践推动团队技术提升的成功案例；\n6. 具备优秀的跨部门沟通能力、系统化思维及复杂问题解决能力；\n7. 具备成熟健康的职业素养，开放学习心态，高度自驱，兼具技术领导力与强烈的结果责任感；\n8. 熟练使用AI主流工具，能将AI工具有效融入开发日常工作流。\n\n具备以下条件优先\n1. 拥有机器人、实时控制系统、飞行控制或自动驾驶领域从业经验，或具备大规模商用MCU系统产品开发及维护经验；\n2. 具有在大型嵌入式系统部署中建立数据驱动观测能力的实战经验；\n3. 除了C/C++以外，精通至少一种现代系统编程语言（如嵌入式系统开发常用的Rust）；\n4. 熟悉电机控制、传感器融合或电源管理系统相关知识；\n5. 具备实施安全启动（secure boot）、加密算法等嵌入式安全方案的经验；\n6. 拥有为嵌入式项目构建和维护CI/CD流水线（如Jenkins、Gerrit）及硬件在环（HIL）测试系统的经验；\n7. 具有在工程项目中定制，集成 AI 工具，并为项目以及研发团队提效有具体落地案例；\n8. 2年以上技术领导或管理经验，具备成功主导工程项目及有效管理团队的良好记录。\n\n岗位亮点\n这是一个早期快速发展的项目，岗位可参与产品到工程全链条的探索和发展，影响力大。技术深度足，业务可见度高，战略价值真实。\n我们正在建设一支追求出色的工程结果，优雅的工程品味以及卓越工程效率的一流嵌入式软件团队，为持续演进的硬件、传感器和算力平台，提供统一、高效、稳定的嵌入式系统底座。 \n我们诚邀行业内的杰出人才，和我们一起建设一支世界一流嵌入式软件团队。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4164768170","sourceKey":"meituan_social","company":"美团","title":"KA大客户品牌经理（西式快餐）","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4164768170&jobShareType=1","duty":"1.对接全球性西式快餐品牌\n2.与品牌方共同制定年度生意计划，包含经营目标、年度营销规划、深度合作规划等\n3.规划落地：制定季度/月度经营规划、推进落地、及时复盘\n4.数据分析：出具外卖经营诊断报告帮助品牌方定位问题解决问题，提升经营效率\n5.及时跟踪及处理客户反馈，针对各项目进行基础流程优化和改善，维护客户关系；\n6.负责整理客户资料及档案、销售协议、合同等存档管理；\n7.收集客户有关信息和需求，相关市场讯息的挖掘与整理收集，完成相关销售报表","requirements":"1.本科以上学历，3年-5年以上工作经验，有外卖运营经验优先；\n2.具有较强的组织协调力、统筹力、执行力；\n3.良好的沟通表达能力及较强的数据处理能力，熟练掌握办公工具；\n4.工作积极主动，耐心细致，责任心强，富于团队协作精神，具备综合、系统分析驾驭能力，善于沟通；","description":"部门介绍\n美团外卖秉承“帮大家吃得更好，生活更好”的使命，始终聚焦于消费者用餐需求。我们通过科技连接消费者和商家，依托庞大的骑手团队，以“线上+线下”的业务模式，为消费者提供品质化、精细化、多样化的餐饮外卖服务。\n外卖事业部是为用户与商家提供全链路交易服务的业务组织，围绕餐饮外卖搭建了包含外卖业务与创新孵化业务在内的多个部门。\n我们的目标是帮助商家开源增收、提高经营效率，促进餐饮行业数字化，以及为更多用户提供更便捷更有品质的外卖服务。加入我们，一起为上亿用户提供更好的用餐体验，帮助大家吃得更好，生活更好！\n\n岗位职责\n1.对接全球性西式快餐品牌\n2.与品牌方共同制定年度生意计划，包含经营目标、年度营销规划、深度合作规划等\n3.规划落地：制定季度/月度经营规划、推进落地、及时复盘\n4.数据分析：出具外卖经营诊断报告帮助品牌方定位问题解决问题，提升经营效率\n5.及时跟踪及处理客户反馈，针对各项目进行基础流程优化和改善，维护客户关系；\n6.负责整理客户资料及档案、销售协议、合同等存档管理；\n7.收集客户有关信息和需求，相关市场讯息的挖掘与整理收集，完成相关销售报表\n\n岗位基本要求\n1.本科以上学历，3年-5年以上工作经验，有外卖运营经验优先；\n2.具有较强的组织协调力、统筹力、执行力；\n3.良好的沟通表达能力及较强的数据处理能力，熟练掌握办公工具；\n4.工作积极主动，耐心细致，责任心强，富于团队协作精神，具备综合、系统分析驾驭能力，善于沟通；\n\n具备以下条件优先\n1、外卖运营、连锁餐饮品牌经验者优先\n2、熟悉食品供应链者优先\n3、具备定制化解决方案经验优先\n\n岗位亮点\n1.共同服务于全球知名的大型连锁餐饮品牌，能够在大客户销售专业领域逐步建立自身的知识框架和专业积累。\n2.机会参与美团外卖复杂业务及跨部门重大业务项目的推进及协调工作。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4721163866","sourceKey":"meituan_social","company":"美团","title":"高级经营分析专家（全球目标与经营管理方向）","city":"北京市/香港特别行政区","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4721163866&jobShareType=1","duty":"1. 统筹多个海外市场的年度经营规划，建立统一的规划节奏、国家目标包、核心假设口径和管理层决策流程。\n2. 结合市场空间、竞争格局、发展阶段、组织能力和战略要求，对不同国家进行经营定位，提出规模、份额、盈利、用户、供给或模式验证等目标优先级。\n3. 建立自上而下与自下而上相结合的目标校验机制，判断国家计划与全球战略是否一致，不同国家的目标压力和资源配置是否合理、可解释。\n4. 将订单、用户、供给、履约、定价、补贴、收入和利润等关键变量纳入目标模型，识别增长路径、资源需求、回报质量和关键约束。\n5. 统筹月度滚动预测，持续更新全年预估、目标偏差、资源变化和关键假设，形成跨国横向比较、风险分级及待决策事项。\n6. 面向高级管理层和国家 GM 输出清晰的经营判断，讲清事实、假设、选择和代价，推动目标调整、资源配置及关键经营动作形成决策。\n7. 沉淀全球目标管理方法，包括国家分型、目标拆解、资源回报测算、关键假设库、风险升级标准和典型案例，并推动目标管理 AI 工具建设和应用。","requirements":"1. 5 年及以上经营分析、商业分析、战略规划、战略财务或目标预算相关经验，能够独立负责一个业务线、区域或多个国家的目标与经营管理。\n2. 完整参与过年度经营规划、预算、滚动预测和经营复盘。能基于市场阶段和战略选择设计目标，具备较强的 P&L、单位经济和资源效率意识，能够讲清规模、份额、用户价值、供给、履约、补贴、收入和利润之间的关系。\n3. 具备跨业务、跨职能项目推动能力，推动国家商分、GM、财务、业务和数据团队共同完成复杂交付。\n4. 具备优秀的管理层表达和书面表达能力，能将复杂分析转化为可讨论、可选择、可执行的管理建议。\n5. 熟练使用 SQL 和常用分析工具，能够独立完成业务测算和数据校验；能在英文环境下工作，接受跨时区协作及必要的海外出差。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. 统筹多个海外市场的年度经营规划，建立统一的规划节奏、国家目标包、核心假设口径和管理层决策流程。\n2. 结合市场空间、竞争格局、发展阶段、组织能力和战略要求，对不同国家进行经营定位，提出规模、份额、盈利、用户、供给或模式验证等目标优先级。\n3. 建立自上而下与自下而上相结合的目标校验机制，判断国家计划与全球战略是否一致，不同国家的目标压力和资源配置是否合理、可解释。\n4. 将订单、用户、供给、履约、定价、补贴、收入和利润等关键变量纳入目标模型，识别增长路径、资源需求、回报质量和关键约束。\n5. 统筹月度滚动预测，持续更新全年预估、目标偏差、资源变化和关键假设，形成跨国横向比较、风险分级及待决策事项。\n6. 面向高级管理层和国家 GM 输出清晰的经营判断，讲清事实、假设、选择和代价，推动目标调整、资源配置及关键经营动作形成决策。\n7. 沉淀全球目标管理方法，包括国家分型、目标拆解、资源回报测算、关键假设库、风险升级标准和典型案例，并推动目标管理 AI 工具建设和应用。\n\n岗位基本要求\n1. 5 年及以上经营分析、商业分析、战略规划、战略财务或目标预算相关经验，能够独立负责一个业务线、区域或多个国家的目标与经营管理。\n2. 完整参与过年度经营规划、预算、滚动预测和经营复盘。能基于市场阶段和战略选择设计目标，具备较强的 P&L、单位经济和资源效率意识，能够讲清规模、份额、用户价值、供给、履约、补贴、收入和利润之间的关系。\n3. 具备跨业务、跨职能项目推动能力，推动国家商分、GM、财务、业务和数据团队共同完成复杂交付。\n4. 具备优秀的管理层表达和书面表达能力，能将复杂分析转化为可讨论、可选择、可执行的管理建议。\n5. 熟练使用 SQL 和常用分析工具，能够独立完成业务测算和数据校验；能在英文环境下工作，接受跨时区协作及必要的海外出差。\n\n具备以下条件优先\n1. 有外卖、即时零售、电商、出行、酒旅或其他平台型业务经验。\n2. 有海外多国经营、新市场从 0 到 1、区域目标统筹经验。\n3. 做过市场进入、国家战略定位、目标预算、资源配置、滚动预测或盈利规划。\n4. 曾直接支持 CEO、区域负责人、国家 GM 或事业部负责人进行经营决策。\n5. 有将目标管理方法沉淀为模板、机制、数据产品或 AI 工具的经验。\n\n岗位亮点\n1. 我们期待你真正参与目标选择和资源取舍，让年度规划能够被持续追踪、验证和调整，并将多国经营经验沉淀为组织能力。\n2. 你会面对不同市场阶段、竞争环境和经营约束下的真实问题，需要在不完全信息中形成判断，也有机会参与 Keeta 全球经营管理机制从建立到成熟的全过程。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4647648944","sourceKey":"meituan_social","company":"美团","title":"闪购-店铺运营专家-华北","city":"北京市/青岛市/石家庄市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4647648944&jobShareType=1","duty":"1.根据区域消费特征及市场行情变化，制定城市/门店差异化运营策略（包含但不限于门店选址/商品运营/营销活动/门店营运管理/流量投放等）；\n2.协调内外部营销活动资源，指导并监督合作商落地执行，实现品牌销售增长目标；\n3.对合作商及门店日常运营进行监控，对运营数据进行分析，及时发现异常并探寻可增长点；\n4.负责建立日常运营管理工具，为运营监控提效，为合作商赋能；\n5.负责与协同部门及合作商密切沟通，促进品牌整体运营结果达成和策略落地。","requirements":"1.有连锁品牌线上运营管理经验，熟悉外卖运营规则，超市便利品类优先；\n2.有较强的数据分析能力，熟练使用SQL优先；\n3.有较强的多方协同能力、沟通能力；\n4.有较强的有自驱力、执行力；\n5.能适应快速变化及快节奏工作。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.根据区域消费特征及市场行情变化，制定城市/门店差异化运营策略（包含但不限于门店选址/商品运营/营销活动/门店营运管理/流量投放等）；\n2.协调内外部营销活动资源，指导并监督合作商落地执行，实现品牌销售增长目标；\n3.对合作商及门店日常运营进行监控，对运营数据进行分析，及时发现异常并探寻可增长点；\n4.负责建立日常运营管理工具，为运营监控提效，为合作商赋能；\n5.负责与协同部门及合作商密切沟通，促进品牌整体运营结果达成和策略落地。\n\n岗位基本要求\n1.有连锁品牌线上运营管理经验，熟悉外卖运营规则，超市便利品类优先；\n2.有较强的数据分析能力，熟练使用SQL优先；\n3.有较强的多方协同能力、沟通能力；\n4.有较强的有自驱力、执行力；\n5.能适应快速变化及快节奏工作。\n\n岗位亮点\n1.有机会从0-1跟随项目成长，更广阔的的视角，更多的机会与发展空间；\n2.工作氛围简单、直接、开放、高效。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4491564181","sourceKey":"meituan_social","company":"美团","title":"酒店直连通道运营专家","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4491564181&jobShareType=1","duty":"1.负责酒店直连通道的运营管理，统筹商家侧咨询响应机制、预订链路监控及异常问题的协调处理，保障直连交易链路的稳定性与高效性；\n2.负责商家供给运营体系的管理与优化，推进供应商、酒店及房型产品的上下线运营和营销配置标准化，持续提升供给质量与运营效率；合理配置监控报警机制，确保异常信息准确触达相关方。\n3.负责境内重点酒店商家的供给运营，通过数据分析和一线调研洞察供给问题，联动产品与业务团队制定解决方案并推动落地，闭环负责商家供给策略的产出与结果达成。\n4.负责直连/预付产品策略的制定与运营，推动核心商家供给质量提升；多方协同确保产品策略在商家端的有效执行与闭环。\n5.通过数据归因识别供给机会，持续优化商家供给效率指标；定期输出业务数据分析报告，为运营决策提供数据支持；沉淀共性问题与知识库，探索AI工具在运营场景的落地应用。","requirements":"1.大学本科及以上学历，5年以上酒店/旅游/OTA行业相关经验。\n2.熟悉重点商家的供给运营模式；熟悉商家分层分类、供应链经营成本分析、供需联动相关知识。\n3.具备OTA产品运营、B端商家运营或商务合作经验者优先；有供给运营或业主关系经验优先。\n4.具备优秀的数据分析能力，能通过数据归因识别供给问题并推动改进；有熟练的项目复盘能力；具备体系性思考能力，表达逻辑清晰。\n5.具备出色的沟通理解能力、团队合作能力与项目推动管理能力，能高效协同多部门落地项目。\n6.能结合AI工具输出做业务判断，具备与AI产品团队协同的经验优先；对大模型在B端运营场景的应用有基础认知。\n7.学习能力强，自我驱动，有韧劲。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1.负责酒店直连通道的运营管理，统筹商家侧咨询响应机制、预订链路监控及异常问题的协调处理，保障直连交易链路的稳定性与高效性；\n2.负责商家供给运营体系的管理与优化，推进供应商、酒店及房型产品的上下线运营和营销配置标准化，持续提升供给质量与运营效率；合理配置监控报警机制，确保异常信息准确触达相关方。\n3.负责境内重点酒店商家的供给运营，通过数据分析和一线调研洞察供给问题，联动产品与业务团队制定解决方案并推动落地，闭环负责商家供给策略的产出与结果达成。\n4.负责直连/预付产品策略的制定与运营，推动核心商家供给质量提升；多方协同确保产品策略在商家端的有效执行与闭环。\n5.通过数据归因识别供给机会，持续优化商家供给效率指标；定期输出业务数据分析报告，为运营决策提供数据支持；沉淀共性问题与知识库，探索AI工具在运营场景的落地应用。\n\n岗位基本要求\n1.大学本科及以上学历，5年以上酒店/旅游/OTA行业相关经验。\n2.熟悉重点商家的供给运营模式；熟悉商家分层分类、供应链经营成本分析、供需联动相关知识。\n3.具备OTA产品运营、B端商家运营或商务合作经验者优先；有供给运营或业主关系经验优先。\n4.具备优秀的数据分析能力，能通过数据归因识别供给问题并推动改进；有熟练的项目复盘能力；具备体系性思考能力，表达逻辑清晰。\n5.具备出色的沟通理解能力、团队合作能力与项目推动管理能力，能高效协同多部门落地项目。\n6.能结合AI工具输出做业务判断，具备与AI产品团队协同的经验优先；对大模型在B端运营场景的应用有基础认知。\n7.学习能力强，自我驱动，有韧劲。\n\n具备以下条件优先\n1.有供给运营或商家关系管理经验。\n2.有OTA平台商家运营或产品运营经验。\n3.对直连产品（系统对接、通道建设等）有基础认知。\n4.了解大模型在B端运营场景的应用方向。\n\n岗位亮点\n1.参与核心商家的供给业务，对接行业头部品牌；岗位职能兼具体系建设和业务实践。\n2.主导产品策略从需求到落地的全链路；可构建深入的业务领域知识体系，有机会在多个细分领域探索、积累、实践。\n3.独立owner方向，接触直连/预付等产品体系，提升跨业务环节的系统化运营能力。\n4.团队氛围开放、友好，具备业务与产品方法论体系及培养机制。\n5.发展方向清晰：入职以通道运营为核心，积累业务理解后可向供给运营、策略运营方向发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4721095543","sourceKey":"meituan_social","company":"美团","title":"上海仓拣库存主管","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4721095543&jobShareType=1","duty":"1. 负责上海仓拣货区域的日常运营管理，确保拣货、补货、盘点等作业高效有序进行。  \n2. 管理并带领团队，制定排班计划，监督执行标准操作流程，提升团队作业效率。  \n3. 监控库存准确率，组织定期盘点，分析差异原因并推动改进措施落地。  \n4. 协同仓储运营团队，优化拣货路径与库存布局，降低作业成本。  \n5. 落实安全管理制度，开展员工培训，营造安全、规范的工作环境。","requirements":"1. 大学专科及以上学历，物流、供应链或相关专业优先。  \n2. 具备3年以上仓储物流现场管理经验，有电商或快消行业背景者优先。  \n3. 熟悉WMS系统操作及库存管理流程，具备数据分析与问题解决能力。  \n4. 具备较强的团队管理与沟通协调能力，能承受一定工作压力。  \n5. 熟练使用办公软件，具备基本的英语读写能力。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责上海仓拣货区域的日常运营管理，确保拣货、补货、盘点等作业高效有序进行。  \n2. 管理并带领团队，制定排班计划，监督执行标准操作流程，提升团队作业效率。  \n3. 监控库存准确率，组织定期盘点，分析差异原因并推动改进措施落地。  \n4. 协同仓储运营团队，优化拣货路径与库存布局，降低作业成本。  \n5. 落实安全管理制度，开展员工培训，营造安全、规范的工作环境。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、供应链或相关专业优先。  \n2. 具备3年以上仓储物流现场管理经验，有电商或快消行业背景者优先。  \n3. 熟悉WMS系统操作及库存管理流程，具备数据分析与问题解决能力。  \n4. 具备较强的团队管理与沟通协调能力，能承受一定工作压力。  \n5. 熟练使用办公软件，具备基本的英语读写能力。\n\n岗位亮点\n1. 大型仓储团队管理经验积累，快速提升综合管理能力。  \n2. 位于上海核心物流枢纽，业务规模大，发展平台广阔。  \n3. 完善的培训体系与晋升通道，支持个人职业成长。  \n4. 行业具有竞争力的薪酬福利与绩效激励机制。  \n5. 扁平化管理氛围，注重员工发展与团队协作。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4435462200","sourceKey":"meituan_social","company":"美团","title":"AI支付产品经理","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4435462200&jobShareType=1","duty":"负责AI 支付产品的整体规划与路线图制定，定义产品边界、体验标准与演进节奏，推动从0到1的产品落地。\n\n深入了解业务场景，识别业务痛点，聚焦支付核心链路，构建主动服务型智能产品，提升平台整体效率与用户体验。\n\n通过新的协作范式，完成产品方案设计，与协作团队紧密配合，把控从方案到上线的完整交付链路；建立产品效果评估体系，通过数据与用户反馈持续优化产品体验。\n\n持续观察行业最前沿的技术能力及应用实例，为团队输入有效的信息。","requirements":"3年以上互联网产品经验，了解 LLM/Agent 技术原理，有 AI 产品实践经验。有金融支付背景优先。\n\n具备优秀的用户洞察与需求分析能力，能够独立完成复杂产品方案设计、设计评测方案、分析线上数据。\n\n有良好的学习能力和自驱力，持续关注行业前沿，输出可落地的产品建议。","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n负责AI 支付产品的整体规划与路线图制定，定义产品边界、体验标准与演进节奏，推动从0到1的产品落地。\n\n深入了解业务场景，识别业务痛点，聚焦支付核心链路，构建主动服务型智能产品，提升平台整体效率与用户体验。\n\n通过新的协作范式，完成产品方案设计，与协作团队紧密配合，把控从方案到上线的完整交付链路；建立产品效果评估体系，通过数据与用户反馈持续优化产品体验。\n\n持续观察行业最前沿的技术能力及应用实例，为团队输入有效的信息。\n\n岗位基本要求\n3年以上互联网产品经验，了解 LLM/Agent 技术原理，有 AI 产品实践经验。有金融支付背景优先。\n\n具备优秀的用户洞察与需求分析能力，能够独立完成复杂产品方案设计、设计评测方案、分析线上数据。\n\n有良好的学习能力和自驱力，持续关注行业前沿，输出可落地的产品建议。\n\n岗位亮点\n美团有丰富的业务场景，AI 落地空间极大，参与并推动AI支付产品从 0 到 1 的落地。\n\n美团连接数亿用户与千万商家，支付作为连接交易、资金与商业的关键环节，价值巨大。\n\n新团队刚成立，扁平化管理，产研一体，汇报给业务负责人，流程简单高效，想法快速落地。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4676963042","sourceKey":"meituan_social","company":"美团","title":"净菜运营总监","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4676963042&jobShareType=1","duty":"1. 负责净菜业务的整体运营规划与管理，制定并执行运营策略，提升运营效率与服务质量。  \n2. 协同供应链各环节，包括采购、品控、加工、配送等，确保流程标准化与成本优化。  \n3. 带领团队完成日常运营目标，监控关键指标，及时调整运营方案以应对市场变化。  \n4. 推动净菜产品标准化建设，保证质量目标达成；  \n5. 根据公司下发目标，制定经营策略，提升毛利降低成本，带领团队逐步拓展深加工边界拓展.","requirements":"1. 大学本科及以上学历，物流\\食品科学或相关专业优先。  \n2. 具备8年以上生鲜运营相关工作经验，有净菜、预制菜背景者优先。  \n3. 具备资深运营管理能力，有100人以上团队管理经验，擅长跨部门协作与资源整合。  \n4. 熟悉生鲜供应链全流程，对食品安全、冷链物流、仓储管理有深入理解。  \n5. 具备较强的数据分析能力与战略思维，能独立制定并推动运营策略落地。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责净菜业务的整体运营规划与管理，制定并执行运营策略，提升运营效率与服务质量。  \n2. 协同供应链各环节，包括采购、品控、加工、配送等，确保流程标准化与成本优化。  \n3. 带领团队完成日常运营目标，监控关键指标，及时调整运营方案以应对市场变化。  \n4. 推动净菜产品标准化建设，保证质量目标达成；  \n5. 根据公司下发目标，制定经营策略，提升毛利降低成本，带领团队逐步拓展深加工边界拓展.\n\n岗位基本要求\n1. 大学本科及以上学历，物流\\食品科学或相关专业优先。  \n2. 具备8年以上生鲜运营相关工作经验，有净菜、预制菜背景者优先。  \n3. 具备资深运营管理能力，有100人以上团队管理经验，擅长跨部门协作与资源整合。  \n4. 熟悉生鲜供应链全流程，对食品安全、冷链物流、仓储管理有深入理解。  \n5. 具备较强的数据分析能力与战略思维，能独立制定并推动运营策略落地。\n\n具备以下条件优先\n1、具有净菜和沙拉菜生产管理者优先；\n2、具有城市管理和中台运营能力者优先；\n\n岗位亮点\n1. 加入快速发展的生鲜行业，参与净菜业务从0到1的规模化建设。  \n2. 拥有高度自主权，全面负责运营体系搭建与团队管理。  \n 3. 工作地点位于北京，享受具有竞争力的薪酬与职业发展通道。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4645387574","sourceKey":"meituan_social","company":"美团","title":"仓储经理","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4645387574&jobShareType=1","duty":"1.负责RDC仓库的日常运营管理工作，包括入库、出库、库存管理等，确保仓库运作顺畅。\n2.负责制定并执行仓库的作业流程和标准操作规范，提高工作效率和准确性。\n3.负责团队的日常管理和指导，培训新员工，提升团队整体素质。\n4.负责仓库设备的维护和保养，确保设备正常运转。\n5.协调内部各部门，保障仓库运营的顺利进行。","requirements":"1.大学专科及以上学历，物流管理、仓储管理等相关专业优先。\n2.具有5年以上物流/仓储运营管理经验，有大型RDC仓库管理经验者优先。\n3.具备良好的团队管理能力和沟通协调能力，能够有效领导团队达成目标。\n4.熟悉仓储管理系统和操作流程，具备较强的数据分析能力和问题解决能力。\n5.有韧性，由良好的应变能力，能够应对复杂的工作环境和突发事件。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责RDC仓库的日常运营管理工作，包括入库、出库、库存管理等，确保仓库运作顺畅。\n2.负责制定并执行仓库的作业流程和标准操作规范，提高工作效率和准确性。\n3.负责团队的日常管理和指导，培训新员工，提升团队整体素质。\n4.负责仓库设备的维护和保养，确保设备正常运转。\n5.协调内部各部门，保障仓库运营的顺利进行。\n\n岗位基本要求\n1.大学专科及以上学历，物流管理、仓储管理等相关专业优先。\n2.具有5年以上物流/仓储运营管理经验，有大型RDC仓库管理经验者优先。\n3.具备良好的团队管理能力和沟通协调能力，能够有效领导团队达成目标。\n4.熟悉仓储管理系统和操作流程，具备较强的数据分析能力和问题解决能力。\n5.有韧性，由良好的应变能力，能够应对复杂的工作环境和突发事件。\n\n岗位亮点\n1.薪资福利优厚，提供完善的培训和晋升机会。\n2.工作地点灵活，可选择在上海市或苏州市。\n3.所属团队规模适中，工作氛围轻松愉快，有较大的发展空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4665479999","sourceKey":"meituan_social","company":"美团","title":"运筹优化算法工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4665479999&jobShareType=1","duty":"1. 负责骑行换电&资产业务相关的运筹优化算法设计、研发和迭代优化，包括但不限于资产找寻调度、换电调度、换电智能排班、换电站点选址、换电责任田划分等\n\n2. 参与算法体系搭建，抽象并定义算法问题、算法技术选型、模型搭建、落地推广应用，实现业务效果优化\n\n3. 深入了解业务，与产品、工程、数据、业务团队密切合作，持续推动从算法技术到业务价值的转化，驱动业务变革\n\n4. 综合运用机器学习、运筹优化、强化学习、因果推断、大模型等前沿技术优化骑行领域的相关问题","requirements":"1. 硕士研究生及以上学历，专业背景为运筹学、数学、计算机科学等相关领域\n\n2. 熟悉常用的运筹调度算法和模型优化方法，具备扎实的运筹优化理论基础\n\n3. 熟悉运筹调度问题的建模和求解，具备扎实的数学基础和优秀的分析能力\n\n4. 熟练掌握至少一种编程语言，如Java、Python、C++等，并具备良好的编程能力\n\n5. 具备良好的沟通能力和团队合作精神，能够与各个团队紧密合作，解决问题\n\n6. 具备较强的自我驱动力和学习能力，了解常用 AI Coding 工作范式、方法论等","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. 负责骑行换电&资产业务相关的运筹优化算法设计、研发和迭代优化，包括但不限于资产找寻调度、换电调度、换电智能排班、换电站点选址、换电责任田划分等\n\n2. 参与算法体系搭建，抽象并定义算法问题、算法技术选型、模型搭建、落地推广应用，实现业务效果优化\n\n3. 深入了解业务，与产品、工程、数据、业务团队密切合作，持续推动从算法技术到业务价值的转化，驱动业务变革\n\n4. 综合运用机器学习、运筹优化、强化学习、因果推断、大模型等前沿技术优化骑行领域的相关问题\n\n岗位基本要求\n1. 硕士研究生及以上学历，专业背景为运筹学、数学、计算机科学等相关领域\n\n2. 熟悉常用的运筹调度算法和模型优化方法，具备扎实的运筹优化理论基础\n\n3. 熟悉运筹调度问题的建模和求解，具备扎实的数学基础和优秀的分析能力\n\n4. 熟练掌握至少一种编程语言，如Java、Python、C++等，并具备良好的编程能力\n\n5. 具备良好的沟通能力和团队合作精神，能够与各个团队紧密合作，解决问题\n\n6. 具备较强的自我驱动力和学习能力，了解常用 AI Coding 工作范式、方法论等\n\n岗位亮点\n1. 业务价值高：核心决策岗位，算法方案直接作用于业务关键运营指标，从底层驱动成本优化与效率提升，技术投入的 ROI 高度可量化\n\n2. 技术纵深广：深度融合运筹优化、机器学习、强化学习等多技术栈，技术挑战覆盖从复杂业务建模、大规模高效求解到在线自适应决策的完整算法链路","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4687058259","sourceKey":"meituan_social","company":"美团","title":"丽人行业专家（美发方向）","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4687058259&jobShareType=1","duty":"1、行业经营\n对所负责细分行业的经营结果端到端负责，包括收入（CPS/CPC/增值服务）、交易规模（GTV）、补贴效率与投入产出比，独立完成年度/季度运营规划与目标拆解；\n基于市场规模、竞争格局、供需结构的定量分析，判断行业所处阶段与核心矛盾，识别增长杠杆；\n\n2、产运端到端闭环\n不止于提出需求，而是定义产品：基于对用户决策链路和商家经营流程的理解，输出产品策略与方案，与协作团队共同完成从 0 到 1 的能力建设；\n打通「策略设计 → 产品落地 → 运营放大 → 效果归因 → 策略迭代」的完整闭环，对闭环中的每一环负责，而非只负责其中一段；\n推动能力从单点验证走向规模化：把为头部客户定制的解决方案，抽象为可低成本复制的标准产品与 SOP。\n\n3、商家分层经营与生态建设\n基于商家规模、经营意识、数字化程度进行分层，针对不同层级设计差异化的产品组合、激励政策与服务模式；\n\n4、方法论沉淀\n将实践中验证有效的策略抽象为可迁移的方法论，形成可复制的行业解决方案；","requirements":"本科及以上学历，3 年以上产品、行业运营、商家运营、产品运营或战略/商业分析经验；\n有完整负责过一个业务单元或从 0 到 1 项目的经历，能清晰讲出自己的判断逻辑与结果归因。\n\n核心能力要求\n① 行业洞察力\n掌握结构化的行业分析方法，能独立完成市场规模测算、竞争格局分析、供需结构拆解和上下游产业链梳理；\n对线下商业的真实经营逻辑有体感——理解一家门店的成本结构、人员激励、获客路径，而非只看得懂线上数据；\n\n② 产品闭环能力\n具备产品思维，能独立输出产品策略、参与方案设计，与产研团队高效对话；\n理解 AI 时代的产品设计范式差异——从「设计操作流程」转向「定义目标与约束」，从「控制每一步」转向「信任与验证结果」；\n有推动复杂产品从设计到上线到规模化覆盖的完整经验。\n\n③ AI 应用能力\n在实际工作中高频使用 AI 完成分析、内容生产、方案设计等任务，对 AI 的能力边界与失效模式有真实体感；\n加分项：有 Agent/AI 产品的设计或落地经验，理解评测体系、知识库建设、工具调用等核心机制；\n\n④ 数据驱动\n强数据敏感度，能通过指标异动定位业务问题，建立输入-输出指标体系并持续迭代；\n能用数据支撑决策与说服，而非用观点说服。\n\n⑤ 推动力与影响力\n具备复杂项目的跨组织协调能力，能在多方目标不一致时找到共识路径；\n具备面对高模糊度问题时的韧性——从定策略、到多方对齐、到能力迭代、到销售侧落地，链条长、周期久、变量多。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1、行业经营\n对所负责细分行业的经营结果端到端负责，包括收入（CPS/CPC/增值服务）、交易规模（GTV）、补贴效率与投入产出比，独立完成年度/季度运营规划与目标拆解；\n基于市场规模、竞争格局、供需结构的定量分析，判断行业所处阶段与核心矛盾，识别增长杠杆；\n\n2、产运端到端闭环\n不止于提出需求，而是定义产品：基于对用户决策链路和商家经营流程的理解，输出产品策略与方案，与协作团队共同完成从 0 到 1 的能力建设；\n打通「策略设计 → 产品落地 → 运营放大 → 效果归因 → 策略迭代」的完整闭环，对闭环中的每一环负责，而非只负责其中一段；\n推动能力从单点验证走向规模化：把为头部客户定制的解决方案，抽象为可低成本复制的标准产品与 SOP。\n\n3、商家分层经营与生态建设\n基于商家规模、经营意识、数字化程度进行分层，针对不同层级设计差异化的产品组合、激励政策与服务模式；\n\n4、方法论沉淀\n将实践中验证有效的策略抽象为可迁移的方法论，形成可复制的行业解决方案；\n\n岗位基本要求\n本科及以上学历，3 年以上产品、行业运营、商家运营、产品运营或战略/商业分析经验；\n有完整负责过一个业务单元或从 0 到 1 项目的经历，能清晰讲出自己的判断逻辑与结果归因。\n\n核心能力要求\n① 行业洞察力\n掌握结构化的行业分析方法，能独立完成市场规模测算、竞争格局分析、供需结构拆解和上下游产业链梳理；\n对线下商业的真实经营逻辑有体感——理解一家门店的成本结构、人员激励、获客路径，而非只看得懂线上数据；\n\n② 产品闭环能力\n具备产品思维，能独立输出产品策略、参与方案设计，与产研团队高效对话；\n理解 AI 时代的产品设计范式差异——从「设计操作流程」转向「定义目标与约束」，从「控制每一步」转向「信任与验证结果」；\n有推动复杂产品从设计到上线到规模化覆盖的完整经验。\n\n③ AI 应用能力\n在实际工作中高频使用 AI 完成分析、内容生产、方案设计等任务，对 AI 的能力边界与失效模式有真实体感；\n加分项：有 Agent/AI 产品的设计或落地经验，理解评测体系、知识库建设、工具调用等核心机制；\n\n④ 数据驱动\n强数据敏感度，能通过指标异动定位业务问题，建立输入-输出指标体系并持续迭代；\n能用数据支撑决策与说服，而非用观点说服。\n\n⑤ 推动力与影响力\n具备复杂项目的跨组织协调能力，能在多方目标不一致时找到共识路径；\n具备面对高模糊度问题时的韧性——从定策略、到多方对齐、到能力迭代、到销售侧落地，链条长、周期久、变量多。\n\n岗位亮点\n1、你负责的不是一个项目，而是一个行业单元。统筹看策略、产品方向、资源调度，最接近「创业」的组织内岗位形态。\n\n2、服务零售是 AI 最难啃、但一旦啃下来非常有价值的场景——高度非标、角色复杂、数据分散。你不是在用别人做好的 AI 工具，而是在定义 AI 在这个行业里应该长什么样。这段经历在市场上具有稀缺性。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4701902765","sourceKey":"meituan_social","company":"美团","title":"运健行业运营","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4701902765&jobShareType=1","duty":"1. 负责运健行业用户和供给管理，包括行业流量运营、商家及供给日常运营，促平台交易转化；\n2. 协助制定并执行行业运营策略，提升多渠道用户流量、商家活跃度和供给丰富度；\n3. 深入运健产业链/价值链，探查机会点，并输出产品方案，推动商业化收入达成；\n4. 与产品、市场、销售等团队协作，推动运营工具及流程的AI优化落地，持续提升工作效率。","requirements":"1. 大学本科及以上学历，具备3年以上产品运营或商家运营相关工作经验。\n2. 熟悉运健行业者（如运动健身、健康管理等）及AI工具使用者优先。\n3. 具备较强的数据分析能力，熟练使用AI分析工具。\n4. 具备良好的沟通能力和团队协作意识，能承受一定工作压力。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1. 负责运健行业用户和供给管理，包括行业流量运营、商家及供给日常运营，促平台交易转化；\n2. 协助制定并执行行业运营策略，提升多渠道用户流量、商家活跃度和供给丰富度；\n3. 深入运健产业链/价值链，探查机会点，并输出产品方案，推动商业化收入达成；\n4. 与产品、市场、销售等团队协作，推动运营工具及流程的AI优化落地，持续提升工作效率。\n\n岗位基本要求\n1. 大学本科及以上学历，具备3年以上产品运营或商家运营相关工作经验。\n2. 熟悉运健行业者（如运动健身、健康管理等）及AI工具使用者优先。\n3. 具备较强的数据分析能力，熟练使用AI分析工具。\n4. 具备良好的沟通能力和团队协作意识，能承受一定工作压力。\n\n岗位亮点\n1. 加入快速发展的运健行业，参与平台生态建设。\n2. 与行业头部商家深度合作，积累丰富的运营经验。\n3. 成长空间大，有机会参与核心运动健身AI工具项目。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4709592616","sourceKey":"meituan_social","company":"美团","title":"小象超市-工程经理","city":"广州市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4709592616&jobShareType=1","duty":"1. 制度与体系：结合业务模式拟定工程管理制度并严格落实，建立符合小象超市业态特点的项目管理标准化流程，保障项目安全高效推进；\n2. 全面管控：对工程项目的进度、质量、成本、安全进行全面把控，持续优化项目管理模式，做好指导、监督与考核，确保批量开店目标达成；\n3. 多方协同：组织设计、施工、供应商等多方会审，主导重要物料及工程验收备案；实时监督总包/分包履约状况，敏锐捕捉工程问题并迅速给出整改方案；\n4. 选址与交接：实地勘察场地，协同拓展部明确技术条件，助力完成选址、签约与场地交接，对门店的工程可行性提供专业判断；\n5. 结算与审计：严谨审查竣工图纸与结算资料，推动审计结算进程，配合完成结算闭环，有效控制工程超支风险；\n6. 报批报建：牵头负责施工及消防报批报建工作，获取开工许可等审批文件，熟练应对各地政策差异；\n7. 供应商管理：以设计标准为指引管理供应商体系，驱动培训考核，持续提升施工执行能力和材料品控水平；\n8. 数字化工程管控：推动工程管理数字化落地——运用BIM/数字孪生进行施工前预演和图纸审查；\n9. 借助AI辅助工具（如AI图纸合规检查、AI工期/成本预警）提升工程决策效率；\n10. 借助智能工单系统实现多项目并行的进度追踪和问题闭环；配合门店智能化改造，完成IoT设备（冷链监控、能耗管理、智能安防）调试与验收交付。","requirements":"1. 5年以上连锁商超或餐饮工程管理实践经验；\n2. 工程、土木、机电专业出身优先熟悉商超/餐饮工程各类标准、规范、技术方案及常用设备（制冷/强弱电/消防等）\n3. 精通工程管理、招投标、成本管控流程，具备独立管理多项目并行能力拥有施工报建、消防报审全流程实操经验具备良好的跨部门沟通协调能力，能有效推动多方资源协同\n4. 具备BIM基础操作能力，或使用过工程数字化工具\n5. 有使用AI工具辅助工程工作的经验（如AI图纸审查、AI工程文档生成、AI成本测算等工具）","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 制度与体系：结合业务模式拟定工程管理制度并严格落实，建立符合小象超市业态特点的项目管理标准化流程，保障项目安全高效推进；\n2. 全面管控：对工程项目的进度、质量、成本、安全进行全面把控，持续优化项目管理模式，做好指导、监督与考核，确保批量开店目标达成；\n3. 多方协同：组织设计、施工、供应商等多方会审，主导重要物料及工程验收备案；实时监督总包/分包履约状况，敏锐捕捉工程问题并迅速给出整改方案；\n4. 选址与交接：实地勘察场地，协同拓展部明确技术条件，助力完成选址、签约与场地交接，对门店的工程可行性提供专业判断；\n5. 结算与审计：严谨审查竣工图纸与结算资料，推动审计结算进程，配合完成结算闭环，有效控制工程超支风险；\n6. 报批报建：牵头负责施工及消防报批报建工作，获取开工许可等审批文件，熟练应对各地政策差异；\n7. 供应商管理：以设计标准为指引管理供应商体系，驱动培训考核，持续提升施工执行能力和材料品控水平；\n8. 数字化工程管控：推动工程管理数字化落地——运用BIM/数字孪生进行施工前预演和图纸审查；\n9. 借助AI辅助工具（如AI图纸合规检查、AI工期/成本预警）提升工程决策效率；\n10. 借助智能工单系统实现多项目并行的进度追踪和问题闭环；配合门店智能化改造，完成IoT设备（冷链监控、能耗管理、智能安防）调试与验收交付。\n\n岗位基本要求\n1. 5年以上连锁商超或餐饮工程管理实践经验；\n2. 工程、土木、机电专业出身优先熟悉商超/餐饮工程各类标准、规范、技术方案及常用设备（制冷/强弱电/消防等）\n3. 精通工程管理、招投标、成本管控流程，具备独立管理多项目并行能力拥有施工报建、消防报审全流程实操经验具备良好的跨部门沟通协调能力，能有效推动多方资源协同\n4. 具备BIM基础操作能力，或使用过工程数字化工具\n5. 有使用AI工具辅助工程工作的经验（如AI图纸审查、AI工程文档生成、AI成本测算等工具）\n\n岗位亮点\n有机会全身心地参与新零售业态，和团队一起更快速、更有效的完成工程筹建，提升个人能力； 能和电商、物流、零售、人工智能等多元化背景的团队技术大牛一起，综合学习，共同进步；工程团队的图纸审查、进度预警、成本分析都在探索AI辅助，你将有机会成为\"AI+工程管理\"这个新方向的先行者","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4691912539","sourceKey":"meituan_social","company":"美团","title":"休闲行业运营","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4691912539&jobShareType=1","duty":"1. 负责按摩足疗&洗浴商家及供给的运营策略制定与执行，提升平台商家活跃度与供给质量\n2. 深度理解按摩足疗&洗浴行业用户需求与商家痛点，推动产品功能优化与运营活动落地\n3. 搭建并完善商家成长体系，通过数据分析驱动商家运营效率提升\n4. 协同产品、市场、技术等团队，推动行业解决方案的迭代与创新\n5. 定期输出运营数据分析报告，识别问题并推动持续优化","requirements":"1. 大学本科及以上学历，3年以上产品运营或商家运营相关工作经验\n2. 具备休闲行业（如按摩足疗、洗浴等）运营经验者优先\n3. 熟悉商家生命周期管理，具备较强的数据分析与策略制定能力\n4. 优秀的沟通协调能力和跨团队协作能力，具备较强的项目推动力\n5. 能适应快节奏工作环境，具备高度责任心","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1. 负责按摩足疗&洗浴商家及供给的运营策略制定与执行，提升平台商家活跃度与供给质量\n2. 深度理解按摩足疗&洗浴行业用户需求与商家痛点，推动产品功能优化与运营活动落地\n3. 搭建并完善商家成长体系，通过数据分析驱动商家运营效率提升\n4. 协同产品、市场、技术等团队，推动行业解决方案的迭代与创新\n5. 定期输出运营数据分析报告，识别问题并推动持续优化\n\n岗位基本要求\n1. 大学本科及以上学历，3年以上产品运营或商家运营相关工作经验\n2. 具备休闲行业（如按摩足疗、洗浴等）运营经验者优先\n3. 熟悉商家生命周期管理，具备较强的数据分析与策略制定能力\n4. 优秀的沟通协调能力和跨团队协作能力，具备较强的项目推动力\n5. 能适应快节奏工作环境，具备高度责任心\n\n具备以下条件优先\n具备AI运营的主观性，能用AI处理日常运营的绝大部分工作；数据逻辑强\n\n岗位亮点\n1. 深耕垂直行业，参与平台核心供给运营，发展空间广阔\n2. 与行业头部商家深度合作，积累丰富的B端运营经验\n3. 团队氛围开放，鼓励创新与数据驱动决策","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4720793416","sourceKey":"meituan_social","company":"美团","title":"丽人行业运营","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4720793416&jobShareType=1","duty":"1. 负责行业运营策略的制定与执行，结合市场趋势和用户需求，推动业务增长。  \n2. 协调产品、技术、市场等多方资源，确保项目高效落地并达成目标。  \n3. 深入分析行业数据，输出运营分析报告，为决策提供数据支持。  \n4. 搭建并优化行业运营流程，提升团队协作效率与运营质量。","requirements":"1. 大学本科及以上学历，3年以上产品运营或项目管理相关工作经验。  \n2. 具备优秀的沟通协调能力，能够推动跨部门协作。  \n3. 熟悉行业运营方法论，有成功案例者优先。  \n4. 具备较强的数据分析能力，熟练使用各类数据工具。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1. 负责行业运营策略的制定与执行，结合市场趋势和用户需求，推动业务增长。  \n2. 协调产品、技术、市场等多方资源，确保项目高效落地并达成目标。  \n3. 深入分析行业数据，输出运营分析报告，为决策提供数据支持。  \n4. 搭建并优化行业运营流程，提升团队协作效率与运营质量。\n\n岗位基本要求\n1. 大学本科及以上学历，3年以上产品运营或项目管理相关工作经验。  \n2. 具备优秀的沟通协调能力，能够推动跨部门协作。  \n3. 熟悉行业运营方法论，有成功案例者优先。  \n4. 具备较强的数据分析能力，熟练使用各类数据工具。\n\n岗位亮点\n1. 参与核心业务运营，直接影响公司战略方向。  \n2. 与行业优秀团队共事，快速提升专业能力。  \n3. 提供广阔的职业发展空间和晋升机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4702367353","sourceKey":"meituan_social","company":"美团","title":"美团骑行-车辆运营主管（大理市）","city":"大理白族自治州","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4702367353&jobShareType=1","duty":"1.负责所属区域的车辆运营管理工作，对有效运营车辆和活跃车辆指标负责；\n2.通过实地观察、数据分析、行业分析，制定提升市占营收的经营策略，例如车辆投放、调度策略，故障干预策略等，提升市占营收等指标；\n3.组建和管理运维团队，包括一线运维司机、摆车人员；\n4.对接区域内政府主管部门，配合政府部门对城市运营问题进行管理。","requirements":"1.本科及以上学历，不限专业不限工作经历；\n2.具备较好的沟通协调能力和执行力。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.负责所属区域的车辆运营管理工作，对有效运营车辆和活跃车辆指标负责；\n2.通过实地观察、数据分析、行业分析，制定提升市占营收的经营策略，例如车辆投放、调度策略，故障干预策略等，提升市占营收等指标；\n3.组建和管理运维团队，包括一线运维司机、摆车人员；\n4.对接区域内政府主管部门，配合政府部门对城市运营问题进行管理。\n\n岗位基本要求\n1.本科及以上学历，不限专业不限工作经历；\n2.具备较好的沟通协调能力和执行力。\n\n岗位亮点\n年轻团队、富有活力；发展空间大，开放的工作氛围","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4630136117","sourceKey":"meituan_social","company":"美团","title":"美团企业版-餐饮商户供应链商务拓展（BD）","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4630136117&jobShareType=1","duty":"品牌签约：负责所属品牌方的商务合作，包含外卖、到餐KA及CKA品牌，协同品牌业务、财税、SaaS等多方角色的方案讲解、商务谈判、合同签署；\n发票回收：负责所属品牌方的周期性发票回收工作；\n品牌经营：借助数据分析工具，基于行业数据、品牌经营数据分析，持续指导品牌B端场景资源投入，包括企业专属商品、价格的经营方案迭代，确保品牌经营策略有效性。","requirements":"本科及以上学历，3年及以上大客户销售/运营工作经验；\n逻辑清晰，强烈的责任心和事业心，具备良好的职业素养，正直诚信；\n具备良好的沟通表达能力、较强的数据分析能力及良好的跨部门协作能力；\n适应互联网行业的快速发展，精力充沛，心态积极进取，有较强的目标意识及自驱力；\n具备较好的商家谈判与沟通能力，同时具备商家运营能力；\n具备AI辅助工作工具的使用意愿，能利用AI工具辅助商务方案撰写、拜访准备及数据报告生成。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n品牌签约：负责所属品牌方的商务合作，包含外卖、到餐KA及CKA品牌，协同品牌业务、财税、SaaS等多方角色的方案讲解、商务谈判、合同签署；\n发票回收：负责所属品牌方的周期性发票回收工作；\n品牌经营：借助数据分析工具，基于行业数据、品牌经营数据分析，持续指导品牌B端场景资源投入，包括企业专属商品、价格的经营方案迭代，确保品牌经营策略有效性。\n\n岗位基本要求\n本科及以上学历，3年及以上大客户销售/运营工作经验；\n逻辑清晰，强烈的责任心和事业心，具备良好的职业素养，正直诚信；\n具备良好的沟通表达能力、较强的数据分析能力及良好的跨部门协作能力；\n适应互联网行业的快速发展，精力充沛，心态积极进取，有较强的目标意识及自驱力；\n具备较好的商家谈判与沟通能力，同时具备商家运营能力；\n具备AI辅助工作工具的使用意愿，能利用AI工具辅助商务方案撰写、拜访准备及数据报告生成。\n\n岗位亮点\n【新业务】美团内部专业面向企业市场的To B业务。我们为“企业公务消费管理”提供一站式SaaS服务，涵盖企业用餐、报销费控等多个领域（这些领域已经在服务美团自身）。我们帮助企业实现公务消费线上化，助力企业降本增效，帮助员工告别线下报销；\n【空间大】公务消费有数万亿的大盘，有足够的想象力。该业务会涉及外卖、到店餐饮等业务类型，能给大家提供足够的学习成长空间；\n【有希望】To B的大势刚刚开始，依托于美团过去10年的积累和对自身服务的深厚理解，我们认为很有机会把业务做大做成；\n【氛围好】务实求真，创业氛围。人际简单，组织扁平。这是一个巨大的机会，也需要长期的耐心。To B星辰大海，征程期待有你。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4705906085","sourceKey":"meituan_social","company":"美团","title":"高级投放运营专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4705906085&jobShareType=1","duty":"1.独立操盘投放增长业务，基于用户生命周期、业务目标与竞争格局，制定分层分阶段的投放增长策略，对用户规模、交易与ROI等核心指标负责；\n\n2.主导预算规划与动态调优，构建渠道组合与资源分配机制，以数据驱动持续优化投放模型，在规模与效率之间实现最优平衡；\n\n3.深度洞察用户需求与决策逻辑，联动货品供给、补贴政策、营销热点等要素设计投放打法，沉淀可复用的增长方法论；\n\n4.研判电商、OTA等交易型行业的核心打法与趋势，迁移跨行业最佳实践，驱动策略持续迭代；\n\n5.探索并落地AI在投放增长中的应用，借助AIGC、智能投放、大模型等技术提升素材创意产出、人群洞察与出价效率，构建智能化投放能力；\n\n6.协同商分、产研、供给等团队推动策略落地，并对投放链路能力（RTA、归因、唤端等）提出系统性优化建议。","requirements":"1.本科及以上学历，具备扎实的互联网投放或用户增长经验，有电商、OTA等交易型行业背景者优先；\n\n2.精通信息流、搜索、DSP等主流投放渠道与增长手段，熟悉RTA、归因分析等技术体系；\n\n3.具备AI/智能化投放的应用能力，熟悉AIGC、智能投放工具或大模型在营销增长场景的落地，有相关实践者优先；\n\n4.对数据高度敏感，具备优秀的数据分析与商业判断能力，能够以数据洞察驱动策略决策；\n\n5.具备成熟的策略思维与全局视角，既能独立操盘亦能推动高质量落地，逻辑严谨、学习能力强；\n\n6.具备优秀的跨团队协同与资源整合能力，沟通表达精准高效。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.独立操盘投放增长业务，基于用户生命周期、业务目标与竞争格局，制定分层分阶段的投放增长策略，对用户规模、交易与ROI等核心指标负责；\n\n2.主导预算规划与动态调优，构建渠道组合与资源分配机制，以数据驱动持续优化投放模型，在规模与效率之间实现最优平衡；\n\n3.深度洞察用户需求与决策逻辑，联动货品供给、补贴政策、营销热点等要素设计投放打法，沉淀可复用的增长方法论；\n\n4.研判电商、OTA等交易型行业的核心打法与趋势，迁移跨行业最佳实践，驱动策略持续迭代；\n\n5.探索并落地AI在投放增长中的应用，借助AIGC、智能投放、大模型等技术提升素材创意产出、人群洞察与出价效率，构建智能化投放能力；\n\n6.协同商分、产研、供给等团队推动策略落地，并对投放链路能力（RTA、归因、唤端等）提出系统性优化建议。\n\n岗位基本要求\n1.本科及以上学历，具备扎实的互联网投放或用户增长经验，有电商、OTA等交易型行业背景者优先；\n\n2.精通信息流、搜索、DSP等主流投放渠道与增长手段，熟悉RTA、归因分析等技术体系；\n\n3.具备AI/智能化投放的应用能力，熟悉AIGC、智能投放工具或大模型在营销增长场景的落地，有相关实践者优先；\n\n4.对数据高度敏感，具备优秀的数据分析与商业判断能力，能够以数据洞察驱动策略决策；\n\n5.具备成熟的策略思维与全局视角，既能独立操盘亦能推动高质量落地，逻辑严谨、学习能力强；\n\n6.具备优秀的跨团队协同与资源整合能力，沟通表达精准高效。\n\n岗位亮点\n1.核心业务、资源充足：处于强竞争、复杂度的核心业务，资源投入充分，提供稀缺的策略决策实践机会；\n\n2.决策价值高：可深度参与业务增长核心决策，接触前沿的用户增长理念、AI应用与行业最佳实践；\n\n3.团队氛围好：团队开放团结、气氛轻松，人际关系简单纯粹。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4063523731","sourceKey":"meituan_social","company":"美团","title":"食杂零售税务BP","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4063523731&jobShareType=1","duty":"1.深入了解公司业务，积极为业务提供可落地的税务问题解决方案；\n2.识别业务操作中的税务风险，并从税务合规角度提供优化建议；\n3.掌握与业务相关的税务政策变化及趋势，有能力向业务提供前瞻性的税务指引，为业务创造长期可持续的价值；\n4.为承载业务的法人主体提供税金预测、税务筹划和关联交易安排；\n5.研究同业的税务处理方案，可对标匹配优秀方案供业务参考；\n6.配合公司发展战略和税收政策，优化税务结构，提高税收效益；\n7.加强零售业务线税务系统智能化建设；\n8.推动该领域AI 化提效： 梳理税务高频工作场景，建立标准化 AI 辅助工作流与 Prompt 模板，沉淀团队操作规范，持续提升人均处理效率与决策质量。","requirements":"1. 对中国财税政策清晰和深刻的掌握，能为业务提供闭环的税务解决方案；\n2. 有全局观，对零售行业税务工作有熟练实操经验，有产品化思维能力，能通过AI提高工作效率及沉淀经验；\n3. 有四大+互联网公司税务工作经历者优先；\n4. 英语可作为日常沟通语言；\n4. 具有较强的沟通协同能力，业务思维好。\n5. 关注大模型、AI Agent 等前沿技术在税务领域的应用进展，有参与或推动资金场景/AI/数字化工具落地经验者优先。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1.深入了解公司业务，积极为业务提供可落地的税务问题解决方案；\n2.识别业务操作中的税务风险，并从税务合规角度提供优化建议；\n3.掌握与业务相关的税务政策变化及趋势，有能力向业务提供前瞻性的税务指引，为业务创造长期可持续的价值；\n4.为承载业务的法人主体提供税金预测、税务筹划和关联交易安排；\n5.研究同业的税务处理方案，可对标匹配优秀方案供业务参考；\n6.配合公司发展战略和税收政策，优化税务结构，提高税收效益；\n7.加强零售业务线税务系统智能化建设；\n8.推动该领域AI 化提效： 梳理税务高频工作场景，建立标准化 AI 辅助工作流与 Prompt 模板，沉淀团队操作规范，持续提升人均处理效率与决策质量。\n\n岗位基本要求\n1. 对中国财税政策清晰和深刻的掌握，能为业务提供闭环的税务解决方案；\n2. 有全局观，对零售行业税务工作有熟练实操经验，有产品化思维能力，能通过AI提高工作效率及沉淀经验；\n3. 有四大+互联网公司税务工作经历者优先；\n4. 英语可作为日常沟通语言；\n4. 具有较强的沟通协同能力，业务思维好。\n5. 关注大模型、AI Agent 等前沿技术在税务领域的应用进展，有参与或推动资金场景/AI/数字化工具落地经验者优先。\n\n岗位亮点\n1. 有机会深刻了解美团的业务和运作、深度学习美团方法论；\n2. 有机会深度参与互联网头部企业的战略和业务的税务方案设计；\n3. 美团有丰富的业务线和专业领域，提供给同学们在税务管理各个岗位轮岗锻炼的机会；\n4. 我们的团队专业、开放、乐于分享、拥抱挑战。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2754956080","sourceKey":"meituan_social","company":"美团","title":"内部审计专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2754956080&jobShareType=1","duty":"1. 参与业务运营类审计项目，识别风险，基于业务目标、行业现状等提出可落地的改进建议；\n2. 追踪整改进展，并探索建设持续化审计工具开展长期风险监控；\n3. 探索利用AI能力和工具延展审计边界，提高工作效率，发掘深度风险和新兴风险。","requirements":"1. 硕士研究生学历，审计、信息管理或相关专业背景；  \n2. 具备3年以上风险管理相关工作经验，具有零售或IoT行业背景优先；    \n3. 具备优秀的主动性和韧性、良好的沟通能力和团队协作精神。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1. 参与业务运营类审计项目，识别风险，基于业务目标、行业现状等提出可落地的改进建议；\n2. 追踪整改进展，并探索建设持续化审计工具开展长期风险监控；\n3. 探索利用AI能力和工具延展审计边界，提高工作效率，发掘深度风险和新兴风险。\n\n岗位基本要求\n1. 硕士研究生学历，审计、信息管理或相关专业背景；  \n2. 具备3年以上风险管理相关工作经验，具有零售或IoT行业背景优先；    \n3. 具备优秀的主动性和韧性、良好的沟通能力和团队协作精神。\n\n岗位亮点\n1. 深入零售、IoT、平台服务等多业态，兼具业务深度和广度，单点问题解法可形成横向高杠杆成果；  \n2. 风险管理视角和业务运营视角兼备，可参与到管理动作决策过程；\n3. 参与AI时代内审行业变革探索；\n4. 团队实事求是，严肃活泼，各有专长，是很好的成长平台。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3750031159","sourceKey":"meituan_social","company":"美团","title":"LongCat - Search Agent 算法研究员","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3750031159&jobShareType=1","duty":"1. 深度参与LongCat基模Agent能力优化，包括但不限于以DeepSearch、DeepResearch等为代表的Search Agent能力，以及以生活服务等为代表的真实世界复杂任务上的Agentic能力\n2. 跟进大模型的前沿技术，包括但不限于：Mid-Train、SFT、GRM、PRM、RLVR、Agentic RL、Agent自进化、Context管理/Memory等，在LongCat模型上做出创新性的研究成果\n3. 结合大模型全模态能力，探索下一代大模型+Agent+搜索的新的技术和产品范式","requirements":"1. 硕士研究生及以上学历，计算机科学、人工智能、自然语言处理等相关领域优先；\n2. 优秀的编程能力，熟悉PyTorch、TensorFlow等深度学习框架，同时具备极强的AI Coding意识和能力；\n3. 熟悉深度学习和LLM相关的算法和技术，具备丰富的模型训练调优经验；\n4. 出色的分析和解决问题能力，具备极强的自驱力，能够独立地开展前沿研究工作\n5. 有ACL/NeurIPS等顶会论文者优先，有ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 深度参与LongCat基模Agent能力优化，包括但不限于以DeepSearch、DeepResearch等为代表的Search Agent能力，以及以生活服务等为代表的真实世界复杂任务上的Agentic能力\n2. 跟进大模型的前沿技术，包括但不限于：Mid-Train、SFT、GRM、PRM、RLVR、Agentic RL、Agent自进化、Context管理/Memory等，在LongCat模型上做出创新性的研究成果\n3. 结合大模型全模态能力，探索下一代大模型+Agent+搜索的新的技术和产品范式\n\n岗位基本要求\n1. 硕士研究生及以上学历，计算机科学、人工智能、自然语言处理等相关领域优先；\n2. 优秀的编程能力，熟悉PyTorch、TensorFlow等深度学习框架，同时具备极强的AI Coding意识和能力；\n3. 熟悉深度学习和LLM相关的算法和技术，具备丰富的模型训练调优经验；\n4. 出色的分析和解决问题能力，具备极强的自驱力，能够独立地开展前沿研究工作\n5. 有ACL/NeurIPS等顶会论文者优先，有ACM/ICPC、NOI/IOI、Top Coder、Kaggle等比赛获奖者优先\n\n岗位亮点\n1、丰富的研发经验，参与公司核心产品的研发和优化。\n2、充足的GPU资源用于实验探索。\n3、提供优厚的薪资福利和良好的晋升空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4720843309","sourceKey":"meituan_social","company":"美团","title":"点评技术-推荐算法工程师","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4720843309&jobShareType=1","duty":"1. 负责推荐系统全链路的优化与设计，包括召回、粗排、精排等模块的迭代与创新。  \n2. 基于用户行为数据构建和迭代推荐模型，探索scaling up、多模态推荐等前沿方向。  \n3. 探索并落地生成式推荐技术，推动大模型在推荐场景中的应用与创新。  \n4. 与产品、工程团队协作，推动算法策略在业务场景中的落地应用。","requirements":"1. 硕士研究生学历，计算机、数学、统计学等相关专业。  \n2. 1年以上推荐算法或相关领域工作经验，具备扎实的机器学习理论基础。  \n3. 熟练掌握Python、C++等编程语言，熟悉TensorFlow、PyTorch等深度学习框架。  \n4. 具备良好的数据分析和问题解决能力，有大规模推荐系统实践经验者优先。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1. 负责推荐系统全链路的优化与设计，包括召回、粗排、精排等模块的迭代与创新。  \n2. 基于用户行为数据构建和迭代推荐模型，探索scaling up、多模态推荐等前沿方向。  \n3. 探索并落地生成式推荐技术，推动大模型在推荐场景中的应用与创新。  \n4. 与产品、工程团队协作，推动算法策略在业务场景中的落地应用。\n\n岗位基本要求\n1. 硕士研究生学历，计算机、数学、统计学等相关专业。  \n2. 1年以上推荐算法或相关领域工作经验，具备扎实的机器学习理论基础。  \n3. 熟练掌握Python、C++等编程语言，熟悉TensorFlow、PyTorch等深度学习框架。  \n4. 具备良好的数据分析和问题解决能力，有大规模推荐系统实践经验者优先。\n\n具备以下条件优先\n具有之前做搜广推相关经历。\n\n岗位亮点\n1. 参与亿级用户产品的推荐系统建设，业务影响力大。  \n2. 技术氛围浓厚，可与资深算法专家共同成长。  \n3. 工作地点覆盖北京、上海，提供灵活办公选择。  \n4. 完善的职业发展路径和具有竞争力的薪酬福利。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4705321633","sourceKey":"meituan_social","company":"美团","title":"小象超市-线下店前场运营-成都","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4705321633&jobShareType=1","duty":"1.经营目标管理：负责对大区门店前场各模块的销售、毛利及利润指标进行拆解、追踪与达成管理，确保整体经营目标实现。\n2.运营标准建设：建立并迭代所辖品类的运营SOP、服务标准与质量管控体系，并通过巡检、督导与考核机制确保在终端门店的落地执行。\n3.卖场效能优化：主导前场的品类结构、空间布局与商品陈列方案的规划与优化，基于销售数据与顾客动线分析，持续提升卖场空间效率与产出。\n4.营销活动落地：负责区域级营销活动在前场部门的策划、执行与效果追踪，完成活动复盘，以驱动客流与销售转化。\n5.顾客体验管理：监控并分析前台服务模块的运营数据与客诉反馈，定位服务短板，推动改善流程，对顾客满意度负责。\n6.数据复盘赋能：具备优秀的数据处理与报告撰写能力，定期输出前场经营分析报告，精准诊断问题并提出行动策略，为管理层决策与门店运营提供专业支持。","requirements":"1.本科及以上学历。\n2.拥有3年以上零售行业运营管理经验，具备线下多品类管理背景者优先。\n3.在品类规划、卖场布局、商品陈列等方面拥有扎实的实践经验。\n4.具备良好的数据处理能力，能熟练使用报表类处理工具进行业务分析。\n5.拥有优秀的报告撰写与陈述能力，能清晰呈现经营状况与策略计划。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.经营目标管理：负责对大区门店前场各模块的销售、毛利及利润指标进行拆解、追踪与达成管理，确保整体经营目标实现。\n2.运营标准建设：建立并迭代所辖品类的运营SOP、服务标准与质量管控体系，并通过巡检、督导与考核机制确保在终端门店的落地执行。\n3.卖场效能优化：主导前场的品类结构、空间布局与商品陈列方案的规划与优化，基于销售数据与顾客动线分析，持续提升卖场空间效率与产出。\n4.营销活动落地：负责区域级营销活动在前场部门的策划、执行与效果追踪，完成活动复盘，以驱动客流与销售转化。\n5.顾客体验管理：监控并分析前台服务模块的运营数据与客诉反馈，定位服务短板，推动改善流程，对顾客满意度负责。\n6.数据复盘赋能：具备优秀的数据处理与报告撰写能力，定期输出前场经营分析报告，精准诊断问题并提出行动策略，为管理层决策与门店运营提供专业支持。\n\n岗位基本要求\n1.本科及以上学历。\n2.拥有3年以上零售行业运营管理经验，具备线下多品类管理背景者优先。\n3.在品类规划、卖场布局、商品陈列等方面拥有扎实的实践经验。\n4.具备良好的数据处理能力，能熟练使用报表类处理工具进行业务分析。\n5.拥有优秀的报告撰写与陈述能力，能清晰呈现经营状况与策略计划。\n\n岗位亮点\n“前场经营质量”关键角色，岗位价值高，晋升空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4705833566","sourceKey":"meituan_social","company":"美团","title":"小象超市-线下店培训运营-成都","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4705833566&jobShareType=1","duty":"1.培训体系规划：基于大区业务战略与人才梯队现状，进行培训需求分析，负责构建并持续迭代区域分层、分条线的全流程培训体系与年度规划。\n2.学习内容开发：主导关键课程（如服务标准、运营流程、销售技巧、管理能力等）的课件设计与内容制作，开发标准化教材、案例库及数字化学习材料。\n3.培训项目落地：负责组织并实施各类培训项目，包括新员工入职集训、在岗技能提升、储备干部培养及管理层发展项目，确保培训高效落地。\n4.讲师团队管理与赋能：负责区域内部讲师团队的选拔、培养、认证与激励，通过定期教研与技能培训，提升讲师团队的专业交付能力。\n5.培训效果检验：建立科学的培训效果评估体系，通过考核、调研、行为观察及业务数据比对等方式，检验培训转化效果，并持续优化培训策略。\n6.学习运营与数字化：负责学习平台与资源的日常运营管理，探索并应用多样化的学习技术与形式，提升培训的覆盖度、便捷性与员工学习体验。\n7.掌握基本的AI工具，使用工具提升工作流程效率。","requirements":"1.人力资源管理、教育学、心理学等相关专业优先。\n2.拥有3年以上培训相关工作经验，具备零售行业培训背景者佳。\n3.具备独立完成培训需求分析、项目规划、课件开发与授课交付的全流程实操经验。\n4.具备良好的数据处理能力，能使用常用函数和相关数据工具分析培训效果与人才数据。\n5.拥有优秀的报告撰写与呈现能力，能清晰展示培训项目价值与人才发展成果。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.培训体系规划：基于大区业务战略与人才梯队现状，进行培训需求分析，负责构建并持续迭代区域分层、分条线的全流程培训体系与年度规划。\n2.学习内容开发：主导关键课程（如服务标准、运营流程、销售技巧、管理能力等）的课件设计与内容制作，开发标准化教材、案例库及数字化学习材料。\n3.培训项目落地：负责组织并实施各类培训项目，包括新员工入职集训、在岗技能提升、储备干部培养及管理层发展项目，确保培训高效落地。\n4.讲师团队管理与赋能：负责区域内部讲师团队的选拔、培养、认证与激励，通过定期教研与技能培训，提升讲师团队的专业交付能力。\n5.培训效果检验：建立科学的培训效果评估体系，通过考核、调研、行为观察及业务数据比对等方式，检验培训转化效果，并持续优化培训策略。\n6.学习运营与数字化：负责学习平台与资源的日常运营管理，探索并应用多样化的学习技术与形式，提升培训的覆盖度、便捷性与员工学习体验。\n7.掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位基本要求\n1.人力资源管理、教育学、心理学等相关专业优先。\n2.拥有3年以上培训相关工作经验，具备零售行业培训背景者佳。\n3.具备独立完成培训需求分析、项目规划、课件开发与授课交付的全流程实操经验。\n4.具备良好的数据处理能力，能使用常用函数和相关数据工具分析培训效果与人才数据。\n5.拥有优秀的报告撰写与呈现能力，能清晰展示培训项目价值与人才发展成果。\n\n岗位亮点\n区域人才发展的“总教练”与“赋能引擎”，岗位价值高，未来发展空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4705838762","sourceKey":"meituan_social","company":"美团","title":"小象超市-线下店后场运营-成都","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4705838762&jobShareType=1","duty":"1.仓储体系管理：负责建立与优化大区各门店后场的仓储运营标准、作业流程与管理制度，确保库存准确、作业规范与库内安全。\n2.物流配送优化：统筹管理区域内的物流配送网络，监控配送时效与成本，持续优化调拨、补货等物流路由，提升商品到店效率。\n3.库存精准控制：通过有效的库存数据分析，设定并监控各类别商品的安全库存与周转天数，推动库存结构的持续优化，降低滞销与缺货风险。\n4.成本效率管控：负责后场运营相关成本（如仓储、人力、物流等）的预算编制与过程控制，通过流程改进与技术应用，提升人效与坪效，实现降本增效。\n5.团队与安全督导：建立后场员工作业技能培训与绩效考核体系，并全面落实仓储物流环节的安全生产管理，杜绝重大运营与安全事故。\n6.数据复盘赋能：具备优秀的数据处理与报告撰写能力，定期输出后场运营分析报告，精准诊断库存、效率、成本等问题，并推动改善策略落地。","requirements":"1.本科及以上学历，物流管理、供应链管理等相关专业优先。\n2.拥有3年以上零售行业仓储管理、物流管理相关工作经验，熟悉现代化仓储物流运作模式。\n3.在WMS系统应用、库存控制、物流规划及成本管控方面拥有扎实的实践经验。\n4.具备良好的数据处理能力，能熟练使用报表等工具进行运营分析。\n5.拥有优秀的报告撰写与陈述能力，能清晰呈现运营状况与管理策略。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.仓储体系管理：负责建立与优化大区各门店后场的仓储运营标准、作业流程与管理制度，确保库存准确、作业规范与库内安全。\n2.物流配送优化：统筹管理区域内的物流配送网络，监控配送时效与成本，持续优化调拨、补货等物流路由，提升商品到店效率。\n3.库存精准控制：通过有效的库存数据分析，设定并监控各类别商品的安全库存与周转天数，推动库存结构的持续优化，降低滞销与缺货风险。\n4.成本效率管控：负责后场运营相关成本（如仓储、人力、物流等）的预算编制与过程控制，通过流程改进与技术应用，提升人效与坪效，实现降本增效。\n5.团队与安全督导：建立后场员工作业技能培训与绩效考核体系，并全面落实仓储物流环节的安全生产管理，杜绝重大运营与安全事故。\n6.数据复盘赋能：具备优秀的数据处理与报告撰写能力，定期输出后场运营分析报告，精准诊断库存、效率、成本等问题，并推动改善策略落地。\n\n岗位基本要求\n1.本科及以上学历，物流管理、供应链管理等相关专业优先。\n2.拥有3年以上零售行业仓储管理、物流管理相关工作经验，熟悉现代化仓储物流运作模式。\n3.在WMS系统应用、库存控制、物流规划及成本管控方面拥有扎实的实践经验。\n4.具备良好的数据处理能力，能熟练使用报表等工具进行运营分析。\n5.拥有优秀的报告撰写与陈述能力，能清晰呈现运营状况与管理策略。\n\n岗位亮点\n区域后场供应链的“运营专家”和“效率中心”，岗位价值高，未来晋升空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4704954573","sourceKey":"meituan_social","company":"美团","title":"小象超市-线下店综合运营（EHS）-成都","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4704954573&jobShareType=1","duty":"1.EHS体系管理：负责建立、推行与维护大区的环境、健康与安全（EHS）管理体系，制定并落实安全运营标准与应急预案，确保区域合规零风险。\n2.联营商运营管理：负责联营商家的引入评估、合同履约管理与日常运营协调，建立联营商效能评估体系，提升合作方的经营质量与顾客服务水平。\n3.质量稽核与控管：主导建立门店运营质量稽核标准与流程，定期组织对门店环境、服务、商品质量及操作规范进行审计，并追踪整改结果，形成管理闭环。\n4.风险前置管控：建立常态化的风险排查机制，能够对EHS、联营商运营及商品质量中的潜在风险进行精准识别与前置预警，并推动预防性措施落地。\n5.标准建设与赋能：针对EHS、联营、质控三大模块，输出标准化的作业流程与管理工具，并通过培训、宣导与现场指导，赋能门店团队执行到位。\n6.数据复盘与报告：具备优秀的数据处理与报告撰写能力，定期输出综合运营分析报告，清晰呈现各模块运营状态、核心问题及改进策略，为管理决策提供支持。","requirements":"1.安全工程、质量管理、工商管理等相关专业优先。\n2.拥有3年以上零售或相关服务业综合运营管理经验，必须具备EHS管理、质量稽核、联营运营管理其中至少两项的实战经验。\n3.熟悉业内EHS相关规范，具备质量体系搭建或稽核经验，精通联营商管理全流程。\n4.具备良好的数据处理能力，能熟练使用报表工具进行多维度运营分析。\n5.拥有优秀的报告撰写与陈述能力，能输出逻辑严谨、建议专业的综合分析报告。\n6.掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.EHS体系管理：负责建立、推行与维护大区的环境、健康与安全（EHS）管理体系，制定并落实安全运营标准与应急预案，确保区域合规零风险。\n2.联营商运营管理：负责联营商家的引入评估、合同履约管理与日常运营协调，建立联营商效能评估体系，提升合作方的经营质量与顾客服务水平。\n3.质量稽核与控管：主导建立门店运营质量稽核标准与流程，定期组织对门店环境、服务、商品质量及操作规范进行审计，并追踪整改结果，形成管理闭环。\n4.风险前置管控：建立常态化的风险排查机制，能够对EHS、联营商运营及商品质量中的潜在风险进行精准识别与前置预警，并推动预防性措施落地。\n5.标准建设与赋能：针对EHS、联营、质控三大模块，输出标准化的作业流程与管理工具，并通过培训、宣导与现场指导，赋能门店团队执行到位。\n6.数据复盘与报告：具备优秀的数据处理与报告撰写能力，定期输出综合运营分析报告，清晰呈现各模块运营状态、核心问题及改进策略，为管理决策提供支持。\n\n岗位基本要求\n1.安全工程、质量管理、工商管理等相关专业优先。\n2.拥有3年以上零售或相关服务业综合运营管理经验，必须具备EHS管理、质量稽核、联营运营管理其中至少两项的实战经验。\n3.熟悉业内EHS相关规范，具备质量体系搭建或稽核经验，精通联营商管理全流程。\n4.具备良好的数据处理能力，能熟练使用报表工具进行多维度运营分析。\n5.拥有优秀的报告撰写与陈述能力，能输出逻辑严谨、建议专业的综合分析报告。\n6.掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位亮点\n区域运营“安全、质量与合作伙伴管理”的基石，岗位价值高，晋升空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4411483145","sourceKey":"meituan_social","company":"美团","title":"小象综合分析财务BP","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4411483145&jobShareType=1","duty":"1. 深入理解业务模式，结合财务数据与业务指标，提供多维度的财务分析与决策支持。  \n2. 负责预算编制、执行监控、滚动预测及差异分析，推动业务目标达成。  \n3. 搭建并优化财务分析模型和长期预测模型，提升数据洞察效率与准确性。 探索 AI 工具在预测模型中的应用，提升预测准确率和响应速度。\n4. 定期输出经营分析报告，向管理层提供可落地的财务建议。能够借助 AI 辅助生成分析框架与报告初稿，提升产出效率。","requirements":"1. 5年以上财务分析或财务BP相关工作经验，具备互联网或高增长行业背景优先。  \n2. 具备较强的逻辑思维、数据敏感度和业务理解能力。  \n3. 具备良好的沟通协调能力，能独立推动跨部门协作。\n4. 熟悉SQL、Power BI、AI工具等数据分析工具者优先。\n5. 具备 AI 工具学习意愿，能主动探索 AI 在财务场景中的落地应用。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1. 深入理解业务模式，结合财务数据与业务指标，提供多维度的财务分析与决策支持。  \n2. 负责预算编制、执行监控、滚动预测及差异分析，推动业务目标达成。  \n3. 搭建并优化财务分析模型和长期预测模型，提升数据洞察效率与准确性。 探索 AI 工具在预测模型中的应用，提升预测准确率和响应速度。\n4. 定期输出经营分析报告，向管理层提供可落地的财务建议。能够借助 AI 辅助生成分析框架与报告初稿，提升产出效率。\n\n岗位基本要求\n1. 5年以上财务分析或财务BP相关工作经验，具备互联网或高增长行业背景优先。  \n2. 具备较强的逻辑思维、数据敏感度和业务理解能力。  \n3. 具备良好的沟通协调能力，能独立推动跨部门协作。\n4. 熟悉SQL、Power BI、AI工具等数据分析工具者优先。\n5. 具备 AI 工具学习意愿，能主动探索 AI 在财务场景中的落地应用。\n\n岗位亮点\n1. 深入参与核心业务决策，发挥财务价值引领作用。  \n2. 与高速发展的业务团队共同成长，发展空间广阔。  \n3. 扁平化管理，开放沟通氛围，鼓励创新与主动担当。  \n4. 身处 AI 应用探索前沿，有机会参与财务智能化转型实践。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4685609051","sourceKey":"meituan_social","company":"美团","title":"美团骑行-城市经理（重庆）","city":"重庆市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4685609051&jobShareType=1","duty":"1. 负责美团骑行在重庆地区的日常运营支持与车辆运维管理工作，确保车辆调度、维修、投放等环节高效运转。  \n2. 带领5人团队，制定并执行城市运营策略，提升车辆使用率与用户满意度。  \n3. 协同城市政府、物业等外部单位，推动合规运营与资源协调，保障业务稳定开展。  \n4. 监控运营数据，分析问题并提出优化方案，持续改善城市骑行体验与运营效率。  \n5. 建立并完善团队培训与考核机制，提升团队专业能力与执行力。","requirements":"1. 大学本科及以上学历，具备5年以上运营或运维相关工作经验。  \n2. 有团队管理经验，具备较强的组织协调能力与问题解决能力。  \n3. 熟悉城市交通或共享出行行业，具备较强的数据分析与策略制定能力。  \n4. 具备良好的沟通能力和跨部门协作经验，能应对复杂外部环境。  \n5. 工作责任心强，能适应高强度工作节奏。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1. 负责美团骑行在重庆地区的日常运营支持与车辆运维管理工作，确保车辆调度、维修、投放等环节高效运转。  \n2. 带领5人团队，制定并执行城市运营策略，提升车辆使用率与用户满意度。  \n3. 协同城市政府、物业等外部单位，推动合规运营与资源协调，保障业务稳定开展。  \n4. 监控运营数据，分析问题并提出优化方案，持续改善城市骑行体验与运营效率。  \n5. 建立并完善团队培训与考核机制，提升团队专业能力与执行力。\n\n岗位基本要求\n1. 大学本科及以上学历，具备5年以上运营或运维相关工作经验。  \n2. 有团队管理经验，具备较强的组织协调能力与问题解决能力。  \n3. 熟悉城市交通或共享出行行业，具备较强的数据分析与策略制定能力。  \n4. 具备良好的沟通能力和跨部门协作经验，能应对复杂外部环境。  \n5. 工作责任心强，能适应高强度工作节奏。\n\n岗位亮点\n1. 加入美团核心出行业务，参与城市绿色出行生态建设。  \n2. 拥有明确的职业发展路径与丰富的跨部门协作机会。  \n3. 团队氛围积极，注重员工成长与能力提升。  \n4. 工作地点位于重庆核心区域，交通便利，办公环境优良。  \n5. 提供具有竞争力的薪酬福利与完善的培训体系。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4612329304","sourceKey":"meituan_social","company":"美团","title":"Darkstore Workforce Management","city":"利雅得/科威特城/多哈","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4612329304&jobShareType=1","duty":"1.Based on the headcount targets required by business needs, break down the recruitment pace and cycle to ensure sufficient personnel.\n2. With the goal of achieving the scale of suppliers and delivery capabilities, promote the improvement of the quantity and quality of procurement and introduction of merchants, and establish a supporting merchant management mechanism and system capabilities. \n3. Assist in developing and optimizing staffing strategies to support manpower allocation and temporary staffing arrangements during peak business periods.\n4. Establish and improve local employment management systems and processes, and promote the standardization of the employment system through internal and external benchmarking and efficiency optimization.   \n5. Work closely with the city operations team to promote the implementation of standardized processes and ensure compliance with employment regulations.","requirements":"1. Bachelor's degree or above, with preference given to candidates majoring in Human Resource Management, Operations Management, or a related field.\n2. Minimum 3 years of experience in operations or HR-related work, with preference given to candidates with backgrounds in warehousing, retail, or logistics.\n3. Proficient in data analysis tools and possess basic data insight capabilities.\n4. Excellent communication and coordination skills, able to adapt to a fast-paced work environment across multiple cities.","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1.Based on the headcount targets required by business needs, break down the recruitment pace and cycle to ensure sufficient personnel.\n2. With the goal of achieving the scale of suppliers and delivery capabilities, promote the improvement of the quantity and quality of procurement and introduction of merchants, and establish a supporting merchant management mechanism and system capabilities. \n3. Assist in developing and optimizing staffing strategies to support manpower allocation and temporary staffing arrangements during peak business periods.\n4. Establish and improve local employment management systems and processes, and promote the standardization of the employment system through internal and external benchmarking and efficiency optimization.   \n5. Work closely with the city operations team to promote the implementation of standardized processes and ensure compliance with employment regulations.\n\n岗位基本要求\n1. Bachelor's degree or above, with preference given to candidates majoring in Human Resource Management, Operations Management, or a related field.\n2. Minimum 3 years of experience in operations or HR-related work, with preference given to candidates with backgrounds in warehousing, retail, or logistics.\n3. Proficient in data analysis tools and possess basic data insight capabilities.\n4. Excellent communication and coordination skills, able to adapt to a fast-paced work environment across multiple cities.\n\n具备以下条件优先\nTalabat、Sultan、snoonu mart 、Ninja  work experience\n\n岗位亮点\n1. Join a rapidly growing regional business team and participate in building the core operational system.\n2. Work locations cover Riyadh, Kuwait City, and Doha, providing cross-regional development opportunities.\n3. Assume key management responsibilities, with ample room for growth and a clear promotion path.\n4. Collaborate with a multicultural team to enhance international perspectives and comprehensive management capabilities.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4611846725","sourceKey":"meituan_social","company":"美团","title":"闪购-歪马-前置仓区域主管（青岛、济南、天津、石家庄）","city":"天津市/石家庄市/济南市/青岛市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4611846725&jobShareType=1","duty":"1.管辖13-17个酒水前置仓的业务开拓和日常管理；\n2.团队搭建，完成前置仓团队搭建，人员选用育励汰；\n3.具备一定的销售管理能力，有进行目标拆解和过程管理能力，承担区域增长目标，完成地推获客，留存等增长指标；\n4.对前置仓的商品进行管理，并不断提高前置仓操作规范性和门店的规范性；\n5.保障前置仓的日常营运，确保配送时效，前置仓内商品准确，保障用户体验；\n6.有较好的数据意识，能过通过数据发现前置仓运行中的问题；\n7.有较好的成本意识，能合理的管控仓内日常消耗品，地推赠品等耗材的管理。","requirements":"1.有1-3年的前置仓履约或直销管理经验，熟悉零售业务，对前置仓管理，商品管理等有一定经验；\n2.熟悉即时配业务特性，关注用户体验；\n3.有较好的团队管理，人员培养的经验和方法沉淀；\n4.有价值观正，能够横向协同多部门，达成公司业务指标；\n5.有较好的数据敏感度，能够透过数据发现问题。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.管辖13-17个酒水前置仓的业务开拓和日常管理；\n2.团队搭建，完成前置仓团队搭建，人员选用育励汰；\n3.具备一定的销售管理能力，有进行目标拆解和过程管理能力，承担区域增长目标，完成地推获客，留存等增长指标；\n4.对前置仓的商品进行管理，并不断提高前置仓操作规范性和门店的规范性；\n5.保障前置仓的日常营运，确保配送时效，前置仓内商品准确，保障用户体验；\n6.有较好的数据意识，能过通过数据发现前置仓运行中的问题；\n7.有较好的成本意识，能合理的管控仓内日常消耗品，地推赠品等耗材的管理。\n\n岗位基本要求\n1.有1-3年的前置仓履约或直销管理经验，熟悉零售业务，对前置仓管理，商品管理等有一定经验；\n2.熟悉即时配业务特性，关注用户体验；\n3.有较好的团队管理，人员培养的经验和方法沉淀；\n4.有价值观正，能够横向协同多部门，达成公司业务指标；\n5.有较好的数据敏感度，能够透过数据发现问题。\n\n具备以下条件优先\n长期有耐心，认可美团文化！熟悉零售业务，有前置仓管理，商品管理经验，直销外卖/团购/SaaS销售团队管理经验者优先！\n\n岗位亮点\n1.【歪马业务】是【本地核心商业/闪购事业部】下新成立的，由前线业务+运营/采购+产品全闭环的组织;\n2.歪马业务聚焦于酒类万亿市场，通过中心仓+前置仓、平台自营模式，为用户提供15分钟送达的买酒业务;\n3.业务当前正处于快速发展期，26年将覆盖全国，目前歪马送酒已是即时零售行业中的头部品牌！\n4.全方位深入业务，在全闭环的组织里感受不同职能彼此的输入/输出，同时可以参与业务模式的定义；\n5.足够宽的Scope，深入参与自营零售业务的经营。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4580016645","sourceKey":"meituan_social","company":"美团","title":"Maintenance Manager","city":"利雅得/吉达/艾卜哈/麦地那/吉赞","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4580016645&jobShareType=1","duty":"1. Engineering Equipment Maintenance Management: Responsible for overseeing regional engineering equipment maintenance operations, monitoring and enhancing the quality and efficiency of maintenance work within the area to ensure timely delivery, quality standards and cost control are met;\n2. Maintenance Process Standards: Establish and refine maintenance procedures and operational standards for engineering equipment, encompassing daily operations, repairs, servicing, inspection management and other aspects to safeguard business continuity;\n3. Maintenance Supplier Management: Establish supplier maintenance management mechanisms, encompassing supplier tendering, assessment, incentives, allocation, and replacement;\n4. Incident Response: Manage engineering equipment work orders during store operations, track progress, quality and cost. Demonstrate proficiency in specialist disciplines (plumbing, electrical, refrigeration, etc.), develop contingency plans, and lead relevant personnel to swiftly resolve unexpected equipment failures;\n5. Energy Consumption Management: Oversee energy usage of engineering equipment across stores within the region, implement energy-saving measures, and achieve store-level energy reduction targets.","requirements":"1.大学专科及以上学历，机电工程专业优先，具备电工证件；\n2. 5年以上零售、冷链、制冷设备或相关行业工程设备维护工作经历，具备维保人员管理经验；\n3. 具备良好的沟通和协调能力，能够与不同部门和候选人进行有效沟通和协调；\n4.工作积极主动、严谨，执行力强，具有强烈目标达成意识；\n5 .学习能力和协作能力强，思维缜密，接受新事物能力强，能在短时间内迅速了解行业特点.","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. Engineering Equipment Maintenance Management: Responsible for overseeing regional engineering equipment maintenance operations, monitoring and enhancing the quality and efficiency of maintenance work within the area to ensure timely delivery, quality standards and cost control are met;\n2. Maintenance Process Standards: Establish and refine maintenance procedures and operational standards for engineering equipment, encompassing daily operations, repairs, servicing, inspection management and other aspects to safeguard business continuity;\n3. Maintenance Supplier Management: Establish supplier maintenance management mechanisms, encompassing supplier tendering, assessment, incentives, allocation, and replacement;\n4. Incident Response: Manage engineering equipment work orders during store operations, track progress, quality and cost. Demonstrate proficiency in specialist disciplines (plumbing, electrical, refrigeration, etc.), develop contingency plans, and lead relevant personnel to swiftly resolve unexpected equipment failures;\n5. Energy Consumption Management: Oversee energy usage of engineering equipment across stores within the region, implement energy-saving measures, and achieve store-level energy reduction targets.\n\n岗位基本要求\n1.大学专科及以上学历，机电工程专业优先，具备电工证件；\n2. 5年以上零售、冷链、制冷设备或相关行业工程设备维护工作经历，具备维保人员管理经验；\n3. 具备良好的沟通和协调能力，能够与不同部门和候选人进行有效沟通和协调；\n4.工作积极主动、严谨，执行力强，具有强烈目标达成意识；\n5 .学习能力和协作能力强，思维缜密，接受新事物能力强，能在短时间内迅速了解行业特点.\n\n具备以下条件优先\n小象、朴朴维保经验\n\n岗位亮点\n有沙特及中东国家工作经验者优先；\n\n熟练掌握英语、阿拉伯语、汉语者优先。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4100394858","sourceKey":"meituan_social","company":"美团","title":"CKA业务中心-成都-产品销售","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4100394858&jobShareType=1","duty":"岗位职责:\n1.深刻、全面的理解客户需求，协同相关部门制定服务方案，帮助客户更好进行服务规划、完成服务目标、提升服务满意度，从而提升美团公司品牌影响力；\n2.深入理解客户流程、决策的决策链和关键人；\n3.理解行业规律及市场空间，总结销售方法论；\n4.开拓中型大型客户、维护客户关系、建立长期的合作关系，对结果负责。","requirements":"岗位要求:\n1.三年以上客户销售经验，有食材客户销售经验者优先考虑；\n2.较强的沟通能力和同理心，能够和客户深入交流、赢得客户信任、获取客户需求、进行专业宣讲和方案引导；\n3.能够跟进客户需求制定销售策略；\n4.自我驱动、有创新意识、有激情、结果导向，具备良好的团队合作精神，以客户为中心，能组织、协调周边资源达成组织、项目的目标；\n5.较强的学习能力、适应性强、组织协调能力强。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n岗位职责:\n1.深刻、全面的理解客户需求，协同相关部门制定服务方案，帮助客户更好进行服务规划、完成服务目标、提升服务满意度，从而提升美团公司品牌影响力；\n2.深入理解客户流程、决策的决策链和关键人；\n3.理解行业规律及市场空间，总结销售方法论；\n4.开拓中型大型客户、维护客户关系、建立长期的合作关系，对结果负责。\n\n岗位基本要求\n岗位要求:\n1.三年以上客户销售经验，有食材客户销售经验者优先考虑；\n2.较强的沟通能力和同理心，能够和客户深入交流、赢得客户信任、获取客户需求、进行专业宣讲和方案引导；\n3.能够跟进客户需求制定销售策略；\n4.自我驱动、有创新意识、有激情、结果导向，具备良好的团队合作精神，以客户为中心，能组织、协调周边资源达成组织、项目的目标；\n5.较强的学习能力、适应性强、组织协调能力强。\n\n岗位亮点\n岗位亮点:\n1.能够较快的建立销售技能及视野；\n2.加入快速成长的学习型团队，快速提升综合能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4098791079","sourceKey":"meituan_social","company":"美团","title":"CKA业务中心-重庆-产品销售","city":"重庆市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4098791079&jobShareType=1","duty":"1.深刻、全面的理解客户需求，协同相关部门制定服务方案，帮助客户更好进行服务规划、完成服务目标、提升服务满意度，从而提升美团公司品牌影响力；2.深入理解客户流程、决策的决策链和关键人；3.理解行业规律及市场空间，总结销售方法论；4.开拓中型大型客户、维护客户关系、建立长期的合作关系，对销售结果负责。","requirements":"1.三年以上客户销售经验，有食材客户销售经验者优先考虑；2.较强的沟通能力和同理心，能够和客户深入交流、赢得客户信任、获取客户需求、进行专业宣讲和方案引导；3.能够跟进客户需求制定销售策略；4.自我驱动、有创新意识、有激情、结果导向，具备良好的团队合作精神，以客户为中心，能组织、协调周边资源达成组织、项目的目标；5.较强的学习能力、适应性强、组织协调能力强。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1.深刻、全面的理解客户需求，协同相关部门制定服务方案，帮助客户更好进行服务规划、完成服务目标、提升服务满意度，从而提升美团公司品牌影响力；2.深入理解客户流程、决策的决策链和关键人；3.理解行业规律及市场空间，总结销售方法论；4.开拓中型大型客户、维护客户关系、建立长期的合作关系，对销售结果负责。\n\n岗位基本要求\n1.三年以上客户销售经验，有食材客户销售经验者优先考虑；2.较强的沟通能力和同理心，能够和客户深入交流、赢得客户信任、获取客户需求、进行专业宣讲和方案引导；3.能够跟进客户需求制定销售策略；4.自我驱动、有创新意识、有激情、结果导向，具备良好的团队合作精神，以客户为中心，能组织、协调周边资源达成组织、项目的目标；5.较强的学习能力、适应性强、组织协调能力强。\n\n岗位亮点\n1.能够较快的建立销售技能及视野；2.加入快速成长的学习型团队，快速提升综合能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4685590070","sourceKey":"meituan_social","company":"美团","title":"PC城市负责人--华南","city":"深圳市/广州市/南宁市/厦门市/福州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4685590070&jobShareType=1","duty":"1、履约保障：全面统筹加工中心日常运营管理，制定并分解生产计划，确保各环节有序推进、按时交付，保障中心整体产能目标达成。\n2、团队建设：负责团队的选用育励汰，为团队成员的成长和发展负责，建设一直高执行、高标准的一线运营团队。\n3、跨部门协同：建立与横向部门高效的协同关系，推动链路卡点解决，善于形成方法论，推动流程制度建设。\n4、精益改善：建立生产数据监控机制，定期分析关键指标（效率、质量、损耗等），识别瓶颈与异常，持续优化加工工艺与作业流程，提升效率，保障加工品质，提出针对性改进方案，推动持续改善。\n5、项目运营：负责新项目的测试进度、结果分析总结，推动新项目落地。","requirements":"1. 大学本科及以上学历，物流、工业工程、食品等相关专业优先。\n2. 具备5年以上物流、食品加工、生鲜领域工作经验，有大规模（300人以上）团队管理经验。\n3. 熟悉生产管理流程，具备较强的数据分析能力和问题解决能力。\n4. 具备良好的沟通协调能力和项目管理能力，能独立推动复杂项目落地\n5. 工作责任心强，能适应快节奏工作环境。\n6.有中央厨房、净菜生产经验优先。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、履约保障：全面统筹加工中心日常运营管理，制定并分解生产计划，确保各环节有序推进、按时交付，保障中心整体产能目标达成。\n2、团队建设：负责团队的选用育励汰，为团队成员的成长和发展负责，建设一直高执行、高标准的一线运营团队。\n3、跨部门协同：建立与横向部门高效的协同关系，推动链路卡点解决，善于形成方法论，推动流程制度建设。\n4、精益改善：建立生产数据监控机制，定期分析关键指标（效率、质量、损耗等），识别瓶颈与异常，持续优化加工工艺与作业流程，提升效率，保障加工品质，提出针对性改进方案，推动持续改善。\n5、项目运营：负责新项目的测试进度、结果分析总结，推动新项目落地。\n\n岗位基本要求\n1. 大学本科及以上学历，物流、工业工程、食品等相关专业优先。\n2. 具备5年以上物流、食品加工、生鲜领域工作经验，有大规模（300人以上）团队管理经验。\n3. 熟悉生产管理流程，具备较强的数据分析能力和问题解决能力。\n4. 具备良好的沟通协调能力和项目管理能力，能独立推动复杂项目落地\n5. 工作责任心强，能适应快节奏工作环境。\n6.有中央厨房、净菜生产经验优先。\n\n岗位亮点\n平台宽广，晋升空间大；\n业务快速发展期，个人成长快速","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4637218190","sourceKey":"meituan_social","company":"美团","title":"华西大区负责人","city":"成都市/西安市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4637218190&jobShareType=1","duty":"1. 全面负责华西大区物流运营生产体系的规划、建设与优化，确保区域效率与服务质量及新能看建设的持续提升。  \n2. 制定并执行大区物流战略，统筹多个城市，果蔬加工，净菜加工，等项目的运营管理及目标达成。  \n3. 带领团队完成日常运营目标，监督KPI达成情况，推动流程标准化与数字化升级。  \n4. 协同总部与各区域资源，解决重大运营问题，提升客户满意度与市场响应速度。  \n5. 建立并培养高效物流团队，完善人才梯队建设与绩效激励机制。","requirements":"1. 大学本科及以上学历，食品、物流、供应链、管理类相关专业优先。  \n2. 8年以上生产行业工作经验，具备大区或跨区域物流运营管理经验。  \n3. 具备较强的数据分析能力、战略规划能力和团队管理能力。  \n5. 工作地点为上海市或杭州市，能适应高频次跨区域出差。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 全面负责华西大区物流运营生产体系的规划、建设与优化，确保区域效率与服务质量及新能看建设的持续提升。  \n2. 制定并执行大区物流战略，统筹多个城市，果蔬加工，净菜加工，等项目的运营管理及目标达成。  \n3. 带领团队完成日常运营目标，监督KPI达成情况，推动流程标准化与数字化升级。  \n4. 协同总部与各区域资源，解决重大运营问题，提升客户满意度与市场响应速度。  \n5. 建立并培养高效物流团队，完善人才梯队建设与绩效激励机制。\n\n岗位基本要求\n1. 大学本科及以上学历，食品、物流、供应链、管理类相关专业优先。  \n2. 8年以上生产行业工作经验，具备大区或跨区域物流运营管理经验。  \n3. 具备较强的数据分析能力、战略规划能力和团队管理能力。  \n5. 工作地点为上海市或杭州市，能适应高频次跨区域出差。\n\n具备以下条件优先\n1、区域管理经验 — 有区域/中台综合岗位经历者优先\n2、数据化思维 — 具备数据驱动管理理念\n3、生鲜工厂背景 — 大型生鲜生产工厂、多元化业务经验\n\n岗位亮点\n1. 担任大区负责人，拥有高度自主权与战略决策参与机会。  \n2. 加入行业优选企业，平台资源丰富，发展空间广阔。  \n3. 大团队规模的管理，具备完善的管理支持体系与晋升通道。  \n4. 工作地点位于长三角核心城市，交通便利，生活配套完善。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4712530077","sourceKey":"meituan_social","company":"美团","title":"生鲜加工主管","city":"青岛市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4712530077&jobShareType=1","duty":"1、负责排产、排班、出勤计划执行，加工进度管控、每日订单目标交付达成；\n2、负责加工过程中人员组台、品类拆分、原料进度追踪、异常协调等业务；\n3、负责加工品质保障、加工数据准确性管理、上下游入库准确性管理；\n4、负责设备高效使用，员工积极性策略推动与执行；\n5、负责加工区域6S、生产安全、消防安全、食品安全等管理；\n6、负责促成部门各指标达成（品质、原料成本、人力成本、员工留存等）\n7、负责班次团队组织架构搭建、招聘计划、人员培养汰换，每日生产会议。","requirements":"1.具备物流或仓储相关领域的大学专科及以上学历。\n2.至少3年以上物流或仓储管理经验，有生鲜加工管理经验者优先考虑。\n3.熟悉生鲜产品的质量标准和加工工艺，具备相关品控知识。\n4.具备较好的团队管理能力，能够激励团队成员，提高工作效率。\n5.具备良好的沟通协调能力，能够与不同部门和供应商进行有效的合作。\n6.具备一定的问题解决能力和应变能力，能够灵活应对工作中的各种挑战。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责排产、排班、出勤计划执行，加工进度管控、每日订单目标交付达成；\n2、负责加工过程中人员组台、品类拆分、原料进度追踪、异常协调等业务；\n3、负责加工品质保障、加工数据准确性管理、上下游入库准确性管理；\n4、负责设备高效使用，员工积极性策略推动与执行；\n5、负责加工区域6S、生产安全、消防安全、食品安全等管理；\n6、负责促成部门各指标达成（品质、原料成本、人力成本、员工留存等）\n7、负责班次团队组织架构搭建、招聘计划、人员培养汰换，每日生产会议。\n\n岗位基本要求\n1.具备物流或仓储相关领域的大学专科及以上学历。\n2.至少3年以上物流或仓储管理经验，有生鲜加工管理经验者优先考虑。\n3.熟悉生鲜产品的质量标准和加工工艺，具备相关品控知识。\n4.具备较好的团队管理能力，能够激励团队成员，提高工作效率。\n5.具备良好的沟通协调能力，能够与不同部门和供应商进行有效的合作。\n6.具备一定的问题解决能力和应变能力，能够灵活应对工作中的各种挑战。\n\n具备以下条件优先\n有食品加工或生鲜加工管理经验优先。\n\n岗位亮点\n1、公司业务发展快，晋升空间大；\n2、公司有定期培训，学习机会多，个人成长速度快。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4712480835","sourceKey":"meituan_social","company":"美团","title":"生鲜加工主管","city":"青岛市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4712480835&jobShareType=1","duty":"1、负责排产、排班、出勤计划执行，加工进度管控、每日订单目标交付达成；\n2、负责加工过程中人员组台、品类拆分、原料进度追踪、异常协调等业务；\n3、负责加工品质保障、加工数据准确性管理、上下游入库准确性管理；\n4、负责设备高效使用，员工积极性策略推动与执行；\n5、负责加工区域6S、生产安全、消防安全、食品安全等管理；\n6、负责促成部门各指标达成（品质、原料成本、人力成本、员工留存等）\n7、负责班次团队组织架构搭建、招聘计划、人员培养汰换，每日生产会议。","requirements":"1.具备物流或仓储相关领域的大学本科及以上学历。\n2.至少5年以上物流或仓储管理经验，有生鲜加工管理经验者优先考虑。\n3.熟悉生鲜产品的质量标准和加工工艺，具备相关品控知识。\n4.具备团队搭建能力，较强的团队管理能力能够激励团队成员，提高工作效率。\n5.具备良好的沟通协调能力，能够与不同部门和供应商进行有效的合作。\n6.具备一定的问题解决能力和应变能力，能够灵活应对工作中的各种挑战。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责排产、排班、出勤计划执行，加工进度管控、每日订单目标交付达成；\n2、负责加工过程中人员组台、品类拆分、原料进度追踪、异常协调等业务；\n3、负责加工品质保障、加工数据准确性管理、上下游入库准确性管理；\n4、负责设备高效使用，员工积极性策略推动与执行；\n5、负责加工区域6S、生产安全、消防安全、食品安全等管理；\n6、负责促成部门各指标达成（品质、原料成本、人力成本、员工留存等）\n7、负责班次团队组织架构搭建、招聘计划、人员培养汰换，每日生产会议。\n\n岗位基本要求\n1.具备物流或仓储相关领域的大学本科及以上学历。\n2.至少5年以上物流或仓储管理经验，有生鲜加工管理经验者优先考虑。\n3.熟悉生鲜产品的质量标准和加工工艺，具备相关品控知识。\n4.具备团队搭建能力，较强的团队管理能力能够激励团队成员，提高工作效率。\n5.具备良好的沟通协调能力，能够与不同部门和供应商进行有效的合作。\n6.具备一定的问题解决能力和应变能力，能够灵活应对工作中的各种挑战。\n\n具备以下条件优先\n有食品加工或生鲜加工管理经验优先。\n\n岗位亮点\n1、公司业务发展快，晋升空间大；\n2、公司有定期培训，学习机会多，个人成长速度快。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4712066831","sourceKey":"meituan_social","company":"美团","title":"快乐猴仓储主管（冷藏）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4712066831&jobShareType=1","duty":"1、负责仓库的日常管理工作；做好仓库商品的收发管理控制工作，提高员工的工作效率；持续提升、不断改善工作效率和工作质量。提高入库工作的管理水平，保证突发问题能够予以快速、妥善的解决；\n2、监督各项管理制的执行，检查和审核员工的工作进度，负责员工的考勤及绩效考核；\n3、组织做好仓库的安全管理工作，发现问题或隐患及时上报处理；\n4、对工进行必要的岗位知识培训，同时对工作结果进行评价；\n5、合理对货位进行安排，做到物资整洁、清晰、便于操作、便于识别；\n6、提高库房各项资源的利用率；\n7、完成上级交办的其他作务。","requirements":"1、专科以上学历，物流管理等相关专业优先；\n2、3年以上物流、仓储相关领域管理工作经验，有分仓管理经验者优先；\n3、较强的计划组强能力、计划落实能力、执行能力；\n4、良好的沟通协调能力，熟练使用电脑，熟悉办公软件；\n5、熟悉物流、仓储业务流程，熟悉相关质量管理体系；\n6、有零售便利店或者生鲜工作经验优先；\n7、了解仓储自动化相关机械设备。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1、负责仓库的日常管理工作；做好仓库商品的收发管理控制工作，提高员工的工作效率；持续提升、不断改善工作效率和工作质量。提高入库工作的管理水平，保证突发问题能够予以快速、妥善的解决；\n2、监督各项管理制的执行，检查和审核员工的工作进度，负责员工的考勤及绩效考核；\n3、组织做好仓库的安全管理工作，发现问题或隐患及时上报处理；\n4、对工进行必要的岗位知识培训，同时对工作结果进行评价；\n5、合理对货位进行安排，做到物资整洁、清晰、便于操作、便于识别；\n6、提高库房各项资源的利用率；\n7、完成上级交办的其他作务。\n\n岗位基本要求\n1、专科以上学历，物流管理等相关专业优先；\n2、3年以上物流、仓储相关领域管理工作经验，有分仓管理经验者优先；\n3、较强的计划组强能力、计划落实能力、执行能力；\n4、良好的沟通协调能力，熟练使用电脑，熟悉办公软件；\n5、熟悉物流、仓储业务流程，熟悉相关质量管理体系；\n6、有零售便利店或者生鲜工作经验优先；\n7、了解仓储自动化相关机械设备。\n\n具备以下条件优先\n大型商超物流工作经验优先\n\n岗位亮点\n发展前景好，薪资体系成熟，大平台，团队工作氛围好","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4718352008","sourceKey":"meituan_social","company":"美团","title":"深圳蔬果前置品控","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4718352008&jobShareType=1","duty":"1. 负责深圳地区蔬果前置仓的品质管控工作，确保商品符合公司质量标准。  \n2. 对入库、存储及出库环节的蔬果进行抽检与评估，及时发现并反馈品质异常。  \n3. 协助制定并优化蔬果品控流程，提升前置运营效率与商品合格率。  \n4. 与采购、仓储及物流团队协同，推动品质问题的闭环解决。","requirements":"1. 大学专科及以上学历，农业、食品科学、供应链管理等相关专业优先。  \n2. 具备3年以上生鲜、蔬果或快消品行业品质管理经验。  \n3. 熟悉蔬果品类特性及常见品质问题，具备现场判断与处理能力。  \n4. 工作细致、责任心强，能适应前置仓现场工作环境。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责深圳地区蔬果前置仓的品质管控工作，确保商品符合公司质量标准。  \n2. 对入库、存储及出库环节的蔬果进行抽检与评估，及时发现并反馈品质异常。  \n3. 协助制定并优化蔬果品控流程，提升前置运营效率与商品合格率。  \n4. 与采购、仓储及物流团队协同，推动品质问题的闭环解决。\n\n岗位基本要求\n1. 大学专科及以上学历，农业、食品科学、供应链管理等相关专业优先。  \n2. 具备3年以上生鲜、蔬果或快消品行业品质管理经验。  \n3. 熟悉蔬果品类特性及常见品质问题，具备现场判断与处理能力。  \n4. 工作细致、责任心强，能适应前置仓现场工作环境。\n\n具备以下条件优先\n基本的数据分析、蔬果专业知识、沟通协作能力\n\n岗位亮点\n1. 深入生鲜供应链一线，积累实战型品控经验。  \n2. 参与流程优化与标准建设，提升专业影响力。  \n3. 地处深圳核心区域，交通便利，团队氛围积极。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4626088366","sourceKey":"meituan_social","company":"美团","title":"政府/校园渠道业务拓展经理","city":"济南市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4626088366&jobShareType=1","duty":"1、负责区域内高校、职教园区渠道开发与维护，对接院校后勤、保卫、学工等部门，洽谈校园共享电单车准入合作，推进校园站点布局、运营方案落地；\n2、统筹政企、校园项目全流程：商务谈判、合作方案撰写、合同洽谈签署、项目落地跟进、存量合作续约，完成渠道拓展指标；\n3、持续跟踪地方政策变化、区域动态，定期输出市场分析，为业务投放策略、运营调整提供依据；\n4、协同运营、合规团队，保障政企项目、校园项目平稳运营、校园运营相关问题。\n5、负责所辖区域政府主管部门对接，建立常态化沟通机制，跟进共享电单车路权、投放准入、运营政策，推动项目准入落地；","requirements":"1、本科及以上学历，市场营销、公共管理、商务管理相关专业优先；\n2、5年以上大客户商务拓展经验，拥有政府政企对接经验，或高校校园渠道拓展经验优先；有出行、共享行业资源者加分；\n3、熟悉高校校园生态，具备大客户谈判、方案撰写、资源整合能力，能够独立推进项目从洽谈至落地；\n4、优秀对外沟通、跨部门协同、项目推进能力，目标导向，具备较强结果意识；\n5、能够接受区域内短途出差，主动进取，具备良好的商务礼仪；\n6、了解共享电单车、两轮出行行业者优先。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1、负责区域内高校、职教园区渠道开发与维护，对接院校后勤、保卫、学工等部门，洽谈校园共享电单车准入合作，推进校园站点布局、运营方案落地；\n2、统筹政企、校园项目全流程：商务谈判、合作方案撰写、合同洽谈签署、项目落地跟进、存量合作续约，完成渠道拓展指标；\n3、持续跟踪地方政策变化、区域动态，定期输出市场分析，为业务投放策略、运营调整提供依据；\n4、协同运营、合规团队，保障政企项目、校园项目平稳运营、校园运营相关问题。\n5、负责所辖区域政府主管部门对接，建立常态化沟通机制，跟进共享电单车路权、投放准入、运营政策，推动项目准入落地；\n\n岗位基本要求\n1、本科及以上学历，市场营销、公共管理、商务管理相关专业优先；\n2、5年以上大客户商务拓展经验，拥有政府政企对接经验，或高校校园渠道拓展经验优先；有出行、共享行业资源者加分；\n3、熟悉高校校园生态，具备大客户谈判、方案撰写、资源整合能力，能够独立推进项目从洽谈至落地；\n4、优秀对外沟通、跨部门协同、项目推进能力，目标导向，具备较强结果意识；\n5、能够接受区域内短途出差，主动进取，具备良好的商务礼仪；\n6、了解共享电单车、两轮出行行业者优先。\n\n具备以下条件优先\n校园事务工作经验、大客户销售经验、有渠道商合作管理经验，对共享出行行业有一定了解和热爱\n\n岗位亮点\n内部业务发展快，个人成长空间大；基于公司平台接触社会资源更广泛，对个人能力提升有很大帮助","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4708709770","sourceKey":"meituan_social","company":"美团","title":"大客户销售（线索和新行业）","city":"北京市/上海市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4708709770&jobShareType=1","duty":"岗位职责：\n\n1.存量KA品牌营销运营：协同全国行业品牌提升线上经营能力，通过改善线上运营的方法，策略，有效提升商家流量、转化、转介绍等指标；\n2.白名单客户开拓：通过线上线下的方式主动拓展行业头部白名单客户，包含KA客户建立联系，挖掘需求，邀约拜访，传递产品价值，为KA客户提供整套数字化整合营销方案及商业变现的解决方案；\n3.专业赋能：研究LE行业特点，品牌线上及线下经营阻碍，帮助品牌制定专业线上经营方案和策略，输出赋能，影响品牌方；\n4.数据分析：KA销售（大客户销售）通过分析历史经营数据，行业数据分析，品牌经营数据分析，了解行业规律，确保品牌经营策略有效性，持续指导经营方案迭代；\n5.创新孵化：思考分析行业发展走势，赋能品牌共同探索下阶段行业商业模式和增长点；\n6.跨团队协同：根据业务发展需要，跨团队协调资源，共同解决商家需求，维护商家与平台的良性长久合作。","requirements":"1、KA客户分层管理：工作3年以上，有品牌客户/KA客户的销售经验；；\n2、有制作营销提案的能力，有较快的学习能力；\n3、对互联网行业各平台发展历程有认知；\n4、良好的商务沟通与方案演讲能力；\n5、本科及以上学历，熟知办公软件技能；\n6、跨部门沟通协调能力。\n7、有教育、家具家居、家用电器、亲子母婴、结婚/摄影，生活服务等行业KA销售或运营经验者优先。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n岗位职责：\n\n1.存量KA品牌营销运营：协同全国行业品牌提升线上经营能力，通过改善线上运营的方法，策略，有效提升商家流量、转化、转介绍等指标；\n2.白名单客户开拓：通过线上线下的方式主动拓展行业头部白名单客户，包含KA客户建立联系，挖掘需求，邀约拜访，传递产品价值，为KA客户提供整套数字化整合营销方案及商业变现的解决方案；\n3.专业赋能：研究LE行业特点，品牌线上及线下经营阻碍，帮助品牌制定专业线上经营方案和策略，输出赋能，影响品牌方；\n4.数据分析：KA销售（大客户销售）通过分析历史经营数据，行业数据分析，品牌经营数据分析，了解行业规律，确保品牌经营策略有效性，持续指导经营方案迭代；\n5.创新孵化：思考分析行业发展走势，赋能品牌共同探索下阶段行业商业模式和增长点；\n6.跨团队协同：根据业务发展需要，跨团队协调资源，共同解决商家需求，维护商家与平台的良性长久合作。\n\n岗位基本要求\n1、KA客户分层管理：工作3年以上，有品牌客户/KA客户的销售经验；；\n2、有制作营销提案的能力，有较快的学习能力；\n3、对互联网行业各平台发展历程有认知；\n4、良好的商务沟通与方案演讲能力；\n5、本科及以上学历，熟知办公软件技能；\n6、跨部门沟通协调能力。\n7、有教育、家具家居、家用电器、亲子母婴、结婚/摄影，生活服务等行业KA销售或运营经验者优先。\n\n岗位亮点\n岗位亮点：\n1、开放、直接的工作氛围，以逻辑、数据和事实说话，而不是岗位级别和层级。我们尊重知识和常识，努力以业务视角思考自身工作。\n2、行业覆盖面广，在这个团队你能够接触各个行业的专家，打开你的职场新视角。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4711517636","sourceKey":"meituan_social","company":"美团","title":"员工关系管理高级专家（风险安全方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4711517636&jobShareType=1","duty":"ER事件全流程处理，覆盖全国前置仓几万员工；降低事故发生率。\n\n1. 劳资纠纷处理： 负责日常员工劳资纠纷的受理、调查、调解与闭环处理，包括但不限于工资争议、工伤认定争议、解除劳动合同纠纷等。\n2. 交通/仓内事故处理： 对接城市管理者，代理商，保险公司，公司安全法务等各方，负责员工交通事故的应急响应、责任认定跟进、伤者安置与善后处理，协调交警、保险等多方资源，推动ER事件快速闭环。\n3. 对接劳动监察人社等部门，配合调查和政策推发，解释相关业务逻辑。\n4. 台账维护： 全量ER事件分类登记、全程记录、定期更新，建立规范化管理台账，确保数据真实、完整、可追溯。\n5. 经验总结与优化： 针对不同事故类型，定期总结经验教训，识别高频风险点和管理薄弱环节，针对性改进，降低事故发生率。联动城市调优管理动作， 基于ER事件数据分析，向城市管理层提供决策支持，优化骑手管理、仓储运营、站点调度等可能引发事故和纠纷的关键环节，持续降低事故发生率。\n6. 流程与制度完善：推动完善员工关系管理相关制度（例如车辆车牌管理）、流程与标准，形成规范化的操作手册和应急预案，了解代理商的垫款和兜底空间能力，建立风险备用金等相关机制。\n7. 保险公司理赔进度跟进，优化保险条款，确保保障范围与实际风险匹配，管理保费合理性，定期评估保险方案性价比。","requirements":"1. 大学本科及以上学历，人力资源相关专业优先。  \n2. 至少3年员工关系或相关业务运营管理工作经验。  \n3. 熟悉劳动法律法规，具备较强的沟通协调与问题解决能力。  \n4. 工作城市为北京市，能适应跨部门协作与快节奏工作环境。\n5.  需要全国出差，根据监察部门要求、事故严重程度等，现场沟通。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\nER事件全流程处理，覆盖全国前置仓几万员工；降低事故发生率。\n\n1. 劳资纠纷处理： 负责日常员工劳资纠纷的受理、调查、调解与闭环处理，包括但不限于工资争议、工伤认定争议、解除劳动合同纠纷等。\n2. 交通/仓内事故处理： 对接城市管理者，代理商，保险公司，公司安全法务等各方，负责员工交通事故的应急响应、责任认定跟进、伤者安置与善后处理，协调交警、保险等多方资源，推动ER事件快速闭环。\n3. 对接劳动监察人社等部门，配合调查和政策推发，解释相关业务逻辑。\n4. 台账维护： 全量ER事件分类登记、全程记录、定期更新，建立规范化管理台账，确保数据真实、完整、可追溯。\n5. 经验总结与优化： 针对不同事故类型，定期总结经验教训，识别高频风险点和管理薄弱环节，针对性改进，降低事故发生率。联动城市调优管理动作， 基于ER事件数据分析，向城市管理层提供决策支持，优化骑手管理、仓储运营、站点调度等可能引发事故和纠纷的关键环节，持续降低事故发生率。\n6. 流程与制度完善：推动完善员工关系管理相关制度（例如车辆车牌管理）、流程与标准，形成规范化的操作手册和应急预案，了解代理商的垫款和兜底空间能力，建立风险备用金等相关机制。\n7. 保险公司理赔进度跟进，优化保险条款，确保保障范围与实际风险匹配，管理保费合理性，定期评估保险方案性价比。\n\n岗位基本要求\n1. 大学本科及以上学历，人力资源相关专业优先。  \n2. 至少3年员工关系或相关业务运营管理工作经验。  \n3. 熟悉劳动法律法规，具备较强的沟通协调与问题解决能力。  \n4. 工作城市为北京市，能适应跨部门协作与快节奏工作环境。\n5.  需要全国出差，根据监察部门要求、事故严重程度等，现场沟通。\n\n具备以下条件优先\n1. 具备一线员工及家属谈判能力： 直接与员工及其家属进行沟通谈判，妥善处理赔偿、安抚等事宜，维护公司形象与员工关系稳定。\n2. 具备数据归纳整理能力： 定期汇总各类型事故/纠纷数据，从事件类型、发生频次、责任方、赔付金额、处理周期等多维度进行数据分析和归纳整理。\n3. 总结汇报能力： 每半年度完成风险与安全方向的全面总结，沉淀典型ERcase与经验，向管理层汇报风险态势、处理成效、优化成果及下一步规划，形成可复制的经验方法论。\n\n岗位亮点\n1. 业务发展上升期，平稳扩张，与平台一起发展进步。\n2. 提供完善的职业发展通道。  \n3. 团队氛围开放包容，鼓励创新与主动担当。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4718245519","sourceKey":"meituan_social","company":"美团","title":"景点玩乐服务流程运营","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4718245519&jobShareType=1","duty":"1、负责统筹服务全流程和链路的设计与运营，持续改善客户/商户服务的工作流程、执行规范等基础制度，并能落地实施。\n2、持续提升客户服务解决能力，关注客户体验，建立有效的运营机制，赋能客服团队并提升其解决问题的能力。\n3、通过对行业/业务分析&调研、客户声音的洞察&分析等举措，发现痛点问题，与协同团队密切合作，推动问题从源头解决。\n4、负责与业务建立良好的协同关系，带领团队通过深入走访业务一线等方式熟悉业务运营的各个环节，识别有效问题，主动为业务团队提出改善建议并推动需求项目执行。\n5、引入AI工具辅助服务流程优化。","requirements":"1、本科及以上学历，3年以上客户服务行业经验。\n2、具备大中型复杂项目管理能力和较强的业务推动能力，有一定的目标导向，自驱力强。\n3、逻辑性强，具备较强的数据分析能力，能清楚的判断客户痛点，具备发现问题及主动改善能力，解析影响客户体验的具体因素，结构化输出合理化解决方案，并推动方案执行达成结果。\n4、能够协同或整合内外部资源 ，有团队合作精神，工作严谨踏实，责任心强。\n5、能够熟练运用AI工具和人机协作，具备岗位要求的AI能力。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1、负责统筹服务全流程和链路的设计与运营，持续改善客户/商户服务的工作流程、执行规范等基础制度，并能落地实施。\n2、持续提升客户服务解决能力，关注客户体验，建立有效的运营机制，赋能客服团队并提升其解决问题的能力。\n3、通过对行业/业务分析&调研、客户声音的洞察&分析等举措，发现痛点问题，与协同团队密切合作，推动问题从源头解决。\n4、负责与业务建立良好的协同关系，带领团队通过深入走访业务一线等方式熟悉业务运营的各个环节，识别有效问题，主动为业务团队提出改善建议并推动需求项目执行。\n5、引入AI工具辅助服务流程优化。\n\n岗位基本要求\n1、本科及以上学历，3年以上客户服务行业经验。\n2、具备大中型复杂项目管理能力和较强的业务推动能力，有一定的目标导向，自驱力强。\n3、逻辑性强，具备较强的数据分析能力，能清楚的判断客户痛点，具备发现问题及主动改善能力，解析影响客户体验的具体因素，结构化输出合理化解决方案，并推动方案执行达成结果。\n4、能够协同或整合内外部资源 ，有团队合作精神，工作严谨踏实，责任心强。\n5、能够熟练运用AI工具和人机协作，具备岗位要求的AI能力。\n\n岗位亮点\n1、热门核心行业以及重点岗位，能够全面接触以及深入了解行业动态、服务策略等，有助于眼界开阔。\n2、有机会参与或统筹复杂业务场景中跨部门重大项目管理工作。\n3、专业可靠的工作搭子，团队关系融洽，工作学习氛围好，重视每个成员的个人发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4711646586","sourceKey":"meituan_social","company":"美团","title":"供应链计划专家","city":"广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4711646586&jobShareType=1","duty":"1、负责供应链品类计划：基于用户需求预测，输出品类备货计划，并通过持续提升计划准确度及备货弹性，保障商品稳定供给，提升用户体验； \n2、负责供应链产品优化：根据不同品类的独特发展需求及特点，建立全链路供应链优化及解决方案，沉淀策略并推进产品化，提升自动化进程； \n3、负责供应链运营提效：通过管控输入及输出指标，监控库存现货率、周转、库龄，及时提出滞销、断货预警，识别风险点及机会点，提升现有供给链路效率。","requirements":"1、具备创业精神，积极主动，有较强的自驱力； \n2、熟练掌握各类办公软件，具有较强的逻辑思考能力、数据分析能力、复杂问题的拆解能力； \n3、具备沟通、协同、推动影响力。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1、负责供应链品类计划：基于用户需求预测，输出品类备货计划，并通过持续提升计划准确度及备货弹性，保障商品稳定供给，提升用户体验； \n2、负责供应链产品优化：根据不同品类的独特发展需求及特点，建立全链路供应链优化及解决方案，沉淀策略并推进产品化，提升自动化进程； \n3、负责供应链运营提效：通过管控输入及输出指标，监控库存现货率、周转、库龄，及时提出滞销、断货预警，识别风险点及机会点，提升现有供给链路效率。\n\n岗位基本要求\n1、具备创业精神，积极主动，有较强的自驱力； \n2、熟练掌握各类办公软件，具有较强的逻辑思考能力、数据分析能力、复杂问题的拆解能力； \n3、具备沟通、协同、推动影响力。\n\n岗位亮点\n1、供应链能力建设价值高：供给侧需要有无限接近和满足消费者的能力，对于需求计划，库存计划，补货管理专业能力建设；以及通过供应链条的整体优化最大化供给的弹性。这种能力区别于现在的远场电商/线下电商已有的供应链能力，也会成为未来即时零售的核心竞争力。 \n2、构建更宽广的职业发展图景：有机会全身心地参与新零售业态，在急速发展的业务当中，从0到1地建立对业务和产业的认知，能和电商、O2O、物流、零售、人工智能等多元化背景的团队一起，综合学习，共同进步。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4679202315","sourceKey":"meituan_social","company":"美团","title":"小象超市长沙-PC仓运营支持主管","city":"长沙市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4679202315&jobShareType=1","duty":"1、数据监控体系搭建：能深入了解业务，熟悉负责方向的业务流程，建立区域业务数据跟踪监控体系，搭建可准确反映业务运作状况的数据指标体系和数据产品；\n2、数据提取：负责团队内业务数据需求梳理，结合业务逻辑，为团队提供数据查询、提取及数据分析处理工作；\n3、数据看板及可视化：根据公司提供的相关数据渠道搭建并维护各种线上报表，为业务侧提供数据过程监控，能够使用Ex-cel、SQL、Power BI、Ta-bleau等工具实现数据可视化；\n4、数据检核：配合运营团队完成对业务侧的日常关键输入/输出数据核查、异常定位等工作；\n5、项目管理：参与业务核心项目，负责核心项目的运营支持，协助项目组成员目标制定、策略拆解、路径达成、组织资源等多维度的合理性和可提升的机会点，及时识别业务风险、推动问题解决、形成闭环管理，保障项目目标达成；\n6、部门内其他需要协调完成的相关工作。","requirements":"1、专科及以上学历，计算机、数学、统计学相关专业优先；\n2、至少3年左右数据分析经验，互联网数据库经验者优先，拥有1年以上项目管理及PMO相关工作经验优先；\n3、精通HIVE/SQL数据查询语言，有很好数据报表以及报告呈现能力；熟练操作办公软件，掌握Ex-cel、Power BI、Ta-bleau等工具，并有使用经验者优先；\n4、具备快速学习能力，能在短期内快速了解业务逻辑；\n5、具备较强的逻辑思维能力、独立解决问题的能力；\n6、积极主动、性格开朗、善于沟通、工作严谨、责任心强、具有团队合作精神。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、数据监控体系搭建：能深入了解业务，熟悉负责方向的业务流程，建立区域业务数据跟踪监控体系，搭建可准确反映业务运作状况的数据指标体系和数据产品；\n2、数据提取：负责团队内业务数据需求梳理，结合业务逻辑，为团队提供数据查询、提取及数据分析处理工作；\n3、数据看板及可视化：根据公司提供的相关数据渠道搭建并维护各种线上报表，为业务侧提供数据过程监控，能够使用Ex-cel、SQL、Power BI、Ta-bleau等工具实现数据可视化；\n4、数据检核：配合运营团队完成对业务侧的日常关键输入/输出数据核查、异常定位等工作；\n5、项目管理：参与业务核心项目，负责核心项目的运营支持，协助项目组成员目标制定、策略拆解、路径达成、组织资源等多维度的合理性和可提升的机会点，及时识别业务风险、推动问题解决、形成闭环管理，保障项目目标达成；\n6、部门内其他需要协调完成的相关工作。\n\n岗位基本要求\n1、专科及以上学历，计算机、数学、统计学相关专业优先；\n2、至少3年左右数据分析经验，互联网数据库经验者优先，拥有1年以上项目管理及PMO相关工作经验优先；\n3、精通HIVE/SQL数据查询语言，有很好数据报表以及报告呈现能力；熟练操作办公软件，掌握Ex-cel、Power BI、Ta-bleau等工具，并有使用经验者优先；\n4、具备快速学习能力，能在短期内快速了解业务逻辑；\n5、具备较强的逻辑思维能力、独立解决问题的能力；\n6、积极主动、性格开朗、善于沟通、工作严谨、责任心强、具有团队合作精神。\n\n岗位亮点\n1、公司业务发展快，晋升空间大；\n2、学习机会多，个人成长速度快；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4469108597","sourceKey":"meituan_social","company":"美团","title":"美团骑行-资管城市经理-安徽","city":"合肥市/厦门市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4469108597&jobShareType=1","duty":"1.负责所辖区域运营资源供给保障及仓库管理，支撑管辖区域经营目标的达成；\n2.执行落地相关管理要求及流程标准；\n3.对资产/作业/现场等的各场景下的安全管理工作进行体系化建设，防范和处理风险；\n4.管理和培养团队，持续提升团队现场管理能力和作业效率。","requirements":"1.本科及以上学历，具有2年以上团队管理经验，有相关物流仓储工作经验优先；\n2.具有较强的人际交往能力和应变能力；\n3.熟悉基本电脑办公软件，有良好的数据分析和提炼能力；\n4.具有强烈的责任感，学习能力强，吃苦耐劳，认可公司绿色出行与共享理念。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.负责所辖区域运营资源供给保障及仓库管理，支撑管辖区域经营目标的达成；\n2.执行落地相关管理要求及流程标准；\n3.对资产/作业/现场等的各场景下的安全管理工作进行体系化建设，防范和处理风险；\n4.管理和培养团队，持续提升团队现场管理能力和作业效率。\n\n岗位基本要求\n1.本科及以上学历，具有2年以上团队管理经验，有相关物流仓储工作经验优先；\n2.具有较强的人际交往能力和应变能力；\n3.熟悉基本电脑办公软件，有良好的数据分析和提炼能力；\n4.具有强烈的责任感，学习能力强，吃苦耐劳，认可公司绿色出行与共享理念。\n\n具备以下条件优先\n有两轮共享出行、骑行资产管理相关经验的\n\n岗位亮点\n1.岗位未来可以承担更大的管理宽幅和职级提升；\n2.职级上，表现优异着可获得晋升机会；\n3.公司平台大，发展空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4701466661","sourceKey":"meituan_social","company":"美团","title":"公共事务专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4701466661&jobShareType=1","duty":"1.日常与网信等政府部门、行业协会相关方的沟通，包括会议参与、活动组织等，承担对外公文及材料的撰写工作。\n2.熟悉网络文化领域的相关政策，熟练运用AI工具协助做好研判分析，寻找创造双赢合作机会，为业务发展提供助力。\n3.支持公司相关业务板块的需求，获取更多资源和正向合作机会，及时化解相关危机，排查业务运行过程中的风险。","requirements":"1.本科及以上学历，5年以上工作经验。\n2.具备较强的政治敏锐性和政策敏感性，具备良好的沟通表达能力。\n3.工作具备主动性，善于思考总结和使用相关AI产品工具，能适应互联网创新环境。","description":"部门介绍\n公司事务平台负责构建公司的公共战略体系，助力业务可持续发展及公司对外影响力的提升。通过内外部风险管理，确保公司合规发展；通过深耕公共战略，推动内外良好沟通，连接公司发展与社会期待，助力业务高质量发展；通过管理社会责任议题、公益投入等，助力公司创造更多社会价值；同时为公司提供行政、采购等基础服务。我们坚持“懂业务、拿结果，勇担当、善协同，不唯上、只唯真”的工作理念，期待具有公共战略素养、了解公司治理逻辑的你加入！\n\n岗位职责\n1.日常与网信等政府部门、行业协会相关方的沟通，包括会议参与、活动组织等，承担对外公文及材料的撰写工作。\n2.熟悉网络文化领域的相关政策，熟练运用AI工具协助做好研判分析，寻找创造双赢合作机会，为业务发展提供助力。\n3.支持公司相关业务板块的需求，获取更多资源和正向合作机会，及时化解相关危机，排查业务运行过程中的风险。\n\n岗位基本要求\n1.本科及以上学历，5年以上工作经验。\n2.具备较强的政治敏锐性和政策敏感性，具备良好的沟通表达能力。\n3.工作具备主动性，善于思考总结和使用相关AI产品工具，能适应互联网创新环境。\n\n岗位亮点\n1.大平台锻炼机会：美团拥有庞大的用户基础和广泛的业务覆盖，为员工提供了在大平台上锻炼和成长的机会。员工可以接触到最前沿的技术和业务模式，参与大型项目，积累宝贵的经验。\n2.成长型组织：美团注重员工的成长和发展，提供多样化的培训和学习机会。员工可以参与内部培训课程、在线学习平台、跨部门交流等活动，不断提升自己的专业技能和综合素质。同时，公司还鼓励员工跨部门合作，拓展视野和思维方式。\n3.共同参与和见证团队发展：美团正处于快速发展阶段，员工可以亲身参与并见证公司的成长和变革。这种参与感不仅能让员工感受到自己的价值和贡献，还能激发员工的归属感和自豪感。\n4.创新氛围浓厚：公司鼓励员工勇于尝试、敢于创新，积极探索使用AI，为公司的未来发展贡献智慧和力量。在这种创新氛围中，员工可以不断挑战自我、超越自我，实现个人价值和企业价值的双赢。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4674117477","sourceKey":"meituan_social","company":"美团","title":"下沉市场-校园业务运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4674117477&jobShareType=1","duty":"1.负责校园合作商运营，结合市场竞争及业务盈亏表现，制定合作政策及运营政策；搭建商管理机制，推动合作商完成校园开拓和运营，通过数据监控和分析，优化过程管理质量。\n\n2.提升校园业务开展系统化能力，通过CRM产品、销售工具等完成对高校经营基本要素（学校、食堂、档口、履约路线等）的线上化运营，结合流程建设等改善运营效率。\n\n3.挖掘并培育下沉市场校内外新增长机会，包含校园团购、校园跑腿等多模式尝试及培育，并协作其他团队实现相应资源/政策落地。","requirements":"1.本科及以上学历，有4年以上业务运营经验，目标感、自驱力强。\n\n2.具备优秀的逻辑思维和沟通表达能力，善于跨团队协同，具备中大型项目管理经验者优先。\n\n3.具备数据SQL使用和分析和复盘。","description":"部门介绍\n美团核心本地商业-下沉市场发展部于2015年成立，通过招募优质的合作商伙伴并对其业务经营能力、组织能力等赋能，以期为下沉城市提供一站式的本地生活服务。\n下沉市场发展部的业务场景涵盖了外卖餐饮、团购、拼好饭、闪购、医药等多元化的生活服务领域，同时搭建了一套稳定、高效的即时配送网络，为更多本地用户提供品质化、多样化、便捷高效的生活服务体验，为当地商户提供数字化发展机遇、提升数字化水平，为社会创造更多的就地就业机会。\n截至2024年6月，下沉市场发展部已开拓全国4000+县区市，帮助百万商户实现本地生活服务数字化，日订单量突破千万，为数十万名骑手提供就业岗位，让本地生活服务逐渐成长为地方新基建，实现美团“帮助大家吃得更好，生活更好”的使命！\n\n岗位职责\n1.负责校园合作商运营，结合市场竞争及业务盈亏表现，制定合作政策及运营政策；搭建商管理机制，推动合作商完成校园开拓和运营，通过数据监控和分析，优化过程管理质量。\n\n2.提升校园业务开展系统化能力，通过CRM产品、销售工具等完成对高校经营基本要素（学校、食堂、档口、履约路线等）的线上化运营，结合流程建设等改善运营效率。\n\n3.挖掘并培育下沉市场校内外新增长机会，包含校园团购、校园跑腿等多模式尝试及培育，并协作其他团队实现相应资源/政策落地。\n\n岗位基本要求\n1.本科及以上学历，有4年以上业务运营经验，目标感、自驱力强。\n\n2.具备优秀的逻辑思维和沟通表达能力，善于跨团队协同，具备中大型项目管理经验者优先。\n\n3.具备数据SQL使用和分析和复盘。\n\n具备以下条件优先\n具备校园业务经验、以及服务商、合作商运营经验者优先。\n\n岗位亮点\n外卖核心业务，平台大，视角广，有足够的成长空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4717145056","sourceKey":"meituan_social","company":"美团","title":"社群运营高级专家","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4717145056&jobShareType=1","duty":"1、社群体系策略制定：制定平台深入城市的社群运营的策略，包括自营社群定位、外部社群合作、以及两者之间的协同机制；基于市场趋势、用户洞察和竞争格局，制定中长期社群运营发展策略\n2、用户行为变化设计：基于用户洞察，设计通过社群运营引发用户从认知到行动再到传播的全链路行为变化路径（C的变化）；建立用户分层运营机制，实现精准触达与高效转化\n3、自营社群矩阵搭建：建立多层次、多维度的自营社群矩阵，包括社群搭建、内容运营、活动策划、用户管理等全链路流程\n4、外部社群生态建设：建立和维护与各类外部社群的合作关系；探索多样化的合作模式；建立外部社群渠道的价值评估体系，优化资源配置，提升合作ROI\n5、数据驱动优化：建立社群运营的指标体系，通过数据分析持续优化社群运营效率和效果；运用AI技术提升社群运营效率，探索社群渠道的AI化管理","requirements":"1、本科及以上学历，5年以上用户运营/社群运营相关经验，其中至少3年团队管理的经验\n2、有互联网平台、本地生活、社交产品等相关行业背景，对社群经济有深刻理解；具备从0到1搭建社群运营体系的经验，有成功的社群增长案例\n3、具备极强的策略思维能力，能够从宏观视角制定业务策略，并拆解为可执行的行动方案；面对复杂业务场景，能够快速识别核心矛盾，做出有价值的策略选择\n4、具备优秀的数据分析能力，能够通过数据驱动业务决策；建立数据指标体系，持续追踪和优化运营效果\n5、具备出色的团队搭建和人才培养能力，能够建立清晰的人才梯队，激发团队潜能；具备优秀的跨部门协同能力，能够推动复杂项目高效落地\n6、在行业有一定影响力，有行业演讲、文章发表等经历者优先；对本地生活行业有深刻洞察，能够代表行业发声","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1、社群体系策略制定：制定平台深入城市的社群运营的策略，包括自营社群定位、外部社群合作、以及两者之间的协同机制；基于市场趋势、用户洞察和竞争格局，制定中长期社群运营发展策略\n2、用户行为变化设计：基于用户洞察，设计通过社群运营引发用户从认知到行动再到传播的全链路行为变化路径（C的变化）；建立用户分层运营机制，实现精准触达与高效转化\n3、自营社群矩阵搭建：建立多层次、多维度的自营社群矩阵，包括社群搭建、内容运营、活动策划、用户管理等全链路流程\n4、外部社群生态建设：建立和维护与各类外部社群的合作关系；探索多样化的合作模式；建立外部社群渠道的价值评估体系，优化资源配置，提升合作ROI\n5、数据驱动优化：建立社群运营的指标体系，通过数据分析持续优化社群运营效率和效果；运用AI技术提升社群运营效率，探索社群渠道的AI化管理\n\n岗位基本要求\n1、本科及以上学历，5年以上用户运营/社群运营相关经验，其中至少3年团队管理的经验\n2、有互联网平台、本地生活、社交产品等相关行业背景，对社群经济有深刻理解；具备从0到1搭建社群运营体系的经验，有成功的社群增长案例\n3、具备极强的策略思维能力，能够从宏观视角制定业务策略，并拆解为可执行的行动方案；面对复杂业务场景，能够快速识别核心矛盾，做出有价值的策略选择\n4、具备优秀的数据分析能力，能够通过数据驱动业务决策；建立数据指标体系，持续追踪和优化运营效果\n5、具备出色的团队搭建和人才培养能力，能够建立清晰的人才梯队，激发团队潜能；具备优秀的跨部门协同能力，能够推动复杂项目高效落地\n6、在行业有一定影响力，有行业演讲、文章发表等经历者优先；对本地生活行业有深刻洞察，能够代表行业发声\n\n具备以下条件优先\n有独立负责社群0-1搭建或品牌会员运营经验的优先\n\n岗位亮点\n1、业务持续高速增长，核心战略方向，成长空间充足；理解全国城市不同用户特征，影响亿万用户的本地生活体验\n2、岗位视角全面，横跨自营社群与外部社群生态，是深度理解社群经济运营的较全面视角之一\n3、团队氛围融洽，业务节奏快，适合有进取心、有想法、能落地的运营leader；与优秀的人一起做有挑战的事","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4716968935","sourceKey":"meituan_social","company":"美团","title":"热点运营高级专家","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4716968935&jobShareType=1","duty":"1、热点运营顶层设计：制定热点运营的整体策略，形成系统化的热点运营方法论；建立热点标签生产及内容关联、热点内容生产与分发、重点场景完整解决方案的三层策略体系\n2、热点内容生产与运营：建立热点标签与存量内容的高效关联机制，实现热点的快速内容化；建立规模化的热点内容生产模式，包括常态热点和非常态热点、线上线下联动的差异化承接策略。\n3、市场与行业影响力突破：灵活调度资源形成多样性的合作机制，通过热点运营持续扩大平台在本地生活领域的影响力，建立平台在热点响应方面的行业标杆地位；\n4、团队搭建与资源整合：搭建高效热点运营团队，培养具备热点敏感度和执行力的专业人才；整合外部合作伙伴资源，包括兼职团队、地推渠道等，建立灵活的外部协作网络","requirements":"1、本科及以上学历，5年以上市场营销、品牌运营或热点营销相关经验，其中至少3年独立项目负责人或管理经验\n2、有互联网平台、本地生活、内容平台等相关行业背景，对热点营销有深刻理解和实操经验；具备极强的热点敏感度和判断力，能够快速识别有价值的社会热点并进行有效承接\n3、有成功操盘大型热点营销活动的经验，有从热点发掘到效果放大的完整案例；具备创新思维，能够不断探索热点运营的新模式、新路径\n4、具备完整的从策略到落地的全链路操盘能力，能够独立制定并落地热点运营策略，对业务结果负责；熟悉搜索承接、内容分发等多端触达逻辑\n5、具备较强的策略思维、数据分析能力和跨团队协作能力，能够通过数据发现问题、验证策略并持续优化；具备优秀的团队搭建和人才培养能力\n6、在行业有一定影响力，有行业演讲、文章发表等经历者优先；能够代表行业发声，参与行业对话","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1、热点运营顶层设计：制定热点运营的整体策略，形成系统化的热点运营方法论；建立热点标签生产及内容关联、热点内容生产与分发、重点场景完整解决方案的三层策略体系\n2、热点内容生产与运营：建立热点标签与存量内容的高效关联机制，实现热点的快速内容化；建立规模化的热点内容生产模式，包括常态热点和非常态热点、线上线下联动的差异化承接策略。\n3、市场与行业影响力突破：灵活调度资源形成多样性的合作机制，通过热点运营持续扩大平台在本地生活领域的影响力，建立平台在热点响应方面的行业标杆地位；\n4、团队搭建与资源整合：搭建高效热点运营团队，培养具备热点敏感度和执行力的专业人才；整合外部合作伙伴资源，包括兼职团队、地推渠道等，建立灵活的外部协作网络\n\n岗位基本要求\n1、本科及以上学历，5年以上市场营销、品牌运营或热点营销相关经验，其中至少3年独立项目负责人或管理经验\n2、有互联网平台、本地生活、内容平台等相关行业背景，对热点营销有深刻理解和实操经验；具备极强的热点敏感度和判断力，能够快速识别有价值的社会热点并进行有效承接\n3、有成功操盘大型热点营销活动的经验，有从热点发掘到效果放大的完整案例；具备创新思维，能够不断探索热点运营的新模式、新路径\n4、具备完整的从策略到落地的全链路操盘能力，能够独立制定并落地热点运营策略，对业务结果负责；熟悉搜索承接、内容分发等多端触达逻辑\n5、具备较强的策略思维、数据分析能力和跨团队协作能力，能够通过数据发现问题、验证策略并持续优化；具备优秀的团队搭建和人才培养能力\n6、在行业有一定影响力，有行业演讲、文章发表等经历者优先；能够代表行业发声，参与行业对话\n\n岗位亮点\n1、业务持续高速增长，核心战略方向，成长空间充足；理解全国城市不同用户特征，影响亿万用户的本地生活体验\n2、岗位视角全面，横跨热点识别、内容生产、线上线下联动等多个维度，是深度理解热点营销运营的较全面视角之一\n3、团队氛围融洽，业务节奏快，适合有进取心、有想法、能落地的运营leader；有机会打造行业级的热点运营方法论","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4716978871","sourceKey":"meituan_social","company":"美团","title":"会员运营高级专家","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4716978871&jobShareType=1","duty":"1、会员权益体系设计：结合平台会员结构进行权益体系顶层策略指定，通过有效的权益设计和运营手段，激发会员的活跃度和忠诚度\n2、品牌与平台会员体系协同：兼顾品牌会员体系与平台会员体系的运营需求，实现两者之间的协同效应。能打造行业内有影响力的标杆案例并沉淀系统方法论\n3、AI技术赋能会员运营：探索AI技术在会员运营中的应用，通过技术手段提升会员运营的效率和效果；将AI能力融入日常会员运营体系，推动会员运营的智能化升级\n4、数据驱动与效果评估：建立完善会员运营的数据指标体系，包括会员规模、活跃度、留存率、LTV等核心指标；建立会员价值的评估模型，量化会员运营对公司业务的贡献，为资源投入决策提供依据\n5、团队搭建与人才培养：搭建高效会员运营团队（10-15人），培养具备会员策略思维和运营能力的专业人才；与品牌方、产品团队、技术团队等高效协同，推动会员运营策略的落地执行","requirements":"1、本科及以上学历，8年以上用户运营、会员运营或CRM相关经验，其中至少3年管理经验\n2、有互联网平台、零售、餐饮等相关行业的会员运营经验，对会员经济有深刻理解；有从0到1搭建会员体系或重构会员权益体系的成功经验，对会员权益设计有深刻洞察\n3、有连锁品牌会员运营经验，了解品牌会员体系与平台会员体系的差异和协同点；有成功操盘大型会员运营项目的经验，能够将创意构想转化为可执行、可衡量的增长方案\n4、具备优秀的方法论沉淀和输出能力，能够将实战经验转化为可复用的知识体系；对AI工具在运营场景有实践认知，能将AI能力融入日常运营体系\n5、具备较强的策略思维、数据分析能力和跨团队协作能力，能够通过数据驱动业务决策；具备优秀的团队搭建和人才培养能力","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1、会员权益体系设计：结合平台会员结构进行权益体系顶层策略指定，通过有效的权益设计和运营手段，激发会员的活跃度和忠诚度\n2、品牌与平台会员体系协同：兼顾品牌会员体系与平台会员体系的运营需求，实现两者之间的协同效应。能打造行业内有影响力的标杆案例并沉淀系统方法论\n3、AI技术赋能会员运营：探索AI技术在会员运营中的应用，通过技术手段提升会员运营的效率和效果；将AI能力融入日常会员运营体系，推动会员运营的智能化升级\n4、数据驱动与效果评估：建立完善会员运营的数据指标体系，包括会员规模、活跃度、留存率、LTV等核心指标；建立会员价值的评估模型，量化会员运营对公司业务的贡献，为资源投入决策提供依据\n5、团队搭建与人才培养：搭建高效会员运营团队（10-15人），培养具备会员策略思维和运营能力的专业人才；与品牌方、产品团队、技术团队等高效协同，推动会员运营策略的落地执行\n\n岗位基本要求\n1、本科及以上学历，8年以上用户运营、会员运营或CRM相关经验，其中至少3年管理经验\n2、有互联网平台、零售、餐饮等相关行业的会员运营经验，对会员经济有深刻理解；有从0到1搭建会员体系或重构会员权益体系的成功经验，对会员权益设计有深刻洞察\n3、有连锁品牌会员运营经验，了解品牌会员体系与平台会员体系的差异和协同点；有成功操盘大型会员运营项目的经验，能够将创意构想转化为可执行、可衡量的增长方案\n4、具备优秀的方法论沉淀和输出能力，能够将实战经验转化为可复用的知识体系；对AI工具在运营场景有实践认知，能将AI能力融入日常运营体系\n5、具备较强的策略思维、数据分析能力和跨团队协作能力，能够通过数据驱动业务决策；具备优秀的团队搭建和人才培养能力\n\n具备以下条件优先\n具备出色的外部影响力，有行业演讲、文章发表等经历者优先；能够代表行业发声，提升公司在会员运营领域的品牌影响力\n\n岗位亮点\n1、业务持续高速增长，核心战略方向，成长空间充足；理解全国城市不同用户特征，影响亿万用户的本地生活体验\n2、岗位视角全面，横跨品牌会员与平台会员体系，是深度理解会员经济运营的较全面视角之一；有机会打造行业级的会员运营方法论\n3、团队氛围融洽，业务节奏快，适合有进取心、有想法、能落地的运营leader；与优秀的人一起做有挑战的事，推动AI技术在会员运营中的创新应用","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4716143043","sourceKey":"meituan_social","company":"美团","title":"内容运营高级专家","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4716143043&jobShareType=1","duty":"1、内容运营体系设计：制定平台城市化内容运营的整体策略，包括内容定位、内容标准、内容生态等核心框架；\n2、内容生产能力/流程建设：规划和建设组织的内容生产能力，包括内部团队、外部合作、UGC激励等多种生产模式；建立内容质量标准体系，包括内容完整性、鲜活度、可信度等维度的标准\n3、内容分发模型推动：推动内容分发策略迭代，通过搜索、推荐、活动等多渠道实现内容的有效触达；通过活动策划、用户激励等手段促进内容消费，提升内容的二次传播和转化效果\n4、团队搭建与人才培养：搭建高效的内容运营团队，培养具备内容策划、生产和分发能力的专业人才；与产品、技术、市场、社群等部门高效协同，推动内容运营策略的落地执行","requirements":"1、本科及以上学历，8年以上内容运营、内容营销或内容产品相关经验，其中至少3年管理经验\n2、有互联网平台、内容平台、本地生活等相关行业背景，对内容生态有深刻理解；具备优秀的内容策划能力，有从0到1搭建内容运营体系的经验\n3、对平台内容生态有深入了解，能够制定符合平台特性的内容策略；熟悉搜索承接、推荐分发等多端触达逻辑\n4、具备优秀的数据分析能力，能够通过数据驱动内容运营决策；建立内容运营效果评估体系，持续追踪和优化运营效果\n5、具备出色的团队搭建和人才培养能力，能够建立清晰的人才梯队，激发团队潜能；具备优秀的跨部门协同能力，能够推动复杂项目高效落地","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1、内容运营体系设计：制定平台城市化内容运营的整体策略，包括内容定位、内容标准、内容生态等核心框架；\n2、内容生产能力/流程建设：规划和建设组织的内容生产能力，包括内部团队、外部合作、UGC激励等多种生产模式；建立内容质量标准体系，包括内容完整性、鲜活度、可信度等维度的标准\n3、内容分发模型推动：推动内容分发策略迭代，通过搜索、推荐、活动等多渠道实现内容的有效触达；通过活动策划、用户激励等手段促进内容消费，提升内容的二次传播和转化效果\n4、团队搭建与人才培养：搭建高效的内容运营团队，培养具备内容策划、生产和分发能力的专业人才；与产品、技术、市场、社群等部门高效协同，推动内容运营策略的落地执行\n\n岗位基本要求\n1、本科及以上学历，8年以上内容运营、内容营销或内容产品相关经验，其中至少3年管理经验\n2、有互联网平台、内容平台、本地生活等相关行业背景，对内容生态有深刻理解；具备优秀的内容策划能力，有从0到1搭建内容运营体系的经验\n3、对平台内容生态有深入了解，能够制定符合平台特性的内容策略；熟悉搜索承接、推荐分发等多端触达逻辑\n4、具备优秀的数据分析能力，能够通过数据驱动内容运营决策；建立内容运营效果评估体系，持续追踪和优化运营效果\n5、具备出色的团队搭建和人才培养能力，能够建立清晰的人才梯队，激发团队潜能；具备优秀的跨部门协同能力，能够推动复杂项目高效落地\n\n具备以下条件优先\n在行业有一定影响力，有行业演讲、文章发表等经历者优先；对内容运营领域有深刻洞察，能够代表行业发声\n\n岗位亮点\n1、业务持续高速增长，核心战略方向，成长空间充足；理解全国城市不同用户特征，影响亿万用户的本地生活体验\n2、岗位视角全面，横跨内容生产、内容分发、搜索承接等多个维度，是深度理解内容运营的较全面视角之一；有机会探索AI技术在内容生产中的创新应用\n3、团队氛围融洽，业务节奏快，适合有进取心、有想法、能落地的运营leader；与优秀的人一起做有挑战的事，打造行业级的内容运营方法论","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4715510665","sourceKey":"meituan_social","company":"美团","title":"商业分析师","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4715510665&jobShareType=1","duty":"1.协同公信力生态和星级评价业务团队一起深入分析研究业务逻辑，通过数据帮助业务制定发展方向和策略；\n2.数据洞察诊断分析，通过数据发现业务问题，并进行专题分析，输出结论和建议；\n3.从App整体视角和项目视角，提供策略制定、分析体系搭建、监控体系设计及监控分析，评估分析的闭环，为业务执行提供全方面的分析建议，并积极推进策略落地；\n4.关注外部行业和公司变化，编写研究报告，为平台提供发展建议；","requirements":"1.有行业视角和具体业务分析项目落地经验；\n2.具有框架式分析能力，较好的逻辑思维能力；\n3.沟通能力较好，积极主动，具备自驱力和成长意愿；\n4.具有优秀的商业分析技能，熟练掌握SQL等数据处理和分析工具，具备一定的算法建模能力","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1.协同公信力生态和星级评价业务团队一起深入分析研究业务逻辑，通过数据帮助业务制定发展方向和策略；\n2.数据洞察诊断分析，通过数据发现业务问题，并进行专题分析，输出结论和建议；\n3.从App整体视角和项目视角，提供策略制定、分析体系搭建、监控体系设计及监控分析，评估分析的闭环，为业务执行提供全方面的分析建议，并积极推进策略落地；\n4.关注外部行业和公司变化，编写研究报告，为平台提供发展建议；\n\n岗位基本要求\n1.有行业视角和具体业务分析项目落地经验；\n2.具有框架式分析能力，较好的逻辑思维能力；\n3.沟通能力较好，积极主动，具备自驱力和成长意愿；\n4.具有优秀的商业分析技能，熟练掌握SQL等数据处理和分析工具，具备一定的算法建模能力\n\n具备以下条件优先\n统计学、计算机、经济学相关专业优先，有内容生态、AI分析应用落地相关数据分析经验者\n具备所有者精神（Ownership）、学习并好奇（Learn and Be Curious）、坚持高标准（Insist on the Highest Standards）、应对不确定性的能力(Deal with Ambiguity）等价值观者优先\n\n岗位亮点\n我们有开放、直接的工作氛围，以逻辑和事实说话，而不是岗位级别和层级。我们尊重知识和常识，努力以业务视角思考自身工作。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4592075220","sourceKey":"meituan_social","company":"美团","title":"城市经理/区域经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4592075220&jobShareType=1","duty":"1. 负责区域内快驴业务的市场开拓与销售策略制定，推动业务规模持续增长。  \n2. 管理并带领销售团队，优化团队结构，提升团队执行力与业务转化效率。  \n3. 深度挖掘本地餐饮商户需求，拓展重点客户资源，建立并维护长期稳定的合作关系。  \n4. 协同总部运营、供应链及物流团队，推动区域业务高效落地，确保业绩目标达成。","requirements":"1. 大学专科及以上学历，市场营销、供应链管理或相关专业优先。  \n2. 具备7年以上B2B销售或业务开发经验，其中至少3年团队管理经验，有餐饮供应链或快消品行业背景者优先。  \n3. 熟悉北京市餐饮市场生态，具备较强的商户拓展能力与客户关系管理能力。  \n4. 具备优秀的领导力和数据分析能力，能够驱动团队实现高绩效目标。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责区域内快驴业务的市场开拓与销售策略制定，推动业务规模持续增长。  \n2. 管理并带领销售团队，优化团队结构，提升团队执行力与业务转化效率。  \n3. 深度挖掘本地餐饮商户需求，拓展重点客户资源，建立并维护长期稳定的合作关系。  \n4. 协同总部运营、供应链及物流团队，推动区域业务高效落地，确保业绩目标达成。\n\n岗位基本要求\n1. 大学专科及以上学历，市场营销、供应链管理或相关专业优先。  \n2. 具备7年以上B2B销售或业务开发经验，其中至少3年团队管理经验，有餐饮供应链或快消品行业背景者优先。  \n3. 熟悉北京市餐饮市场生态，具备较强的商户拓展能力与客户关系管理能力。  \n4. 具备优秀的领导力和数据分析能力，能够驱动团队实现高绩效目标。\n\n岗位亮点\n1. 深度参与快驴核心业务，具备高成长性与战略影响力。  \n2. 深耕本地餐饮供应链市场，直面商户痛点，推动业务创新与突破。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4698476095","sourceKey":"meituan_social","company":"美团","title":"闪购-歪马-督导经理（内蒙古/河南/河北）","city":"石家庄市/呼和浩特市/郑州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4698476095&jobShareType=1","duty":"1.协助合作商组建和管理团队，辅导和监督合作商做好团队管理工作；\n2.对合作商各级人员形成有效赋能，在履约配送、推广获客、商品运营、门店经营等模块实现标准化管理、业绩达成和盈利管理；\n3.稽核门店在仓内管理履约体验地推获客标准化落地，提升各个环节效率；\n4.结合商管政策做上传下达，做好门店全生命周期管控，达成总部目标；\n5.收集行业和竞争信息，做好战场动态传达。\n6.负责管理省内各城市商及门店","requirements":"1.本科及以上学历，市场营销、商务管理或相关专业优先考虑。\n2.具备丰富的渠道管理经验，熟悉渠道销售流程和渠道拓展方法。\n3.具备较强的市场分析能力和数据分析能力，能够准确判断市场需求和销售趋势。\n4.具备良好的沟通能力和团队合作精神，能够与不同部门和合作伙伴进行有效沟通和协调。\n5.具备较强的计划和执行能力，能够制定并执行有效的渠道销售策略。\n6.具备较强问题解决能力，保持良好的工作状态。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.协助合作商组建和管理团队，辅导和监督合作商做好团队管理工作；\n2.对合作商各级人员形成有效赋能，在履约配送、推广获客、商品运营、门店经营等模块实现标准化管理、业绩达成和盈利管理；\n3.稽核门店在仓内管理履约体验地推获客标准化落地，提升各个环节效率；\n4.结合商管政策做上传下达，做好门店全生命周期管控，达成总部目标；\n5.收集行业和竞争信息，做好战场动态传达。\n6.负责管理省内各城市商及门店\n\n岗位基本要求\n1.本科及以上学历，市场营销、商务管理或相关专业优先考虑。\n2.具备丰富的渠道管理经验，熟悉渠道销售流程和渠道拓展方法。\n3.具备较强的市场分析能力和数据分析能力，能够准确判断市场需求和销售趋势。\n4.具备良好的沟通能力和团队合作精神，能够与不同部门和合作伙伴进行有效沟通和协调。\n5.具备较强的计划和执行能力，能够制定并执行有效的渠道销售策略。\n6.具备较强问题解决能力，保持良好的工作状态。\n\n具备以下条件优先\n1.有加盟/酒水连锁门店管理经验者优先；\n2.有前置仓行业经验者优先。\n\n岗位亮点\n1.能够接触到全面的渠道管理工作，为个人职业发展提供广阔的空间。\n2.可以与各类合作伙伴进行广泛的合作，提升沟通和协调能力。\n3.可以参与制定并执行渠道营销方案，提升销售业绩和市场份额。\n4.可以通过分析市场动态和销售数据，提供有针对性的销售策略和决策支持。\n5.可以在团队协作中提升自己的团队合作和领导能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4661385969","sourceKey":"meituan_social","company":"美团","title":"AI安全专家","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4661385969&jobShareType=1","duty":"1、AI资产梳理与风险分级：识别企业内部AI资产（如：AI Agent、MCP Server、RAG应用等），梳理其数据访问范围与权限边界，建立资产清单和风险分级机制。\n2、AI行为风险识别：分析AI Agent在工具调用、文件访问、命令执行、身份权限使用等环节的行为风险，识别越权操作、敏感数据外传、异常自动化执行等问题。\n3、AI安全检测与响应：建立AI安全告警分级、调查和响应流程，协同公司内部系统实现高风险访问阻断、Agent暂停、Token回收等响应机制。\n4、AI使用安全治理：负责三方模型、Al Agent场景的日常安全管控与风险治理。","requirements":"1，具备3年以上信息安全经验，具备公司级安全产品设计或开发经验。\n2，具备AI 安全相关经验，拥有成功的AI安全落地案例。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1、AI资产梳理与风险分级：识别企业内部AI资产（如：AI Agent、MCP Server、RAG应用等），梳理其数据访问范围与权限边界，建立资产清单和风险分级机制。\n2、AI行为风险识别：分析AI Agent在工具调用、文件访问、命令执行、身份权限使用等环节的行为风险，识别越权操作、敏感数据外传、异常自动化执行等问题。\n3、AI安全检测与响应：建立AI安全告警分级、调查和响应流程，协同公司内部系统实现高风险访问阻断、Agent暂停、Token回收等响应机制。\n4、AI使用安全治理：负责三方模型、Al Agent场景的日常安全管控与风险治理。\n\n岗位基本要求\n1，具备3年以上信息安全经验，具备公司级安全产品设计或开发经验。\n2，具备AI 安全相关经验，拥有成功的AI安全落地案例。\n\n具备以下条件优先\n互联网大厂安全履历\n\n岗位亮点\nAI安全蓝海领域，共建AI安全业界最佳实践","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4677153178","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-嵌入式系统软件BSP工程师(蓝牙/Wi-Fi方向)","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4677153178&jobShareType=1","duty":"1、负责车载蓝牙/Wi-Fi 模组的嵌入式驱动开发与 Bring-up，包括芯片选型评估、BSP 层适配、外设驱动（UART/SDIO/PCIe/USB 等）调试及电源管理、低功耗优化。\n2、负责 Bluetooth（Classic + BLE）协议栈的移植、集成与调优，重点覆盖 A2DP、HFP、AVRCP、SPP、LE Audio（LC3/BAP）等核心 Profile，保障车载数据透传、蓝牙遥控器等业务的连接稳定性与低延时。\n3、主导无线连接稳定性与抗干扰方案的研发，深入分析与解决复杂电磁环境下的信号干扰、断连、延时等问题，确保产品在任何场景下的可靠连接。\n4、负责 Wi-Fi 协议栈的适配与性能调优，包括 802.11 协议栈参数优化、TCP/IP 传输性能优化，以及车载场景下的漫游/抗干扰/共存策略设计与验证。\n5、参与无人车的车端分布式系统的迭代设计开发、系统移植和定制，以及深度性能优化，交付高可靠性、高性能的车载分布式系统。\n6、参与车载综合业务网关（TBU）设备的系统软件和底层软件设计与开发，保障系统稳定性与性能。\n7、参与BootLoader、Linux Kernel 配置与裁剪、外设驱动的开发与调试，以及锁、调度、IO 等系统级优化。","requirements":"1、熟悉 Linux 系统（不限于 Ubuntu、Yocto、OpenWRT），OS 功底扎实。具备出色的 C/C++ 软件工程能力，以及良好的软件架构设计能力。\n2、具备 Linux 驱动开发能力，熟悉常见的总线接口（SPI、I2C、UART、PCIe、USB、SDIO 等）。\n3、3年以上嵌入式无线通信软件开发经验，有完整的蓝牙或 Wi-Fi 产品从方案选型到量产的全流程经验。\n4、精通 Bluetooth 协议栈架构，深入理解 BT Classic 与 BLE 双模原理，熟悉 A2DP、HFP、AVRCP、SPP、LE Audio（LC3/BAP）等核心规范及其编解码传输机制。\n5、具备无线抗干扰问题解决能力：熟悉无线电频谱、射频基本原理，有使用频谱分析仪等工具定位无线干扰问题的实际经验。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1、负责车载蓝牙/Wi-Fi 模组的嵌入式驱动开发与 Bring-up，包括芯片选型评估、BSP 层适配、外设驱动（UART/SDIO/PCIe/USB 等）调试及电源管理、低功耗优化。\n2、负责 Bluetooth（Classic + BLE）协议栈的移植、集成与调优，重点覆盖 A2DP、HFP、AVRCP、SPP、LE Audio（LC3/BAP）等核心 Profile，保障车载数据透传、蓝牙遥控器等业务的连接稳定性与低延时。\n3、主导无线连接稳定性与抗干扰方案的研发，深入分析与解决复杂电磁环境下的信号干扰、断连、延时等问题，确保产品在任何场景下的可靠连接。\n4、负责 Wi-Fi 协议栈的适配与性能调优，包括 802.11 协议栈参数优化、TCP/IP 传输性能优化，以及车载场景下的漫游/抗干扰/共存策略设计与验证。\n5、参与无人车的车端分布式系统的迭代设计开发、系统移植和定制，以及深度性能优化，交付高可靠性、高性能的车载分布式系统。\n6、参与车载综合业务网关（TBU）设备的系统软件和底层软件设计与开发，保障系统稳定性与性能。\n7、参与BootLoader、Linux Kernel 配置与裁剪、外设驱动的开发与调试，以及锁、调度、IO 等系统级优化。\n\n岗位基本要求\n1、熟悉 Linux 系统（不限于 Ubuntu、Yocto、OpenWRT），OS 功底扎实。具备出色的 C/C++ 软件工程能力，以及良好的软件架构设计能力。\n2、具备 Linux 驱动开发能力，熟悉常见的总线接口（SPI、I2C、UART、PCIe、USB、SDIO 等）。\n3、3年以上嵌入式无线通信软件开发经验，有完整的蓝牙或 Wi-Fi 产品从方案选型到量产的全流程经验。\n4、精通 Bluetooth 协议栈架构，深入理解 BT Classic 与 BLE 双模原理，熟悉 A2DP、HFP、AVRCP、SPP、LE Audio（LC3/BAP）等核心规范及其编解码传输机制。\n5、具备无线抗干扰问题解决能力：熟悉无线电频谱、射频基本原理，有使用频谱分析仪等工具定位无线干扰问题的实际经验。\n\n具备以下条件优先\n1、有主流蓝牙/Wi-Fi 芯片平台开发经验者优先，如：Qualcomm（高通）、Realtek（瑞昱）、恒玄 BES、炬芯、Nordic、杰理等。\n2、有车载场景下的蓝牙/Wi-Fi 开发经验，如车载信息娱乐系统（IVI）、T-Box、车载音频（A2DP/HFP/LE Audio）等。\n3、有 TWS 耳机、蓝牙音箱、Wi-Fi 音箱、智能穿戴等消费类无线音频产品量产经验。\n\n岗位亮点\n1、自动驾驶分布式系统平台和智能网联域控制器是无人车配送系统的核心支撑，跨越多个软硬件平台，对技术的广度和深度都有很大的挑战和锻炼。\n\n2、密切参与到最前沿的自动驾驶技术和无人车配送技术的研发迭代，为无人车配送系统的规模化落地运营贡献力量，开阔视野、扩宽个人职业道路。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4491537434","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-公共事务发展经理-华中","city":"北京市/上海市/深圳市/武汉市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4491537434&jobShareType=1","duty":"1、负责目标城市政府关系从0到1搭建，协调地方政府及交通部门，推动自动驾驶运营权、路权及商业化运营资质的获取；借助 AI 工具快速梳理华中各城市政策法规差异，生成定制化政策沟通材料，提升开城节奏；\n2、协调跨部门资源，完成数据上报、平台对接等合规要求；探索 AI 辅助合规文档整理和报送流程标准化，减少重复性行政事务投入；\n3、联动科研院所、车企等合作伙伴，推动常态化运营项目落地；利用 AI 工具进行合作伙伴图谱梳理和优先级分析，提高资源整合效率；\n4、处理属地舆情与问题，平衡政府数据安全要求与企业技术诉求；利用 AI 辅助舆情监测与快速响应材料撰写，提升危机处置速度与质量。","requirements":"1、本科及以上学历，5年以上工作经验。\n2、具备开城经验、有智能网联/新能源汽车领域路权成功案例者优先；在目标区域（华中区）具备成熟政企合作经验优先。\n3、善于沟通和协同合作伙伴推动业务落地，有较强的销售能力，掌握自动驾驶技术基础（如传感器配置、算法合规要求），实现技术与政策语言转化。\n4、有主动使用 AI 工具提升政策研究、文案撰写、信息整合效率的习惯；能识别日常工作中可 AI 化的重复性事务并付诸实践；对 AI 辅助政务工作持开放态度。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1、负责目标城市政府关系从0到1搭建，协调地方政府及交通部门，推动自动驾驶运营权、路权及商业化运营资质的获取；借助 AI 工具快速梳理华中各城市政策法规差异，生成定制化政策沟通材料，提升开城节奏；\n2、协调跨部门资源，完成数据上报、平台对接等合规要求；探索 AI 辅助合规文档整理和报送流程标准化，减少重复性行政事务投入；\n3、联动科研院所、车企等合作伙伴，推动常态化运营项目落地；利用 AI 工具进行合作伙伴图谱梳理和优先级分析，提高资源整合效率；\n4、处理属地舆情与问题，平衡政府数据安全要求与企业技术诉求；利用 AI 辅助舆情监测与快速响应材料撰写，提升危机处置速度与质量。\n\n岗位基本要求\n1、本科及以上学历，5年以上工作经验。\n2、具备开城经验、有智能网联/新能源汽车领域路权成功案例者优先；在目标区域（华中区）具备成熟政企合作经验优先。\n3、善于沟通和协同合作伙伴推动业务落地，有较强的销售能力，掌握自动驾驶技术基础（如传感器配置、算法合规要求），实现技术与政策语言转化。\n4、有主动使用 AI 工具提升政策研究、文案撰写、信息整合效率的习惯；能识别日常工作中可 AI 化的重复性事务并付诸实践；对 AI 辅助政务工作持开放态度。\n\n岗位亮点\n无人配送是行业最快落地的场景，是美团战略部署，加入美团无人配送将有机会引领整个行业的政策导向、推动整个行业的发展。\nAI 深度赋能岗位：政策文本分析、申报材料生成、知识库管理\n带薪年假、定期体检、五险一金、发展空间大、个人能力提升快。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4695430105","sourceKey":"meituan_social","company":"美团","title":"酒店供应链采购经理（工程物资）","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4695430105&jobShareType=1","duty":"1. 根据业务目标，倒推动作，结合品类策略制定采购策略、价格策略达成结果； \n\n2. 负责供应商筛选、合作洽谈、考察、合同签约等； \n\n3. 负责供应商履约管理与投诉管理，核实投诉与履约问题，督促问题整改、执行处罚； \n\n4. 负责供应商产品/服务质量监督检查，不定期抽检、公示度、督导改进一级处罚执行； \n\n5. 与公司各部门配合，及时处理客户/各部门的反馈、投诉和建议，提高服务满意度。","requirements":"1. 本科及以上学历；\n\n 2. 5以上采购管理经验； \n\n3. 熟悉采购工作流程，拥有较强的产品资源开拓、商务洽谈等能力；\n\n 4. 良好的沟通能力，逻辑清晰，跨部门沟通顺畅，具有良好额团队合作精神，善于学习与思考，执行力强； \n\n5. 过往从事过酒店、地产类等工程采购经验优先；","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1. 根据业务目标，倒推动作，结合品类策略制定采购策略、价格策略达成结果； \n\n2. 负责供应商筛选、合作洽谈、考察、合同签约等； \n\n3. 负责供应商履约管理与投诉管理，核实投诉与履约问题，督促问题整改、执行处罚； \n\n4. 负责供应商产品/服务质量监督检查，不定期抽检、公示度、督导改进一级处罚执行； \n\n5. 与公司各部门配合，及时处理客户/各部门的反馈、投诉和建议，提高服务满意度。\n\n岗位基本要求\n1. 本科及以上学历；\n\n 2. 5以上采购管理经验； \n\n3. 熟悉采购工作流程，拥有较强的产品资源开拓、商务洽谈等能力；\n\n 4. 良好的沟通能力，逻辑清晰，跨部门沟通顺畅，具有良好额团队合作精神，善于学习与思考，执行力强； \n\n5. 过往从事过酒店、地产类等工程采购经验优先；\n\n岗位亮点\n可接触更多品类，拓宽个人对产品的知识点，从采购到管理全链条接触。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3574337886","sourceKey":"meituan_social","company":"美团","title":"酒店连锁品牌合作商管理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3574337886&jobShareType=1","duty":"1.负责合作商准入准出机制的设计与持续优化，制定资质审核、运营能力评估等标准，确保机制与品牌战略及市场动态匹配。\n2.负责合作全链路流程管理，包括合同起草与签署、费用收取与核算、装修验收及开业支持等关键环节的推进与优化，提升执行效率。\n3.定期监控合作商经营数据（入住率、收益率等），输出运营分析报告，识别经营风险并推动整改落地。\n4.监督合作商品牌标准执行情况，对服务质量、卫生条件、设施维护等不达标项提出整改要求并跟踪闭环。\n5.为合作商提供运营赋能支持，包括收益优化建议、市场推广协助、培训资源对接等，建立高效沟通机制。\n6.建立并维护合作商管理数据库，深入分析合作商数据，为品牌战略调整、区域布局及合作政策优化提供决策支撑。\n7.探索AI工具在合作商管理中的应用，如利用智能模型辅助经营健康度预警、合作商风险评估、数据报告自动生成等，推动管理流程的数字化与智能化升级。","requirements":"1.本科及以上学历，酒店管理、工商管理、财务管理等相关专业优先。\n2.3年以上连锁酒店、连锁餐饮或其他连锁品牌合作商管理经验，熟悉合作商全生命周期管理。\n3.熟悉合作商管理全流程及相关法律法规，具备合同管理、财务核算及数据分析能力，对酒店4.行业运营模式及品牌标准有深刻理解。\n5.出色的沟通协调能力与逻辑思维能力，能推动跨部门协作、梳理复杂业务链条并提出解决方案。\n6.具备风险识别与管理能力，能应对突发问题并妥善解决。\n7.熟练使用办公软件及数据分析工具，善于利用AI工具提升数据处理与日常管理效率者优先。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1.负责合作商准入准出机制的设计与持续优化，制定资质审核、运营能力评估等标准，确保机制与品牌战略及市场动态匹配。\n2.负责合作全链路流程管理，包括合同起草与签署、费用收取与核算、装修验收及开业支持等关键环节的推进与优化，提升执行效率。\n3.定期监控合作商经营数据（入住率、收益率等），输出运营分析报告，识别经营风险并推动整改落地。\n4.监督合作商品牌标准执行情况，对服务质量、卫生条件、设施维护等不达标项提出整改要求并跟踪闭环。\n5.为合作商提供运营赋能支持，包括收益优化建议、市场推广协助、培训资源对接等，建立高效沟通机制。\n6.建立并维护合作商管理数据库，深入分析合作商数据，为品牌战略调整、区域布局及合作政策优化提供决策支撑。\n7.探索AI工具在合作商管理中的应用，如利用智能模型辅助经营健康度预警、合作商风险评估、数据报告自动生成等，推动管理流程的数字化与智能化升级。\n\n岗位基本要求\n1.本科及以上学历，酒店管理、工商管理、财务管理等相关专业优先。\n2.3年以上连锁酒店、连锁餐饮或其他连锁品牌合作商管理经验，熟悉合作商全生命周期管理。\n3.熟悉合作商管理全流程及相关法律法规，具备合同管理、财务核算及数据分析能力，对酒店4.行业运营模式及品牌标准有深刻理解。\n5.出色的沟通协调能力与逻辑思维能力，能推动跨部门协作、梳理复杂业务链条并提出解决方案。\n6.具备风险识别与管理能力，能应对突发问题并妥善解决。\n7.熟练使用办公软件及数据分析工具，善于利用AI工具提升数据处理与日常管理效率者优先。\n\n岗位亮点\n岗位亮点：\n1.全面参与连锁酒店品牌的合作商全生命周期管理，助力品牌扩张与运营优化。\n2.深度参与合作商准入准出机制及流程优化设计，推动品牌加盟体系的规范化与高效化。\n3.与品牌总部及合作上紧密协作，积累丰富的行业资源与管理经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4711376783","sourceKey":"meituan_social","company":"美团","title":"华南干调招商采购","city":"广州市/深圳市/东莞市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4711376783&jobShareType=1","duty":"1. 负责广州/深圳/东莞地区干调类商品的招商工作，拓展优质供应商资源，建立长期合作关系。  \n2. 价格谈判及合同签订，确保商品供应稳定。  \n3. 分析销售数据与市场趋势，优化商品结构，提升品类竞争力 \n4. 协同运营、仓储等团队，保障供应链高效运转。","requirements":"1. 大学专科及以上学历，3年以上商品招商或采购相关工作经验，有干调行业背景优先。  \n2. 熟悉广东市场（广州/深圳/东莞优先），具备一定的供应商资源及渠道拓展能力。  \n3. 具备良好的谈判技巧、数据分析能力和跨部门沟通协调能力。  \n4. 工作积极主动，具备较强的责任心和执行力，能适应一定的工作压力。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责广州/深圳/东莞地区干调类商品的招商工作，拓展优质供应商资源，建立长期合作关系。  \n2. 价格谈判及合同签订，确保商品供应稳定。  \n3. 分析销售数据与市场趋势，优化商品结构，提升品类竞争力 \n4. 协同运营、仓储等团队，保障供应链高效运转。\n\n岗位基本要求\n1. 大学专科及以上学历，3年以上商品招商或采购相关工作经验，有干调行业背景优先。  \n2. 熟悉广东市场（广州/深圳/东莞优先），具备一定的供应商资源及渠道拓展能力。  \n3. 具备良好的谈判技巧、数据分析能力和跨部门沟通协调能力。  \n4. 工作积极主动，具备较强的责任心和执行力，能适应一定的工作压力。\n\n具备以下条件优先\n有美菜、优大集工作经验优先\n\n岗位亮点\n1. 深耕本地市场，聚焦干调品类，发展空间广阔。  \n2. 团队氛围开放协作，支持个人成长与能力提升。  \n3. 公司提供完善的培训体系与职业发展通道。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4713261240","sourceKey":"meituan_social","company":"美团","title":"点评玩乐-高级产品专家","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4713261240&jobShareType=1","duty":"1、负责大众点评玩乐业务的用户产品规划与迭代，对点评玩乐的用户规模、转化效率及核心体验负责。结合行业发展趋势与业务特性，明确规划并推动业务增长。\n\n2、主导点评玩乐的核心场景产品设计、体验优化与持续迭代。运用 AI 辅助原型生成工具验证方案可行性，通过数据驱动与用户研究定位关键问题；探索并落地AI产品功能，驱动产品创新与解决方案落地。\n\n3、与运营、研发、算法、商业分析等团队紧密协作，利用 AI 辅助项目管理工具提升跨团队协同效率，高效推动复杂项目，确保业务目标高质量达成。\n\n4、深度洞察用户需求与行业趋势，基于大模型辅助用户调研分析定义差异化产品价值，支撑点评玩乐业务规模增长。","requirements":"1、3年及以上互联网用户产品经验，具备0-1负责复杂产品模块的经验，有O2O、本地生活背景者优先。\n\n2、出色的业务分析与产品规划能力，能在复杂业务环境中保持清晰判断，具备独当一面的项目推进与落地能力。熟悉 AI 辅助产品设计工具链，能将 AI 能力融入日常产品工作流。\n\n3、目标导向，拥有优秀的横向沟通与协同能力，能够有效整合资源，推动跨团队协作。具备数据驱动思维，可以熟练使用 AI 增强型数据分析工具进行指标归因与决策支持。\n\n4、对用户需求有敏锐的洞察力，具备创新思维与解题能力，不拘泥于固有模式。对 AI 技术发展趋势有敏锐感知，能主动探索 AI 在本地生活场景的创新应用，通过产品方案解决本质问题。","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1、负责大众点评玩乐业务的用户产品规划与迭代，对点评玩乐的用户规模、转化效率及核心体验负责。结合行业发展趋势与业务特性，明确规划并推动业务增长。\n\n2、主导点评玩乐的核心场景产品设计、体验优化与持续迭代。运用 AI 辅助原型生成工具验证方案可行性，通过数据驱动与用户研究定位关键问题；探索并落地AI产品功能，驱动产品创新与解决方案落地。\n\n3、与运营、研发、算法、商业分析等团队紧密协作，利用 AI 辅助项目管理工具提升跨团队协同效率，高效推动复杂项目，确保业务目标高质量达成。\n\n4、深度洞察用户需求与行业趋势，基于大模型辅助用户调研分析定义差异化产品价值，支撑点评玩乐业务规模增长。\n\n岗位基本要求\n1、3年及以上互联网用户产品经验，具备0-1负责复杂产品模块的经验，有O2O、本地生活背景者优先。\n\n2、出色的业务分析与产品规划能力，能在复杂业务环境中保持清晰判断，具备独当一面的项目推进与落地能力。熟悉 AI 辅助产品设计工具链，能将 AI 能力融入日常产品工作流。\n\n3、目标导向，拥有优秀的横向沟通与协同能力，能够有效整合资源，推动跨团队协作。具备数据驱动思维，可以熟练使用 AI 增强型数据分析工具进行指标归因与决策支持。\n\n4、对用户需求有敏锐的洞察力，具备创新思维与解题能力，不拘泥于固有模式。对 AI 技术发展趋势有敏锐感知，能主动探索 AI 在本地生活场景的创新应用，通过产品方案解决本质问题。\n\n岗位亮点\n1、开放、务实、以用户价值为导向的团队氛围，鼓励创新思考与突破实践，欢迎一起探索AI在本地生活场景的实际落地。\n\n2、具有市场竞争力的薪酬福利、长期激励与完善的职业发展通道。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4713156325","sourceKey":"meituan_social","company":"美团","title":"软硬件法务BP","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4713156325&jobShareType=1","duty":"1.结合业务目标、外部环境变化及法律合规需求，形成对业务有效的法律风险控制方案，如业务全国各区域运营、数据合规、信息安全、广告合规等风险评估；\n2.参与业务的产品设计，评估法律风险和提出法律建议，能运用自己的专业知识通过合同、流程、机制、培训等多种路径，帮助实现业务目标；\n3.支持业务硬件（整车、零部件、电池等）采购、供应链管理、产品研发等项目风险评估，合同支持以及纠纷事件处置；\n4.支持业务各链路发生的争议纠纷、突发事件、行政处罚风险等；\n5.业务政策、立法跟踪、分析解读并向业务输出指导意见；\n6.整合法务团队内外部资源，协调多个部门，完成重点专项的推进与落地。","requirements":"1.有耐心，能够熟练进行法律风险咨询和评估，有应对突发事件经验；\n2.执行力强，善于沟通，愿意配合团队完成任务；\n3.通过国家统一法律职业资格考试，法学本科及以上学历；\n4.有5年以上公司法务或律师工作经验，熟悉硬件、有产品质量纠纷处置经验或诉讼经验优先。","description":"部门介绍\n公司事务平台负责构建公司的公共战略体系，助力业务可持续发展及公司对外影响力的提升。通过内外部风险管理，确保公司合规发展；通过深耕公共战略，推动内外良好沟通，连接公司发展与社会期待，助力业务高质量发展；通过管理社会责任议题、公益投入等，助力公司创造更多社会价值；同时为公司提供行政、采购等基础服务。我们坚持“懂业务、拿结果，勇担当、善协同，不唯上、只唯真”的工作理念，期待具有公共战略素养、了解公司治理逻辑的你加入！\n\n岗位职责\n1.结合业务目标、外部环境变化及法律合规需求，形成对业务有效的法律风险控制方案，如业务全国各区域运营、数据合规、信息安全、广告合规等风险评估；\n2.参与业务的产品设计，评估法律风险和提出法律建议，能运用自己的专业知识通过合同、流程、机制、培训等多种路径，帮助实现业务目标；\n3.支持业务硬件（整车、零部件、电池等）采购、供应链管理、产品研发等项目风险评估，合同支持以及纠纷事件处置；\n4.支持业务各链路发生的争议纠纷、突发事件、行政处罚风险等；\n5.业务政策、立法跟踪、分析解读并向业务输出指导意见；\n6.整合法务团队内外部资源，协调多个部门，完成重点专项的推进与落地。\n\n岗位基本要求\n1.有耐心，能够熟练进行法律风险咨询和评估，有应对突发事件经验；\n2.执行力强，善于沟通，愿意配合团队完成任务；\n3.通过国家统一法律职业资格考试，法学本科及以上学历；\n4.有5年以上公司法务或律师工作经验，熟悉硬件、有产品质量纠纷处置经验或诉讼经验优先。\n\n岗位亮点\n业务多元、有机会接触前沿商业模式，团队氛围活泼","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4704871410","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-融合定位算法专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4704871410&jobShareType=1","duty":"1、负责提升当前多传感器融合定位系统在各类长尾场景上的能力。\n2、负责探索基于深度学习模型的3D视觉的应用能力；例如deep odometry, deep 3D matching and reconstruction.\n3、与高精地图、感知、PnC等算法团队合作，能够完成从研发到工程化到上线落地的过程。","requirements":"1、硕士以上学历优先，计算机相关专业（人工智能，模式识别，计算机科学，数学等)；\n2、熟练掌握计算机视觉及多传感器融合相关的知识。熟悉深度学习相关知识。具有独立分析问题、制定技术方案、开发上线的能力；\n3、熟悉GPS卫星定位原理，如PVT、精密单点定位（PPP）、RTK算法、卫星差分后处理算法等；\n4、具备较好的编程能力，熟练掌握C/C++或Python编程语言。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1、负责提升当前多传感器融合定位系统在各类长尾场景上的能力。\n2、负责探索基于深度学习模型的3D视觉的应用能力；例如deep odometry, deep 3D matching and reconstruction.\n3、与高精地图、感知、PnC等算法团队合作，能够完成从研发到工程化到上线落地的过程。\n\n岗位基本要求\n1、硕士以上学历优先，计算机相关专业（人工智能，模式识别，计算机科学，数学等)；\n2、熟练掌握计算机视觉及多传感器融合相关的知识。熟悉深度学习相关知识。具有独立分析问题、制定技术方案、开发上线的能力；\n3、熟悉GPS卫星定位原理，如PVT、精密单点定位（PPP）、RTK算法、卫星差分后处理算法等；\n4、具备较好的编程能力，熟练掌握C/C++或Python编程语言。\n\n具备以下条件优先\n1、3年以上计算机视觉或2年以上自动驾驶相关工作经验优先；\n2、在机器人领域或者计算机视觉或机器学习相关领域发表过高质量论文；\n3、在Github上有深度学习、计算机视觉、融合定位等相关高质量项目。\n\n岗位亮点\n美团自动车配送部在公开道路、居民区、校园三大行驶场景上有深厚的技术和数据积累，定位作为自动驾驶最基础且核心的功能之一，对自动驾驶落地有重要的价值，过去、现在及未来都是自动车配送部重点建设团队。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4708608380","sourceKey":"meituan_social","company":"美团","title":"生产主管","city":"石家庄市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4708608380&jobShareType=1","duty":"1.负责石家庄仓内生产管理工作，并对人效，质量和履约负责；\n2.持续员工培训，并监督有效执行；\n3.横向部门沟通协调工作；\n4.不断优化现有作业流程。提高人效.减低差异；\n5.仓内员工的正负激励措施及执行；\n6.现场6S管理；\n7.直接上级安排的其它工作；","requirements":"具备较强团队管理能力，激发员工工作热情；\n熟悉仓库管理各操作流程；\n熟练使用仓库WMS操作系统和办公软件；","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责石家庄仓内生产管理工作，并对人效，质量和履约负责；\n2.持续员工培训，并监督有效执行；\n3.横向部门沟通协调工作；\n4.不断优化现有作业流程。提高人效.减低差异；\n5.仓内员工的正负激励措施及执行；\n6.现场6S管理；\n7.直接上级安排的其它工作；\n\n岗位基本要求\n具备较强团队管理能力，激发员工工作热情；\n熟悉仓库管理各操作流程；\n熟练使用仓库WMS操作系统和办公软件；\n\n具备以下条件优先\n大型仓储生产管理经验；\n\n岗位亮点\n团队稳定，大平台，晋升空间大，模块仓库，便于个人能力发挥；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4689242033","sourceKey":"meituan_social","company":"美团","title":"功能安全工程师","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4689242033&jobShareType=1","duty":"1、负责具身智能产品/无人机/电池等产品的功能安全开发工作，制定安全策略，分解细化安全要求，识别和评估安全性风险，制定预防和缓解措施；\n2、针对产品的安全指标、系统失效、性能局限等，制定对应的安全策略，分解安全需求并推动本体、硬件、软件团队实施；\n3、负责人机交互设备的协作安全、交互安全的策略制定或审查，支持开展协作安全的设计、分析与验证；\n4、按照规范要求和产品特点，组织开展HARA、FMEDA、CCA等具体的安全性分析评估工作；\n5、负责安全相关测试策略和用例设计，如测试场景搭建、测试能力建设；\n6、开展具身智能、AI相关安全能力的建设和前瞻，如场景泛化的安全问题分析，AI相关的安全保证等\n7、主动探索并运用各类AI工具优化日常工作流程，积极推动AI在业务场景中的落地实践，持续提升个人及团队的工作效率与产出质量；","requirements":"1、大学本科以上学历，电子电气、机器人、汽车、飞行器、机械、可靠性、安全性等相关专业。\n2、5年以上机器人、汽车、电池、航空领域的适航安全/功能安全/协作安全的工作经验，熟练掌握机器人/民航/汽车等至少一个领域的安全性标准或规范，如ISO13849、ISO26262、IEC61508/ISO 15066、预期功能安全标准等\n3、熟练掌握功能安全领域的HARA、FMEDA等分析方法，负责或参与过机器人、车辆、无人机或相关组件的安全分析、测试或认证。\n4、熟悉机器人、无人机、SOC、MCU、传感器、电机、电池、机械臂等常见产品的软硬件工作原理或控制算法。\n5、能够快速学习新知识，思维清晰，善于合作、分析和总结\n6、具备主动学习与探索AI新工具、新方法的意识，能持续将AI能力融入实际工作场景并独立落地；\n7、对AI工具有实际使用经验，能清晰阐述利用AI解决复杂问题的思路与方法，保持对AI前沿趋势的敏感度。","description":"部门介绍\n为了更好地提升城市即时配送的效率与体验，2017年，美团启动了无人机配送服务的探索，通过科技创新推动履约工具变革，加快建设空地协同的本地即时配送网络。\n在过去的六年里，美团无人机完成了飞行器、自动化机场及智能调度系统的研发工作，实现了研发设计、生产制造、运营运维全链条布局，达成了城市复杂场景物流无人机高频次、高密度、多天时、多天侯运行。\n2023年7月，美团无人机在上海发布了自主研发的第四代无人机，跟此前机型相比，新机型升级了环境适应能力，可在“零下20度至50度”的中雨、中雪、6级风、弱光等环境中稳定飞行，能够适应97%以上国内城市的自然环境要求。\n截至2024年12月，美团无人机已在深圳、北京、上海、广州、南京、迪拜等城市开通53条航线，并累计完成订单超40万单。即时零售配送服务覆盖了办公、社区、景区、市政公园、校园、医疗、图书馆等多种场景。在医疗场景中，美团无人机可围绕医疗血液、检验样本、院前急救物资、特殊药品等医疗物资配送需求建设端到端的全天时急送网络。\n\n岗位职责\n1、负责具身智能产品/无人机/电池等产品的功能安全开发工作，制定安全策略，分解细化安全要求，识别和评估安全性风险，制定预防和缓解措施；\n2、针对产品的安全指标、系统失效、性能局限等，制定对应的安全策略，分解安全需求并推动本体、硬件、软件团队实施；\n3、负责人机交互设备的协作安全、交互安全的策略制定或审查，支持开展协作安全的设计、分析与验证；\n4、按照规范要求和产品特点，组织开展HARA、FMEDA、CCA等具体的安全性分析评估工作；\n5、负责安全相关测试策略和用例设计，如测试场景搭建、测试能力建设；\n6、开展具身智能、AI相关安全能力的建设和前瞻，如场景泛化的安全问题分析，AI相关的安全保证等\n7、主动探索并运用各类AI工具优化日常工作流程，积极推动AI在业务场景中的落地实践，持续提升个人及团队的工作效率与产出质量；\n\n岗位基本要求\n1、大学本科以上学历，电子电气、机器人、汽车、飞行器、机械、可靠性、安全性等相关专业。\n2、5年以上机器人、汽车、电池、航空领域的适航安全/功能安全/协作安全的工作经验，熟练掌握机器人/民航/汽车等至少一个领域的安全性标准或规范，如ISO13849、ISO26262、IEC61508/ISO 15066、预期功能安全标准等\n3、熟练掌握功能安全领域的HARA、FMEDA等分析方法，负责或参与过机器人、车辆、无人机或相关组件的安全分析、测试或认证。\n4、熟悉机器人、无人机、SOC、MCU、传感器、电机、电池、机械臂等常见产品的软硬件工作原理或控制算法。\n5、能够快速学习新知识，思维清晰，善于合作、分析和总结\n6、具备主动学习与探索AI新工具、新方法的意识，能持续将AI能力融入实际工作场景并独立落地；\n7、对AI工具有实际使用经验，能清晰阐述利用AI解决复杂问题的思路与方法，保持对AI前沿趋势的敏感度。\n\n具备以下条件优先\n1、同时具备可靠性设计与测试相关知识或经验者优先\n2、有跨多个行业/领域安全性或功能安全经验者优先\n\n岗位亮点\n1.有机会参与具身智能领域的创新项目，跟随行业技术发展的最前沿；\n2.团队氛围好，工作环境舒适，有机会接触到各种前沿技术；\n3.公司提供良好的职业发展空间和晋升机会，能够帮助员工实现个人职业目标。","jdComplete":true,"sourceStatus":"000"}];
